INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('1', 'kej', 'Kejadian', 1, 1, 'Pada mulanya Allah menciptakan langit dan bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 2, 'Bumi belum berbentuk dan kosong; gelap gulita menutupi samudera raya, dan Roh Allah melayang-layang di atas permukaan air.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 3, 'Berfirmanlah Allah: "Jadilah terang." Lalu terang itu jadi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 4, 'Allah melihat bahwa terang itu baik, lalu dipisahkan-Nyalah terang itu dari gelap.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 5, 'Dan Allah menamai terang itu siang, dan gelap itu malam. Jadilah petang dan jadilah pagi, itulah hari pertama.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 6, 'Berfirmanlah Allah: "Jadilah cakrawala di tengah segala air untuk memisahkan air dari air."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 7, 'Maka Allah menjadikan cakrawala dan Ia memisahkan air yang ada di bawah cakrawala itu dari air yang ada di atasnya. Dan jadilah demikian.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 8, 'Lalu Allah menamai cakrawala itu langit. Jadilah petang dan jadilah pagi, itulah hari kedua.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 9, 'Berfirmanlah Allah: "Hendaklah segala air yang di bawah langit berkumpul pada satu tempat, sehingga kelihatan yang kering." Dan jadilah demikian.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 10, 'Lalu Allah menamai yang kering itu darat, dan kumpulan air itu dinamai-Nya laut. Allah melihat bahwa semuanya itu baik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 11, 'Berfirmanlah Allah: "Hendaklah tanah menumbuhkan tunas-tunas muda, tumbuh-tumbuhan yang berbiji, segala jenis pohon buah-buahan yang menghasilkan buah yang berbiji, supaya ada tumbuh-tumbuhan di bumi." Dan jadilah demikian.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 12, 'Tanah itu menumbuhkan tunas-tunas muda, segala jenis tumbuh-tumbuhan yang berbiji dan segala jenis pohon-pohonan yang menghasilkan buah yang berbiji. Allah melihat bahwa semuanya itu baik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 13, 'Jadilah petang dan jadilah pagi, itulah hari ketiga.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 14, 'Berfirmanlah Allah: "Jadilah benda-benda penerang pada cakrawala untuk memisahkan siang dari malam. Biarlah benda-benda penerang itu menjadi tanda yang menunjukkan masa-masa yang tetap dan hari-hari dan tahun-tahun,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 15, 'dan sebagai penerang pada cakrawala biarlah benda-benda itu menerangi bumi." Dan jadilah demikian.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 16, 'Maka Allah menjadikan kedua benda penerang yang besar itu, yakni yang lebih besar untuk menguasai siang dan yang lebih kecil untuk menguasai malam, dan menjadikan juga bintang-bintang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 17, 'Allah menaruh semuanya itu di cakrawala untuk menerangi bumi,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 18, 'dan untuk menguasai siang dan malam, dan untuk memisahkan terang dari gelap. Allah melihat bahwa semuanya itu baik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 19, 'Jadilah petang dan jadilah pagi, itulah hari keempat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 20, 'Berfirmanlah Allah: "Hendaklah dalam air berkeriapan makhluk yang hidup, dan hendaklah burung beterbangan di atas bumi melintasi cakrawala."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 21, 'Maka Allah menciptakan binatang-binatang laut yang besar dan segala jenis makhluk hidup yang bergerak, yang berkeriapan dalam air, dan segala jenis burung yang bersayap. Allah melihat bahwa semuanya itu baik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 22, 'Lalu Allah memberkati semuanya itu, firman-Nya: "Berkembangbiaklah dan bertambah banyaklah serta penuhilah air dalam laut, dan hendaklah burung-burung di bumi bertambah banyak."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 23, 'Jadilah petang dan jadilah pagi, itulah hari kelima.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 24, 'Berfirmanlah Allah: "Hendaklah bumi mengeluarkan segala jenis makhluk yang hidup, ternak dan binatang melata dan segala jenis binatang liar." Dan jadilah demikian.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 25, 'Allah menjadikan segala jenis binatang liar dan segala jenis ternak dan segala jenis binatang melata di muka bumi. Allah melihat bahwa semuanya itu baik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 26, 'Berfirmanlah Allah: "Baiklah Kita menjadikan manusia menurut gambar dan rupa Kita, supaya mereka berkuasa atas ikan-ikan di laut dan burung-burung di udara dan atas ternak dan atas seluruh bumi dan atas segala binatang melata yang merayap di bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 27, 'Maka Allah menciptakan manusia itu menurut gambar-Nya, menurut gambar Allah diciptakan-Nya dia; laki-laki dan perempuan diciptakan-Nya mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 28, 'Allah memberkati mereka, lalu Allah berfirman kepada mereka: "Beranakcuculah dan bertambah banyak; penuhilah bumi dan taklukkanlah itu, berkuasalah atas ikan-ikan di laut dan burung-burung di udara dan atas segala binatang yang merayap di bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 29, 'Berfirmanlah Allah: "Lihatlah, Aku memberikan kepadamu segala tumbuh-tumbuhan yang berbiji di seluruh bumi dan segala pohon-pohonan yang buahnya berbiji; itulah akan menjadi makananmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 30, 'Tetapi kepada segala binatang di bumi dan segala burung di udara dan segala yang merayap di bumi, yang bernyawa, Kuberikan segala tumbuh-tumbuhan hijau menjadi makanannya." Dan jadilah demikian.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 1, 31, 'Maka Allah melihat segala yang dijadikan-Nya itu, sungguh amat baik. Jadilah petang dan jadilah pagi, itulah hari keenam.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 1, 'Demikianlah diselesaikan langit dan bumi dan segala isinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 2, 'Ketika Allah pada hari ketujuh telah menyelesaikan pekerjaan yang dibuat-Nya itu, berhentilah Ia pada hari ketujuh dari segala pekerjaan yang telah dibuat-Nya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 3, 'Lalu Allah memberkati hari ketujuh itu dan menguduskannya, karena pada hari itulah Ia berhenti dari segala pekerjaan penciptaan yang telah dibuat-Nya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 4, 'Demikianlah riwayat langit dan bumi pada waktu diciptakan. Ketika TUHAN Allah menjadikan bumi dan langit, ?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 5, 'belum ada semak apapun di bumi, belum timbul tumbuh-tumbuhan apapun di padang, sebab TUHAN Allah belum menurunkan hujan ke bumi, dan belum ada orang untuk mengusahakan tanah itu;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 6, 'tetapi ada kabut naik ke atas dari bumi dan membasahi seluruh permukaan bumi itu?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 7, 'ketika itulah TUHAN Allah membentuk manusia itu dari debu tanah dan menghembuskan nafas hidup ke dalam hidungnya; demikianlah manusia itu menjadi makhluk yang hidup.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 8, 'Selanjutnya TUHAN Allah membuat taman di Eden, di sebelah timur; disitulah ditempatkan-Nya manusia yang dibentuk-Nya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 9, 'Lalu TUHAN Allah menumbuhkan berbagai-bagai pohon dari bumi, yang menarik dan yang baik untuk dimakan buahnya; dan pohon kehidupan di tengah-tengah taman itu, serta pohon pengetahuan tentang yang baik dan yang jahat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 10, 'Ada suatu sungai mengalir dari Eden untuk membasahi taman itu, dan dari situ sungai itu terbagi menjadi empat cabang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 11, 'Yang pertama, namanya Pison, yakni yang mengalir mengelilingi seluruh tanah Hawila, tempat emas ada.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 12, 'Dan emas dari negeri itu baik; di sana ada damar bedolah dan batu krisopras.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 13, 'Nama sungai yang kedua ialah Gihon, yakni yang mengalir mengelilingi seluruh tanah Kush.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 14, 'Nama sungai yang ketiga ialah Tigris, yakni yang mengalir di sebelah timur Asyur. Dan sungai yang keempat ialah Efrat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 15, 'TUHAN Allah mengambil manusia itu dan menempatkannya dalam taman Eden untuk mengusahakan dan memelihara taman itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 16, 'Lalu TUHAN Allah memberi perintah ini kepada manusia: "Semua pohon dalam taman ini boleh kaumakan buahnya dengan bebas,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 17, 'tetapi pohon pengetahuan tentang yang baik dan yang jahat itu, janganlah kaumakan buahnya, sebab pada hari engkau memakannya, pastilah engkau mati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 18, 'TUHAN Allah berfirman: "Tidak baik, kalau manusia itu seorang diri saja. Aku akan menjadikan penolong baginya, yang sepadan dengan dia."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 19, 'Lalu TUHAN Allah membentuk dari tanah segala binatang hutan dan segala burung di udara. Dibawa-Nyalah semuanya kepada manusia itu untuk melihat, bagaimana ia menamainya; dan seperti nama yang diberikan manusia itu kepada tiap-tiap makhluk yang hidup, demikianlah nanti nama makhluk itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 20, 'Manusia itu memberi nama kepada segala ternak, kepada burung-burung di udara dan kepada segala binatang hutan, tetapi baginya sendiri ia tidak menjumpai penolong yang sepadan dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 21, 'Lalu TUHAN Allah membuat manusia itu tidur nyenyak; ketika ia tidur, TUHAN Allah mengambil salah satu rusuk dari padanya, lalu menutup tempat itu dengan daging.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 22, 'Dan dari rusuk yang diambil TUHAN Allah dari manusia itu, dibangun-Nyalah seorang perempuan, lalu dibawa-Nya kepada manusia itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 23, 'Lalu berkatalah manusia itu: "Inilah dia, tulang dari tulangku dan daging dari dagingku. Ia akan dinamai perempuan, sebab ia diambil dari laki-laki."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 24, 'Sebab itu seorang laki-laki akan meninggalkan ayahnya dan ibunya dan bersatu dengan isterinya, sehingga keduanya menjadi satu daging.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 2, 25, 'Mereka keduanya telanjang, manusia dan isterinya itu, tetapi mereka tidak merasa malu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 1, 'Adapun ular ialah yang paling cerdik dari segala binatang di darat yang dijadikan oleh TUHAN Allah. Ular itu berkata kepada perempuan itu: "Tentulah Allah berfirman: Semua pohon dalam taman ini jangan kamu makan buahnya, bukan?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 2, 'Lalu sahut perempuan itu kepada ular itu: "Buah pohon-pohonan dalam taman ini boleh kami makan,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 3, 'tetapi tentang buah pohon yang ada di tengah-tengah taman, Allah berfirman: Jangan kamu makan ataupun raba buah itu, nanti kamu mati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 4, 'Tetapi ular itu berkata kepada perempuan itu: "Sekali-kali kamu tidak akan mati,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 5, 'tetapi Allah mengetahui, bahwa pada waktu kamu memakannya matamu akan terbuka, dan kamu akan menjadi seperti Allah, tahu tentang yang baik dan yang jahat."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 6, 'Perempuan itu melihat, bahwa buah pohon itu baik untuk dimakan dan sedap kelihatannya, lagipula pohon itu menarik hati karena memberi pengertian. Lalu ia mengambil dari buahnya dan dimakannya dan diberikannya juga kepada suaminya yang bersama-sama dengan dia, dan suaminyapun memakannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 7, 'Maka terbukalah mata mereka berdua dan mereka tahu, bahwa mereka telanjang; lalu mereka menyemat daun pohon ara dan membuat cawat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 8, 'Ketika mereka mendengar bunyi langkah TUHAN Allah, yang berjalan-jalan dalam taman itu pada waktu hari sejuk, bersembunyilah manusia dan isterinya itu terhadap TUHAN Allah di antara pohon-pohonan dalam taman.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 9, 'Tetapi TUHAN Allah memanggil manusia itu dan berfirman kepadanya: "Di manakah engkau?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 10, 'Ia menjawab: "Ketika aku mendengar, bahwa Engkau ada dalam taman ini, aku menjadi takut, karena aku telanjang; sebab itu aku bersembunyi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 11, 'Firman-Nya: "Siapakah yang memberitahukan kepadamu, bahwa engkau telanjang? Apakah engkau makan dari buah pohon, yang Kularang engkau makan itu?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 12, 'Manusia itu menjawab: "Perempuan yang Kautempatkan di sisiku, dialah yang memberi dari buah pohon itu kepadaku, maka kumakan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 13, 'Kemudian berfirmanlah TUHAN Allah kepada perempuan itu: "Apakah yang telah kauperbuat ini?" Jawab perempuan itu: "Ular itu yang memperdayakan aku, maka kumakan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 14, 'Lalu berfirmanlah TUHAN Allah kepada ular itu: "Karena engkau berbuat demikian, terkutuklah engkau di antara segala ternak dan di antara segala binatang hutan; dengan perutmulah engkau akan menjalar dan debu tanahlah akan kaumakan seumur hidupmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 15, 'Aku akan mengadakan permusuhan antara engkau dan perempuan ini, antara keturunanmu dan keturunannya; keturunannya akan meremukkan kepalamu, dan engkau akan meremukkan tumitnya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 16, 'Firman-Nya kepada perempuan itu: "Susah payahmu waktu mengandung akan Kubuat sangat banyak; dengan kesakitan engkau akan melahirkan anakmu; namun engkau akan berahi kepada suamimu dan ia akan berkuasa atasmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 17, 'Lalu firman-Nya kepada manusia itu: "Karena engkau mendengarkan perkataan isterimu dan memakan dari buah pohon, yang telah Kuperintahkan kepadamu: Jangan makan dari padanya, maka terkutuklah tanah karena engkau; dengan bersusah payah engkau akan mencari rezekimu dari tanah seumur hidupmu:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 18, 'semak duri dan rumput duri yang akan dihasilkannya bagimu, dan tumbuh-tumbuhan di padang akan menjadi makananmu;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 19, 'dengan berpeluh engkau akan mencari makananmu, sampai engkau kembali lagi menjadi tanah, karena dari situlah engkau diambil; sebab engkau debu dan engkau akan kembali menjadi debu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 20, 'Manusia itu memberi nama Hawa kepada isterinya, sebab dialah yang menjadi ibu semua yang hidup.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 21, 'Dan TUHAN Allah membuat pakaian dari kulit binatang untuk manusia dan untuk isterinya itu, lalu mengenakannya kepada mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 22, 'Berfirmanlah TUHAN Allah: "Sesungguhnya manusia itu telah menjadi seperti salah satu dari Kita, tahu tentang yang baik dan yang jahat; maka sekarang jangan sampai ia mengulurkan tangannya dan mengambil pula dari buah pohon kehidupan itu dan memakannya, sehingga ia hidup untuk selama-lamanya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 23, 'Lalu TUHAN Allah mengusir dia dari taman Eden supaya ia mengusahakan tanah dari mana ia diambil.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 3, 24, 'Ia menghalau manusia itu dan di sebelah timur taman Eden ditempatkan-Nyala beberapa kerub dengan pedang yang bernyala-nyala dan menyambar-nyambar, untuk menjaga jalan ke pohon kehidupan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 1, 'Kemudian manusia itu bersetubuh dengan Hawa, isterinya, dan mengandunglah perempuan itu, lalu melahirkan Kain; maka kata perempuan itu: "Aku telah mendapat seorang anak laki-laki dengan pertolongan TUHAN."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 2, 'Selanjutnya dilahirkannyalah Habel, adik Kain; dan Habel menjadi gembala kambing domba, Kain menjadi petani.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 3, 'Setelah beberapa waktu lamanya, maka Kain mempersembahkan sebagian dari hasil tanah itu kepada TUHAN sebagai korban persembahan;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 4, 'Habel juga mempersembahkan korban persembahan dari anak sulung kambing dombanya, yakni lemak-lemaknya; maka TUHAN mengindahkan Habel dan korban persembahannya itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 5, 'tetapi Kain dan korban persembahannya tidak diindahkan-Nya. Lalu hati Kain menjadi sangat panas, dan mukanya muram.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 6, 'Firman TUHAN kepada Kain: "Mengapa hatimu panas dan mukamu muram?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 7, 'Apakah mukamu tidak akan berseri, jika engkau berbuat baik? Tetapi jika engkau tidak berbuat baik, dosa sudah mengintip di depan pintu; ia sangat menggoda engkau, tetapi engkau harus berkuasa atasnya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 8, 'Kata Kain kepada Habel, adiknya: "Marilah kita pergi ke padang." Ketika mereka ada di padang, tiba-tiba Kain memukul Habel, adiknya itu, lalu membunuh dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 9, 'Firman TUHAN kepada Kain: "Di mana Habel, adikmu itu?" Jawabnya: "Aku tidak tahu! Apakah aku penjaga adikku?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 10, 'Firman-Nya: "Apakah yang telah kauperbuat ini? Darah adikmu itu berteriak kepada-Ku dari tanah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 11, 'Maka sekarang, terkutuklah engkau, terbuang jauh dari tanah yang mengangakan mulutnya untuk menerima darah adikmu itu dari tanganmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 12, 'Apabila engkau mengusahakan tanah itu, maka tanah itu tidak akan memberikan hasil sepenuhnya lagi kepadamu; engkau menjadi seorang pelarian dan pengembara di bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 13, 'Kata Kain kepada TUHAN: "Hukumanku itu lebih besar dari pada yang dapat kutanggung.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 14, 'Engkau menghalau aku sekarang dari tanah ini dan aku akan tersembunyi dari hadapan-Mu, seorang pelarian dan pengembara di bumi; maka barangsiapa yang akan bertemu dengan aku, tentulah akan membunuh aku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 15, 'Firman TUHAN kepadanya: "Sekali-kali tidak! Barangsiapa yang membunuh Kain akan dibalaskan kepadanya tujuh kali lipat." Kemudian TUHAN menaruh tanda pada Kain, supaya ia jangan dibunuh oleh barangsiapapun yang bertemu dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 16, 'Lalu Kain pergi dari hadapan TUHAN dan ia menetap di tanah Nod, di sebelah timur Eden.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 17, 'Kain bersetubuh dengan isterinya dan mengandunglah perempuan itu, lalu melahirkan Henokh; kemudian Kain mendirikan suatu kota dan dinamainya kota itu Henokh, menurut nama anaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 18, 'Bagi Henokh lahirlah Irad, dan Irad itu memperanakkan Mehuyael dan Mehuyael memperanakkan Metusael, dan Metusael memperanakkan Lamekh.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 19, 'Lamekh mengambil isteri dua orang; yang satu namanya Ada, yang lain Zila.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 20, 'Ada itu melahirkan Yabal; dialah yang menjadi bapa orang yang diam dalam kemah dan memelihara ternak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 21, 'Nama adiknya ialah Yubal; dialah yang menjadi bapa semua orang yang memainkan kecapi dan suling.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 22, 'Zila juga melahirkan anak, yakni Tubal-Kain, bapa semua tukang tembaga dan tukang besi. Adik perempuan Tubal-Kain ialah Naama.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 23, 'Berkatalah Lamekh kepada kedua isterinya itu: "Ada dan Zila, dengarkanlah suaraku: hai isteri-isteri Lamekh, pasanglah telingamu kepada perkataanku ini: Aku telah membunuh seorang laki-laki karena ia melukai aku, membunuh seorang muda karena ia memukul aku sampai bengkak;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 24, 'sebab jika Kain harus dibalaskan tujuh kali lipat, maka Lamekh tujuh puluh tujuh kali lipat."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 25, 'Adam bersetubuh pula dengan isterinya, lalu perempuan itu melahirkan seorang anak laki-laki dan menamainya Set, sebab katanya: "Allah telah mengaruniakan kepadaku anak yang lain sebagai ganti Habel; sebab Kain telah membunuhnya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 4, 26, 'Lahirlah seorang anak laki-laki bagi Set juga dan anak itu dinamainya Enos. Waktu itulah orang mulai memanggil nama TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 1, 'Inilah daftar keturunan Adam. Pada waktu manusia itu diciptakan oleh Allah, dibuat-Nyalah dia menurut rupa Allah;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 2, 'laki-laki dan perempuan diciptakan-Nya mereka. Ia memberkati mereka dan memberikan nama "Manusia" kepada mereka, pada waktu mereka diciptakan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 3, 'Setelah Adam hidup seratus tiga puluh tahun, ia memperanakkan seorang laki-laki menurut rupa dan gambarnya, lalu memberi nama Set kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 4, 'Umur Adam, setelah memperanakkan Set, delapan ratus tahun, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 5, 'Jadi Adam mencapai umur sembilan ratus tiga puluh tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 6, 'Setelah Set hidup seratus lima tahun, ia memperanakkan Enos.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 7, 'Dan Set masih hidup delapan ratus tujuh tahun, setelah ia memperanakkan Enos, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 8, 'Jadi Set mencapai umur sembilan ratus dua belas tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 9, 'Setelah Enos hidup sembilan puluh tahun, ia memperanakkan Kenan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 10, 'Dan Enos masih hidup delapan ratus lima belas tahun, setelah ia memperanakkan Kenan, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 11, 'Jadi Enos mencapai umur sembilan ratus lima tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 12, 'Setelah Kenan hidup tujuh puluh tahun, ia memperanakkan Mahalaleel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 13, 'Dan Kenan masih hidup delapan ratus empat puluh tahun, setelah ia memperanakkan Mahalaleel, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 14, 'Jadi Kenan mencapai umur sembilan ratus sepuluh tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 15, 'Setelah Mahalaleel hidup enam puluh lima tahun, ia memperanakkan Yared.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 16, 'Dan Mahalaleel masih hidup delapan ratus tiga puluh tahun, setelah ia memperanakkan Yared, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 17, 'Jadi Mahalaleel mencapai umur delapan ratus sembilan puluh lima tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 18, 'Setelah Yared hidup seratus enam puluh dua tahun, ia memperanakkan Henokh.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 19, 'Dan Yared masih hidup delapan ratus tahun, setelah ia memperanakkan Henokh, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 20, 'Jadi Yared mencapai umur sembilan ratus enam puluh dua tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 21, 'Setelah Henokh hidup enam puluh lima tahun, ia memperanakkan Metusalah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 22, 'Dan Henokh hidup bergaul dengan Allah selama tiga ratus tahun lagi, setelah ia memperanakkan Metusalah, dan ia memperanakkan anak-anak lelaki dan perempuan', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 23, 'Jadi Henokh mencapai umur tiga ratus enam puluh lima tahun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 24, 'Dan Henokh hidup bergaul dengan Allah, lalu ia tidak ada lagi, sebab ia telah diangkat oleh Allah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 25, 'Setelah Metusalah hidup seratus delapan puluh tujuh tahun, ia memperanakkan Lamekh.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 26, 'Dan Metusalah masih hidup tujuh ratus delapan puluh dua tahun, setelah ia memperanakkan Lamekh, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 27, 'Jadi Metusalah mencapai umur sembilan ratus enam puluh sembilan tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 28, 'Setelah Lamekh hidup seratus delapan puluh dua tahun, ia memperanakkan seorang anak laki-laki,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 29, 'dan memberi nama Nuh kepadanya, katanya: "Anak ini akan memberi kepada kita penghiburan dalam pekerjaan kita yang penuh susah payah di tanah yang telah terkutuk oleh TUHAN."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 30, 'Dan Lamekh masih hidup lima ratus sembilan puluh lima tahun, setelah ia memperanakkan Nuh, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 31, 'Jadi Lamekh mencapai umur tujuh ratus tujuh puluh tujuh tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 5, 32, 'Setelah Nuh berumur lima ratus tahun, ia memperanakkan Sem, Ham dan Yafet.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 1, 'Ketika manusia itu mulai bertambah banyak jumlahnya di muka bumi, dan bagi mereka lahir anak-anak perempuan,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 2, 'maka anak-anak Allah melihat, bahwa anak-anak perempuan manusia itu cantik-cantik, lalu mereka mengambil isteri dari antara perempuan-perempuan itu, siapa saja yang disukai mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 3, 'Berfirmanlah TUHAN: "Roh-Ku tidak akan selama-lamanya tinggal di dalam manusia, karena manusia itu adalah daging, tetapi umurnya akan seratus dua puluh tahun saja."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 4, 'Pada waktu itu orang-orang raksasa ada di bumi, dan juga pada waktu sesudahnya, ketika anak-anak Allah menghampiri anak-anak perempuan manusia, dan perempuan-perempuan itu melahirkan anak bagi mereka; inilah orang-orang yang gagah perkasa di zaman purbakala, orang-orang yang kenamaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 5, 'Ketika dilihat TUHAN, bahwa kejahatan manusia besar di bumi dan bahwa segala kecenderungan hatinya selalu membuahkan kejahatan semata-mata,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 6, 'maka menyesallah TUHAN, bahwa Ia telah menjadikan manusia di bumi, dan hal itu memilukan hati-Nya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 7, 'Berfirmanlah TUHAN: "Aku akan menghapuskan manusia yang telah Kuciptakan itu dari muka bumi, baik manusia maupun hewan dan binatang-binatang melata dan burung-burung di udara, sebab Aku menyesal, bahwa Aku telah menjadikan mereka."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 8, 'Tetapi Nuh mendapat kasih karunia di mata TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 9, 'Inilah riwayat Nuh: Nuh adalah seorang yang benar dan tidak bercela di antara orang-orang sezamannya; dan Nuh itu hidup bergaul dengan Allah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 10, 'Nuh memperanakkan tiga orang laki-laki: Sem, Ham dan Yafet.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 11, 'Adapun bumi itu telah rusak di hadapan Allah dan penuh dengan kekerasan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 12, 'Allah menilik bumi itu dan sungguhlah rusak benar, sebab semua manusia menjalankan hidup yang rusak di bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 13, 'Berfirmanlah Allah kepada Nuh: "Aku telah memutuskan untuk mengakhiri hidup segala makhluk, sebab bumi telah penuh dengan kekerasan oleh mereka, jadi Aku akan memusnahkan mereka bersama-sama dengan bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 14, 'Buatlah bagimu sebuah bahtera dari kayu gofir; bahtera itu harus kaubuat berpetak-petak dan harus kaututup dengan pakal dari luar dan dari dalam.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 15, 'Beginilah engkau harus membuat bahtera itu: tiga ratus hasta panjangnya, lima puluh hasta lebarnya dan tiga puluh hasta tingginya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 16, 'Buatlah atap pada bahtera itu dan selesaikanlah bahtera itu sampai sehasta dari atas, dan pasanglah pintunya pada lambungnya; buatlah bahtera itu bertingkat bawah, tengah dan atas.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 17, 'Sebab sesungguhnya Aku akan mendatangkan air bah meliputi bumi untuk memusnahkan segala yang hidup dan bernyawa di kolong langit; segala yang ada di bumi akan mati binasa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 18, 'Tetapi dengan engkau Aku akan mengadakan perjanjian-Ku, dan engkau akan masuk ke dalam bahtera itu: engkau bersama-sama dengan anak-anakmu dan isterimu dan isteri anak-anakmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 19, 'Dan dari segala yang hidup, dari segala makhluk, dari semuanya haruslah engkau bawa satu pasang ke dalam bahtera itu, supaya terpelihara hidupnya bersama-sama dengan engkau; jantan dan betina harus kaubawa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 20, 'Dari segala jenis burung dan dari segala jenis hewan, dari segala jenis binatang melata di muka bumi, dari semuanya itu harus datang satu pasang kepadamu, supaya terpelihara hidupnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 21, 'Dan engkau, bawalah bagimu segala apa yang dapat dimakan; kumpulkanlah itu padamu untuk menjadi makanan bagimu dan bagi mereka."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 6, 22, 'Lalu Nuh melakukan semuanya itu; tepat seperti yang diperintahkan Allah kepadanya, demikianlah dilakukannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 1, 'Lalu berfirmanlah TUHAN kepada Nuh: "Masuklah ke dalam bahtera itu, engkau dan seisi rumahmu, sebab engkaulah yang Kulihat benar di hadapan-Ku di antara orang zaman ini.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 2, 'Dari segala binatang yang tidak haram haruslah kauambil tujuh pasang, jantan dan betinanya, tetapi dari binatang yang haram satu pasang, jantan dan betinanya;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 3, 'juga dari burung-burung di udara tujuh pasang, jantan dan betina, supaya terpelihara hidup keturunannya di seluruh bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 4, 'Sebab tujuh hari lagi Aku akan menurunkan hujan ke atas bumi empat puluh hari empat puluh malam lamanya, dan Aku akan menghapuskan dari muka bumi segala yang ada, yang Kujadikan itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 5, 'Lalu Nuh melakukan segala yang diperintahkan TUHAN kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 6, 'Nuh berumur enam ratus tahun, ketika air bah datang meliputi bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 7, 'Masuklah Nuh ke dalam bahtera itu bersama-sama dengan anak-anaknya dan isterinya dan isteri anak-anaknya karena air bah itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 8, 'Dari binatang yang tidak haram dan yang haram, dari burung-burung dan dari segala yang merayap di muka bumi,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 9, 'datanglah sepasang mendapatkan Nuh ke dalam bahtera itu, jantan dan betina, seperti yang diperintahkan Allah kepada Nuh.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 10, 'Setelah tujuh hari datanglah air bah meliputi bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 11, 'Pada waktu umur Nuh enam ratus tahun, pada bulan yang kedua, pada hari yang ketujuh belas bulan itu, pada hari itulah terbelah segala mata air samudera raya yang dahsyat dan terbukalah tingkap-tingkap di langit.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 12, 'Dan turunlah hujan lebat meliputi bumi empat puluh hari empat puluh malam lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 13, 'Pada hari itu juga masuklah Nuh serta Sem, Ham dan Yafet, anak-anak Nuh, dan isteri Nuh, dan ketiga isteri anak-anaknya bersama-sama dengan dia, ke dalam bahtera itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 14, 'mereka itu dan segala jenis binatang liar dan segala jenis ternak dan segala jenis binatang melata yang merayap di bumi dan segala jenis burung, yakni segala yang berbulu bersayap;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 15, 'dari segala yang hidup dan bernyawa datanglah sepasang mendapatkan Nuh ke dalam bahtera itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 16, 'Dan yang masuk itu adalah jantan dan betina dari segala yang hidup, seperti yang diperintahkan Allah kepada Nuh; lalu TUHAN menutup pintu bahtera itu di belakang Nuh.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 17, 'Empat puluh hari lamanya air bah itu meliputi bumi; air itu naik dan mengangkat bahtera itu, sehingga melampung tinggi dari bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 18, 'Ketika air itu makin bertambah-tambah dan naik dengan hebatnya di atas bumi, terapung-apunglah bahtera itu di muka air.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 19, 'Dan air itu sangat hebatnya bertambah-tambah meliputi bumi, dan ditutupinyalah segala gunung tinggi di seluruh kolong langit,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 20, 'sampai lima belas hasta di atasnya bertambah-tambah air itu, sehingga gunung-gunung ditutupinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 21, 'Lalu mati binasalah segala yang hidup, yang bergerak di bumi, burung-burung, ternak dan binatang liar dan segala binatang merayap, yang berkeriapan di bumi, serta semua manusia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 22, 'Matilah segala yang ada nafas hidup dalam hidungnya, segala yang ada di darat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 23, 'Demikianlah dihapuskan Allah segala yang ada, segala yang di muka bumi, baik manusia maupun hewan dan binatang melata dan burung-burung di udara, sehingga semuanya itu dihapuskan dari atas bumi; hanya Nuh yang tinggal hidup dan semua yang bersama-sama dengan dia dalam bahtera itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 7, 24, 'Dan berkuasalah air itu di atas bumi seratus lima puluh hari lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 1, 'Maka Allah mengingat Nuh dan segala binatang liar dan segala ternak, yang bersama-sama dengan dia dalam bahtera itu, dan Allah membuat angin menghembus melalui bumi, sehingga air itu turun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 2, 'Ditutuplah mata-mata air samudera raya serta tingkap-tingkap di langit dan berhentilah hujan lebat dari langit,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 3, 'dan makin surutlah air itu dari muka bumi. Demikianlah berkurang air itu sesudah seratus lima puluh hari.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 4, 'Dalam bulan yang ketujuh, pada hari yang ketujuh belas bulan itu, terkandaslah bahtera itu pada pegunungan Ararat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 5, 'Sampai bulan yang kesepuluh makin berkuranglah air itu; dalam bulan yang kesepuluh, pada tanggal satu bulan itu, tampaklah puncak-puncak gunung.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 6, 'Sesudah lewat empat puluh hari, maka Nuh membuka tingkap yang dibuatnya pada bahtera itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 7, 'Lalu ia melepaskan seekor burung gagak; dan burung itu terbang pulang pergi, sampai air itu menjadi kering dari atas bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 8, 'Kemudian dilepaskannya seekor burung merpati untuk melihat, apakah air itu telah berkurang dari muka bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 9, 'Tetapi burung merpati itu tidak mendapat tempat tumpuan kakinya dan pulanglah ia kembali mendapatkan Nuh ke dalam bahtera itu, karena di seluruh bumi masih ada air; lalu Nuh mengulurkan tangannya, ditangkapnya burung itu dan dibawanya masuk ke dalam bahtera.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 10, 'Ia menunggu tujuh hari lagi, kemudian dilepaskannya pula burung merpati itu dari bahtera;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 11, 'menjelang waktu senja pulanglah burung merpati itu mendapatkan Nuh, dan pada paruhnya dibawanya sehelai daun zaitun yang segar. Dari situlah diketahui Nuh, bahwa air itu telah berkurang dari atas bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 12, 'Selanjutnya ditunggunya pula tujuh hari lagi, kemudian dilepaskannya burung merpati itu, tetapi burung itu tidak kembali lagi kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 13, 'Dalam tahun keenam ratus satu, dalam bulan pertama, pada tanggal satu bulan itu, sudahlah kering air itu dari atas bumi; kemudian Nuh membuka tutup bahtera itu dan melihat-lihat; ternyatalah muka bumi sudah mulai kering.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 14, 'Dalam bulan kedua, pada hari yang kedua puluh tujuh bulan itu, bumi telah kering.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 15, 'Lalu berfirmanlah Allah kepada Nuh:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 16, '"Keluarlah dari bahtera itu, engkau bersama-sama dengan isterimu serta anak-anakmu dan isteri anak-anakmu;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 17, 'segala binatang yang bersama-sama dengan engkau, segala yang hidup: burung-burung, hewan dan segala binatang melata yang merayap di bumi, suruhlah keluar bersama-sama dengan engkau, supaya semuanya itu berkeriapan di bumi serta berkembang biak dan bertambah banyak di bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 18, 'Lalu keluarlah Nuh bersama-sama dengan anak-anaknya dan isterinya dan isteri anak-anaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 19, 'Segala binatang liar, segala binatang melata dan segala burung, semuanya yang bergerak di bumi, masing-masing menurut jenisnya, keluarlah juga dari bahtera itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 20, 'Lalu Nuh mendirikan mezbah bagi TUHAN; dari segala binatang yang tidak haram dan dari segala burung yang tidak haram diambilnyalah beberapa ekor, lalu ia mempersembahkan korban bakaran di atas mezbah itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 21, 'Ketika TUHAN mencium persembahan yang harum itu, berfirmanlah TUHAN dalam hati-Nya: "Aku takkan mengutuk bumi ini lagi karena manusia, sekalipun yang ditimbulkan hatinya adalah jahat dari sejak kecilnya, dan Aku takkan membinasakan lagi segala yang hidup seperti yang telah Kulakukan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 8, 22, 'Selama bumi masih ada, takkan berhenti-henti musim menabur dan menuai, dingin dan panas, kemarau dan hujan, siang dan malam."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 1, 'Lalu Allah memberkati Nuh dan anak-anaknya serta berfirman kepada mereka: "Beranakcuculah dan bertambah banyaklah serta penuhilah bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 2, 'Akan takut dan akan gentar kepadamu segala binatang di bumi dan segala burung di udara, segala yang bergerak di muka bumi dan segala ikan di laut; ke dalam tanganmulah semuanya itu diserahkan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 3, 'Segala yang bergerak, yang hidup, akan menjadi makananmu. Aku telah memberikan semuanya itu kepadamu seperti juga tumbuh-tumbuhan hijau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 4, 'Hanya daging yang masih ada nyawanya, yakni darahnya, janganlah kamu makan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 5, 'Tetapi mengenai darah kamu, yakni nyawa kamu, Aku akan menuntut balasnya; dari segala binatang Aku akan menuntutnya, dan dari setiap manusia Aku akan menuntut nyawa sesama manusia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 6, 'Siapa yang menumpahkan darah manusia, darahnya akan tertumpah oleh manusia, sebab Allah membuat manusia itu menurut gambar-Nya sendiri.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 7, 'Dan kamu, beranakcuculah dan bertambah banyak, sehingga tak terbilang jumlahmu di atas bumi, ya, bertambah banyaklah di atasnya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 8, 'Berfirmanlah Allah kepada Nuh dan kepada anak-anaknya yang bersama-sama dengan dia:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 9, '"Sesungguhnya Aku mengadakan perjanjian-Ku dengan kamu dan dengan keturunanmu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 10, 'dan dengan segala makhluk hidup yang bersama-sama dengan kamu: burung-burung, ternak dan binatang-binatang liar di bumi yang bersama-sama dengan kamu, segala yang keluar dari bahtera itu, segala binatang di bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 11, 'Maka Kuadakan perjanjian-Ku dengan kamu, bahwa sejak ini tidak ada yang hidup yang akan dilenyapkan oleh air bah lagi, dan tidak akan ada lagi air bah untuk memusnahkan bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 12, 'Dan Allah berfirman: "Inilah tanda perjanjian yang Kuadakan antara Aku dan kamu serta segala makhluk yang hidup, yang bersama-sama dengan kamu, turun-temurun, untuk selama-lamanya:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 13, 'Busur-Ku Kutaruh di awan, supaya itu menjadi tanda perjanjian antara Aku dan bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 14, 'Apabila kemudian Kudatangkan awan di atas bumi dan busur itu tampak di awan,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 15, 'maka Aku akan mengingat perjanjian-Ku yang telah ada antara Aku dan kamu serta segala makhluk yang hidup, segala yang bernyawa, sehingga segenap air tidak lagi menjadi air bah untuk memusnahkan segala yang hidup.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 16, 'Jika busur itu ada di awan, maka Aku akan melihatnya, sehingga Aku mengingat perjanjian-Ku yang kekal antara Allah dan segala makhluk yang hidup, segala makhluk yang ada di bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 17, 'Berfirmanlah Allah kepada Nuh: "Inilah tanda perjanjian yang Kuadakan antara Aku dan segala makhluk yang ada di bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 18, 'Anak-anak Nuh yang keluar dari bahtera ialah Sem, Ham dan Yafet; Ham adalah bapa Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 19, 'Yang tiga inilah anak-anak Nuh, dan dari mereka inilah tersebar penduduk seluruh bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 20, 'Nuh menjadi petani; dialah yang mula-mula membuat kebun anggur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 21, 'Setelah ia minum anggur, mabuklah ia dan ia telanjang dalam kemahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 22, 'Maka Ham, bapa Kanaan itu, melihat aurat ayahnya, lalu diceritakannya kepada kedua saudaranya di luar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 23, 'Sesudah itu Sem dan Yafet mengambil sehelai kain dan membentangkannya pada bahu mereka berdua, lalu mereka berjalan mundur; mereka menutupi aurat ayahnya sambil berpaling muka, sehingga mereka tidak melihat aurat ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 24, 'Setelah Nuh sadar dari mabuknya dan mendengar apa yang dilakukan anak bungsunya kepadanya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 25, 'berkatalah ia: "Terkutuklah Kanaan, hendaklah ia menjadi hamba yang paling hina bagi saudara-saudaranya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 26, 'Lagi katanya: "Terpujilah TUHAN, Allah Sem, tetapi hendaklah Kanaan menjadi hamba baginya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 27, 'Allah meluaskan kiranya tempat kediaman Yafet, dan hendaklah ia tinggal dalam kemah-kemah Sem, tetapi hendaklah Kanaan menjadi hamba baginya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 28, 'Nuh masih hidup tiga ratus lima puluh tahun sesudah air bah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 9, 29, 'Jadi Nuh mencapai umur sembilan ratus lima puluh tahun, lalu ia mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 1, 'Inilah keturunan Sem, Ham dan Yafet, anak-anak Nuh. Setelah air bah itu lahirlah anak-anak lelaki bagi mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 2, 'Keturunan Yafet ialah Gomer, Magog, Madai, Yawan, Tubal, Mesekh dan Tiras.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 3, 'Keturunan Gomer ialah Askenas, Rifat dan Togarma.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 4, 'Keturunan Yawan ialah Elisa, Tarsis, orang Kitim dan orang Dodanim.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 5, 'Dari mereka inilah berpencar bangsa-bangsa daerah pesisir. Itulah keturunan Yafet, masing-masing di tanahnya, dengan bahasanya sendiri, menurut kaum dan bangsa mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 6, 'Keturunan Ham ialah Kush, Misraim, Put dan Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 7, 'Keturunan Kush ialah Seba, Hawila, Sabta, Raema dan Sabtekha; anak-anak Raema ialah Syeba dan Dedan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 8, 'Kush memperanakkan Nimrod; dialah yang mula-mula sekali orang yang berkuasa di bumi;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 9, 'ia seorang pemburu yang gagah perkasa di hadapan TUHAN, sebab itu dikatakan orang: "Seperti Nimrod, seorang pemburu yang gagah perkasa di hadapan TUHAN."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 10, 'Mula-mula kerajaannya terdiri dari Babel, Erekh, dan Akad, semuanya di tanah Sinear.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 11, 'Dari negeri itu ia pergi ke Asyur, lalu mendirikan Niniwe, Rehobot-Ir, Kalah', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 12, 'dan Resen di antara Niniwe dan Kalah; itulah kota besar itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 13, 'Misraim memperanakkan orang Ludim, orang Anamim, orang Lehabim, orang Naftuhim,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 14, 'orang Patrusim, orang Kasluhim dan orang Kaftorim; dari mereka inilah berasal orang Filistin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 15, 'Kanaan memperanakkan Sidon, anak sulungnya, dan Het,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 16, 'serta orang Yebusi, orang Amori dan orang Girgasi;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 17, 'orang Hewi, orang Arki, orang Sini,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 18, 'orang Arwadi, orang Semari dan orang Hamati; kemudian berseraklah kaum-kaum orang Kanaan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 19, 'Daerah orang Kanaan adalah dari Sidon ke arah Gerar sampai ke Gaza, ke arah Sodom, Gomora, Adma dan Zeboim sampai ke Lasa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 20, 'Itulah keturunan Ham menurut kaum mereka, menurut bahasa mereka, menurut tanah mereka, menurut bangsa mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 21, 'Lahirlah juga anak-anak bagi Sem, bapa semua anak Eber serta abang Yafet.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 22, 'Keturunan Sem ialah Elam, Asyur, Arpakhsad, Lud dan Aram.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 23, 'Keturunan Aram ialah Us, Hul, Geter dan Mas.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 24, 'Arpakhsad memperanakkan Selah, dan Selah memperanakkan Eber.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 25, 'Bagi Eber lahir dua anak laki-laki; nama yang seorang ialah Peleg, sebab dalam zamannya bumi terbagi, dan nama adiknya ialah Yoktan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 26, 'Yoktan memperanakkan Almodad, Selef, Hazar-Mawet dan Yerah,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 27, 'Hadoram, Uzal dan Dikla,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 28, 'Obal, Abimael dan Syeba,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 29, 'Ofir, Hawila dan Yobab; itulah semuanya keturunan Yoktan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 30, 'Daerah kediaman mereka terbentang dari Mesa ke arah Sefar, yaitu pegunungan di sebelah timur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 31, 'Itulah keturunan Sem, menurut kaum mereka, menurut bahasa mereka, menurut tanah mereka, menurut bangsa mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 10, 32, 'Itulah segala kaum anak-anak Nuh menurut keturunan mereka, menurut bangsa mereka. Dan dari mereka itulah berpencar bangsa-bangsa di bumi setelah air bah itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 1, 'Adapun seluruh bumi, satu bahasanya dan satu logatnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 2, 'Maka berangkatlah mereka ke sebelah timur dan menjumpai tanah datar di tanah Sinear, lalu menetaplah mereka di sana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 3, 'Mereka berkata seorang kepada yang lain: "Marilah kita membuat batu bata dan membakarnya baik-baik." Lalu bata itulah dipakai mereka sebagai batu dan ter gala-gala sebagai tanah liat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 4, 'Juga kata mereka: "Marilah kita dirikan bagi kita sebuah kota dengan sebuah menara yang puncaknya sampai ke langit, dan marilah kita cari nama, supaya kita jangan terserak ke seluruh bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 5, 'Lalu turunlah TUHAN untuk melihat kota dan menara yang didirikan oleh anak-anak manusia itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 6, 'dan Ia berfirman: "Mereka ini satu bangsa dengan satu bahasa untuk semuanya. Ini barulah permulaan usaha mereka; mulai dari sekarang apapun juga yang mereka rencanakan, tidak ada yang tidak akan dapat terlaksana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 7, 'Baiklah Kita turun dan mengacaubalaukan di sana bahasa mereka, sehingga mereka tidak mengerti lagi bahasa masing-masing."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 8, 'Demikianlah mereka diserakkan TUHAN dari situ ke seluruh bumi, dan mereka berhenti mendirikan kota itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 9, 'Itulah sebabnya sampai sekarang nama kota itu disebut Babel, karena di situlah dikacaubalaukan TUHAN bahasa seluruh bumi dan dari situlah mereka diserakkan TUHAN ke seluruh bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 10, 'Inilah keturunan Sem. Setelah Sem berumur seratus tahun, ia memperanakkan Arpakhsad, dua tahun setelah air bah itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 11, 'Sem masih hidup lima ratus tahun, setelah ia memperanakkan Arpakhsad, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 12, 'Setelah Arpakhsad hidup tiga puluh lima tahun, ia memperanakkan Selah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 13, 'Arpakhsad masih hidup empat ratus tiga tahun, setelah ia memperanakkan Selah, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 14, 'Setelah Selah hidup tiga puluh tahun, ia memperanakkan Eber.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 15, 'Selah masih hidup empat ratus tiga tahun, setelah ia memperanakkan Eber, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 16, 'Setelah Eber hidup tiga puluh empat tahun, ia memperanakkan Peleg.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 17, 'Eber masih hidup empat ratus tiga puluh tahun, setelah ia memperanakkan Peleg, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 18, 'Setelah Peleg hidup tiga puluh tahun, ia memperanakkan Rehu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 19, 'Peleg masih hidup dua ratus sembilan tahun, setelah ia memperanakkan Rehu, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 20, 'Setelah Rehu hidup tiga puluh dua tahun, ia memperanakkan Serug.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 21, 'Rehu masih hidup dua ratus tujuh tahun, setelah ia memperanakkan Serug, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 22, 'Setelah Serug hidup tiga puluh tahun, ia memperanakkan Nahor.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 23, 'Serug masih hidup dua ratus tahun, setelah ia memperanakkan Nahor, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 24, 'Setelah Nahor hidup dua puluh sembilan tahun, ia memperanakkan Terah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 25, 'Nahor masih hidup seratus sembilan belas tahun, setelah ia memperanakkan Terah, dan ia memperanakkan anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 26, 'Setelah Terah hidup tujuh puluh tahun, ia memperanakkan Abram, Nahor dan Haran.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 27, 'Inilah keturunan Terah. Terah memperanakkan Abram, Nahor dan Haran, dan Haran memperanakkan Lot.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 28, 'Ketika Terah, ayahnya, masih hidup, matilah Haran di negeri kelahirannya, di Ur-Kasdim.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 29, 'Abram dan Nahor kedua-duanya kawin; nama isteri Abram ialah Sarai, dan nama isteri Nahor ialah Milka, anak Haran ayah Milka dan Yiska.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 30, 'Sarai itu mandul, tidak mempunyai anak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 31, 'Lalu Terah membawa Abram, anaknya, serta cucunya, Lot, yaitu anak Haran, dan Sarai, menantunya, isteri Abram, anaknya; ia berangkat bersama-sama dengan mereka dari Ur-Kasdim untuk pergi ke tanah Kanaan, lalu sampailah mereka ke Haran, dan menetap di sana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 11, 32, 'Umur Terah ada dua ratus lima tahun; lalu ia mati di Haran.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 1, 'Berfirmanlah TUHAN kepada Abram: "Pergilah dari negerimu dan dari sanak saudaramu dan dari rumah bapamu ini ke negeri yang akan Kutunjukkan kepadamu;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 2, 'Aku akan membuat engkau menjadi bangsa yang besar, dan memberkati engkau serta membuat namamu masyhur; dan engkau akan menjadi berkat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 3, 'Aku akan memberkati orang-orang yang memberkati engkau, dan mengutuk orang-orang yang mengutuk engkau, dan olehmu semua kaum di muka bumi akan mendapat berkat."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 4, 'Lalu pergilah Abram seperti yang difirmankan TUHAN kepadanya, dan Lotpun ikut bersama-sama dengan dia; Abram berumur tujuh puluh lima tahun, ketika ia berangkat dari Haran.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 5, 'Abram membawa Sarai, isterinya, dan Lot, anak saudaranya, dan segala harta benda yang didapat mereka dan orang-orang yang diperoleh mereka di Haran; mereka berangkat ke tanah Kanaan, lalu sampai di situ.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 6, 'Abram berjalan melalui negeri itu sampai ke suatu tempat dekat Sikhem, yakni pohon tarbantin di More. Waktu itu orang Kanaan diam di negeri itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 7, 'Ketika itu TUHAN menampakkan diri kepada Abram dan berfirman: "Aku akan memberikan negeri ini kepada keturunanmu." Maka didirikannya di situ mezbah bagi TUHAN yang telah menampakkan diri kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 8, 'Kemudian ia pindah dari situ ke pegunungan di sebelah timur Betel. Ia memasang kemahnya dengan Betel di sebelah barat dan Ai di sebelah timur, lalu ia mendirikan di situ mezbah bagi TUHAN dan memanggil nama TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 9, 'Sesudah itu Abram berangkat dan makin jauh ia berjalan ke Tanah Negeb.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 10, 'Ketika kelaparan timbul di negeri itu, pergilah Abram ke Mesir untuk tinggal di situ sebagai orang asing, sebab hebat kelaparan di negeri itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 11, 'Pada waktu ia akan masuk ke Mesir, berkatalah ia kepada Sarai, isterinya: "Memang aku tahu, bahwa engkau adalah seorang perempuan yang cantik parasnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 12, 'Apabila orang Mesir melihat engkau, mereka akan berkata: Itu isterinya. Jadi mereka akan membunuh aku dan membiarkan engkau hidup.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 13, 'Katakanlah, bahwa engkau adikku, supaya aku diperlakukan mereka dengan baik karena engkau, dan aku dibiarkan hidup oleh sebab engkau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 14, 'Sesudah Abram masuk ke Mesir, orang Mesir itu melihat, bahwa perempuan itu sangat cantik,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 15, 'dan ketika punggawa-punggawa Firaun melihat Sarai, mereka memuji-mujinya di hadapan Firaun, sehingga perempuan itu dibawa ke istananya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 16, 'Firaun menyambut Abram dengan baik-baik, karena ia mengingini perempuan itu, dan Abram mendapat kambing domba, lembu sapi, keledai jantan, budak laki-laki dan perempuan, keledai betina dan unta.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 17, 'Tetapi TUHAN menimpakan tulah yang hebat kepada Firaun, demikian juga kepada seisi istananya, karena Sarai, isteri Abram itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 18, 'Lalu Firaun memanggil Abram serta berkata: "Apakah yang kauperbuat ini terhadap aku? Mengapa tidak kauberitahukan, bahwa ia isterimu?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 19, 'Mengapa engkau katakan: dia adikku, sehingga aku mengambilnya menjadi isteriku? Sekarang, inilah isterimu, ambillah dan pergilah!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 12, 20, 'Lalu Firaun memerintahkan beberapa orang untuk mengantarkan Abram pergi, bersama-sama dengan isterinya dan segala kepunyaannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 1, 'Maka pergilah Abram dari Mesir ke Tanah Negeb dengan isterinya dan segala kepunyaannya, dan Lotpun bersama-sama dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 2, 'Adapun Abram sangat kaya, banyak ternak, perak dan emasnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 3, 'Ia berjalan dari tempat persinggahan ke tempat persinggahan, dari Tanah Negeb sampai dekat Betel, di mana kemahnya mula-mula berdiri, antara Betel dan Ai,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 4, 'ke tempat mezbah yang dibuatnya dahulu di sana; di situlah Abram memanggil nama TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 5, 'Juga Lot, yang ikut bersama-sama dengan Abram, mempunyai domba dan lembu dan kemah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 6, 'Tetapi negeri itu tidak cukup luas bagi mereka untuk diam bersama-sama, sebab harta milik mereka amat banyak, sehingga mereka tidak dapat diam bersama-sama.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 7, 'Karena itu terjadilah perkelahian antara para gembala Abram dan para gembala Lot. Waktu itu orang Kanaan dan orang Feris diam di negeri itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 8, 'Maka berkatalah Abram kepada Lot: "Janganlah kiranya ada perkelahian antara aku dan engkau, dan antara para gembalaku dan para gembalamu, sebab kita ini kerabat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 9, 'Bukankah seluruh negeri ini terbuka untuk engkau? Baiklah pisahkan dirimu dari padaku; jika engkau ke kiri, maka aku ke kanan, jika engkau ke kanan, maka aku ke kiri."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 10, 'Lalu Lot melayangkan pandangnya dan dilihatnyalah, bahwa seluruh Lembah Yordan banyak airnya, seperti taman TUHAN, seperti tanah Mesir, sampai ke Zoar. ?Hal itu terjadi sebelum TUHAN memusnahkan Sodom dan Gomora. ?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 11, 'Sebab itu Lot memilih baginya seluruh Lembah Yordan itu, lalu ia berangkat ke sebelah timur dan mereka berpisah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 12, 'Abram menetap di tanah Kanaan, tetapi Lot menetap di kota-kota Lembah Yordan dan berkemah di dekat Sodom.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 13, 'Adapun orang Sodom sangat jahat dan berdosa terhadap TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 14, 'Setelah Lot berpisah dari pada Abram, berfirmanlah TUHAN kepada Abram: "Pandanglah sekelilingmu dan lihatlah dari tempat engkau berdiri itu ke timur dan barat, utara dan selatan,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 15, 'sebab seluruh negeri yang kaulihat itu akan Kuberikan kepadamu dan kepada keturunanmu untuk selama-lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 16, 'Dan Aku akan menjadikan keturunanmu seperti debu tanah banyaknya, sehingga, jika seandainya ada yang dapat menghitung debu tanah, keturunanmupun akan dapat dihitung juga.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 17, 'Bersiaplah, jalanilah negeri itu menurut panjang dan lebarnya, sebab kepadamulah akan Kuberikan negeri itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 13, 18, 'Sesudah itu Abram memindahkan kemahnya dan menetap di dekat pohon-pohon tarbantin di Mamre, dekat Hebron, lalu didirikannyalah mezbah di situ bagi TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 1, 'Pada zaman Amrafel, raja Sinear, Ariokh, raja Elasar, Kedorlaomer, raja Elam, dan Tideal, raja Goyim, terjadilah,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 2, 'bahwa raja-raja ini berperang melawan Bera, raja Sodom, Birsya, raja Gomora, Syinab, raja Adma, Syemeber, raja Zeboim dan raja negeri Bela, yakni negeri Zoar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 3, 'Raja-raja yang disebut terakhir ini semuanya bersekutu dan datang ke lembah Sidim, yakni Laut Asin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 4, 'Dua belas tahun lamanya mereka takluk kepada Kedorlaomer, tetapi dalam tahun yang ketiga belas mereka memberontak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 5, 'Dalam tahun yang keempat belas datanglah Kedorlaomer serta raja-raja yang bersama-sama dengan dia, lalu mereka mengalahkan orang Refaim di Asyterot-Karnaim, orang Zuzim di Ham, orang Emim di Syawe-Kiryataim', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 6, 'dan orang Hori di pegunungan mereka yang bernama Seir, sampai ke El-Paran di tepi padang gurun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 7, 'Sesudah itu baliklah mereka dan sampai ke En-Mispat, yakni Kadesh, dan mengalahkan seluruh daerah orang Amalek, dan juga orang Amori, yang diam di Hazezon-Tamar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 8, 'Lalu keluarlah raja negeri Sodom, raja negeri Gomora, raja negeri Adma, raja negeri Zeboim dan raja negeri Bela, yakni negeri Zoar, dan mengatur barisan perangnya melawan mereka di lembah Sidim,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 9, 'melawan Kedorlaomer, raja Elam, Tideal, raja Goyim, Amrafel, raja Sinear, dan Ariokh, raja Elasar, empat raja lawan lima.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 10, 'Di lembah Sidim itu di mana-mana ada sumur aspal. Ketika raja Sodom dan raja Gomora melarikan diri, jatuhlah mereka ke dalamnya, dan orang-orang yang masih tinggal hidup melarikan diri ke pegunungan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 11, 'Segala harta benda Sodom dan Gomora beserta segala bahan makanan dirampas musuh, lalu mereka pergi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 12, 'Juga Lot, anak saudara Abram, beserta harta bendanya, dibawa musuh, lalu mereka pergi?sebab Lot itu diam di Sodom.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 13, 'Kemudian datanglah seorang pelarian dan menceritakan hal ini kepada Abram, orang Ibrani itu, yang tinggal dekat pohon-pohon tarbantin kepunyaan Mamre, orang Amori itu, saudara Eskol dan Aner, yakni teman-teman sekutu Abram.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 14, 'Ketika Abram mendengar, bahwa anak saudaranya tertawan, maka dikerahkannyalah orang-orangnya yang terlatih, yakni mereka yang lahir di rumahnya, tiga ratus delapan belas orang banyaknya, lalu mengejar musuh sampai ke Dan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 15, 'Dan pada waktu malam berbagilah mereka, ia dan hamba-hambanya itu, untuk melawan musuh; mereka mengalahkan dan mengejar musuh sampai ke Hoba di sebelah utara Damsyik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 16, 'Dibawanyalah kembali segala harta benda itu; juga Lot, anak saudaranya itu, serta harta bendanya dibawanya kembali, demikian juga perempuan-perempuan dan orang-orangnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 17, 'Setelah Abram kembali dari mengalahkan Kedorlaomer dan para raja yang bersama-sama dengan dia, maka keluarlah raja Sodom menyongsong dia ke lembah Syawe, yakni Lembah Raja.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 18, 'Melkisedek, raja Salem, membawa roti dan anggur; ia seorang imam Allah Yang Mahatinggi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 19, 'Lalu ia memberkati Abram, katanya: "Diberkatilah kiranya Abram oleh Allah Yang Mahatinggi, Pencipta langit dan bumi,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 20, 'dan terpujilah Allah Yang Mahatinggi, yang telah menyerahkan musuhmu ke tanganmu." Lalu Abram memberikan kepadanya sepersepuluh dari semuanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 21, 'Berkatalah raja Sodom itu kepada Abram: "Berikanlah kepadaku orang-orang itu, dan ambillah untukmu harta benda itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 22, 'Tetapi kata Abram kepada raja negeri Sodom itu: "Aku bersumpah demi TUHAN, Allah Yang Mahatinggi, Pencipta langit dan bumi:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 23, 'Aku tidak akan mengambil apa-apa dari kepunyaanmu itu, sepotong benang atau tali kasutpun tidak, supaya engkau jangan dapat berkata: Aku telah membuat Abram menjadi kaya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 14, 24, 'Kalau aku, jangan sekali-kali! Hanya apa yang telah dimakan oleh bujang-bujang ini dan juga bagian orang-orang yang pergi bersama-sama dengan aku, yakni Aner, Eskol dan Mamre, biarlah mereka itu mengambil bagiannya masing-masing."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 1, 'Kemudian datanglah firman TUHAN kepada Abram dalam suatu penglihatan: "Janganlah takut, Abram, Akulah perisaimu; upahmu akan sangat besar."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 2, 'Abram menjawab: "Ya Tuhan ALLAH, apakah yang akan Engkau berikan kepadaku, karena aku akan meninggal dengan tidak mempunyai anak, dan yang akan mewarisi rumahku ialah Eliezer, orang Damsyik itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 3, 'Lagi kata Abram: "Engkau tidak memberikan kepadaku keturunan, sehingga seorang hambaku nanti menjadi ahli warisku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 4, 'Tetapi datanglah firman TUHAN kepadanya, demikian: "Orang ini tidak akan menjadi ahli warismu, melainkan anak kandungmu, dialah yang akan menjadi ahli warismu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 5, 'Lalu TUHAN membawa Abram ke luar serta berfirman: "Coba lihat ke langit, hitunglah bintang-bintang, jika engkau dapat menghitungnya." Maka firman-Nya kepadanya: "Demikianlah banyaknya nanti keturunanmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 6, 'Lalu percayalah Abram kepada TUHAN, maka TUHAN memperhitungkan hal itu kepadanya sebagai kebenaran.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 7, 'Lagi firman TUHAN kepadanya: "Akulah TUHAN, yang membawa engkau keluar dari Ur-Kasdim untuk memberikan negeri ini kepadamu menjadi milikmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 8, 'Kata Abram: "Ya Tuhan ALLAH, dari manakah aku tahu, bahwa aku akan memilikinya?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 9, 'Firman TUHAN kepadanya: "Ambillah bagi-Ku seekor lembu betina berumur tiga tahun, seekor kambing betina berumur tiga tahun, seekor domba jantan berumur tiga tahun, seekor burung tekukur dan seekor anak burung merpati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 10, 'Diambilnyalah semuanya itu bagi TUHAN, dipotong dua, lalu diletakkannya bagian-bagian itu yang satu di samping yang lain, tetapi burung-burung itu tidak dipotong dua.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 11, 'Ketika burung-burung buas hinggap pada daging binatang-binatang itu, maka Abram mengusirnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 12, 'Menjelang matahari terbenam, tertidurlah Abram dengan nyenyak. Lalu turunlah meliputinya gelap gulita yang mengerikan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 13, 'Firman TUHAN kepada Abram: "Ketahuilah dengan sesungguhnya bahwa keturunanmu akan menjadi orang asing dalam suatu negeri, yang bukan kepunyaan mereka, dan bahwa mereka akan diperbudak dan dianiaya, empat ratus tahun lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 14, 'Tetapi bangsa yang akan memperbudak mereka, akan Kuhukum, dan sesudah itu mereka akan keluar dengan membawa harta benda yang banyak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 15, 'Tetapi engkau akan pergi kepada nenek moyangmu dengan sejahtera; engkau akan dikuburkan pada waktu telah putih rambutmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 16, 'Tetapi keturunan yang keempat akan kembali ke sini, sebab sebelum itu kedurjanaan orang Amori itu belum genap."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 17, 'Ketika matahari telah terbenam, dan hari menjadi gelap, maka kelihatanlah perapian yang berasap beserta suluh yang berapi lewat di antara potongan-potongan daging itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 18, 'Pada hari itulah TUHAN mengadakan perjanjian dengan Abram serta berfirman: "Kepada keturunanmulah Kuberikan negeri ini, mulai dari sungai Mesir sampai ke sungai yang besar itu, sungai Efrat:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 19, 'yakni tanah orang Keni, orang Kenas, orang Kadmon,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 20, 'orang Het, orang Feris, orang Refaim,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 15, 21, 'orang Amori, orang Kanaan, orang Girgasi dan orang Yebus itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 1, 'Adapun Sarai, isteri Abram itu, tidak beranak. Ia mempunyai seorang hamba perempuan, orang Mesir, Hagar namanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 2, 'Berkatalah Sarai kepada Abram: "Engkau tahu, TUHAN tidak memberi aku melahirkan anak. Karena itu baiklah hampiri hambaku itu; mungkin oleh dialah aku dapat memperoleh seorang anak." Dan Abram mendengarkan perkataan Sarai.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 3, 'Jadi Sarai, isteri Abram itu, mengambil Hagar, hambanya, orang Mesir itu, ?yakni ketika Abram telah sepuluh tahun tinggal di tanah Kanaan?,lalu memberikannya kepada Abram, suaminya, untuk menjadi isterinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 4, 'Abram menghampiri Hagar, lalu mengandunglah perempuan itu. Ketika Hagar tahu, bahwa ia mengandung, maka ia memandang rendah akan nyonyanya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 5, 'Lalu berkatalah Sarai kepada Abram: "Penghinaan yang kuderita ini adalah tanggung jawabmu; akulah yang memberikan hambaku ke pangkuanmu, tetapi baru saja ia tahu, bahwa ia mengandung, ia memandang rendah akan aku; TUHAN kiranya yang menjadi Hakim antara aku dan engkau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 6, 'Kata Abram kepada Sarai: "Hambamu itu di bawah kekuasaanmu; perbuatlah kepadanya apa yang kaupandang baik." Lalu Sarai menindas Hagar, sehingga ia lari meninggalkannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 7, 'Lalu Malaikat TUHAN menjumpainya dekat suatu mata air di padang gurun, yakni dekat mata air di jalan ke Syur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 8, 'Katanya: "Hagar, hamba Sarai, dari manakah datangmu dan ke manakah pergimu?" Jawabnya: "Aku lari meninggalkan Sarai, nyonyaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 9, 'Lalu kata Malaikat TUHAN itu kepadanya: "Kembalilah kepada nyonyamu, biarkanlah engkau ditindas di bawah kekuasaannya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 10, 'Lagi kata Malaikat TUHAN itu kepadanya: "Aku akan membuat sangat banyak keturunanmu, sehingga tidak dapat dihitung karena banyaknya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 11, 'Selanjutnya kata Malaikat TUHAN itu kepadanya: "Engkau mengandung dan akan melahirkan seorang anak laki-laki dan akan menamainya Ismael, sebab TUHAN telah mendengar tentang penindasan atasmu itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 12, 'Seorang laki-laki yang lakunya seperti keledai liar, demikianlah nanti anak itu; tangannya akan melawan tiap-tiap orang dan tangan tiap-tiap orang akan melawan dia, dan di tempat kediamannya ia akan menentang semua saudaranya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 13, 'Kemudian Hagar menamakan TUHAN yang telah berfirman kepadanya itu dengan sebutan: "Engkaulah El-Roi." Sebab katanya: "Bukankah di sini kulihat Dia yang telah melihat aku?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 14, 'Sebab itu sumur tadi disebutkan orang: sumur Lahai-Roi; letaknya antara Kadesh dan Bered.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 15, 'Lalu Hagar melahirkan seorang anak laki-laki bagi Abram dan Abram menamai anak yang dilahirkan Hagar itu Ismael.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 16, 16, 'Abram berumur delapan puluh enam tahun, ketika Hagar melahirkan Ismael baginya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 1, 'Ketika Abram berumur sembilan puluh sembilan tahun, maka TUHAN menampakkan diri kepada Abram dan berfirman kepadanya: "Akulah Allah Yang Mahakuasa, hiduplah di hadapan-Ku dengan tidak bercela.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 2, 'Aku akan mengadakan perjanjian antara Aku dan engkau, dan Aku akan membuat engkau sangat banyak."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 3, 'Lalu sujudlah Abram, dan Allah berfirman kepadanya:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 4, '"Dari pihak-Ku, inilah perjanjian-Ku dengan engkau: Engkau akan menjadi bapa sejumlah besar bangsa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 5, 'Karena itu namamu bukan lagi Abram, melainkan Abraham, karena engkau telah Kutetapkan menjadi bapa sejumlah besar bangsa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 6, 'Aku akan membuat engkau beranak cucu sangat banyak; engkau akan Kubuat menjadi bangsa-bangsa, dan dari padamu akan berasal raja-raja.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 7, 'Aku akan mengadakan perjanjian antara Aku dan engkau serta keturunanmu turun-temurun menjadi perjanjian yang kekal, supaya Aku menjadi Allahmu dan Allah keturunanmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 8, 'Kepadamu dan kepada keturunanmu akan Kuberikan negeri ini yang kaudiami sebagai orang asing, yakni seluruh tanah Kanaan akan Kuberikan menjadi milikmu untuk selama-lamanya; dan Aku akan menjadi Allah mereka."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 9, 'Lagi firman Allah kepada Abraham: "Dari pihakmu, engkau harus memegang perjanjian-Ku, engkau dan keturunanmu turun-temurun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 10, 'Inilah perjanjian-Ku, yang harus kamu pegang, perjanjian antara Aku dan kamu serta keturunanmu, yaitu setiap laki-laki di antara kamu harus disunat;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 11, 'haruslah dikerat kulit khatanmu dan itulah akan menjadi tanda perjanjian antara Aku dan kamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 12, 'Anak yang berumur delapan hari haruslah disunat, yakni setiap laki-laki di antara kamu, turun-temurun: baik yang lahir di rumahmu, maupun yang dibeli dengan uang dari salah seorang asing, tetapi tidak termasuk keturunanmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 13, 'Orang yang lahir di rumahmu dan orang yang engkau beli dengan uang harus disunat; maka dalam dagingmulah perjanjian-Ku itu menjadi perjanjian yang kekal.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 14, 'Dan orang yang tidak disunat, yakni laki-laki yang tidak dikerat kulit khatannya, maka orang itu harus dilenyapkan dari antara orang-orang sebangsanya: ia telah mengingkari perjanjian-Ku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 15, 'Selanjutnya Allah berfirman kepada Abraham: "Tentang isterimu Sarai, janganlah engkau menyebut dia lagi Sarai, tetapi Sara, itulah namanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 16, 'Aku akan memberkatinya, dan dari padanya juga Aku akan memberikan kepadamu seorang anak laki-laki, bahkan Aku akan memberkatinya, sehingga ia menjadi ibu bangsa-bangsa; raja-raja bangsa-bangsa akan lahir dari padanya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 17, 'Lalu tertunduklah Abraham dan tertawa serta berkata dalam hatinya: "Mungkinkah bagi seorang yang berumur seratus tahun dilahirkan seorang anak dan mungkinkah Sara, yang telah berumur sembilan puluh tahun itu melahirkan seorang anak?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 18, 'Dan Abraham berkata kepada Allah: "Ah, sekiranya Ismael diperkenankan hidup di hadapan-Mu!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 19, 'Tetapi Allah berfirman: "Tidak, melainkan isterimu Saralah yang akan melahirkan anak laki-laki bagimu, dan engkau akan menamai dia Ishak, dan Aku akan mengadakan perjanjian-Ku dengan dia menjadi perjanjian yang kekal untuk keturunannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 20, 'Tentang Ismael, Aku telah mendengarkan permintaanmu; ia akan Kuberkati, Kubuat beranak cucu dan sangat banyak; ia akan memperanakkan dua belas raja, dan Aku akan membuatnya menjadi bangsa yang besar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 21, 'Tetapi perjanjian-Ku akan Kuadakan dengan Ishak, yang akan dilahirkan Sara bagimu tahun yang akan datang pada waktu seperti ini juga."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 22, 'Setelah selesai berfirman kepada Abraham, naiklah Allah meninggalkan Abraham.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 23, 'Setelah itu Abraham memanggil Ismael, anaknya, dan semua orang yang lahir di rumahnya, juga semua orang yang dibelinya dengan uang, yakni setiap laki-laki dari isi rumahnya, lalu ia mengerat kulit khatan mereka pada hari itu juga, seperti yang telah difirmankan Allah kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 24, 'Abraham berumur sembilan puluh sembilan tahun ketika dikerat kulit khatannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 25, 'Dan Ismael, anaknya, berumur tiga belas tahun ketika dikerat kulit khatannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 26, 'Pada hari itu juga Abraham dan Ismael, anaknya, disunat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 17, 27, 'Dan semua orang dari isi rumah Abraham, baik yang lahir di rumahnya, maupun yang dibeli dengan uang dari orang asing, disunat bersama-sama dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 1, 'Kemudian TUHAN menampakkan diri kepada Abraham dekat pohon tarbantin di Mamre, sedang ia duduk di pintu kemahnya waktu hari panas terik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 2, 'Ketika ia mengangkat mukanya, ia melihat tiga orang berdiri di depannya. Sesudah dilihatnya mereka, ia berlari dari pintu kemahnya menyongsong mereka, lalu sujudlah ia sampai ke tanah,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 3, 'serta berkata: "Tuanku, jika aku telah mendapat kasih tuanku, janganlah kiranya lampaui hambamu ini.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 4, 'Biarlah diambil air sedikit, basuhlah kakimu dan duduklah beristirahat di bawah pohon ini;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 5, 'biarlah kuambil sepotong roti, supaya tuan-tuan segar kembali; kemudian bolehlah tuan-tuan meneruskan perjalanannya; sebab tuan-tuan telah datang ke tempat hambamu ini." Jawab mereka: "Perbuatlah seperti yang kaukatakan itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 6, 'Lalu Abraham segera pergi ke kemah mendapatkan Sara serta berkata: "Segeralah! Ambil tiga sukat tepung yang terbaik! Remaslah itu dan buatlah roti bundar!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 7, 'Lalu berlarilah Abraham kepada lembu sapinya, ia mengambil seekor anak lembu yang empuk dan baik dagingnya dan memberikannya kepada seorang bujangnya, lalu orang ini segera mengolahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 8, 'Kemudian diambilnya dadih dan susu serta anak lembu yang telah diolah itu, lalu dihidangkannya di depan orang-orang itu; dan ia berdiri di dekat mereka di bawah pohon itu, sedang mereka makan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 9, 'Lalu kata mereka kepadanya: "Di manakah Sara, isterimu?" Jawabnya: "Di sana, di dalam kemah."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 10, 'Dan firman-Nya: "Sesungguhnya Aku akan kembali tahun depan mendapatkan engkau, pada waktu itulah Sara, isterimu, akan mempunyai seorang anak laki-laki." Dan Sara mendengarkan pada pintu kemah yang di belakang-Nya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 11, 'Adapun Abraham dan Sara telah tua dan lanjut umurnya dan Sara telah mati haid.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 12, 'Jadi tertawalah Sara dalam hatinya, katanya: "Akan berahikah aku, setelah aku sudah layu, sedangkan tuanku sudah tua?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 13, 'Lalu berfirmanlah TUHAN kepada Abraham: "Mengapakah Sara tertawa dan berkata: Sungguhkah aku akan melahirkan anak, sedangkan aku telah tua?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 14, 'Adakah sesuatu apapun yang mustahil untuk TUHAN? Pada waktu yang telah ditetapkan itu, tahun depan, Aku akan kembali mendapatkan engkau, pada waktu itulah Sara mempunyai seorang anak laki-laki."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 15, 'Lalu Sara menyangkal, katanya: "Aku tidak tertawa," sebab ia takut; tetapi TUHAN berfirman: "Tidak, memang engkau tertawa!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 16, 'Lalu berangkatlah orang-orang itu dari situ dan memandang ke arah Sodom; dan Abraham berjalan bersama-sama dengan mereka untuk mengantarkan mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 17, 'Berpikirlah TUHAN: "Apakah Aku akan menyembunyikan kepada Abraham apa yang hendak Kulakukan ini?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 18, 'Bukankah sesungguhnya Abraham akan menjadi bangsa yang besar serta berkuasa, dan oleh dia segala bangsa di atas bumi akan mendapat berkat?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 19, 'Sebab Aku telah memilih dia, supaya diperintahkannya kepada anak-anaknya dan kepada keturunannya supaya tetap hidup menurut jalan yang ditunjukkan TUHAN, dengan melakukan kebenaran dan keadilan, dan supaya TUHAN memenuhi kepada Abraham apa yang dijanjikan-Nya kepadanya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 20, 'Sesudah itu berfirmanlah TUHAN: "Sesungguhnya banyak keluh kesah orang tentang Sodom dan Gomora dan sesungguhnya sangat berat dosanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 21, 'Baiklah Aku turun untuk melihat, apakah benar-benar mereka telah berkelakuan seperti keluh kesah orang yang telah sampai kepada-Ku atau tidak; Aku hendak mengetahuinya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 22, 'Lalu berpalinglah orang-orang itu dari situ dan berjalan ke Sodom, tetapi Abraham masih tetap berdiri di hadapan TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 23, 'Abraham datang mendekat dan berkata: "Apakah Engkau akan melenyapkan orang benar bersama-sama dengan orang fasik?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 24, 'Bagaimana sekiranya ada lima puluh orang benar dalam kota itu? Apakah Engkau akan melenyapkan tempat itu dan tidakkah Engkau mengampuninya karena kelima puluh orang benar yang ada di dalamnya itu?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 25, 'Jauhlah kiranya dari pada-Mu untuk berbuat demikian, membunuh orang benar bersama-sama dengan orang fasik, sehingga orang benar itu seolah-olah sama dengan orang fasik! Jauhlah kiranya yang demikian dari pada-Mu! Masakan Hakim segenap bumi tidak menghukum dengan adil?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 26, 'TUHAN berfirman: "Jika Kudapati lima puluh orang benar dalam kota Sodom, Aku akan mengampuni seluruh tempat itu karena mereka."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 27, 'Abraham menyahut: "Sesungguhnya aku telah memberanikan diri berkata kepada Tuhan, walaupun aku debu dan abu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 28, 'Sekiranya kurang lima orang dari kelima puluh orang benar itu, apakah Engkau akan memusnahkan seluruh kota itu karena yang lima itu?" Firman-Nya: "Aku tidak memusnahkannya, jika Kudapati empat puluh lima di sana."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 29, 'Lagi Abraham melanjutkan perkataannya kepada-Nya: "Sekiranya empat puluh didapati di sana?" Firman-Nya: "Aku tidak akan berbuat demikian karena yang empat puluh itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 30, 'Katanya: "Janganlah kiranya Tuhan murka, kalau aku berkata sekali lagi. Sekiranya tiga puluh didapati di sana?" Firman-Nya: "Aku tidak akan berbuat demikian, jika Kudapati tiga puluh di sana."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 31, 'Katanya: "Sesungguhnya aku telah memberanikan diri berkata kepada Tuhan. Sekiranya dua puluh didapati di sana?" Firman-Nya: "Aku tidak akan memusnahkannya karena yang dua puluh itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 32, 'Katanya: "Janganlah kiranya Tuhan murka, kalau aku berkata lagi sekali ini saja. Sekiranya sepuluh didapati di sana?" Firman-Nya: "Aku tidak akan memusnahkannya karena yang sepuluh itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 18, 33, 'Lalu pergilah TUHAN, setelah Ia selesai berfirman kepada Abraham; dan kembalilah Abraham ke tempat tinggalnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 1, 'Kedua malaikat itu tiba di Sodom pada waktu petang. Lot sedang duduk di pintu gerbang Sodom dan ketika melihat mereka, bangunlah ia menyongsong mereka, lalu sujud dengan mukanya sampai ke tanah,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 2, 'serta berkata: "Tuan-tuan, silakanlah singgah ke rumah hambamu ini, bermalamlah di sini dan basuhlah kakimu, maka besok pagi tuan-tuan boleh melanjutkan perjalanannya." Jawab mereka: "Tidak, kami akan bermalam di tanah lapang."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 3, 'Tetapi karena ia sangat mendesak mereka, singgahlah mereka dan masuk ke dalam rumahnya, kemudian ia menyediakan hidangan bagi mereka, ia membakar roti yang tidak beragi, lalu mereka makan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 4, 'Tetapi sebelum mereka tidur, orang-orang lelaki dari kota Sodom itu, dari yang muda sampai yang tua, bahkan seluruh kota, tidak ada yang terkecuali, datang mengepung rumah itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 5, 'Mereka berseru kepada Lot: "Di manakah orang-orang yang datang kepadamu malam ini? Bawalah mereka keluar kepada kami, supaya kami pakai mereka."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 6, 'Lalu keluarlah Lot menemui mereka, ke depan pintu, tetapi pintu ditutupnya di belakangnya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 7, 'dan ia berkata: "Saudara-saudaraku, janganlah kiranya berbuat jahat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 8, 'Kamu tahu, aku mempunyai dua orang anak perempuan yang belum pernah dijamah laki-laki, baiklah mereka kubawa ke luar kepadamu; perbuatlah kepada mereka seperti yang kamu pandang baik; hanya jangan kamu apa-apakan orang-orang ini, sebab mereka memang datang untuk berlindung di dalam rumahku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 9, 'Tetapi mereka berkata: "Enyahlah!" Lagi kata mereka: "Orang ini datang ke sini sebagai orang asing dan dia mau menjadi hakim atas kita! Sekarang kami akan menganiaya engkau lebih dari pada kedua orang itu!" Lalu mereka mendesak orang itu, yaitu Lot, dengan keras, dan mereka mendekat untuk mendobrak pintu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 10, 'Tetapi kedua orang itu mengulurkan tangannya, menarik Lot masuk ke dalam rumah, lalu menutup pintu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 11, 'Dan mereka membutakan mata orang-orang yang di depan pintu rumah itu, dari yang kecil sampai yang besar, sehingga percumalah orang-orang itu mencari-cari pintu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 12, 'Lalu kedua orang itu berkata kepada Lot: "Siapakah kaummu yang ada di sini lagi? Menantu atau anakmu laki-laki, anakmu perempuan, atau siapa saja kaummu di kota ini, bawalah mereka keluar dari tempat ini,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 13, 'sebab kami akan memusnahkan tempat ini, karena banyak keluh kesah orang tentang kota ini di hadapan TUHAN; sebab itulah TUHAN mengutus kami untuk memusnahkannya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 14, 'Keluarlah Lot, lalu berbicara dengan kedua bakal menantunya, yang akan kawin dengan kedua anaknya perempuan, katanya: "Bangunlah, keluarlah dari tempat ini, sebab TUHAN akan memusnahkan kota ini." Tetapi ia dipandang oleh kedua bakal menantunya itu sebagai orang yang berolok-olok saja.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 15, 'Ketika fajar telah menyingsing, kedua malaikat itu mendesak Lot, supaya bersegera, katanya: "Bangunlah, bawalah isterimu dan kedua anakmu yang ada di sini, supaya engkau jangan mati lenyap karena kedurjanaan kota ini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 16, 'Ketika ia berlambat-lambat, maka tangannya, tangan isteri dan tangan kedua anaknya dipegang oleh kedua orang itu, sebab TUHAN hendak mengasihani dia; lalu kedua orang itu menuntunnya ke luar kota dan melepaskannya di sana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 17, 'Sesudah kedua orang itu menuntun mereka sampai ke luar, berkatalah seorang: "Larilah, selamatkanlah nyawamu; janganlah menoleh ke belakang, dan janganlah berhenti di manapun juga di Lembah Yordan, larilah ke pegunungan, supaya engkau jangan mati lenyap."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 18, 'Kata Lot kepada mereka: "Janganlah kiranya demikian, tuanku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 19, 'Sungguhlah hambamu ini telah dikaruniai belas kasihan di hadapanmu, dan tuanku telah berbuat kemurahan besar kepadaku dengan memelihara hidupku, tetapi jika aku harus lari ke pegunungan, pastilah aku akan tersusul oleh bencana itu, sehingga matilah aku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 20, 'Sungguhlah kota yang di sana itu cukup dekat kiranya untuk lari ke sana; kota itu kecil; izinkanlah kiranya aku lari ke sana. Bukankah kota itu kecil? Jika demikian, nyawaku akan terpelihara."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 21, 'Sahut malaikat itu kepadanya: "Baiklah, dalam hal inipun permintaanmu akan kuterima dengan baik; yakni kota yang telah kau sebut itu tidak akan kutunggangbalikkan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 22, 'Cepatlah, larilah ke sana, sebab aku tidak dapat berbuat apa-apa, sebelum engkau sampai ke sana." Itulah sebabnya nama kota itu disebut Zoar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 23, 'Matahari telah terbit menyinari bumi, ketika Lot tiba di Zoar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 24, 'Kemudian TUHAN menurunkan hujan belerang dan api atas Sodom dan Gomora, berasal dari TUHAN, dari langit;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 25, 'dan ditunggangbalikkan-Nyalah kota-kota itu dan Lembah Yordan dan semua penduduk kota-kota serta tumbuh-tumbuhan di tanah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 26, 'Tetapi isteri Lot, yang berjalan mengikutnya, menoleh ke belakang, lalu menjadi tiang garam.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 27, 'Ketika Abraham pagi-pagi pergi ke tempat ia berdiri di hadapan TUHAN itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 28, 'dan memandang ke arah Sodom dan Gomora serta ke seluruh tanah Lembah Yordan, maka dilihatnyalah asap dari bumi membubung ke atas sebagai asap dari dapur peleburan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 29, 'Demikianlah pada waktu Allah memusnahkan kota-kota di Lembah Yordan dan menunggangbalikkan kota-kota kediaman Lot, maka Allah ingat kepada Abraham, lalu dikeluarkan-Nyalah Lot dari tengah-tengah tempat yang ditunggangbalikkan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 30, 'Pergilah Lot dari Zoar dan ia menetap bersama-sama dengan kedua anaknya perempuan di pegunungan, sebab ia tidak berani tinggal di Zoar, maka diamlah ia dalam suatu gua beserta kedua anaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 31, 'Kata kakaknya kepada adiknya: "Ayah kita telah tua, dan tidak ada laki-laki di negeri ini yang dapat menghampiri kita, seperti kebiasaan seluruh bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 32, 'Marilah kita beri ayah kita minum anggur, lalu kita tidur dengan dia, supaya kita menyambung keturunan dari ayah kita."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 33, 'Pada malam itu mereka memberi ayah mereka minum anggur, lalu masuklah yang lebih tua untuk tidur dengan ayahnya; dan ayahnya itu tidak mengetahui ketika anaknya itu tidur dan ketika ia bangun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 34, 'Keesokan harinya berkatalah kakaknya kepada adiknya: "Tadi malam aku telah tidur dengan ayah; baiklah malam ini juga kita beri dia minum anggur; masuklah engkau untuk tidur dengan dia, supaya kita menyambung keturunan dari ayah kita."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 35, 'Demikianlah juga pada malam itu mereka memberi ayah mereka minum anggur, lalu bangunlah yang lebih muda untuk tidur dengan ayahnya; dan ayahnya itu tidak mengetahui ketika anaknya itu tidur dan ketika ia bangun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 36, 'Lalu mengandunglah kedua anak Lot itu dari ayah mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 37, 'Yang lebih tua melahirkan seorang anak laki-laki, dan menamainya Moab; dialah bapa orang Moab yang sekarang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 19, 38, 'Yang lebih mudapun melahirkan seorang anak laki-laki, dan menamainya Ben-Ami; dialah bapa bani Amon yang sekarang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 1, 'Lalu Abraham berangkat dari situ ke Tanah Negeb dan ia menetap antara Kadesh dan Syur. Ia tinggal di Gerar sebagai orang asing.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 2, 'Oleh karena Abraham telah mengatakan tentang Sara, isterinya: "Dia saudaraku," maka Abimelekh, raja Gerar, menyuruh mengambil Sara.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 3, 'Tetapi pada waktu malam Allah datang kepada Abimelekh dalam suatu mimpi serta berfirman kepadanya: "Engkau harus mati oleh karena perempuan yang telah kauambil itu; sebab ia sudah bersuami."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 4, 'Adapun Abimelekh belum menghampiri Sara. Berkatalah ia: "Tuhan! Apakah Engkau membunuh bangsa yang tak bersalah?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 5, 'Bukankah orang itu sendiri mengatakan kepadaku: Dia saudaraku? Dan perempuan itu sendiri telah mengatakan: Ia saudaraku. Jadi hal ini kulakukan dengan hati yang tulus dan dengan tangan yang suci."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 6, 'Lalu berfirmanlah Allah kepadanya dalam mimpi: "Aku tahu juga, bahwa engkau telah melakukan hal itu dengan hati yang tulus, maka Akupun telah mencegah engkau untuk berbuat dosa terhadap Aku; sebab itu Aku tidak membiarkan engkau menjamah dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 7, 'Jadi sekarang, kembalikanlah isteri orang itu, sebab dia seorang nabi; ia akan berdoa untuk engkau, maka engkau tetap hidup; tetapi jika engkau tidak mengembalikan dia, ketahuilah, engkau pasti mati, engkau dan semua orang yang bersama-sama dengan engkau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 8, 'Keesokan harinya pagi-pagi Abimelekh memanggil semua hambanya dan memberitahukan seluruh peristiwa itu kepada mereka, lalu sangat takutlah orang-orang itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 9, 'Kemudian Abimelekh memanggil Abraham dan berkata kepadanya: "Perbuatan apakah yang kaulakukan ini terhadap kami, dan kesalahan apakah yang kulakukan terhadap engkau, sehingga engkau mendatangkan dosa besar atas diriku dan kerajaanku? Engkau telah berbuat hal-hal yang tidak patut kepadaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 10, 'Lagi kata Abimelekh kepada Abraham: "Apakah maksudmu, maka engkau melakukan hal ini?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 11, 'Lalu Abraham berkata: "Aku berpikir: Takut akan Allah tidak ada di tempat ini; tentulah aku akan dibunuh karena isteriku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 12, 'Lagipula ia benar-benar saudaraku, anak ayahku, hanya bukan anak ibuku, tetapi kemudian ia menjadi isteriku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 13, 'Ketika Allah menyuruh aku mengembara keluar dari rumah ayahku, berkatalah aku kepada isteriku: Tunjukkanlah kasihmu kepadaku, yakni: katakanlah tentang aku di tiap-tiap tempat di mana kita tiba: Ia saudaraku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 14, 'Kemudian Abimelekh mengambil kambing domba dan lembu sapi, hamba laki-laki dan perempuan, lalu memberikan semuanya itu kepada Abraham; Sara, isteri Abraham, juga dikembalikannya kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 15, 'Dan Abimelekh berkata: "Negeriku ini terbuka untuk engkau; menetaplah, di mana engkau suka."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 16, 'Lalu katanya kepada Sara: "Telah kuberikan kepada saudaramu seribu syikal perak, itulah bukti kesucianmu bagi semua orang yang bersama-sama dengan engkau. Maka dalam segala hal engkau dibenarkan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 17, 'Lalu Abraham berdoa kepada Allah, dan Allah menyembuhkan Abimelekh dan isterinya dan budak-budaknya perempuan, sehingga mereka melahirkan anak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 20, 18, 'Sebab tadinya TUHAN telah menutup kandungan setiap perempuan di istana Abimelekh karena Sara, isteri Abraham itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 1, 'TUHAN memperhatikan Sara, seperti yang difirmankan-Nya, dan TUHAN melakukan kepada Sara seperti yang dijanjikan-Nya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 2, 'Maka mengandunglah Sara, lalu ia melahirkan seorang anak laki-laki bagi Abraham dalam masa tuanya, pada waktu yang telah ditetapkan, sesuai dengan firman Allah kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 3, 'Abraham menamai anaknya yang baru lahir itu Ishak, yang dilahirkan Sara baginya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 4, 'Kemudian Abraham menyunat Ishak, anaknya itu, ketika berumur delapan hari, seperti yang diperintahkan Allah kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 5, 'Adapun Abraham berumur seratus tahun, ketika Ishak, anaknya, lahir baginya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 6, 'Berkatalah Sara: "Allah telah membuat aku tertawa; setiap orang yang mendengarnya akan tertawa karena aku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 7, 'Lagi katanya: "Siapakah tadinya yang dapat mengatakan kepada Abraham: Sara menyusui anak? Namun aku telah melahirkan seorang anak laki-laki baginya pada masa tuanya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 8, 'Bertambah besarlah anak itu dan ia disapih, lalu Abraham mengadakan perjamuan besar pada hari Ishak disapih itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 9, 'Pada waktu itu Sara melihat, bahwa anak yang dilahirkan Hagar, perempuan Mesir itu bagi Abraham, sedang main dengan Ishak, anaknya sendiri.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 10, 'Berkatalah Sara kepada Abraham: "Usirlah hamba perempuan itu beserta anaknya, sebab anak hamba ini tidak akan menjadi ahli waris bersama-sama dengan anakku Ishak."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 11, 'Hal ini sangat menyebalkan Abraham oleh karena anaknya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 12, 'Tetapi Allah berfirman kepada Abraham: "Janganlah sebal hatimu karena hal anak dan budakmu itu; dalam segala yang dikatakan Sara kepadamu, haruslah engkau mendengarkannya, sebab yang akan disebut keturunanmu ialah yang berasal dari Ishak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 13, 'Tetapi keturunan dari hambamu itu juga akan Kubuat menjadi suatu bangsa, karena iapun anakmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 14, 'Keesokan harinya pagi-pagi Abraham mengambil roti serta sekirbat air dan memberikannya kepada Hagar. Ia meletakkan itu beserta anaknya di atas bahu Hagar, kemudian disuruhnyalah perempuan itu pergi. Maka pergilah Hagar dan mengembara di padang gurun Bersyeba.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 15, 'Ketika air yang dikirbat itu habis, dibuangnyalah anak itu ke bawah semak-semak,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 16, 'dan ia duduk agak jauh, kira-kira sepemanah jauhnya, sebab katanya: "Tidak tahan aku melihat anak itu mati." Sedang ia duduk di situ, menangislah ia dengan suara nyaring.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 17, 'Allah mendengar suara anak itu, lalu Malaikat Allah berseru dari langit kepada Hagar, kata-Nya kepadanya: "Apakah yang engkau susahkan, Hagar? Janganlah takut, sebab Allah telah mendengar suara anak itu dari tempat ia terbaring.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 18, 'Bangunlah, angkatlah anak itu, dan bimbinglah dia, sebab Aku akan membuat dia menjadi bangsa yang besar."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 19, 'Lalu Allah membuka mata Hagar, sehingga ia melihat sebuah sumur; ia pergi mengisi kirbatnya dengan air, kemudian diberinya anak itu minum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 20, 'Allah menyertai anak itu, sehingga ia bertambah besar; ia menetap di padang gurun dan menjadi seorang pemanah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 21, 'Maka tinggallah ia di padang gurun Paran, dan ibunya mengambil seorang isteri baginya dari tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 22, 'Pada waktu itu Abimelekh, beserta Pikhol, panglima tentaranya, berkata kepada Abraham: "Allah menyertai engkau dalam segala sesuatu yang engkau lakukan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 23, 'Oleh sebab itu, bersumpahlah kepadaku di sini demi Allah, bahwa engkau tidak akan berlaku curang kepadaku, atau kepada anak-anakku, atau kepada cucu cicitku; sesuai dengan persahabatan yang kulakukan kepadamu, demikianlah harus engkau berlaku kepadaku dan kepada negeri yang kautinggali sebagai orang asing."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 24, 'Lalu kata Abraham: "Aku bersumpah!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 25, 'Tetapi Abraham menyesali Abimelekh tentang sebuah sumur yang telah dirampas oleh hamba-hamba Abimelekh.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 26, 'Jawab Abimelekh: "Aku tidak tahu, siapa yang melakukan hal itu; lagi tidak kauberitahukan kepadaku, dan sampai hari ini belum pula kudengar."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 27, 'Lalu Abraham mengambil domba dan lembu dan memberikan semuanya itu kepada Abimelekh, kemudian kedua orang itu mengadakan perjanjian.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 28, 'Tetapi Abraham memisahkan tujuh anak domba betina dari domba-domba itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 29, 'Lalu kata Abimelekh kepada Abraham: "Untuk apakah ketujuh anak domba yang kaupisahkan ini?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 30, 'Jawabnya: "Ketujuh anak domba ini harus kauterima dari tanganku untuk menjadi tanda bukti bagiku, bahwa akulah yang menggali sumur ini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 31, 'Sebab itu orang menyebutkan tempat itu Bersyeba, karena kedua orang itu telah bersumpah di sana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 32, 'Setelah mereka mengadakan perjanjian di Bersyeba, pulanglah Abimelekh beserta Pikhol, panglima tentaranya, ke negeri orang Filistin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 33, 'Lalu Abraham menanam sebatang pohon tamariska di Bersyeba, dan memanggil di sana nama TUHAN, Allah yang kekal.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 21, 34, 'Dan masih lama Abraham tinggal sebagai orang asing di negeri orang Filistin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 1, 'Setelah semuanya itu Allah mencoba Abraham. Ia berfirman kepadanya: "Abraham," lalu sahutnya: "Ya, Tuhan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 2, 'Firman-Nya: "Ambillah anakmu yang tunggal itu, yang engkau kasihi, yakni Ishak, pergilah ke tanah Moria dan persembahkanlah dia di sana sebagai korban bakaran pada salah satu gunung yang akan Kukatakan kepadamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 3, 'Keesokan harinya pagi-pagi bangunlah Abraham, ia memasang pelana keledainya dan memanggil dua orang bujangnya beserta Ishak, anaknya; ia membelah juga kayu untuk korban bakaran itu, lalu berangkatlah ia dan pergi ke tempat yang dikatakan Allah kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 4, 'Ketika pada hari ketiga Abraham melayangkan pandangnya, kelihatanlah kepadanya tempat itu dari jauh.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 5, 'Kata Abraham kepada kedua bujangnya itu: "Tinggallah kamu di sini dengan keledai ini; aku beserta anak ini akan pergi ke sana; kami akan sembahyang, sesudah itu kami kembali kepadamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 6, 'Lalu Abraham mengambil kayu untuk korban bakaran itu dan memikulkannya ke atas bahu Ishak, anaknya, sedang di tangannya dibawanya api dan pisau. Demikianlah keduanya berjalan bersama-sama.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 7, 'Lalu berkatalah Ishak kepada Abraham, ayahnya: "Bapa." Sahut Abraham: "Ya, anakku." Bertanyalah ia: "Di sini sudah ada api dan kayu, tetapi di manakah anak domba untuk korban bakaran itu?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 8, 'Sahut Abraham: "Allah yang akan menyediakan anak domba untuk korban bakaran bagi-Nya, anakku." Demikianlah keduanya berjalan bersama-sama.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 9, 'Sampailah mereka ke tempat yang dikatakan Allah kepadanya. Lalu Abraham mendirikan mezbah di situ, disusunnyalah kayu, diikatnya Ishak, anaknya itu, dan diletakkannya di mezbah itu, di atas kayu api.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 10, 'Sesudah itu Abraham mengulurkan tangannya, lalu mengambil pisau untuk menyembelih anaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 11, 'Tetapi berserulah Malaikat TUHAN dari langit kepadanya: "Abraham, Abraham." Sahutnya: "Ya, Tuhan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 12, 'Lalu Ia berfirman: "Jangan bunuh anak itu dan jangan kauapa-apakan dia, sebab telah Kuketahui sekarang, bahwa engkau takut akan Allah, dan engkau tidak segan-segan untuk menyerahkan anakmu yang tunggal kepada-Ku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 13, 'Lalu Abraham menoleh dan melihat seekor domba jantan di belakangnya, yang tanduknya tersangkut dalam belukar. Abraham mengambil domba itu, lalu mengorbankannya sebagai korban bakaran pengganti anaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 14, 'Dan Abraham menamai tempat itu: "TUHAN menyediakan"; sebab itu sampai sekarang dikatakan orang: "Di atas gunung TUHAN, akan disediakan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 15, 'Untuk kedua kalinya berserulah Malaikat TUHAN dari langit kepada Abraham,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 16, 'kata-Nya: "Aku bersumpah demi diri-Ku sendiri?demikianlah firman TUHAN?:Karena engkau telah berbuat demikian, dan engkau tidak segan-segan untuk menyerahkan anakmu yang tunggal kepada-Ku,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 17, 'maka Aku akan memberkati engkau berlimpah-limpah dan membuat keturunanmu sangat banyak seperti bintang di langit dan seperti pasir di tepi laut, dan keturunanmu itu akan menduduki kota-kota musuhnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 18, 'Oleh keturunanmulah semua bangsa di bumi akan mendapat berkat, karena engkau mendengarkan firman-Ku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 19, 'Kemudian kembalilah Abraham kepada kedua bujangnya, dan mereka bersama-sama berangkat ke Bersyeba; dan Abraham tinggal di Bersyeba.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 20, 'Sesudah itu Abraham mendapat kabar: "Juga Milka telah melahirkan anak-anak lelaki bagi Nahor, saudaramu:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 21, 'Us, anak sulung, dan Bus, adiknya, dan Kemuel, ayah Aram,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 22, 'juga Kesed, Hazo, Pildash, Yidlaf dan Betuel."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 23, 'Dan Betuel memperanakkan Ribka. Kedelapan orang inilah dilahirkan Milka bagi Nahor, saudara Abraham itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 22, 24, 'Dan gundik Nahor, yang namanya Reuma, melahirkan anak juga, yakni Tebah, Gaham, Tahash dan Maakha.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 1, 'Sara hidup seratus dua puluh tujuh tahun lamanya; itulah umur Sara.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 2, 'Kemudian matilah Sara di Kiryat-Arba, yaitu Hebron, di tanah Kanaan, lalu Abraham datang meratapi dan menangisinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 3, 'Sesudah itu Abraham bangkit dan meninggalkan isterinya yang mati itu, lalu berkata kepada bani Het:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 4, '"Aku ini orang asing dan pendatang di antara kamu; berikanlah kiranya kuburan milik kepadaku di tanah kamu ini, supaya kiranya aku dapat mengantarkan dan menguburkan isteriku yang mati itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 5, 'Bani Het menjawab Abraham:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 6, '"Dengarlah kepada kami, tuanku. Tuanku ini seorang raja agung di tengah-tengah kami; jadi kuburkanlah isterimu yang mati itu dalam kuburan kami yang terpilih, tidak akan ada seorangpun dari kami yang menolak menyediakan kuburannya bagimu untuk menguburkan isterimu yang mati itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 7, 'Kemudian bangunlah Abraham lalu sujud kepada bani Het, penduduk negeri itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 8, 'serta berkata kepada mereka: "Jika kamu setuju, bahwa aku mengantarkan dan menguburkan isteriku yang mati itu, maka dengarkanlah aku dan tolonglah mintakan dengan sangat kepada Efron bin Zohar,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 9, 'supaya ia memberikan kepadaku gua Makhpela miliknya itu, yang terletak di ujung ladangnya; baiklah itu diberikannya kepadaku dengan harga penuh untuk menjadi kuburan milikku di tengah-tengah kamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 10, 'Pada waktu itu Efron hadir di tengah-tengah bani Het. Maka jawab Efron, orang Het itu, kepada Abraham dengan didengar oleh bani Het, oleh semua orang yang datang di pintu gerbang kota:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 11, '"Tidak, tuanku, dengarkanlah aku; ladang itu kuberikan kepadamu dan gua yang di sanapun kuberikan kepadamu; di depan mata orang-orang sebangsaku kuberikan itu kepadamu; kuburkanlah isterimu yang mati itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 12, 'Lalu sujudlah Abraham di depan penduduk negeri itu', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 13, 'serta berkata kepada Efron dengan didengar oleh mereka: "Sesungguhnya, jika engkau suka, dengarkanlah aku: aku membayar harga ladang itu; terimalah itu dari padaku, supaya aku dapat menguburkan isteriku yang mati itu di sana."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 14, 'Jawab Efron kepada Abraham:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 15, '"Tuanku, dengarkanlah aku: sebidang tanah dengan harga empat ratus syikal perak, apa artinya itu bagi kita? Kuburkan sajalah isterimu yang mati itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 16, 'Lalu Abraham menerima usul Efron, maka ditimbangnyalah perak untuk Efron, sebanyak yang dimintanya dengan didengar oleh bani Het itu, empat ratus syikal perak, seperti yang berlaku di antara para saudagar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 17, 'Demikianlah ladang Efron, yang letaknya di Makhpela di sebelah timur Mamre, ladang dan gua yang di sana, serta segala pohon di ladang itu, bahkan di seluruh tanah itu sampai ke tepi-tepinya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 18, 'diserahkan kepada Abraham menjadi tanah belian, di depan mata bani Het itu, di depan semua orang yang datang di pintu gerbang kota.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 19, 'Sesudah itu Abraham menguburkan Sara, isterinya, di dalam gua ladang Makhpela itu, di sebelah timur Mamre, yaitu Hebron di tanah Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 23, 20, 'Demikianlah dari pihak bani Het ladang dengan gua yang ada di sana diserahkan kepada Abraham menjadi kuburan miliknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 1, 'Adapun Abraham telah tua dan lanjut umurnya, serta diberkati TUHAN dalam segala hal.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 2, 'Berkatalah Abraham kepada hambanya yang paling tua dalam rumahnya, yang menjadi kuasa atas segala kepunyaannya, katanya: "Baiklah letakkan tanganmu di bawah pangkal pahaku,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 3, 'supaya aku mengambil sumpahmu demi TUHAN, Allah yang empunya langit dan yang empunya bumi, bahwa engkau tidak akan mengambil untuk anakku seorang isteri dari antara perempuan Kanaan yang di antaranya aku diam.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 4, 'Tetapi engkau harus pergi ke negeriku dan kepada sanak saudaraku untuk mengambil seorang isteri bagi Ishak, anakku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 5, 'Lalu berkatalah hambanya itu kepadanya: "Mungkin perempuan itu tidak suka mengikuti aku ke negeri ini; haruskah aku membawa anakmu itu kembali ke negeri dari mana tuanku keluar?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 6, 'Tetapi Abraham berkata kepadanya: "Awas, jangan kaubawa anakku itu kembali ke sana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 7, 'TUHAN, Allah yang empunya langit, yang telah memanggil aku dari rumah ayahku serta dari negeri sanak saudaraku, dan yang telah berfirman kepadaku, serta yang bersumpah kepadaku, demikian: kepada keturunanmulah akan Kuberikan negeri ini?Dialah juga akan mengutus malaikat-Nya berjalan di depanmu, sehingga engkau dapat mengambil seorang isteri dari sana untuk anakku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 8, 'Tetapi jika perempuan itu tidak mau mengikuti engkau, maka lepaslah engkau dari sumpahmu kepadaku ini; hanya saja, janganlah anakku itu kaubawa kembali ke sana."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 9, 'Lalu hamba itu meletakkan tangannya di bawah pangkal paha Abraham, tuannya, dan bersumpah kepadanya tentang hal itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 10, 'Kemudian hamba itu mengambil sepuluh ekor dari unta tuannya dan pergi dengan membawa berbagai-bagai barang berharga kepunyaan tuannya; demikianlah ia berangkat menuju Aram-Mesopotamia ke kota Nahor.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 11, 'Di sana disuruhnyalah unta itu berhenti di luar kota dekat suatu sumur, pada waktu petang hari, waktu perempuan-perempuan keluar untuk menimba air.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 12, 'Lalu berkatalah ia: "TUHAN, Allah tuanku Abraham, buatlah kiranya tercapai tujuanku pada hari ini, tunjukkanlah kasih setia-Mu kepada tuanku Abraham.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 13, 'Di sini aku berdiri di dekat mata air, dan anak-anak perempuan penduduk kota ini datang keluar untuk menimba air.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 14, 'Kiranya terjadilah begini: anak gadis, kepada siapa aku berkata: Tolong miringkan buyungmu itu, supaya aku minum, dan yang menjawab: Minumlah, dan unta-untamu juga akan kuberi minum?dialah kiranya yang Kautentukan bagi hamba-Mu, Ishak; maka dengan begitu akan kuketahui, bahwa Engkau telah menunjukkan kasih setia-Mu kepada tuanku itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 15, 'Sebelum ia selesai berkata, maka datanglah Ribka, yang lahir bagi Betuel, anak laki-laki Milka, isteri Nahor, saudara Abraham; buyungnya dibawanya di atas bahunya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 16, 'Anak gadis itu sangat cantik parasnya, seorang perawan, belum pernah bersetubuh dengan laki-laki; ia turun ke mata air itu dan mengisi buyungnya, lalu kembali naik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 17, 'Kemudian berlarilah hamba itu mendapatkannya serta berkata: "Tolong beri aku minum air sedikit dari buyungmu itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 18, 'Jawabnya: "Minumlah, tuan," maka segeralah diturunkannya buyungnya itu ke tangannya, serta diberinya dia minum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 19, 'Setelah ia selesai memberi hamba itu minum, berkatalah ia: "Baiklah untuk unta-untamu juga kutimba air, sampai semuanya puas minum."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 20, 'Kemudian segeralah dituangnya air yang di buyungnya itu ke dalam palungan, lalu berlarilah ia sekali lagi ke sumur untuk menimba air dan ditimbanyalah untuk semua unta orang itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 21, 'Dan orang itu mengamat-amatinya dengan berdiam diri untuk mengetahui apakah TUHAN membuat perjalanannya berhasil atau tidak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 22, 'Setelah unta-unta itu puas minum, maka orang itu mengambil anting-anting emas yang setengah syikal beratnya, dan sepasang gelang tangan yang sepuluh syikal emas beratnya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 23, 'serta berkata: "Anak siapakah engkau? Baiklah katakan kepadaku! Adakah di rumah ayahmu tempat bermalam bagi kami?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 24, 'Lalu jawabnya kepadanya: "Ayahku Betuel, anak Milka, yang melahirkannya bagi Nahor."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 25, 'Lagi kata gadis itu: "Baik jerami, baik makanan unta banyak pada kami, tempat bermalampun ada."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 26, 'Lalu berlututlah orang itu dan sujud menyembah TUHAN,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 27, 'serta berkata: "Terpujilah TUHAN, Allah tuanku Abraham, yang tidak menarik kembali kasih-Nya dan setia-Nya dari tuanku itu; dan TUHAN telah menuntun aku di jalan ke rumah saudara-saudara tuanku ini!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 28, 'Berlarilah gadis itu pergi menceritakan kejadian itu ke rumah ibunya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 29, 'Ribka mempunyai saudara laki-laki, namanya Laban. Laban berlari ke luar mendapatkan orang itu, ke mata air tadi,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 30, 'sesudah dilihatnya anting-anting itu dan gelang pada tangan saudaranya, dan sesudah didengarnya perkataan Ribka, saudaranya, yang bunyinya: "Begitulah dikatakan orang itu kepadaku." Ia mendapatkan orang itu, yang masih berdiri di samping unta-untanya di dekat mata air itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 31, 'dan berkata: "Marilah engkau yang diberkati TUHAN, mengapa engkau berdiri di luar, padahal telah kusediakan rumah bagimu, dan juga tempat untuk unta-untamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 32, 'Masuklah orang itu ke dalam rumah. Ditanggalkanlah pelana unta-unta, diberikan jerami dan makanan kepada unta-unta itu, lalu dibawa air pembasuh kaki untuk orang itu dan orang-orang yang bersama-sama dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 33, 'Tetapi ketika dihidangkan makanan di depannya, berkatalah orang itu: "Aku tidak akan makan sebelum kusampaikan pesan yang kubawa ini." Jawab Laban: "Silakan!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 34, 'Lalu berkatalah ia: "Aku ini hamba Abraham.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 35, 'TUHAN sangat memberkati tuanku itu, sehingga ia telah menjadi kaya; TUHAN telah memberikan kepadanya kambing domba dan lembu sapi, emas dan perak, budak laki-laki dan perempuan, unta dan keledai.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 36, 'Dan Sara, isteri tuanku itu, sesudah tua, telah melahirkan anak laki-laki bagi tuanku itu; kepada anaknya itu telah diberikan tuanku segala harta miliknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 37, 'Tuanku itu telah mengambil sumpahku: Engkau tidak akan mengambil untuk anakku seorang isteri dari antara perempuan Kanaan, yang negerinya kudiami ini,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 38, 'tetapi engkau harus pergi ke rumah ayahku dan kepada kaumku untuk mengambil seorang isteri bagi anakku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 39, 'Jawabku kepada tuanku itu: Mungkin perempuan itu tidak mau mengikut aku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 40, 'Tetapi katanya kepadaku: TUHAN, yang di hadapan-Nya aku hidup, akan mengutus malaikat-Nya menyertai engkau, dan akan membuat perjalananmu berhasil, sehingga engkau akan mengambil bagi anakku seorang isteri dari kaumku dan dari rumah ayahku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 41, 'Barulah engkau lepas dari sumpahmu kepadaku, jika engkau sampai kepada kaumku dan mereka tidak memberikan perempuan itu kepadamu; hanya dalam hal itulah engkau lepas dari sumpahmu kepadaku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 42, 'Dan hari ini aku sampai ke mata air tadi, lalu kataku: TUHAN, Allah tuanku Abraham, sudilah kiranya Engkau membuat berhasil perjalanan yang kutempuh ini.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 43, 'Di sini aku berdiri di dekat mata air ini; kiranya terjadi begini: Apabila seorang gadis datang ke luar untuk menimba air dan aku berkata kepadanya: Tolong berikan aku minum air sedikit dari buyungmu itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 44, 'dan ia menjawab: Minumlah, dan untuk unta-untamu juga akan kutimba air, ?dialah kiranya isteri, yang telah TUHAN tentukan bagi anak tuanku itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 45, 'Belum lagi aku habis berkata dalam hatiku, Ribka telah datang membawa buyung di atas bahunya, dan turun ke mata air itu, lalu menimba air. Kataku kepadanya: Tolong berikan aku minum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 46, 'Segeralah ia menurunkan buyung itu dari atas bahunya serta berkata: Minumlah, dan unta-untamu juga akan kuberi minum. Lalu aku minum, dan unta-unta itu juga diberinya minum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 47, 'Sesudah itu aku bertanya kepadanya: Anak siapakah engkau? Jawabnya: Ayahku Betuel anak Nahor yang dilahirkan Milka. Lalu aku mengenakan anting-anting pada hidungnya dan gelang pada tangannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 48, 'Kemudian berlututlah aku dan sujud menyembah TUHAN, serta memuji TUHAN, Allah tuanku Abraham, yang telah menuntun aku di jalan yang benar untuk mengambil anak perempuan saudara tuanku ini bagi anaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 49, 'Jadi sekarang, apabila kamu mau menunjukkan kasih dan setia kepada tuanku itu, beritahukanlah kepadaku; dan jika tidak, beritahukanlah juga kepadaku, supaya aku tahu entah berpaling ke kanan atau ke kiri."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 50, 'Lalu Laban dan Betuel menjawab: "Semuanya ini datangnya dari TUHAN; kami tidak dapat mengatakan kepadamu baiknya atau buruknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 51, 'Lihat, Ribka ada di depanmu, bawalah dia dan pergilah, supaya ia menjadi isteri anak tuanmu, seperti yang difirmankan TUHAN."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 52, 'Ketika hamba Abraham itu mendengar perkataan mereka, sujudlah ia sampai ke tanah menyembah TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 53, 'Kemudian hamba itu mengeluarkan perhiasan emas dan perak serta pakaian kebesaran, dan memberikan semua itu kepada Ribka; juga kepada saudaranya dan kepada ibunya diberikannya pemberian yang indah-indah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 54, 'Sesudah itu makan dan minumlah mereka, ia dan orang-orang yang bersama-sama dengan dia, dan mereka bermalam di situ. Paginya sesudah mereka bangun, berkatalah hamba itu: "Lepaslah aku pulang kepada tuanku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 55, 'Tetapi saudara Ribka berkata, serta ibunya juga: "Biarkanlah anak gadis itu tinggal pada kami barang sepuluh hari lagi, kemudian bolehlah engkau pergi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 56, 'Tetapi jawabnya kepada mereka: "Janganlah tahan aku, sedang TUHAN telah membuat perjalananku berhasil; lepaslah aku, supaya aku pulang kepada tuanku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 57, 'Kata mereka: "Baiklah kita panggil anak gadis itu dan menanyakan kepadanya sendiri."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 58, 'Lalu mereka memanggil Ribka dan berkata kepadanya: "Maukah engkau pergi beserta orang ini?" Jawabnya: "Mau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 59, 'Maka Ribka, saudara mereka itu, dan inang pengasuhnya beserta hamba Abraham dan orang-orangnya dibiarkan mereka pergi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 24, 60, 'Dan mereka memberkati Ribka, kata mereka kepadanya: "Saudara kami, moga-moga engkau menjadi beribu-ribu laksa, dan moga-moga keturunanmu menduduki kota-kota musuhnya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 1, 'Abraham mengambil pula seorang isteri, namanya Ketura.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 2, 'Perempuan itu melahirkan baginya Zimran, Yoksan, Medan, Midian, Isybak dan Suah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 3, 'Yoksan memperanakkan Syeba dan Dedan. Keturunan Dedan ialah orang Asyur, orang Letush dan orang Leum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 4, 'Anak-anak Midian ialah Efa, Efer, Henokh, Abida dan Eldaa. Itulah semuanya keturunan Ketura.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 5, 'Abraham memberikan segala harta miliknya kepada Ishak,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 6, 'tetapi kepada anak-anaknya yang diperolehnya dari gundik-gundiknya ia memberikan pemberian; kemudian ia menyuruh mereka?masih pada waktu ia hidup?meninggalkan Ishak, anaknya, dan pergi ke sebelah timur, ke Tanah Timur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 7, 'Abraham mencapai umur seratus tujuh puluh lima tahun,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 8, 'lalu ia meninggal. Ia mati pada waktu telah putih rambutnya, tua dan suntuk umur, maka ia dikumpulkan kepada kaum leluhurnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 9, 'Dan anak-anaknya, Ishak dan Ismael, menguburkan dia dalam gua Makhpela, di padang Efron bin Zohar, orang Het itu, padang yang letaknya di sebelah timur Mamre,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 10, 'yang telah dibeli Abraham dari bani Het; di sanalah terkubur Abraham dan Sara isterinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 11, 'Setelah Abraham mati, Allah memberkati Ishak, anaknya itu; dan Ishak diam dekat sumur Lahai-Roi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 12, 'Inilah keturunan Ismael, anak Abraham, yang telah dilahirkan baginya oleh Hagar, perempuan Mesir, hamba Sara itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 13, 'Inilah nama anak-anak Ismael, disebutkan menurut urutan lahirnya: Nebayot, anak sulung Ismael, selanjutnya Kedar, Adbeel, Mibsam,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 14, 'Misyma, Duma, Masa,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 15, 'Hadad, Tema, Yetur, Nafish dan Kedma.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 16, 'Itulah anak-anak Ismael, dan itulah nama-nama mereka, menurut kampung mereka dan menurut perkemahan mereka, dua belas orang raja, masing-masing dengan sukunya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 17, 'Umur Ismael ialah seratus tiga puluh tujuh tahun. Sesudah itu ia meninggal. Ia mati dan dikumpulkan kepada kaum leluhurnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 18, 'Mereka itu mendiami daerah dari Hawila sampai Syur, yang letaknya di sebelah timur Mesir ke arah Asyur. Mereka menetap berhadapan dengan semua saudara mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 19, 'Inilah riwayat keturunan Ishak, anak Abraham. Abraham memperanakkan Ishak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 20, 'Dan Ishak berumur empat puluh tahun, ketika Ribka, anak Betuel, orang Aram dari Padan-Aram, saudara perempuan Laban orang Aram itu, diambilnya menjadi isterinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 21, 'Berdoalah Ishak kepada TUHAN untuk isterinya, sebab isterinya itu mandul; TUHAN mengabulkan doanya, sehingga Ribka, isterinya itu, mengandung.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 22, 'Tetapi anak-anaknya bertolak-tolakan di dalam rahimnya dan ia berkata: "Jika demikian halnya, mengapa aku hidup?" Dan ia pergi meminta petunjuk kepada TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 23, 'Firman TUHAN kepadanya: "Dua bangsa ada dalam kandunganmu, dan dua suku bangsa akan berpencar dari dalam rahimmu; suku bangsa yang satu akan lebih kuat dari yang lain, dan anak yang tua akan menjadi hamba kepada anak yang muda."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 24, 'Setelah genap harinya untuk bersalin, memang anak kembar yang di dalam kandungannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 25, 'Keluarlah yang pertama, warnanya merah, seluruh tubuhnya seperti jubah berbulu; sebab itu ia dinamai Esau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 26, 'Sesudah itu keluarlah adiknya; tangannya memegang tumit Esau, sebab itu ia dinamai Yakub. Ishak berumur enam puluh tahun pada waktu mereka lahir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 27, 'Lalu bertambah besarlah kedua anak itu: Esau menjadi seorang yang pandai berburu, seorang yang suka tinggal di padang, tetapi Yakub adalah seorang yang tenang, yang suka tinggal di kemah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 28, 'Ishak sayang kepada Esau, sebab ia suka makan daging buruan, tetapi Ribka kasih kepada Yakub.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 29, 'Pada suatu kali Yakub sedang memasak sesuatu, lalu datanglah Esau dengan lelah dari padang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 30, 'Kata Esau kepada Yakub: "Berikanlah kiranya aku menghirup sedikit dari yang merah-merah itu, karena aku lelah." Itulah sebabnya namanya disebutkan Edom.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 31, 'Tetapi kata Yakub: "Juallah dahulu kepadaku hak kesulunganmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 32, 'Sahut Esau: "Sebentar lagi aku akan mati; apakah gunanya bagiku hak kesulungan itu?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 33, 'Kata Yakub: "Bersumpahlah dahulu kepadaku." Maka bersumpahlah ia kepada Yakub dan dijualnyalah hak kesulungannya kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 25, 34, 'Lalu Yakub memberikan roti dan masakan kacang merah itu kepada Esau; ia makan dan minum, lalu berdiri dan pergi. Demikianlah Esau memandang ringan hak kesulungan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 1, 'Maka timbullah kelaparan di negeri itu. ?Ini bukan kelaparan yang pertama, yang telah terjadi dalam zaman Abraham. Sebab itu Ishak pergi ke Gerar, kepada Abimelekh, raja orang Filistin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 2, 'Lalu TUHAN menampakkan diri kepadanya serta berfirman: "Janganlah pergi ke Mesir, diamlah di negeri yang akan Kukatakan kepadamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 3, 'Tinggallah di negeri ini sebagai orang asing, maka Aku akan menyertai engkau dan memberkati engkau, sebab kepadamulah dan kepada keturunanmu akan Kuberikan seluruh negeri ini, dan Aku akan menepati sumpah yang telah Kuikrarkan kepada Abraham, ayahmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 4, 'Aku akan membuat banyak keturunanmu seperti bintang di langit; Aku akan memberikan kepada keturunanmu seluruh negeri ini, dan oleh keturunanmu semua bangsa di bumi akan mendapat berkat,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 5, 'karena Abraham telah mendengarkan firman-Ku dan memelihara kewajibannya kepada-Ku, yaitu segala perintah, ketetapan dan hukum-Ku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 6, 'Jadi tinggallah Ishak di Gerar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 7, 'Ketika orang-orang di tempat itu bertanya tentang isterinya, berkatalah ia: "Dia saudaraku," sebab ia takut mengatakan: "Ia isteriku," karena pikirnya: "Jangan-jangan aku dibunuh oleh penduduk tempat ini karena Ribka, sebab elok parasnya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 8, 'Setelah beberapa lama ia ada di sana, pada suatu kali menjenguklah Abimelekh, raja orang Filistin itu dari jendela, maka dilihatnya Ishak sedang bercumbu-cumbuan dengan Ribka, isterinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 9, 'Lalu Abimelekh memanggil Ishak dan berkata: "Sesungguhnya dia isterimu, masakan engkau berkata: Dia saudaraku?" Jawab Ishak kepadanya: "Karena pikirku: Jangan-jangan aku mati karena dia."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 10, 'Tetapi Abimelekh berkata: "Apakah juga yang telah kauperbuat ini terhadap kami? Mudah sekali terjadi, salah seorang dari bangsa ini tidur dengan isterimu, sehingga dengan demikian engkau mendatangkan kesalahan atas kami."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 11, 'Lalu Abimelekh memberi perintah kepada seluruh bangsa itu: "Siapa yang mengganggu orang ini atau isterinya, pastilah ia akan dihukum mati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 12, 'Maka menaburlah Ishak di tanah itu dan dalam tahun itu juga ia mendapat hasil seratus kali lipat; sebab ia diberkati TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 13, 'Dan orang itu menjadi kaya, bahkan kian lama kian kaya, sehingga ia menjadi sangat kaya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 14, 'Ia mempunyai kumpulan kambing domba dan lembu sapi serta banyak anak buah, sehingga orang Filistin itu cemburu kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 15, 'Segala sumur, yang digali dalam zaman Abraham, ayahnya, oleh hamba-hamba ayahnya itu, telah ditutup oleh orang Filistin dan ditimbun dengan tanah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 16, 'Lalu kata Abimelekh kepada Ishak: "Pergilah dari tengah-tengah kami sebab engkau telah menjadi jauh lebih berkuasa dari pada kami."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 17, 'Jadi pergilah Ishak dari situ dan berkemahlah ia di lembah Gerar, dan ia menetap di situ.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 18, 'Kemudian Ishak menggali kembali sumur-sumur yang digali dalam zaman Abraham, ayahnya, dan yang telah ditutup oleh orang Filistin sesudah Abraham mati; disebutkannyalah nama sumur-sumur itu menurut nama-nama yang telah diberikan oleh ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 19, 'Ketika hamba-hamba Ishak menggali di lembah itu, mereka mendapati di situ mata air yang berbual-bual airnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 20, 'Lalu bertengkarlah para gembala Gerar dengan para gembala Ishak. Kata mereka: "Air ini kepunyaan kami." Dan Ishak menamai sumur itu Esek, karena mereka bertengkar dengan dia di sana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 21, 'Kemudian mereka menggali sumur lain, dan mereka bertengkar juga tentang itu. Maka Ishak menamai sumur itu Sitna.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 22, 'Ia pindah dari situ dan menggali sumur yang lain lagi, tetapi tentang sumur ini mereka tidak bertengkar. Sumur ini dinamainya Rehobot, dan ia berkata: "Sekarang TUHAN telah memberikan kelonggaran kepada kita, sehingga kita dapat beranak cucu di negeri ini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 23, 'Dari situ ia pergi ke Bersyeba.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 24, 'Lalu pada malam itu TUHAN menampakkan diri kepadanya serta berfirman: "Akulah Allah ayahmu Abraham; janganlah takut, sebab Aku menyertai engkau; Aku akan memberkati engkau dan membuat banyak keturunanmu karena Abraham, hamba-Ku itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 25, 'Sesudah itu Ishak mendirikan mezbah di situ dan memanggil nama TUHAN. Ia memasang kemahnya di situ, lalu hamba-hambanya menggali sumur di situ.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 26, 'Datanglah Abimelekh dari Gerar mendapatkannya, bersama-sama dengan Ahuzat, sahabatnya, dan Pikhol, kepala pasukannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 27, 'Tetapi kata Ishak kepada mereka: "Mengapa kamu datang mendapatkan aku? Bukankah kamu benci kepadaku, dan telah menyuruh aku keluar dari tanahmu?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 28, 'Jawab mereka: "Kami telah melihat sendiri, bahwa TUHAN menyertai engkau; sebab itu kami berkata: baiklah kita mengadakan sumpah setia, antara kami dan engkau; dan baiklah kami mengikat perjanjian dengan engkau,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 29, 'bahwa engkau tidak akan berbuat jahat kepada kami, seperti kami tidak mengganggu engkau, dan seperti kami semata-mata berbuat baik kepadamu dan membiarkan engkau pergi dengan damai; bukankah engkau sekarang yang diberkati TUHAN."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 30, 'Kemudian Ishak mengadakan perjamuan bagi mereka, lalu mereka makan dan minum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 31, 'Keesokan harinya pagi-pagi bersumpah-sumpahanlah mereka. Kemudian Ishak melepas mereka, dan mereka meninggalkan dia dengan damai.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 32, 'Pada hari itu datanglah hamba-hamba Ishak memberitahukan kepadanya tentang sumur yang telah digali mereka, serta berkata kepadanya: "Kami telah mendapat air."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 33, 'Lalu dinamainyalah sumur itu Syeba. Sebab itu nama kota itu adalah Bersyeba, sampai sekarang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 34, 'Ketika Esau telah berumur empat puluh tahun, ia mengambil Yudit, anak Beeri orang Het, dan Basmat, anak Elon orang Het, menjadi isterinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 26, 35, 'Kedua perempuan itu menimbulkan kepedihan hati bagi Ishak dan bagi Ribka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 1, 'Ketika Ishak sudah tua, dan matanya telah kabur, sehingga ia tidak dapat melihat lagi, dipanggilnyalah Esau, anak sulungnya, serta berkata kepadanya: "Anakku." Sahut Esau: "Ya, bapa."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 2, 'Berkatalah Ishak: "Lihat, aku sudah tua, aku tidak tahu bila hari kematianku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 3, 'Maka sekarang, ambillah senjatamu, tabung panah dan busurmu, pergilah ke padang dan burulah bagiku seekor binatang;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 4, 'olahlah bagiku makanan yang enak, seperti yang kugemari, sesudah itu bawalah kepadaku, supaya kumakan, agar aku memberkati engkau, sebelum aku mati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 5, 'Tetapi Ribka mendengarkannya, ketika Ishak berkata kepada Esau, anaknya. Setelah Esau pergi ke padang memburu seekor binatang untuk dibawanya kepada ayahnya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 6, 'berkatalah Ribka kepada Yakub, anaknya: "Telah kudengar ayahmu berkata kepada Esau, kakakmu:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 7, 'Bawalah bagiku seekor binatang buruan dan olahlah bagiku makanan yang enak, supaya kumakan, dan supaya aku memberkati engkau di hadapan TUHAN, sebelum aku mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 8, 'Maka sekarang, anakku, dengarkanlah perkataanku seperti yang kuperintahkan kepadamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 9, 'Pergilah ke tempat kambing domba kita, ambillah dari sana dua anak kambing yang baik, maka aku akan mengolahnya menjadi makanan yang enak bagi ayahmu, seperti yang digemarinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 10, 'Bawalah itu kepada ayahmu, supaya dimakannya, agar dia memberkati engkau, sebelum ia mati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 11, 'Lalu kata Yakub kepada Ribka, ibunya: "Tetapi Esau, kakakku, adalah seorang yang berbulu badannya, sedang aku ini kulitku licin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 12, 'Mungkin ayahku akan meraba aku; maka nanti ia akan menyangka bahwa aku mau memperolok-olokkan dia; dengan demikian aku akan mendatangkan kutuk atas diriku dan bukan berkat."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 13, 'Tetapi ibunya berkata kepadanya: "Akulah yang menanggung kutuk itu, anakku; dengarkan saja perkataanku, pergilah ambil kambing-kambing itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 14, 'Lalu ia pergi mengambil kambing-kambing itu dan membawanya kepada ibunya; sesudah itu ibunya mengolah makanan yang enak, seperti yang digemari ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 15, 'Kemudian Ribka mengambil pakaian yang indah kepunyaan Esau, anak sulungnya, pakaian yang disimpannya di rumah, lalu disuruhnyalah dikenakan oleh Yakub, anak bungsunya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 16, 'Dan kulit anak kambing itu dipalutkannya pada kedua tangan Yakub dan pada lehernya yang licin itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 17, 'Lalu ia memberikan makanan yang enak dan roti yang telah diolahnya itu kepada Yakub, anaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 18, 'Demikianlah Yakub masuk ke tempat ayahnya serta berkata: "Bapa!" Sahut ayahnya: "Ya, anakku; siapakah engkau?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 19, 'Kata Yakub kepada ayahnya: "Akulah Esau, anak sulungmu. Telah kulakukan, seperti yang bapa katakan kepadaku. Bangunlah, duduklah dan makanlah daging buruan masakanku ini, agar bapa memberkati aku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 20, 'Lalu Ishak berkata kepada anaknya itu: "Lekas juga engkau mendapatnya, anakku!" Jawabnya: "Karena TUHAN, Allahmu, membuat aku mencapai tujuanku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 21, 'Lalu kata Ishak kepada Yakub: "Datanglah mendekat, anakku, supaya aku meraba engkau, apakah engkau ini anakku Esau atau bukan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 22, 'Maka Yakub mendekati Ishak, ayahnya, dan ayahnya itu merabanya serta berkata: "Kalau suara, suara Yakub; kalau tangan, tangan Esau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 23, 'Jadi Ishak tidak mengenal dia, karena tangannya berbulu seperti tangan Esau, kakaknya. Ishak hendak memberkati dia,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 24, 'tetapi ia masih bertanya: "Benarkah engkau ini anakku Esau?" Jawabnya: "Ya!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 25, 'Lalu berkatalah Ishak: "Dekatkanlah makanan itu kepadaku, supaya kumakan daging buruan masakan anakku, agar aku memberkati engkau." Jadi didekatkannyalah makanan itu kepada ayahnya, lalu ia makan, dibawanya juga anggur kepadanya, lalu ia minum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 26, 'Berkatalah Ishak, ayahnya, kepadanya: "Datanglah dekat-dekat dan ciumlah aku, anakku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 27, 'Lalu datanglah Yakub dekat-dekat dan diciumnyalah ayahnya. Ketika Ishak mencium bau pakaian Yakub, diberkatinyalah dia, katanya: "Sesungguhnya bau anakku adalah sebagai bau padang yang diberkati TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 28, 'Allah akan memberikan kepadamu embun yang dari langit dan tanah-tanah gemuk di bumi dan gandum serta anggur berlimpah-limpah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 29, 'Bangsa-bangsa akan takluk kepadamu, dan suku-suku bangsa akan sujud kepadamu; jadilah tuan atas saudara-saudaramu, dan anak-anak ibumu akan sujud kepadamu. Siapa yang mengutuk engkau, terkutuklah ia, dan siapa yang memberkati engkau, diberkatilah ia."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 30, 'Setelah Ishak selesai memberkati Yakub, dan baru saja Yakub keluar meninggalkan Ishak, ayahnya, pulanglah Esau, kakaknya, dari berburu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 31, 'Ia juga menyediakan makanan yang enak, lalu membawanya kepada ayahnya. Katanya kepada ayahnya: "Bapa, bangunlah dan makan daging buruan masakan anakmu, agar engkau memberkati aku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 32, 'Tetapi kata Ishak, ayahnya, kepadanya: "Siapakah engkau ini?" Sahutnya: "Akulah anakmu, anak sulungmu, Esau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 33, 'Lalu terkejutlah Ishak dengan sangat serta berkata: "Siapakah gerangan dia, yang memburu binatang itu dan yang telah membawanya kepadaku? Aku telah memakan semuanya, sebelum engkau datang, dan telah memberkati dia; dan dia akan tetap orang yang diberkati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 34, 'Sesudah Esau mendengar perkataan ayahnya itu, meraung-raunglah ia dengan sangat keras dalam kepedihan hatinya serta berkata kepada ayahnya: "Berkatilah aku ini juga, ya bapa!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 35, 'Jawab ayahnya: "Adikmu telah datang dengan tipu daya dan telah merampas berkat yang untukmu itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 36, 'Kata Esau: "Bukankah tepat namanya Yakub, karena ia telah dua kali menipu aku. Hak kesulunganku telah dirampasnya, dan sekarang dirampasnya pula berkat yang untukku." Lalu katanya: "Apakah bapa tidak mempunyai berkat lain bagiku?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 37, 'Lalu Ishak menjawab Esau, katanya: "Sesungguhnya telah kuangkat dia menjadi tuan atas engkau, dan segala saudaranya telah kuberikan kepadanya menjadi hambanya, dan telah kubekali dia dengan gandum dan anggur; maka kepadamu, apa lagi yang dapat kuperbuat, ya anakku?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 38, 'Kata Esau kepada ayahnya: "Hanya berkat yang satu itukah ada padamu, ya bapa? Berkatilah aku ini juga, ya bapa!" Dan dengan suara keras menangislah Esau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 39, 'Lalu Ishak, ayahnya, menjawabnya: "Sesungguhnya tempat kediamanmu akan jauh dari tanah-tanah gemuk di bumi dan jauh dari embun dari langit di atas.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 40, 'Engkau akan hidup dari pedangmu dan engkau akan menjadi hamba adikmu. Tetapi akan terjadi kelak, apabila engkau berusaha sungguh-sungguh, maka engkau akan melemparkan kuk itu dari tengkukmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 41, 'Esau menaruh dendam kepada Yakub karena berkat yang telah diberikan oleh ayahnya kepadanya, lalu ia berkata kepada dirinya sendiri: "Hari-hari berkabung karena kematian ayahku itu tidak akan lama lagi; pada waktu itulah Yakub, adikku, akan kubunuh."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 42, 'Ketika diberitahukan perkataan Esau, anak sulungnya itu kepada Ribka, maka disuruhnyalah memanggil Yakub, anak bungsunya, lalu berkata kepadanya: "Esau, kakakmu, bermaksud membalas dendam membunuh engkau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 43, 'Jadi sekarang, anakku, dengarkanlah perkataanku, bersiaplah engkau dan larilah kepada Laban, saudaraku, ke Haran,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 44, 'dan tinggallah padanya beberapa waktu lamanya, sampai kegeraman', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 45, 'dan kemarahan kakakmu itu surut dari padamu, dan ia lupa apa yang telah engkau perbuat kepadanya; kemudian aku akan menyuruh orang menjemput engkau dari situ. Mengapa aku akan kehilangan kamu berdua pada satu hari juga?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 27, 46, 'Kemudian Ribka berkata kepada Ishak: "Aku telah jemu hidup karena perempuan-perempuan Het itu; jikalau Yakub juga mengambil seorang isteri dari antara perempuan negeri ini, semacam perempuan Het itu, apa gunanya aku hidup lagi?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 1, 'Kemudian Ishak memanggil Yakub, lalu memberkati dia serta memesankan kepadanya, katanya: "Janganlah mengambil isteri dari perempuan Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 2, 'Bersiaplah, pergilah ke Padan-Aram, ke rumah Betuel, ayah ibumu, dan ambillah dari situ seorang isteri dari anak-anak Laban, saudara ibumu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 3, 'Moga-moga Allah Yang Mahakuasa memberkati engkau, membuat engkau beranak cucu dan membuat engkau menjadi banyak, sehingga engkau menjadi sekumpulan bangsa-bangsa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 4, 'Moga-moga Ia memberikan kepadamu berkat yang untuk Abraham, kepadamu serta kepada keturunanmu, sehingga engkau memiliki negeri ini yang kaudiami sebagai orang asing, yang telah diberikan Allah kepada Abraham."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 5, 'Demikianlah Ishak melepas Yakub, lalu berangkatlah Yakub ke Padan-Aram, kepada Laban anak Betuel, orang Aram itu, saudara Ribka ibu Yakub dan Esau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 6, 'Ketika Esau melihat, bahwa Ishak telah memberkati Yakub dan melepasnya ke Padan-Aram untuk mengambil isteri dari situ?pada waktu ia memberkatinya ia telah memesankan kepada Yakub: "Janganlah ambil isteri dari antara perempuan Kanaan" ?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 7, 'dan bahwa Yakub mendengarkan perkataan ayah dan ibunya, dan pergi ke Padan-Aram,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 8, 'maka Esaupun menyadari, bahwa perempuan Kanaan itu tidak disukai oleh Ishak, ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 9, 'Sebab itu ia pergi kepada Ismael dan mengambil Mahalat menjadi isterinya, di samping kedua isterinya yang telah ada. Mahalat adalah anak Ismael anak Abraham, adik Nebayot.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 10, 'Maka Yakub berangkat dari Bersyeba dan pergi ke Haran.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 11, 'Ia sampai di suatu tempat, dan bermalam di situ, karena matahari telah terbenam. Ia mengambil sebuah batu yang terletak di tempat itu dan dipakainya sebagai alas kepala, lalu membaringkan dirinya di tempat itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 12, 'Maka bermimpilah ia, di bumi ada didirikan sebuah tangga yang ujungnya sampai di langit, dan tampaklah malaikat-malaikat Allah turun naik di tangga itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 13, 'Berdirilah TUHAN di sampingnya dan berfirman: "Akulah TUHAN, Allah Abraham, nenekmu, dan Allah Ishak; tanah tempat engkau berbaring ini akan Kuberikan kepadamu dan kepada keturunanmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 14, 'Keturunanmu akan menjadi seperti debu tanah banyaknya, dan engkau akan mengembang ke sebelah timur, barat, utara dan selatan, dan olehmu serta keturunanmu semua kaum di muka bumi akan mendapat berkat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 15, 'Sesungguhnya Aku menyertai engkau dan Aku akan melindungi engkau, ke manapun engkau pergi, dan Aku akan membawa engkau kembali ke negeri ini, sebab Aku tidak akan meninggalkan engkau, melainkan tetap melakukan apa yang Kujanjikan kepadamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 16, 'Ketika Yakub bangun dari tidurnya, berkatalah ia: "Sesungguhnya TUHAN ada di tempat ini, dan aku tidak mengetahuinya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 17, 'Ia takut dan berkata: "Alangkah dahsyatnya tempat ini. Ini tidak lain dari rumah Allah, ini pintu gerbang sorga."v', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 18, 'Keesokan harinya pagi-pagi Yakub mengambil batu yang dipakainya sebagai alas kepala dan mendirikan itu menjadi tugu dan menuang minyak ke atasnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 19, 'Ia menamai tempat itu Betel; dahulu nama kota itu Lus.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 20, 'Lalu bernazarlah Yakub: "Jika Allah akan menyertai dan akan melindungi aku di jalan yang kutempuh ini, memberikan kepadaku roti untuk dimakan dan pakaian untuk dipakai,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 21, 'sehingga aku selamat kembali ke rumah ayahku, maka TUHAN akan menjadi Allahku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 28, 22, 'Dan batu yang kudirikan sebagai tugu ini akan menjadi rumah Allah. Dari segala sesuatu yang Engkau berikan kepadaku akan selalu kupersembahkan sepersepuluh kepada-Mu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 1, 'Kemudian berangkatlah Yakub dari situ dan pergi ke negeri Bani Timur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 2, 'Ketika ia memandang sekelilingnya, dilihatnya ada sebuah sumur di padang, dan ada tiga kumpulan kambing domba berbaring di dekatnya, sebab dari sumur itulah orang memberi minum kumpulan-kumpulan kambing domba itu. Adapun batu penutup sumur itu besar;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 3, 'dan apabila segala kumpulan kambing domba itu digiring berkumpul ke sana, maka gembala-gembala menggulingkan batu itu dari mulut sumur, lalu kambing domba itu diberi minum; kemudian dikembalikanlah batu itu lagi ke mulut sumur itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 4, 'Bertanyalah Yakub kepada mereka: "Saudara-saudara, dari manakah kamu ini?" Jawab mereka: "Kami ini dari Haran."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 5, 'Lagi katanya kepada mereka: "Kenalkah kamu Laban, cucu Nahor?" Jawab mereka: "Kami kenal."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 6, 'Selanjutnya katanya kepada mereka: "Selamatkah ia?" Jawab mereka: "Selamat! Tetapi lihat, itu datang anaknya perempuan, Rahel, dengan kambing dombanya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 7, 'Lalu kata Yakub: "Hari masih siang, belum waktunya untuk mengumpulkan ternak; berilah minum kambing dombamu itu, kemudian pergilah menggembalakannya lagi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 8, 'Tetapi jawab mereka: "Kami tidak dapat melakukan itu selama segala kumpulan binatang itu belum berkumpul; barulah batu itu digulingkan dari mulut sumur dan kami memberi minum kambing domba kami."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 9, 'Selagi ia berkata-kata dengan mereka, datanglah Rahel dengan kambing domba ayahnya, sebab dialah yang menggembalakannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 10, 'Ketika Yakub melihat Rahel, anak Laban saudara ibunya, serta kambing domba Laban, ia datang mendekat, lalu menggulingkan batu itu dari mulut sumur, dan memberi minum kambing domba itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 11, 'Kemudian Yakub mencium Rahel serta menangis dengan suara keras.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 12, 'Lalu Yakub menceritakan kepada Rahel, bahwa ia sanak saudara ayah Rahel, dan anak Ribka. Maka berlarilah Rahel menceritakannya kepada ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 13, 'Segera sesudah Laban mendengar kabar tentang Yakub, anak saudaranya itu, berlarilah ia menyongsong dia, lalu mendekap dan mencium dia, kemudian membawanya ke rumahnya. Maka Yakub menceritakan segala hal ihwalnya kepada Laban.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 14, 'Kata Laban kepadanya: "Sesungguhnya engkau sedarah sedaging dengan aku." Maka tinggallah Yakub padanya genap sebulan lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 15, 'Kemudian berkatalah Laban kepada Yakub: "Masakan karena engkau adalah sanak saudaraku, engkau bekerja padaku dengan cuma-cuma? Katakanlah kepadaku apa yang patut menjadi upahmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 16, 'Laban mempunyai dua anak perempuan; yang lebih tua namanya Lea dan yang lebih muda namanya Rahel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 17, 'Lea tidak berseri matanya, tetapi Rahel itu elok sikapnya dan cantik parasnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 18, 'Yakub cinta kepada Rahel, sebab itu ia berkata: "Aku mau bekerja padamu tujuh tahun lamanya untuk mendapat Rahel, anakmu yang lebih muda itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 19, 'Sahut Laban: "Lebih baiklah ia kuberikan kepadamu dari pada kepada orang lain; maka tinggallah padaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 20, 'Jadi bekerjalah Yakub tujuh tahun lamanya untuk mendapat Rahel itu, tetapi yang tujuh tahun itu dianggapnya seperti beberapa hari saja, karena cintanya kepada Rahel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 21, 'Sesudah itu berkatalah Yakub kepada Laban: "Berikanlah kepadaku bakal isteriku itu, sebab jangka waktuku telah genap, supaya aku akan kawin dengan dia."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 22, 'Lalu Laban mengundang semua orang di tempat itu, dan mengadakan perjamuan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 23, 'Tetapi pada waktu malam diambilnyalah Lea, anaknya, lalu dibawanya kepada Yakub. Maka Yakubpun menghampiri dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 24, 'Lagipula Laban memberikan Zilpa, budaknya perempuan, kepada Lea, anaknya itu, menjadi budaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 25, 'Tetapi pada waktu pagi tampaklah bahwa itu Lea! Lalu berkatalah Yakub kepada Laban: "Apakah yang kauperbuat terhadap aku ini? Bukankah untuk mendapat Rahel aku bekerja padamu? Mengapa engkau menipu aku?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 26, 'Jawab Laban: "Tidak biasa orang berbuat demikian di tempat kami ini, mengawinkan adiknya lebih dahulu dari pada kakaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 27, 'Genapilah dahulu tujuh hari perkawinanmu dengan anakku ini; kemudian anakku yang lainpun akan diberikan kepadamu sebagai upah, asal engkau bekerja pula padaku tujuh tahun lagi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 28, 'Maka Yakub berbuat demikian; ia menggenapi ketujuh hari perkawinannya dengan Lea, kemudian Laban memberikan kepadanya Rahel, anaknya itu, menjadi isterinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 29, 'Lagipula Laban memberikan Bilha, budaknya perempuan, kepada Rahel, anaknya itu, menjadi budaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 30, 'Yakub menghampiri Rahel juga, malah ia lebih cinta kepada Rahel dari pada kepada Lea. Demikianlah ia bekerja pula pada Laban tujuh tahun lagi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 31, 'Ketika TUHAN melihat, bahwa Lea tidak dicintai, dibuka-Nyalah kandungannya, tetapi Rahel mandul.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 32, 'Lea mengandung, lalu melahirkan seorang anak laki-laki, dan menamainya Ruben, sebab katanya: "Sesungguhnya TUHAN telah memperhatikan kesengsaraanku; sekarang tentulah aku akan dicintai oleh suamiku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 33, 'Mengandung pulalah ia, lalu melahirkan seorang anak laki-laki, maka ia berkata: "Sesungguhnya, TUHAN telah mendengar, bahwa aku tidak dicintai, lalu diberikan-Nya pula anak ini kepadaku." Maka ia menamai anak itu Simeon.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 34, 'Mengandung pulalah ia, lalu melahirkan seorang anak laki-laki, maka ia berkata: "Sekali ini suamiku akan lebih erat kepadaku, karena aku telah melahirkan tiga anak laki-laki baginya." Itulah sebabnya ia menamai anak itu Lewi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 29, 35, 'Mengandung pulalah ia, lalu melahirkan seorang anak laki-laki, maka ia berkata: "Sekali ini aku akan bersyukur kepada TUHAN." Itulah sebabnya ia menamai anak itu Yehuda. Sesudah itu ia tidak melahirkan lagi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 1, 'Ketika dilihat Rahel, bahwa ia tidak melahirkan anak bagi Yakub, cemburulah ia kepada kakaknya itu, lalu berkata kepada Yakub: "Berikanlah kepadaku anak; kalau tidak, aku akan mati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 2, 'Maka bangkitlah amarah Yakub terhadap Rahel dan ia berkata: "Akukah pengganti Allah, yang telah menghalangi engkau mengandung?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 3, 'Kata Rahel: "Ini Bilha, budakku perempuan, hampirilah dia, supaya ia melahirkan anak di pangkuanku, dan supaya oleh dia akupun mempunyai keturunan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 4, 'Maka diberikannyalah Bilha, budaknya itu, kepada Yakub menjadi isterinya dan Yakub menghampiri budak itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 5, 'Bilha mengandung, lalu melahirkan seorang anak laki-laki bagi Yakub.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 6, 'Berkatalah Rahel: "Allah telah memberikan keadilan kepadaku, juga telah didengarkan-Nya permohonanku dan diberikan-Nya kepadaku seorang anak laki-laki." Itulah sebabnya ia menamai anak itu Dan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 7, 'Mengandung pulalah Bilha, budak perempuan Rahel, lalu melahirkan anak laki-laki yang kedua bagi Yakub.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 8, 'Berkatalah Rahel: "Aku telah sangat hebat bergulat dengan kakakku, dan akupun menang." Maka ia menamai anak itu Naftali.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 9, 'Ketika dilihat Lea, bahwa ia tidak melahirkan lagi, diambilnyalah Zilpa, budaknya perempuan, dan diberikannya kepada Yakub menjadi isterinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 10, 'Dan Zilpa, budak perempuan Lea, melahirkan seorang anak laki-laki bagi Yakub.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 11, 'Berkatalah Lea: "Mujur telah datang." Maka ia menamai anak itu Gad.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 12, 'Dan Zilpa, budak perempuan Lea, melahirkan anak laki-laki yang kedua bagi Yakub.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 13, 'Berkatalah Lea: "Aku ini berbahagia! Tentulah perempuan-perempuan akan menyebutkan aku berbahagia." Maka ia menamai anak itu Asyer.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 14, 'Ketika Ruben pada musim menuai gandum pergi berjalan-jalan, didapatinyalah di padang buah dudaim, lalu dibawanya kepada Lea, ibunya. Kata Rahel kepada Lea: "Berilah aku beberapa buah dudaim yang didapat oleh anakmu itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 15, 'Jawab Lea kepadanya: "Apakah belum cukup bagimu mengambil suamiku? Sekarang pula mau mengambil lagi buah dudaim anakku?" Kata Rahel: "Kalau begitu biarlah ia tidur dengan engkau pada malam ini sebagai ganti buah dudaim anakmu itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 16, 'Ketika Yakub pada waktu petang datang dari padang, pergilah Lea mendapatkannya, sambil berkata: "Engkau harus singgah kepadaku malam ini, sebab memang engkau telah kusewa dengan buah dudaim anakku." Sebab itu tidurlah Yakub dengan Lea pada malam itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 17, 'Lalu Allah mendengarkan permohonan Lea. Lea mengandung dan melahirkan anak laki-laki yang kelima bagi Yakub.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 18, 'Lalu kata Lea: "Allah telah memberi upahku, karena aku telah memberi budakku perempuan kepada suamiku." Maka ia menamai anak itu Isakhar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 19, 'Kemudian Lea mengandung pula dan melahirkan anak laki-laki yang keenam bagi Yakub.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 20, 'Berkatalah Lea: "Allah telah memberikan hadiah yang indah kepadaku; sekali ini suamiku akan tinggal bersama-sama dengan aku, karena aku telah melahirkan enam orang anak laki-laki baginya." Maka ia menamai anak itu Zebulon.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 21, 'Sesudah itu ia melahirkan seorang anak perempuan dan menamai anak itu Dina.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 22, 'Lalu ingatlah Allah akan Rahel; Allah mendengarkan permohonannya serta membuka kandungannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 23, 'Maka mengandunglah Rahel dan melahirkan seorang anak laki-laki. Berkatalah ia: "Allah telah menghapuskan aibku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 24, 'Maka ia menamai anak itu Yusuf, sambil berkata: "Mudah-mudahan TUHAN menambah seorang anak laki-laki lagi bagiku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 25, 'Setelah Rahel melahirkan Yusuf, berkatalah Yakub kepada Laban: "Izinkanlah aku pergi, supaya aku pulang ke tempat kelahiranku dan ke negeriku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 26, 'Berikanlah isteri-isteriku dan anak-anakku, yang menjadi upahku selama aku bekerja padamu, supaya aku pulang, sebab engkau tahu, betapa keras aku bekerja padamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 27, 'Tetapi Laban berkata kepadanya: "Sekiranya aku mendapat kasihmu! Telah nyata kepadaku, bahwa TUHAN memberkati aku karena engkau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 28, 'Lagi katanya: "Tentukanlah upahmu yang harus kubayar, maka aku akan memberikannya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 29, 'Sahut Yakub kepadanya: "Engkau sendiri tahu, bagaimana aku bekerja padamu, dan bagaimana keadaan ternakmu dalam penjagaanku,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 30, 'sebab harta milikmu tidak begitu banyak sebelum aku datang, tetapi sekarang telah berkembang dengan sangat, dan TUHAN telah memberkati engkau sejak aku berada di sini; jadi, bilakah dapat aku bekerja untuk rumah tanggaku sendiri?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 31, 'Kata Laban: "Apakah yang harus kuberikan kepadamu?" Jawab Yakub: "Tidak usah kauberikan apa-apa kepadaku; aku mau lagi menggembalakan kambing dombamu dan menjaganya, asal engkau mengizinkan hal ini kepadaku:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 32, 'Hari ini aku akan lewat dari tengah-tengah segala kambing dombamu dan akan mengasingkan dari situ setiap binatang yang berbintik-bintik dan berbelang-belang; segala domba yang hitam dan segala kambing yang berbelang-belang dan berbintik-bintik, itulah upahku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 33, 'Dan kejujuranku akan terbukti di kemudian hari, apabila engkau datang memeriksa upahku: Segala yang tidak berbintik-bintik atau berbelang-belang di antara kambing-kambing dan yang tidak hitam di antara domba-domba, anggaplah itu tercuri olehku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 34, 'Kemudian kata Laban: "Baik, jadilah seperti perkataanmu itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 35, 'Lalu diasingkannyalah pada hari itu kambing-kambing jantan yang bercoreng-coreng dan berbelang-belang dan segala kambing yang berbintik-bintik dan berbelang-belang, segala yang ada warna putih pada badannya, serta segala yang hitam di antara domba-domba, dan diserahkannyalah semuanya itu kepada anak-anaknya untuk dijaga.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 36, 'Kemudian Laban menentukan jarak tiga hari perjalanan jauhnya antara dia dan Yakub, maka tetaplah Yakub menggembalakan kambing domba yang tinggal itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 37, 'Lalu Yakub mengambil dahan hijau dari pohon hawar, pohon badam dan pohon berangan, dikupasnyalah dahan-dahan itu sehingga berbelang-belang, sampai yang putihnya kelihatan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 38, 'Ia meletakkan dahan-dahan yang dikupasnya itu dalam palungan, dalam tempat minum, ke mana kambing domba itu datang minum, sehingga tepat di depan kambing domba itu. Adapun kambing domba itu suka berkelamin pada waktu datang minum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 39, 'Jika kambing domba itu berkelamin dekat dahan-dahan itu, maka anaknya bercoreng-coreng, berbintik-bintik dan berbelang-belang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 40, 'Kemudian Yakub memisahkan domba-domba itu, dihadapkannya kepala-kepala kambing domba itu kepada yang bercoreng-coreng dan kepada segala yang hitam di antara kambing domba Laban. Demikianlah ia beroleh kumpulan-kumpulan hewan baginya sendiri, dan tidak ditempatkannya pada kambing domba Laban.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 41, 'Dan setiap kali, apabila berkelamin kambing domba yang kuat, maka Yakub meletakkan dahan-dahan itu ke dalam palungan di depan mata kambing domba itu, supaya berkelamin dekat dahan-dahan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 42, 'Tetapi apabila datang kambing domba yang lemah, ia tidak meletakkan dahan-dahan itu ke dalamnya. Jadi hewan yang lemah untuk Laban dan yang kuat untuk Yakub.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 30, 43, 'Maka sangatlah bertambah-tambah harta Yakub, dan ia mempunyai banyak kambing domba, budak perempuan dan laki-laki, unta dan keledai.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 1, 'Kedengaranlah kepada Yakub anak-anak Laban berkata demikian: "Yakub telah mengambil segala harta milik ayah kita dan dari harta itulah ia membangun segala kekayaannya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 2, 'Lagi kelihatan kepada Yakub dari muka Laban, bahwa Laban tidak lagi seperti yang sudah-sudah kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 3, 'Lalu berfirmanlah TUHAN kepada Yakub: "Pulanglah ke negeri nenek moyangmu dan kepada kaummu, dan Aku akan menyertai engkau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 4, 'Sesudah itu Yakub menyuruh memanggil Rahel dan Lea untuk datang ke padang, ke tempat kambing dombanya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 5, 'lalu ia berkata kepada mereka: "Telah kulihat dari muka ayahmu, bahwa ia tidak lagi seperti yang sudah-sudah kepadaku, tetapi Allah ayahku menyertai aku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 6, 'Juga kamu sendiri tahu, bahwa aku telah bekerja sekuat-kuatku pada ayahmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 7, 'Tetapi ayahmu telah berlaku curang kepadaku dan telah sepuluh kali mengubah upahku, tetapi Allah tidak membiarkan dia berbuat jahat kepadaku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 8, 'Apabila ia berkata: yang berbintik-bintiklah akan menjadi upahmu, maka segala kambing domba itu beroleh anak yang berbintik-bintik; dan apabila ia berkata: yang bercoreng-corenglah akan menjadi upahmu, maka segala kambing domba itu beroleh anak yang bercoreng-coreng.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 9, 'Demikianlah Allah mengambil ternak ayahmu dan memberikannya kepadaku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 10, 'Pada suatu kali pada masa kambing domba itu suka berkelamin, maka aku bermimpi dan melihat, bahwa jantan-jantan yang menjantani kambing domba itu bercoreng-coreng, berbintik-bintik dan berbelang-belang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 11, 'Dan Malaikat Allah berfirman kepadaku dalam mimpi itu: Yakub! Jawabku: Ya Tuhan!', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 12, 'Lalu Ia berfirman: Angkatlah mukamu dan lihatlah, bahwa segala jantan yang menjantani kambing domba itu bercoreng-coreng, berbintik-bintik dan berbelang-belang, sebab telah Kulihat semua yang dilakukan oleh Laban itu kepadamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 13, 'Akulah Allah yang di Betel itu, di mana engkau mengurapi tugu, dan di mana engkau bernazar kepada-Ku; maka sekarang, bersiaplah engkau, pergilah dari negeri ini dan pulanglah ke negeri sanak saudaramu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 14, 'Lalu Rahel dan Lea menjawab Yakub, katanya: "Bukankah tidak ada lagi bagian atau warisan kami dalam rumah ayah kami?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 15, 'Bukankah kami ini dianggapnya sebagai orang asing, karena ia telah menjual kami? Juga bagian kami telah dihabiskannya sama sekali.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 16, 'Tetapi segala kekayaan, yang telah diambil Allah dari ayah kami, adalah milik kami dan anak-anak kami; maka sekarang, perbuatlah segala yang difirmankan Allah kepadamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 17, 'Lalu bersiaplah Yakub, dinaikkannya anak-anaknya dan isteri-isterinya ke atas unta,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 18, 'digiringnya seluruh ternaknya dan segala apa yang telah diperolehnya, yakni ternak kepunyaannya, yang telah diperolehnya di Padan-Aram, dengan maksud pergi kepada Ishak, ayahnya, ke tanah Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 19, 'Adapun Laban telah pergi menggunting bulu domba-dombanya. Ketika itulah Rahel mencuri terafim ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 20, 'Dan Yakub mengakali Laban, orang Aram itu, dengan tidak memberitahukan kepadanya, bahwa ia mau lari.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 21, 'Demikianlah ia lari dengan segala harta miliknya. Ia berangkat, menyeberangi sungai Efrat dan berjalan menuju pegunungan Gilead.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 22, 'Ketika pada hari ketiga dikabarkan kepada Laban, bahwa Yakub telah lari,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 23, 'dibawanyalah sanak saudaranya bersama-sama, dikejarnya Yakub tujuh hari perjalanan jauhnya, lalu ia dapat menyusulnya di pegunungan Gilead.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 24, 'Pada waktu malam datanglah Allah dalam suatu mimpi kepada Laban, orang Aram itu, serta berfirman kepadanya: "Jagalah baik-baik, supaya engkau jangan mengatai Yakub dengan sepatah katapun."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 25, 'Ketika Laban sampai kepada Yakub, ?Yakub telah memasang kemahnya di pegunungan, juga Laban dengan sanak saudaranya telah memasang kemahnya di pegunungan Gilead?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 26, 'berkatalah Laban kepada Yakub: "Apakah yang kauperbuat ini, maka engkau mengakali aku dan mengangkut anak-anakku perempuan sebagai orang tawanan?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 27, 'Mengapa engkau lari diam-diam dan mengakali aku? Mengapa engkau tidak memberitahu kepadaku, supaya aku menghantarkan engkau dengan sukacita dan nyanyian dengan rebana dan kecapi?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 28, 'Lagipula engkau tidak memberikan aku kesempatan untuk mencium cucu-cucuku laki-laki dan anak-anakku perempuan. Memang bodoh perbuatanmu itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 29, 'Aku ini berkuasa untuk berbuat jahat kepadamu, tetapi Allah ayahmu telah berfirman kepadaku tadi malam: Jagalah baik-baik, jangan engkau mengatai Yakub dengan sepatah katapun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 30, 'Maka sekarang, kalau memang engkau harus pergi, semata-mata karena sangat rindu ke rumah ayahmu, mengapa engkau mencuri dewa-dewaku?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 31, 'Lalu Yakub menjawab Laban: "Aku takut, karena pikirku, jangan-jangan engkau merampas anak-anakmu itu dari padaku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 32, 'Tetapi pada siapa engkau menemui dewa-dewamu itu, janganlah ia hidup lagi. Periksalah di depan saudara-saudara kita segala barang yang ada padaku dan ambillah barangmu." Sebab Yakub tidak tahu, bahwa Rahel yang mencuri terafim itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 33, 'Lalu masuklah Laban ke dalam kemah Yakub dan ke dalam kemah Lea dan ke dalam kemah kedua budak perempuan itu, tetapi terafim itu tidak ditemuinya. Setelah keluar dari kemah Lea, ia masuk ke dalam kemah Rahel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 34, 'Tetapi Rahel telah mengambil terafim itu dan memasukkannya ke dalam pelana untanya, dan duduk di atasnya. Laban menggeledah seluruh kemah itu, tetapi terafim itu tidak ditemuinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 35, 'Lalu kata Rahel kepada ayahnya: "Janganlah bapa marah, karena aku tidak dapat bangun berdiri di depanmu, sebab aku sedang haid." Dan Laban mencari dengan teliti, tetapi ia tidak menemui terafim itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 36, 'Lalu hati Yakub panas dan ia bertengkar dengan Laban. Ia berkata kepada Laban: "Apakah kesalahanku, apakah dosaku, maka engkau memburu aku sehebat itu?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 37, 'Engkau telah menggeledah segala barangku, sekarang apakah yang kautemui dari segala barang rumahmu? Letakkanlah di sini di depan saudara-saudaraku dan saudara-saudaramu, supaya mereka mengadili antara kita berdua.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 38, 'Selama dua puluh tahun ini aku bersama-sama dengan engkau; domba dan kambing betinamu tidak pernah keguguran dan jantan dari kambing dombamu tidak pernah kumakan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 39, 'Yang diterkam oleh binatang buas tidak pernah kubawa kepadamu, aku sendiri yang menggantinya; yang dicuri orang, baik waktu siang, baik waktu malam, selalu engkau tuntut dari padaku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 40, 'Aku dimakan panas hari waktu siang dan kedinginan waktu malam, dan mataku jauh dari pada tertidur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 41, 'Selama dua puluh tahun ini aku di rumahmu; aku telah bekerja padamu empat belas tahun lamanya untuk mendapat kedua anakmu dan enam tahun untuk mendapat ternakmu, dan engkau telah sepuluh kali mengubah upahku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 42, 'Seandainya Allah ayahku, Allah Abraham dan Yang Disegani oleh Ishak tidak menyertai aku, tentulah engkau sekarang membiarkan aku pergi dengan tangan hampa; tetapi kesengsaraanku dan jerih payahku telah diperhatikan Allah dan Ia telah menjatuhkan putusan tadi malam."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 43, 'Lalu Laban menjawab Yakub: "Perempuan-perempuan ini anakku dan anak-anak lelaki ini cucuku dan ternak ini ternakku, bahkan segala yang kaulihat di sini adalah milikku; jadi apakah yang dapat kuperbuat sekarang kepada anak-anakku ini atau kepada anak-anak yang dilahirkan mereka?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 44, 'Maka sekarang, marilah kita mengikat perjanjian, aku dan engkau, supaya itu menjadi kesaksian antara aku dan engkau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 45, 'Kemudian Yakub mengambil sebuah batu dan didirikannya menjadi tugu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 46, 'Selanjutnya berkatalah Yakub kepada sanak saudaranya: "Kumpulkanlah batu." Maka mereka mengambil batu dan membuat timbunan, lalu makanlah mereka di sana di dekat timbunan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 47, 'Laban menamai timbunan batu itu Yegar-Sahaduta, tetapi Yakub menamainya Galed.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 48, 'Lalu kata Laban: "Timbunan batu inilah pada hari ini menjadi kesaksian antara aku dan engkau." Itulah sebabnya timbunan itu dinamainya Galed,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 49, 'dan juga Mizpa, sebab katanya: "TUHAN kiranya berjaga-jaga antara aku dan engkau, apabila kita berjauhan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 50, 'Jika engkau mengaibkan anak-anakku, dan jika engkau mengambil isteri lain di samping anak-anakku itu, ingatlah, walaupun tidak ada orang dekat kita, Allah juga yang menjadi saksi antara aku dan engkau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 51, 'Selanjutnya kata Laban kepada Yakub: "Inilah timbunan batu, dan inilah tugu yang kudirikan antara aku dan engkau?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 52, 'timbunan batu dan tugu inilah menjadi kesaksian, bahwa aku tidak akan melewati timbunan batu ini mendapatkan engkau, dan bahwa engkaupun tidak akan melewati timbunan batu dan tugu ini mendapatkan aku, dengan berniat jahat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 53, 'Allah Abraham dan Allah Nahor, Allah ayah mereka, kiranya menjadi hakim antara kita." Lalu Yakub bersumpah demi Yang Disegani oleh Ishak, ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 54, 'Dan Yakub mempersembahkan korban sembelihan di gunung itu. Ia mengundang makan sanak saudaranya, lalu mereka makan serta bermalam di gunung itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 31, 55, 'Keesokan harinya pagi-pagi Laban mencium cucu-cucunya dan anak-anaknya serta memberkati mereka, kemudian pulanglah Laban kembali ke tempat tinggalnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 1, 'Yakub melanjutkan perjalanannya, lalu bertemulah malaikat-malaikat Allah dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 2, 'Ketika Yakub melihat mereka, berkatalah ia: "Ini bala tentara Allah." Sebab itu dinamainyalah tempat itu Mahanaim.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 3, 'Sesudah itu Yakub menyuruh utusannya berjalan lebih dahulu mendapatkan Esau, kakaknya, ke tanah Seir, daerah Edom.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 4, 'Ia memerintahkan kepada mereka: "Beginilah kamu katakan kepada tuanku, kepada Esau: Beginilah kata hambamu Yakub: Aku telah tinggal pada Laban sebagai orang asing dan diam di situ selama ini.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 5, 'Aku telah mempunyai lembu sapi, keledai dan kambing domba, budak laki-laki dan perempuan, dan aku menyuruh memberitahukan hal ini kepada tuanku, supaya aku mendapat kasihmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 6, 'Kemudian pulanglah para utusan itu kepada Yakub dan berkata: "Kami telah sampai kepada kakakmu, kepada Esau, dan iapun sedang di jalan menemui engkau, diiringi oleh empat ratus orang."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 7, 'Lalu sangat takutlah Yakub dan merasa sesak hati; maka dibaginyalah orang-orangnya yang bersama-sama dengan dia, kambing dombanya, lembu sapi dan untanya menjadi dua pasukan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 8, 'Sebab pikirnya: "Jika Esau datang menyerang pasukan yang satu, sehingga terpukul kalah, maka pasukan yang tinggal akan terluput."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 9, 'Kemudian berkatalah Yakub: "Ya Allah nenekku Abraham dan Allah ayahku Ishak, ya TUHAN, yang telah berfirman kepadaku: Pulanglah ke negerimu serta kepada sanak saudaramu dan Aku akan berbuat baik kepadamu?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 10, 'sekali-kali aku tidak layak untuk menerima segala kasih dan kesetiaan yang Engkau tunjukkan kepada hamba-Mu ini, sebab aku membawa hanya tongkatku ini waktu aku menyeberangi sungai Yordan ini, tetapi sekarang telah menjadi dua pasukan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 11, 'Lepaskanlah kiranya aku dari tangan kakakku, dari tangan Esau, sebab aku takut kepadanya, jangan-jangan ia datang membunuh aku, juga ibu-ibu dengan anak-anaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 12, 'Bukankah Engkau telah berfirman: Tentu Aku akan berbuat baik kepadamu dan menjadikan keturunanmu sebagai pasir di laut, yang karena banyaknya tidak dapat dihitung."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 13, 'Lalu bermalamlah ia di sana pada malam itu. Kemudian diambilnyalah dari apa yang ada padanya suatu persembahan untuk Esau, kakaknya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 14, 'yaitu dua ratus kambing betina dan dua puluh kambing jantan, dua ratus domba betina dan dua puluh domba jantan,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 15, 'tiga puluh unta yang sedang menyusui beserta anak-anaknya, empat puluh lembu betina dan sepuluh lembu jantan, dua puluh keledai betina dan sepuluh keledai jantan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 16, 'Diserahkannyalah semuanya itu kepada budak-budaknya untuk dijaga, tiap-tiap kumpulan tersendiri, dan ia berkata kepada mereka: "Berjalanlah kamu lebih dahulu dan jagalah supaya ada jarak antara kumpulan yang satu dengan kumpulan yang lain."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 17, 'Diperintahkannyalah kepada yang paling di muka: "Apabila Esau, kakakku, bertemu dengan engkau dan bertanya kepadamu: Siapakah tuanmu? dan ke manakah engkau pergi? dan milik siapakah ternak yang di depanmu itu? ?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 18, 'jawablah: milik hambamu Yakub; inilah persembahan yang dikirim kepada tuanku Esau, dan Yakub sendiripun ada di belakang kami."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 19, 'Begitulah diperintahkannya baik kepada yang kedua maupun kepada yang ketiga dan kepada sekalian orang yang berjalan menggiring kumpulan hewan itu, katanya: "Seperti perkataanku tadilah kamu katakan kepada Esau, apabila kamu berjumpa dengan dia;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 20, 'dan kamu harus mengatakan juga: Hambamu Yakub sendiri ada di belakang kami." Sebab pikir Yakub: "Baiklah aku mendamaikan hatinya dengan persembahan yang diantarkan lebih dahulu, kemudian barulah aku akan melihat mukanya; mungkin ia akan menerima aku dengan baik."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 21, 'Jadi persembahan itu diantarkan lebih dahulu, tetapi ia sendiri bermalam pada malam itu di tempat perkemahannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 22, 'Pada malam itu Yakub bangun dan ia membawa kedua isterinya, kedua budaknya perempuan dan kesebelas anaknya, dan menyeberang di tempat penyeberangan sungai Yabok.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 23, 'Sesudah ia menyeberangkan mereka, ia menyeberangkan juga segala miliknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 24, 'Lalu tinggallah Yakub seorang diri. Dan seorang laki-laki bergulat dengan dia sampai fajar menyingsing.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 25, 'Ketika orang itu melihat, bahwa ia tidak dapat mengalahkannya, ia memukul sendi pangkal paha Yakub, sehingga sendi pangkal paha itu terpelecok, ketika ia bergulat dengan orang itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 26, 'Lalu kata orang itu: "Biarkanlah aku pergi, karena fajar telah menyingsing." Sahut Yakub: "Aku tidak akan membiarkan engkau pergi, jika engkau tidak memberkati aku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 27, 'Bertanyalah orang itu kepadanya: "Siapakah namamu?" Sahutnya: "Yakub."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 28, 'Lalu kata orang itu: "Namamu tidak akan disebutkan lagi Yakub, tetapi Israel, sebab engkau telah bergumul melawan Allah dan manusia, dan engkau menang."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 29, 'Bertanyalah Yakub: "Katakanlah juga namamu." Tetapi sahutnya: "Mengapa engkau menanyakan namaku?" Lalu diberkatinyalah Yakub di situ.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 30, 'Yakub menamai tempat itu Pniel, sebab katanya: "Aku telah melihat Allah berhadapan muka, tetapi nyawaku tertolong!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 31, 'Lalu tampaklah kepadanya matahari terbit, ketika ia telah melewati Pniel; dan Yakub pincang karena pangkal pahanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 32, 32, 'Itulah sebabnya sampai sekarang orang Israel tidak memakan daging yang menutupi sendi pangkal paha, karena Dia telah memukul sendi pangkal paha Yakub, pada otot pangkal pahanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 1, 'Yakubpun melayangkan pandangnya, lalu dilihatnyalah Esau datang dengan diiringi oleh empat ratus orang. Maka diserahkannyalah sebagian dari anak-anak itu kepada Lea dan sebagian kepada Rahel serta kepada kedua budak perempuan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 2, 'Ia menempatkan budak-budak perempuan itu beserta anak-anak mereka di muka, Lea beserta anak-anaknya di belakang mereka, dan Rahel beserta Yusuf di belakang sekali.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 3, 'Dan ia sendiri berjalan di depan mereka dan ia sujud sampai ke tanah tujuh kali, hingga ia sampai ke dekat kakaknya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 4, 'Tetapi Esau berlari mendapatkan dia, didekapnya dia, dipeluk lehernya dan diciumnya dia, lalu bertangis-tangisanlah mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 5, 'Kemudian Esau melayangkan pandangnya, dilihatnyalah perempuan-perempuan dan anak-anak itu, lalu ia bertanya: "Siapakah orang-orang yang beserta engkau itu?" Jawab Yakub: "Anak-anak yang telah dikaruniakan Allah kepada hambamu ini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 6, 'Sesudah itu mendekatlah budak-budak perempuan itu beserta anak-anaknya, lalu mereka sujud.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 7, 'Mendekat jugalah Lea beserta anak-anaknya, dan merekapun sujud. Kemudian mendekatlah Yusuf beserta Rahel, dan mereka juga sujud.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 8, 'Berkatalah Esau: "Apakah maksudmu dengan seluruh pasukan, yang telah bertemu dengan aku tadi?" Jawabnya: "Untuk mendapat kasih tuanku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 9, 'Tetapi kata Esau: "Aku mempunyai banyak, adikku; peganglah apa yang ada padamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 10, 'Tetapi kata Yakub: "Janganlah kiranya demikian; jikalau aku telah mendapat kasihmu, terimalah persembahanku ini dari tanganku, karena memang melihat mukamu adalah bagiku serasa melihat wajah Allah, dan engkaupun berkenan menyambut aku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 11, 'Terimalah kiranya pemberian tanda salamku ini, yang telah kubawa kepadamu, sebab Allah telah memberi karunia kepadaku dan akupun mempunyai segala-galanya." Lalu dibujuk-bujuknyalah Esau, sehingga diterimanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 12, 'Kata Esau: "Baiklah kita berangkat berjalan terus; aku akan menyertai engkau."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 13, 'Tetapi Yakub berkata kepadanya: "Tuanku maklum, bahwa anak-anak ini masih kurang kuat, dan bahwa beserta aku ada kambing domba dan lembu sapi yang masih menyusui, jika diburu-buru, satu hari saja, maka seluruh kumpulan binatang itu akan mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 14, 'Biarlah kiranya tuanku berjalan lebih dahulu dari hambamu ini dan aku mau dengan hati-hati beringsut maju menurut langkah hewan, yang berjalan di depanku dan menurut langkah anak-anak, sampai aku tiba pada tuanku di Seir."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 15, 'Lalu kata Esau: "Kalau begitu, baiklah kutinggalkan padamu beberapa orang dari pengiringku." Tetapi Yakub berkata: "Tidak usah demikian! Biarlah aku mendapat kasih tuanku saja."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 16, 'Jadi pulanglah Esau pada hari itu berjalan ke Seir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 17, 'Tetapi Yakub berangkat ke Sukot, lalu mendirikan rumah, dan untuk ternaknya dibuatnya gubuk-gubuk. Itulah sebabnya tempat itu dinamai Sukot.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 18, 'Dalam perjalanannya dari Padan-Aram sampailah Yakub dengan selamat ke Sikhem, di tanah Kanaan, lalu ia berkemah di sebelah timur kota itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 19, 'Kemudian dibelinyalah dari anak-anak Hemor, bapa Sikhem, sebidang tanah, tempat ia memasang kemahnya, dengan harga seratus kesita.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 33, 20, 'Ia mendirikan mezbah di situ dan dinamainya itu: "Allah Israel ialah Allah."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 1, 'Pada suatu kali pergilah Dina, anak perempuan Lea yang dilahirkannya bagi Yakub, mengunjungi perempuan-perempuan di negeri itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 2, 'Ketika itu terlihatlah ia oleh Sikhem, anak Hemor, orang Hewi, raja negeri itu, lalu Dina itu dilarikannya dan diperkosanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 3, 'Tetapi terikatlah hatinya kepada Dina, anak Yakub; ia cinta kepada gadis itu, lalu menenangkan hati gadis itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 4, 'Sebab itu berkatalah Sikhem kepada Hemor, ayahnya: "Ambillah bagiku gadis ini untuk menjadi isteriku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 5, 'Kedengaranlah kepada Yakub, bahwa Sikhem mencemari Dina. Tetapi anak-anaknya ada di padang menjaga ternaknya, jadi Yakub mendiamkan soal itu sampai mereka pulang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 6, 'Lalu Hemor ayah Sikhem, pergi mendapatkan Yakub untuk berbicara dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 7, 'Sementara itu anak-anak Yakub pulang dari padang, dan sesudah mendengar peristiwa itu orang-orang ini sakit hati dan sangat marah karena Sikhem telah berbuat noda di antara orang Israel dengan memperkosa anak perempuan Yakub, sebab yang demikian itu tidak patut dilakukan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 8, 'Berbicaralah Hemor kepada mereka itu: "Hati Sikhem anakku mengingini anakmu; kiranya kamu memberikan dia kepadanya menjadi isterinya', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 9, 'dan biarlah kita ambil-mengambil: berikanlah gadis-gadis kamu kepada kami dan ambillah gadis-gadis kami.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 10, 'Tinggallah pada kami: negeri ini terbuka untuk kamu; tinggallah di sini, jalanilah negeri ini dengan bebas, dan menetaplah di sini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 11, 'Lalu Sikhem berkata kepada ayah anak itu dan kepada kakak-kakaknya: "Biarlah kiranya aku mendapat kasihmu, aku akan memberikan kepadamu apa yang kamu minta;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 12, 'walaupun kamu bebankan kepadaku uang jujuran dan uang mahar seberapa banyakpun, aku akan memberikan apa yang kamu minta; tetapi berilah gadis itu kepadaku menjadi isteriku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 13, 'Lalu anak-anak Yakub menjawab Sikhem dan Hemor, ayahnya, dengan tipu muslihat. Karena Sikhem telah mencemari Dina, adik mereka itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 14, 'berkatalah mereka kepada kedua orang itu: "Kami tidak dapat berbuat demikian, memberikan adik kami kepada seorang laki-laki yang tidak bersunat, sebab hal itu aib bagi kami.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 15, 'Hanyalah dengan syarat ini kami dapat menyetujui permintaanmu: kamu harus sama seperti kami, yaitu setiap laki-laki di antara kamu harus disunat,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 16, 'barulah kami akan memberikan gadis-gadis kami kepada kamu dan mengambil gadis-gadis kamu; maka kami akan tinggal padamu, dan kita akan menjadi satu bangsa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 17, 'Tetapi jika kamu tidak mendengarkan perkataan kami dan kamu tidak disunat, maka kami akan mengambil kembali anak itu, lalu pergi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 18, 'Lalu Hemor dan Sikhem, anak Hemor, menyetujui usul mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 19, 'Dan orang muda itu tidak bertangguh melakukannya, sebab ia suka kepada anak Yakub, lagipula ia seorang yang paling dihormati di antara seluruh kaum keluarganya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 20, 'Lalu pergilah Hemor dan Sikhem, anaknya itu, ke pintu gerbang kota mereka dan mereka berbicara kepada penduduk kota itu:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 21, '"Orang-orang itu mau hidup damai dengan kita, biarlah mereka tinggal di negeri ini dan menjalaninya dengan bebas; bukankah negeri ini cukup luas untuk mereka? Maka kita dapat mengambil gadis-gadis mereka menjadi isteri kita dan kita dapat memberikan gadis-gadis kita kepada mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 22, 'Namun hanya dengan syarat ini orang-orang itu setuju tinggal bersama-sama dengan kita, sehingga kita menjadi satu bangsa, yaitu setiap laki-laki di antara kita harus disunat seperti mereka bersunat.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 23, 'Ternak mereka, harta benda mereka dan segala hewan mereka, bukankah semuanya itu akan menjadi milik kita? Hanya biarlah kita menyetujui permintaan mereka, sehingga mereka tetap tinggal pada kita."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 24, 'Maka usul Hemor dan Sikhem, anaknya itu, didengarkan oleh semua orang yang datang berkumpul di pintu gerbang kota itu, lalu disunatlah setiap laki-laki, yakni setiap orang dewasa di kota itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 25, 'Pada hari ketiga, ketika mereka sedang menderita kesakitan, datanglah dua orang anak Yakub, yaitu Simeon dan Lewi, kakak-kakak Dina, setelah masing-masing mengambil pedangnya, menyerang kota itu dengan tidak takut-takut serta membunuh setiap laki-laki.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 26, 'Juga Hemor dan Sikhem, anaknya, dibunuh mereka dengan mata pedang, dan mereka mengambil Dina dari rumah Sikhem, lalu pergi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 27, 'Kemudian datanglah anak-anak Yakub merampasi orang-orang yang terbunuh itu, lalu menjarah kota itu, karena adik mereka telah dicemari.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 28, 'Kambing dombanya dan lembu sapinya, keledainya dan segala yang di dalam dan di luar kota itu dibawa mereka;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 29, 'segala kekayaannya, semua anaknya dan perempuannya ditawan dan dijarah mereka, juga seluruhnya yang ada di rumah-rumah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 30, 'Yakub berkata kepada Simeon dan Lewi: "Kamu telah mencelakakan aku dengan membusukkan namaku kepada penduduk negeri ini, kepada orang Kanaan dan orang Feris, padahal kita ini hanya sedikit jumlahnya; apabila mereka bersekutu melawan kita, tentulah mereka akan memukul kita kalah, dan kita akan dipunahkan, aku beserta seisi rumahku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 34, 31, 'Tetapi jawab mereka: "Mengapa adik kita diperlakukannya sebagai seorang perempuan sundal!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 1, 'Allah berfirman kepada Yakub: "Bersiaplah, pergilah ke Betel, tinggallah di situ, dan buatlah di situ mezbah bagi Allah, yang telah menampakkan diri kepadamu, ketika engkau lari dari Esau, kakakmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 2, 'Lalu berkatalah Yakub kepada seisi rumahnya dan kepada semua orang yang bersama-sama dengan dia: "Jauhkanlah dewa-dewa asing yang ada di tengah-tengah kamu, tahirkanlah dirimu dan tukarlah pakaianmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 3, 'Marilah kita bersiap dan pergi ke Betel; aku akan membuat mezbah di situ bagi Allah, yang telah menjawab aku pada masa kesesakanku dan yang telah menyertai aku di jalan yang kutempuh."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 4, 'Mereka menyerahkan kepada Yakub segala dewa asing yang dipunyai mereka dan anting-anting yang ada pada telinga mereka, lalu Yakub menanamnya di bawah pohon besar yang dekat Sikhem.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 5, 'Sesudah itu berangkatlah mereka. Dan kedahsyatan yang dari Allah meliputi kota-kota sekeliling mereka, sehingga anak-anak Yakub tidak dikejar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 6, 'Lalu sampailah Yakub ke Lus yang di tanah Kanaan?yaitu Betel?,ia dan semua orang yang bersama-sama dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 7, 'Didirikannyalah mezbah di situ, dan dinamainyalah tempat itu El-Betel, karena Allah telah menyatakan diri kepadanya di situ, ketika ia lari terhadap kakaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 8, 'Ketika Debora, inang pengasuh Ribka, mati, dikuburkanlah ia di sebelah hilir Betel di bawah pohon besar, yang dinamai orang: Pohon Besar Penangisan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 9, 'Setelah Yakub datang dari Padan-Aram, maka Allah menampakkan diri pula kepadanya dan memberkati dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 10, 'Firman Allah kepadanya: "Namamu Yakub; dari sekarang namamu bukan lagi Yakub, melainkan Israel, itulah yang akan menjadi namamu." Maka Allah menamai dia Israel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 11, 'Lagi firman Allah kepadanya: "Akulah Allah Yang Mahakuasa. Beranakcuculah dan bertambah banyak; satu bangsa, bahkan sekumpulan bangsa-bangsa, akan terjadi dari padamu dan raja-raja akan berasal dari padamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 12, 'Dan negeri ini yang telah Kuberikan kepada Abraham dan kepada Ishak, akan Kuberikan kepadamu dan juga kepada keturunanmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 13, 'Lalu naiklah Allah meninggalkan Yakub dari tempat Ia berfirman kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 14, 'Kemudian Yakub mendirikan tugu di tempat itu, yakni tugu batu; ia mempersembahkan korban curahan dan menuangkan minyak di atasnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 15, 'Yakub menamai tempat di mana Allah telah berfirman kepadanya "Betel".', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 16, 'Sesudah itu berangkatlah mereka dari Betel. Ketika mereka tidak berapa jauh lagi dari Efrata, bersalinlah Rahel, dan bersalinnya itu sangat sukar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 17, 'Sedang ia sangat sukar bersalin, berkatalah bidan kepadanya: "Janganlah takut, sekali inipun anak laki-laki yang kaudapat."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 18, 'Dan ketika ia hendak menghembuskan nafas?sebab ia mati kemudian?diberikannyalah nama Ben-oni kepada anak itu, tetapi ayahnya menamainya Benyamin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 19, 'Demikianlah Rahel mati, lalu ia dikuburkan di sisi jalan ke Efrata, yaitu Betlehem.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 20, 'Yakub mendirikan tugu di atas kuburnya; itulah tugu kubur Rahel sampai sekarang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 21, 'Sesudah itu berangkatlah Israel, lalu ia memasang kemahnya di seberang Migdal-Eder.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 22, 'Ketika Israel diam di negeri ini, terjadilah bahwa Ruben sampai tidur dengan Bilha, gundik ayahnya, dan kedengaranlah hal itu kepada Israel. (35-22b) Adapun anak-anak lelaki Yakub dua belas orang jumlahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 23, 'Anak-anak Lea ialah Ruben, anak sulung Yakub, kemudian Simeon, Lewi, Yehuda, Isakhar dan Zebulon.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 24, 'Anak-anak Rahel ialah Yusuf dan Benyamin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 25, 'Dan anak-anak Bilha, budak perempuan Rahel ialah Dan serta Naftali.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 26, 'Dan anak-anak Zilpa, budak perempuan Lea ialah Gad dan Asyer. Itulah anak-anak lelaki Yakub, yang dilahirkan baginya di Padan-Aram.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 27, 'Lalu sampailah Yakub kepada Ishak, ayahnya, di Mamre dekat Kiryat-Arba?itulah Hebron?tempat Abraham dan Ishak tinggal sebagai orang asing.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 28, 'Adapun umur Ishak seratus delapan puluh tahun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 35, 29, 'Lalu meninggallah Ishak, ia mati dan dikumpulkan kepada kaum leluhurnya; ia tua dan suntuk umur, maka Esau dan Yakub, anak-anaknya itu, menguburkan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 1, 'Inilah keturunan Esau, yaitu Edom.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 2, 'Esau mengambil perempuan-perempuan Kanaan menjadi isterinya, yakni Ada, anak Elon orang Het, dan Oholibama, anak Ana anak Zibeon orang Hewi,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 3, 'dan Basmat, anak Ismael, adik Nebayot.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 4, 'Ada melahirkan Elifas bagi Esau, dan Basmat melahirkan Rehuel,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 5, 'dan Oholibama melahirkan Yeush, Yaelam dan Korah. Itulah anak-anak Esau, yang lahir baginya di tanah Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 6, 'Esau membawa isteri-isterinya, anak-anaknya lelaki dan perempuan dan semua orang yang ada di rumahnya, ternaknya, segala hewannya dan segala harta bendanya yang telah diperolehnya di tanah Kanaan, lalu pergilah ia ke negeri lain dan ia meninggalkan Yakub, adiknya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 7, 'Sebab harta milik mereka terlalu banyak, sehingga mereka tidak dapat tinggal bersama-sama, dan negeri penumpangan mereka tidak dapat memuat mereka karena banyaknya ternak mereka itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 8, 'Maka menetaplah Esau di pegunungan Seir; Esau itulah Edom.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 9, 'Inilah keturunan Esau, bapa orang Edom, di pegunungan Seir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 10, 'Nama anak-anaknya ialah: Elifas, anak Ada isteri Esau; Rehuel, anak Basmat isteri Esau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 11, 'Anak-anak Elifas ialah Teman, Omar, Zefo, Gaetam dan Kenas.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 12, 'Timna adalah gundik Elifas anak Esau; ia melahirkan Amalek bagi Elifas. Itulah cucu-cucu Ada isteri Esau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 13, 'Inilah anak-anak Rehuel: Nahat, Zerah, Syama dan Miza. Itulah cucu-cucu Basmat isteri Esau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 14, 'Inilah anak-anak Oholibama, isteri Esau itu, anak Ana anak Zibeon; ia melahirkan bagi Esau: Yeush, Yaelam dan Korah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 15, 'Inilah kepala-kepala kaum bani Esau: keturunan Elifas anak sulung Esau, ialah kepala kaum Teman, kepala kaum Omar, kepala kaum Zefo, kepala kaum Kenas,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 16, 'kepala kaum Korah, kepala kaum Gaetam dan kepala kaum Amalek; itulah kepala-kepala kaum Elifas di tanah Edom; itulah keturunan Ada.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 17, 'Inilah keturunan Rehuel anak Esau: kepala kaum Nahat, kepala kaum Zerah, kepala kaum Syama dan kepala kaum Miza; itulah kepala-kepala kaum Rehuel di tanah Edom; itulah keturunan Basmat isteri Esau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 18, 'Inilah keturunan Oholibama isteri Esau: kepala kaum Yeush, kepala kaum Yaelam, kepala kaum Korah; itulah kepala-kepala kaum Oholibama, isteri Esau, anak Ana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 19, 'Itulah bani Esau, yakni Edom, dan itulah kepala-kepala kaum mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 20, 'Inilah anak-anak Seir, orang Hori, penduduk negeri itu: Lotan, Syobal, Zibeon, Ana,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 21, 'Disyon, Ezer, Disyan; itulah kepala-kepala kaum orang Hori, anak-anak Seir, di tanah Edom.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 22, 'Anak-anak Lotan ialah Hori dan Heman, dan saudara perempuan Lotan ialah Timna.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 23, 'Inilah anak-anak Syobal: Alwan, Manahat, Ebal, Syefo dan Onam.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 24, 'Inilah anak-anak Zibeon: Aya dan Ana; Ana inilah yang menemui mata-mata air panas di padang gurun, ketika ia sedang menggembalakan keledai Zibeon ayahnya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 25, 'Inilah anak-anak Ana: Disyon dan Oholibama anak perempuan Ana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 26, 'Inilah anak-anak Disyon: Hemdan, Esyban, Yitran dan Keran.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 27, 'Inilah anak-anak Ezer: Bilhan, Zaawan dan Akan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 28, 'Inilah anak-anak Disyan: Us dan Aran.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 29, 'Itulah kepala-kepala kaum orang Hori: kepala kaum Lotan, kepala kaum Syobal, kepala kaum Zibeon, kepala kaum Ana,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 30, 'kepala kaum Disyon, kepala kaum Ezer dan kepala kaum Disyan; itulah kepala-kepala kaum orang Hori, kaum demi kaum, di tanah Seir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 31, 'Inilah raja-raja yang memerintah di tanah Edom, sebelum ada seorang raja memerintah atas orang Israel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 32, 'Di Edom yang memerintah ialah Bela bin Beor dan kotanya bernama Dinhaba.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 33, 'Setelah Bela mati, Yobab bin Zerah dari Bozra menjadi raja menggantikan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 34, 'Setelah Yobab mati, Husyam, dari negeri orang Teman, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 35, 'Setelah Husyam mati, Hadad bin Bedad menjadi raja menggantikan dia; dialah yang memukul kalah orang Midian di daerah Moab, dan kotanya bernama Awit.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 36, 'Setelah Hadad mati, Samla dari Masreka menjadi raja menggantikan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 37, 'Setelah Samla mati, Saul, dari Rehobot yang di pinggir sungai, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 38, 'Setelah Saul mati, Baal-Hanan bin Akhbor menjadi raja menggantikan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 39, 'Setelah Baal-Hanan bin Akhbor mati, Hadar menjadi raja menggantikan dia; kotanya bernama Pahu dan isterinya bernama Mehetabeel binti Matred binti Mezahab.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 40, 'Inilah nama kepala-kepala kaum Esau menurut kaum dan tempat mereka, dengan nama mereka masing-masing: kepala kaum Timna, kepala kaum Alwa, kepala kaum Yetet,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 41, 'kepala kaum Oholibama, kepala kaum Ela, kepala kaum Pinon,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 42, 'kepala kaum Kenas, kepala kaum Teman, kepala kaum Mibzar,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 36, 43, 'kepala kaum Magdiel dan kepala kaum Iram; itulah kepala-kepala kaum Edom, menurut tempat kediaman mereka di tanah milik mereka; Edom ialah Esau, bapa orang Edom.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 1, 'Adapun Yakub, ia diam di negeri penumpangan ayahnya, yakni di tanah Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 2, 'Inilah riwayat keturunan Yakub. Yusuf, tatkala berumur tujuh belas tahun?jadi masih muda?biasa menggembalakan kambing domba, bersama-sama dengan saudara-saudaranya, anak-anak Bilha dan Zilpa, kedua isteri ayahnya. Dan Yusuf menyampaikan kepada ayahnya kabar tentang kejahatan saudara-saudaranya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 3, 'Israel lebih mengasihi Yusuf dari semua anaknya yang lain, sebab Yusuf itulah anaknya yang lahir pada masa tuanya; dan ia menyuruh membuat jubah yang maha indah bagi dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 4, 'Setelah dilihat oleh saudara-saudaranya, bahwa ayahnya lebih mengasihi Yusuf dari semua saudaranya, maka bencilah mereka itu kepadanya dan tidak mau menyapanya dengan ramah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 5, 'Pada suatu kali bermimpilah Yusuf, lalu mimpinya itu diceritakannya kepada saudara-saudaranya; sebab itulah mereka lebih benci lagi kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 6, 'Karena katanya kepada mereka: "Coba dengarkan mimpi yang kumimpikan ini:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 7, 'Tampak kita sedang di ladang mengikat berkas-berkas gandum, lalu bangkitlah berkasku dan tegak berdiri; kemudian datanglah berkas-berkas kamu sekalian mengelilingi dan sujud menyembah kepada berkasku itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 8, 'Lalu saudara-saudaranya berkata kepadanya: "Apakah engkau ingin menjadi raja atas kami? Apakah engkau ingin berkuasa atas kami?" Jadi makin bencilah mereka kepadanya karena mimpinya dan karena perkataannya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 9, 'Lalu ia memimpikan pula mimpi yang lain, yang diceritakannya kepada saudara-saudaranya. Katanya: "Aku bermimpi pula: Tampak matahari, bulan dan sebelas bintang sujud menyembah kepadaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 10, 'Setelah hal ini diceritakannya kepada ayah dan saudara-saudaranya, maka ia ditegor oleh ayahnya: "Mimpi apa mimpimu itu? Masakan aku dan ibumu serta saudara-saudaramu sujud menyembah kepadamu sampai ke tanah?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 11, 'Maka iri hatilah saudara-saudaranya kepadanya, tetapi ayahnya menyimpan hal itu dalam hatinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 12, 'Pada suatu kali pergilah saudara-saudaranya menggembalakan kambing domba ayahnya dekat Sikhem.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 13, 'Lalu Israel berkata kepada Yusuf: "Bukankah saudara-saudaramu menggembalakan kambing domba dekat Sikhem? Marilah engkau kusuruh kepada mereka." Sahut Yusuf: "Ya bapa."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 14, 'Kata Israel kepadanya: "Pergilah engkau melihat apakah baik keadaan saudara-saudaramu dan keadaan kambing domba; dan bawalah kabar tentang itu kepadaku." Lalu Yakub menyuruh dia dari lembah Hebron, dan Yusufpun sampailah ke Sikhem.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 15, 'Ketika Yusuf berjalan ke sana ke mari di padang, bertemulah ia dengan seorang laki-laki, yang bertanya kepadanya: "Apakah yang kaucari?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 16, 'Sahutnya: "Aku mencari saudara-saudaraku. Tolonglah katakan kepadaku di mana mereka menggembalakan kambing domba?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 17, 'Lalu kata orang itu: "Mereka telah berangkat dari sini, sebab telah kudengar mereka berkata: Marilah kita pergi ke Dotan." Maka Yusuf menyusul saudara-saudaranya itu dan didapatinyalah mereka di Dotan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 18, 'Dari jauh ia telah kelihatan kepada mereka. Tetapi sebelum ia dekat pada mereka, mereka telah bermufakat mencari daya upaya untuk membunuhnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 19, 'Kata mereka seorang kepada yang lain: "Lihat, tukang mimpi kita itu datang!', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 20, 'Sekarang, marilah kita bunuh dia dan kita lemparkan ke dalam salah satu sumur ini, lalu kita katakan: seekor binatang buas telah menerkamnya. Dan kita akan lihat nanti, bagaimana jadinya mimpinya itu!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 21, 'Ketika Ruben mendengar hal ini, ia ingin melepaskan Yusuf dari tangan mereka, sebab itu katanya: "Janganlah kita bunuh dia!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 22, 'Lagi kata Ruben kepada mereka: "Janganlah tumpahkan darah, lemparkanlah dia ke dalam sumur yang ada di padang gurun ini, tetapi janganlah apa-apakan dia" ?maksudnya hendak melepaskan Yusuf dari tangan mereka dan membawanya kembali kepada ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 23, 'Baru saja Yusuf sampai kepada saudara-saudaranya, merekapun menanggalkan jubah Yusuf, jubah maha indah yang dipakainya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 24, 'Dan mereka membawa dia dan melemparkan dia ke dalam sumur. Sumur itu kosong, tidak berair.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 25, 'Kemudian duduklah mereka untuk makan. Ketika mereka mengangkat muka, kelihatanlah kepada mereka suatu kafilah orang Ismael datang dari Gilead dengan untanya yang membawa damar, balsam dan damar ladan, dalam perjalanannya mengangkut barang-barang itu ke Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 26, 'Lalu kata Yehuda kepada saudara-saudaranya itu: "Apakah untungnya kalau kita membunuh adik kita itu dan menyembunyikan darahnya?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 27, 'Marilah kita jual dia kepada orang Ismael ini, tetapi janganlah kita apa-apakan dia, karena ia saudara kita, darah daging kita." Dan saudara-saudaranya mendengarkan perkataannya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 28, 'Ketika ada saudagar-saudagar Midian lewat, Yusuf diangkat ke atas dari dalam sumur itu, kemudian dijual kepada orang Ismael itu dengan harga dua puluh syikal perak. Lalu Yusuf dibawa mereka ke Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 29, 'Ketika Ruben kembali ke sumur itu, ternyata Yusuf tidak ada lagi di dalamnya. Lalu dikoyakkannyalah bajunya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 30, 'dan kembalilah ia kepada saudara-saudaranya, katanya: "Anak itu tidak ada lagi, ke manakah aku ini?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 31, 'Kemudian mereka mengambil jubah Yusuf, dan menyembelih seekor kambing, lalu mencelupkan jubah itu ke dalam darahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 32, 'Jubah maha indah itu mereka suruh antarkan kepada ayah mereka dengan pesan: "Ini kami dapati. Silakanlah bapa periksa apakah jubah ini milik anak bapa atau tidak?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 33, 'Ketika Yakub memeriksa jubah itu, ia berkata: "Ini jubah anakku; binatang buas telah memakannya; tentulah Yusuf telah diterkam."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 34, 'Dan Yakub mengoyakkan jubahnya, lalu mengenakan kain kabung pada pinggangnya dan berkabunglah ia berhari-hari lamanya karena anaknya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 35, 'Sekalian anaknya laki-laki dan perempuan berusaha menghiburkan dia, tetapi ia menolak dihiburkan, serta katanya: "Tidak! Aku akan berkabung, sampai aku turun mendapatkan anakku, ke dalam dunia orang mati!" Demikianlah Yusuf ditangisi oleh ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 37, 36, 'Adapun Yusuf, ia dijual oleh orang Midian itu ke Mesir, kepada Potifar, seorang pegawai istana Firaun, kepala pengawal raja.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 1, 'Pada waktu itu Yehuda meninggalkan saudara-saudaranya dan menumpang pada seorang Adulam, yang namanya Hira.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 2, 'Di situ Yehuda melihat anak perempuan seorang Kanaan; nama orang itu ialah Syua. Lalu Yehuda kawin dengan perempuan itu dan menghampirinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 3, 'Perempuan itu mengandung, lalu melahirkan seorang anak laki-laki dan menamai anak itu Er.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 4, 'Sesudah itu perempuan itu mengandung lagi, lalu melahirkan seorang anak laki-laki dan menamai anak itu Onan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 5, 'Kemudian perempuan itu melahirkan seorang anak laki-laki sekali lagi, dan menamai anak itu Syela. Yehuda sedang berada di Kezib, ketika anak itu dilahirkan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 6, 'Sesudah itu Yehuda mengambil bagi Er, anak sulungnya, seorang isteri, yang bernama Tamar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 7, 'Tetapi Er, anak sulung Yehuda itu, adalah jahat di mata TUHAN, maka TUHAN membunuh dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 8, 'Lalu berkatalah Yehuda kepada Onan: "Hampirilah isteri kakakmu itu, kawinlah dengan dia sebagai ganti kakakmu dan bangkitkanlah keturunan bagi kakakmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 9, 'Tetapi Onan tahu, bahwa bukan ia yang empunya keturunannya nanti, sebab itu setiap kali ia menghampiri isteri kakaknya itu, ia membiarkan maninya terbuang, supaya ia jangan memberi keturunan kepada kakaknya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 10, 'Tetapi yang dilakukannya itu adalah jahat di mata TUHAN, maka TUHAN membunuh dia juga.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 11, 'Lalu berkatalah Yehuda kepada Tamar, menantunya itu: "Tinggallah sebagai janda di rumah ayahmu, sampai anakku Syela itu besar," sebab pikirnya: "Jangan-jangan ia mati seperti kedua kakaknya itu." Maka pergilah Tamar dan tinggal di rumah ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 12, 'Setelah beberapa lama matilah anak Syua, isteri Yehuda. Habis berkabung pergilah Yehuda ke Timna, kepada orang-orang yang menggunting bulu domba-dombanya, bersama dengan Hira, sahabatnya, orang Adulam itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 13, 'Ketika dikabarkan kepada Tamar: "Bapa mertuamu sedang di jalan ke Timna untuk menggunting bulu domba-dombanya,"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 14, 'maka ditanggalkannyalah pakaian kejandaannya, ia bertelekung dan berselubung, lalu pergi duduk di pintu masuk ke Enaim yang di jalan ke Timna, karena dilihatnya, bahwa Syela telah menjadi besar, dan dia tidak diberikan juga kepada Syela itu untuk menjadi isterinya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 15, 'Ketika Yehuda melihat dia, disangkanyalah dia seorang perempuan sundal, karena ia menutupi mukanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 16, 'Lalu berpalinglah Yehuda mendapatkan perempuan yang di pinggir jalan itu serta berkata: "Marilah, aku mau menghampiri engkau," sebab ia tidak tahu, bahwa perempuan itu menantunya. Tanya perempuan itu: "Apakah yang akan kauberikan kepadaku, jika engkau menghampiri aku?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 17, 'Jawabnya: "Aku akan mengirimkan kepadamu seekor anak kambing dari kambing dombaku." Kata perempuan itu: "Asal engkau memberikan tanggungannya, sampai engkau mengirimkannya kepadaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 18, 'Tanyanya: "Apakah tanggungan yang harus kuberikan kepadamu?" Jawab perempuan itu: "Cap meteraimu serta kalungmu dan tongkat yang ada di tanganmu itu." Lalu diberikannyalah semuanya itu kepadanya, maka ia menghampirinya. Perempuan itu mengandung dari padanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 19, 'Bangunlah perempuan itu, lalu pergi, ditanggalkannya telekungnya dan dikenakannya pula pakaian kejandaannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 20, 'Adapun Yehuda, ia mengirimkan anak kambing itu dengan perantaraan sahabatnya, orang Adulam itu, untuk mengambil kembali tanggungannya dari tangan perempuan itu, tetapi perempuan itu tidak dijumpainya lagi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 21, 'Ia bertanya-tanya di tempat tinggal perempuan itu: "Di manakah perempuan jalang, yang duduk tadinya di pinggir jalan di Enaim itu?" Jawab mereka: "Tidak ada di sini perempuan jalang."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 22, 'Kembalilah ia kepada Yehuda dan berkata: "Tidak ada kujumpai dia; dan juga orang-orang di tempat itu berkata: Tidak ada perempuan jalang di sini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 23, 'Lalu berkatalah Yehuda: "Biarlah barang-barang itu dipegangnya, supaya kita jangan menjadi buah olok-olok orang; sungguhlah anak kambing itu telah kukirimkan, tetapi engkau tidak menjumpai perempuan itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 24, 'Sesudah kira-kira tiga bulan dikabarkanlah kepada Yehuda: "Tamar, menantumu, bersundal, bahkan telah mengandung dari persundalannya itu." Lalu kata Yehuda: "Bawalah perempuan itu, supaya dibakar."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 25, 'Waktu dibawa, perempuan itu menyuruh orang kepada mertuanya mengatakan: "Dari laki-laki yang empunya barang-barang inilah aku mengandung." Juga dikatakannya: "Periksalah, siapa yang empunya cap meterai serta kalung dan tongkat ini?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 26, 'Yehuda memeriksa barang-barang itu, lalu berkata: "Bukan aku, tetapi perempuan itulah yang benar, karena memang aku tidak memberikan dia kepada Syela, anakku." Dan ia tidak bersetubuh lagi dengan perempuan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 27, 'Pada waktu perempuan itu hendak bersalin, nyatalah ada anak kembar dalam kandungannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 28, 'Dan ketika ia bersalin, seorang dari anak itu mengeluarkan tangannya, lalu dipegang oleh bidan, diikatnya dengan benang kirmizi serta berkata: "Inilah yang lebih dahulu keluar."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 29, 'Ketika anak itu menarik tangannya kembali, keluarlah saudaranya laki-laki, dan bidan itu berkata: "Alangkah kuatnya engkau menembus ke luar," maka anak itu dinamai Peres.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 38, 30, 'Sesudah itu keluarlah saudaranya laki-laki yang tangannya telah berikat benang kirmizi itu, lalu kepadanya diberi nama Zerah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 1, 'Adapun Yusuf telah dibawa ke Mesir; dan Potifar, seorang Mesir, pegawai istana Firaun, kepala pengawal raja, membeli dia dari tangan orang Ismael yang telah membawa dia ke situ.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 2, 'Tetapi TUHAN menyertai Yusuf, sehingga ia menjadi seorang yang selalu berhasil dalam pekerjaannya; maka tinggallah ia di rumah tuannya, orang Mesir itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 3, 'Setelah dilihat oleh tuannya, bahwa Yusuf disertai TUHAN dan bahwa TUHAN membuat berhasil segala sesuatu yang dikerjakannya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 4, 'maka Yusuf mendapat kasih tuannya, dan ia boleh melayani dia; kepada Yusuf diberikannya kuasa atas rumahnya dan segala miliknya diserahkannya pada kekuasaan Yusuf.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 5, 'Sejak ia memberikan kuasa dalam rumahnya dan atas segala miliknya kepada Yusuf, TUHAN memberkati rumah orang Mesir itu karena Yusuf, sehingga berkat TUHAN ada atas segala miliknya, baik yang di rumah maupun yang di ladang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 6, 'Segala miliknya diserahkannya pada kekuasaan Yusuf, dan dengan bantuan Yusuf ia tidak usah lagi mengatur apa-apapun selain dari makanannya sendiri. Adapun Yusuf itu manis sikapnya dan elok parasnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 7, 'Selang beberapa waktu isteri tuannya memandang Yusuf dengan berahi, lalu katanya: "Marilah tidur dengan aku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 8, 'Tetapi Yusuf menolak dan berkata kepada isteri tuannya itu: "Dengan bantuanku tuanku itu tidak lagi mengatur apa yang ada di rumah ini dan ia telah menyerahkan segala miliknya pada kekuasaanku,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 9, 'bahkan di rumah ini ia tidak lebih besar kuasanya dari padaku, dan tiada yang tidak diserahkannya kepadaku selain dari pada engkau, sebab engkau isterinya. Bagaimanakah mungkin aku melakukan kejahatan yang besar ini dan berbuat dosa terhadap Allah?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 10, 'Walaupun dari hari ke hari perempuan itu membujuk Yusuf, Yusuf tidak mendengarkan bujukannya itu untuk tidur di sisinya dan bersetubuh dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 11, 'Pada suatu hari masuklah Yusuf ke dalam rumah untuk melakukan pekerjaannya, sedang dari seisi rumah itu seorangpun tidak ada di rumah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 12, 'Lalu perempuan itu memegang baju Yusuf sambil berkata: "Marilah tidur dengan aku." Tetapi Yusuf meninggalkan bajunya di tangan perempuan itu dan lari ke luar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 13, 'Ketika dilihat perempuan itu, bahwa Yusuf meninggalkan bajunya dalam tangannya dan telah lari ke luar,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 14, 'dipanggilnyalah seisi rumah itu, lalu katanya kepada mereka: "Lihat, dibawanya ke mari seorang Ibrani, supaya orang ini dapat mempermainkan kita. Orang ini mendekati aku untuk tidur dengan aku, tetapi aku berteriak-teriak dengan suara keras.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 15, 'Dan ketika didengarnya bahwa aku berteriak sekeras-kerasnya, ditinggalkannyalah bajunya padaku, lalu ia lari ke luar."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 16, 'Juga ditaruhnya baju Yusuf itu di sisinya, sampai tuan rumah pulang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 17, 'Perkataan itu jugalah yang diceritakan perempuan itu kepada Potifar, katanya: "Hamba orang Ibrani yang kaubawa ke mari itu datang kepadaku untuk mempermainkan aku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 18, 'Tetapi ketika aku berteriak sekeras-kerasnya, ditinggalkannya bajunya padaku, lalu ia lari ke luar."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 19, 'Baru saja didengar oleh tuannya perkataan yang diceritakan isterinya kepadanya: begini begitulah aku diperlakukan oleh hambamu itu, maka bangkitlah amarahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 20, 'Lalu Yusuf ditangkap oleh tuannya dan dimasukkan ke dalam penjara, tempat tahanan-tahanan raja dikurung. Demikianlah Yusuf dipenjarakan di sana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 21, 'Tetapi TUHAN menyertai Yusuf dan melimpahkan kasih setia-Nya kepadanya, dan membuat Yusuf kesayangan bagi kepala penjara itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 22, 'Sebab itu kepala penjara mempercayakan semua tahanan dalam penjara itu kepada Yusuf, dan segala pekerjaan yang harus dilakukan di situ, dialah yang mengurusnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 39, 23, 'Dan kepala penjara tidak mencampuri segala yang dipercayakannya kepada Yusuf, karena TUHAN menyertai dia dan apa yang dikerjakannya dibuat TUHAN berhasil.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 1, 'Sesudah semuanya itu terjadilah, bahwa juru minuman raja Mesir dan juru rotinya membuat kesalahan terhadap tuannya, raja Mesir itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 2, 'maka murkalah Firaun kepada kedua pegawai istananya, kepala juru minuman dan kepala juru roti itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 3, 'Ia menahan mereka dalam rumah kepala pengawal raja, dalam penjara tempat Yusuf dikurung.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 4, 'Kepala pengawal raja menempatkan Yusuf bersama-sama dengan mereka untuk melayani mereka. Demikianlah mereka ditahan beberapa waktu lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 5, 'Pada suatu kali bermimpilah mereka keduanya?baik juru minuman maupun juru roti raja Mesir, yang ditahan dalam penjara itu?masing-masing ada mimpinya, pada satu malam juga, dan mimpi masing-masing itu ada artinya sendiri.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 6, 'Ketika pada waktu pagi Yusuf datang kepada mereka, segera dilihatnya, bahwa mereka bersusah hati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 7, 'Lalu ia bertanya kepada pegawai-pegawai istana Firaun yang ditahan bersama-sama dengan dia dalam rumah tuannya itu: "Mengapakah hari ini mukamu semuram itu?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 8, 'Jawab mereka kepadanya: "Kami bermimpi, tetapi tidak ada orang yang dapat mengartikannya." Lalu kata Yusuf kepada mereka: "Bukankah Allah yang menerangkan arti mimpi? Ceritakanlah kiranya mimpimu itu kepadaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 9, 'Kemudian juru minuman itu menceritakan mimpinya kepada Yusuf, katanya: "Dalam mimpiku itu tampak ada pohon anggur di depanku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 10, 'Pohon anggur itu ada tiga carangnya dan baru saja pohon itu bertunas, bunganya sudah keluar dan tandan-tandannya penuh buah anggur yang ranum.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 11, 'Dan di tanganku ada piala Firaun. Buah anggur itu kuambil, lalu kuperas ke dalam piala Firaun, kemudian kusampaikan piala itu ke tangan Firaun."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 12, 'Kata Yusuf kepadanya: "Beginilah arti mimpi itu: ketiga carang itu artinya tiga hari;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 13, 'dalam tiga hari ini Firaun akan meninggikan engkau dan mengembalikan engkau ke dalam pangkatmu yang dahulu dan engkau akan menyampaikan piala ke tangan Firaun seperti dahulu kala, ketika engkau jadi juru minumannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 14, 'Tetapi, ingatlah kepadaku, apabila keadaanmu telah baik nanti, tunjukkanlah terima kasihmu kepadaku dengan menceritakan hal ihwalku kepada Firaun dan tolonglah keluarkan aku dari rumah ini.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 15, 'Sebab aku dicuri diculik begitu saja dari negeri orang Ibrani dan di sinipun aku tidak pernah melakukan apa-apa yang menyebabkan aku layak dimasukkan ke dalam liang tutupan ini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 16, 'Setelah dilihat oleh kepala juru roti, betapa baik arti mimpi itu, berkatalah ia kepadanya: "Akupun bermimpi juga. Tampak aku menjunjung tiga bakul berisi penganan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 17, 'Dalam bakul atas ada berbagai-bagai makanan untuk Firaun, buatan juru roti, tetapi burung-burung memakannya dari dalam bakul yang di atas kepalaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 18, 'Yusuf menjawab: "Beginilah arti mimpi itu: ketiga bakul itu artinya tiga hari;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 19, 'dalam tiga hari ini Firaun akan meninggikan engkau, tinggi ke atas, dan menggantung engkau pada sebuah tiang, dan burung-burung akan memakan dagingmu dari tubuhmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 20, 'Dan terjadilah pada hari ketiga, hari kelahiran Firaun, maka Firaun mengadakan perjamuan untuk semua pegawainya. Ia meninggikan kepala juru minuman dan kepala juru roti itu di tengah-tengah para pegawainya:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 21, 'kepala juru minuman itu dikembalikannya ke dalam jabatannya, sehingga ia menyampaikan pula piala ke tangan Firaun;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 22, 'tetapi kepala juru roti itu digantungnya, seperti yang ditakbirkan Yusuf kepada mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 40, 23, 'Tetapi Yusuf tidaklah diingat oleh kepala juru minuman itu, melainkan dilupakannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 1, 'Setelah lewat dua tahun lamanya, bermimpilah Firaun, bahwa ia berdiri di tepi sungai Nil.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 2, 'Tampaklah dari sungai Nil itu keluar tujuh ekor lembu yang indah bangunnya dan gemuk badannya; lalu memakan rumput yang di tepi sungai itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 3, 'Kemudian tampaklah juga tujuh ekor lembu yang lain, yang keluar dari dalam sungai Nil itu, buruk bangunnya dan kurus badannya, lalu berdiri di samping lembu-lembu yang tadi, di tepi sungai itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 4, 'Lembu-lembu yang buruk bangunnya dan kurus badannya itu memakan ketujuh ekor lembu yang indah bangunnya dan gemuk itu. Lalu terjagalah Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 5, 'Setelah itu tertidur pulalah ia dan bermimpi kedua kalinya: Tampak timbul dari satu tangkai tujuh bulir gandum yang bernas dan baik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 6, 'Tetapi kemudian tampaklah juga tumbuh tujuh bulir gandum yang kurus dan layu oleh angin timur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 7, 'Bulir yang kurus itu menelan ketujuh bulir yang bernas dan berisi tadi. Lalu terjagalah Firaun. Agaknya ia bermimpi!', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 8, 'Pada waktu pagi gelisahlah hatinya, lalu disuruhnyalah memanggil semua ahli dan semua orang berilmu di Mesir. Firaun menceritakan mimpinya kepada mereka, tetapi seorangpun tidak ada yang dapat mengartikannya kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 9, 'Lalu berkatalah kepala juru minuman kepada Firaun: "Hari ini aku merasa perlu menyebutkan kesalahanku yang dahulu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 10, 'Waktu itu tuanku Firaun murka kepada pegawai-pegawainya, dan menahan aku dalam rumah pengawal istana, beserta dengan kepala juru roti.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 11, 'Pada satu malam juga kami bermimpi, aku dan kepala juru roti itu; masing-masing mempunyai mimpi dengan artinya sendiri.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 12, 'Bersama-sama dengan kami ada di sana seorang muda Ibrani, hamba kepala pengawal istana itu; kami menceritakan mimpi kami kepadanya, lalu diartikannya kepada kami mimpi kami masing-masing.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 13, 'Dan seperti yang diartikannya itu kepada kami, demikianlah pula terjadi: aku dikembalikan ke dalam pangkatku, dan kepala juru roti itu digantung."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 14, 'Kemudian Firaun menyuruh memanggil Yusuf. Segeralah ia dikeluarkan dari tutupan; ia bercukur dan berganti pakaian, lalu pergi menghadap Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 15, 'Berkatalah Firaun kepada Yusuf: "Aku telah bermimpi, dan seorangpun tidak ada yang dapat mengartikannya, tetapi telah kudengar tentang engkau: hanya dengan mendengar mimpi saja engkau dapat mengartikannya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 16, 'Yusuf menyahut Firaun: "Bukan sekali-kali aku, melainkan Allah juga yang akan memberitakan kesejahteraan kepada tuanku Firaun."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 17, 'Lalu berkatalah Firaun kepada Yusuf: "Dalam mimpiku itu, aku berdiri di tepi sungai Nil;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 18, 'lalu tampaklah dari sungai Nil itu keluar tujuh ekor lembu yang gemuk badannya dan indah bentuknya, dan makan rumput yang di tepi sungai itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 19, 'Tetapi kemudian tampaklah juga keluar tujuh ekor lembu yang lain, kulit pemalut tulang, sangat buruk bangunnya dan kurus badannya; tidak pernah kulihat yang seburuk itu di seluruh tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 20, 'Lembu yang kurus dan buruk itu memakan ketujuh ekor lembu gemuk yang mula-mula.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 21, 'Lembu-lembu ini masuk ke dalam perutnya, tetapi walaupun telah masuk ke dalam perutnya, tidaklah kelihatan sedikitpun tandanya: bangunnya tetap sama buruknya seperti semula. Lalu terjagalah aku.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 22, 'Selanjutnya dalam mimpiku itu kulihat timbul dari satu tangkai tujuh bulir gandum yang berisi dan baik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 23, 'Tetapi kemudian tampaklah juga tumbuh tujuh bulir yang kering, kurus dan layu oleh angin timur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 24, 'Bulir yang kurus itu memakan ketujuh bulir yang baik tadi. Telah kuceritakan hal ini kepada semua ahli, tetapi seorangpun tidak ada yang dapat menerangkannya kepadaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 25, 'Lalu kata Yusuf kepada Firaun: "Kedua mimpi tuanku Firaun itu sama. Allah telah memberitahukan kepada tuanku Firaun apa yang hendak dilakukan-Nya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 26, 'Ketujuh ekor lembu yang baik itu ialah tujuh tahun, dan ketujuh bulir gandum yang baik itu ialah tujuh tahun juga; kedua mimpi itu sama.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 27, 'Ketujuh ekor lembu yang kurus dan buruk, yang keluar kemudian, maksudnya tujuh tahun, demikian pula ketujuh bulir gandum yang hampa dan layu oleh angin timur itu; maksudnya akan ada tujuh tahun kelaparan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 28, 'Inilah maksud perkataanku, ketika aku berkata kepada tuanku Firaun: Allah telah memperlihatkan kepada tuanku Firaun apa yang hendak dilakukan-Nya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 29, 'Ketahuilah tuanku, akan datang tujuh tahun kelimpahan di seluruh tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 30, 'Kemudian akan timbul tujuh tahun kelaparan; maka akan dilupakan segala kelimpahan itu di tanah Mesir, karena kelaparan itu menguruskeringkan negeri ini.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 31, 'Sesudah itu akan tidak kelihatan lagi bekas-bekas kelimpahan di negeri ini karena kelaparan itu, sebab sangat hebatnya kelaparan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 32, 'Sampai dua kali mimpi itu diulangi bagi tuanku Firaun berarti: hal itu telah ditetapkan oleh Allah dan Allah akan segera melakukannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 33, 'Oleh sebab itu, baiklah tuanku Firaun mencari seorang yang berakal budi dan bijaksana, dan mengangkatnya menjadi kuasa atas tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 34, 'Baiklah juga tuanku Firaun berbuat begini, yakni menempatkan penilik-penilik atas negeri ini dan dalam ketujuh tahun kelimpahan itu memungut seperlima dari hasil tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 35, 'Mereka harus mengumpulkan segala bahan makanan dalam tahun-tahun baik yang akan datang ini dan, di bawah kuasa tuanku Firaun, menimbun gandum di kota-kota sebagai bahan makanan, serta menyimpannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 36, 'Demikianlah segala bahan makanan itu menjadi persediaan untuk negeri ini dalam ketujuh tahun kelaparan yang akan terjadi di tanah Mesir, supaya negeri ini jangan binasa karena kelaparan itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 37, 'Usul itu dipandang baik oleh Firaun dan oleh semua pegawainya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 38, 'Lalu berkatalah Firaun kepada para pegawainya: "Mungkinkah kita mendapat orang seperti ini, seorang yang penuh dengan Roh Allah?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 39, 'Kata Firaun kepada Yusuf: "Oleh karena Allah telah memberitahukan semuanya ini kepadamu, tidaklah ada orang yang demikian berakal budi dan bijaksana seperti engkau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 40, 'Engkaulah menjadi kuasa atas istanaku, dan kepada perintahmu seluruh rakyatku akan taat; hanya takhta inilah kelebihanku dari padamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 41, 'Selanjutnya Firaun berkata kepada Yusuf: "Dengan ini aku melantik engkau menjadi kuasa atas seluruh tanah Mesir."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 42, 'Sesudah itu Firaun menanggalkan cincin meterainya dari jarinya dan mengenakannya pada jari Yusuf; dipakaikannyalah kepada Yusuf pakaian dari pada kain halus dan digantungkannya kalung emas pada lehernya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 43, 'Lalu Firaun menyuruh menaikkan Yusuf dalam keretanya yang kedua, dan berserulah orang di hadapan Yusuf: "Hormat!" Demikianlah Yusuf dilantik oleh Firaun menjadi kuasa atas seluruh tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 44, 'Berkatalah Firaun kepada Yusuf: "Akulah Firaun, tetapi dengan tidak setahumu, seorangpun tidak boleh bergerak di seluruh tanah Mesir."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 45, 'Lalu Firaun menamai Yusuf: Zafnat-Paaneah, serta memberikan Asnat, anak Potifera, imam di On, kepadanya menjadi isterinya. Demikianlah Yusuf muncul sebagai kuasa atas seluruh tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 46, 'Yusuf berumur tiga puluh tahun ketika ia menghadap Firaun, raja Mesir itu. Maka pergilah Yusuf dari depan Firaun, lalu dikelilinginya seluruh tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 47, 'Tanah itu mengeluarkan hasil bertumpuk-tumpuk dalam ketujuh tahun kelimpahan itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 48, 'maka Yusuf mengumpulkan segala bahan makanan ketujuh tahun kelimpahan yang ada di tanah Mesir, lalu disimpannya di kota-kota; hasil daerah sekitar tiap-tiap kota disimpan di dalam kota itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 49, 'Demikianlah Yusuf menimbun gandum seperti pasir di laut, sangat banyak, sehingga orang berhenti menghitungnya, karena memang tidak terhitung.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 50, 'Sebelum datang tahun kelaparan itu, lahirlah bagi Yusuf dua orang anak laki-laki, yang dilahirkan oleh Asnat, anak Potifera, imam di On.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 51, 'Yusuf memberi nama Manasye kepada anak sulungnya itu, sebab katanya: "Allah telah membuat aku lupa sama sekali kepada kesukaranku dan kepada rumah bapaku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 52, 'Dan kepada anaknya yang kedua diberinya nama Efraim, sebab katanya: "Allah membuat aku mendapat anak dalam negeri kesengsaraanku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 53, 'Setelah lewat ketujuh tahun kelimpahan yang ada di tanah Mesir itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 54, 'mulailah datang tujuh tahun kelaparan, seperti yang telah dikatakan Yusuf; dalam segala negeri ada kelaparan, tetapi di seluruh negeri Mesir ada roti.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 55, 'Ketika seluruh negeri Mesir menderita kelaparan, dan rakyat berteriak meminta roti kepada Firaun, berkatalah Firaun kepada semua orang Mesir: "Pergilah kepada Yusuf, perbuatlah apa yang akan dikatakannya kepadamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 56, 'Kelaparan itu merajalela di seluruh bumi. Maka Yusuf membuka segala lumbung dan menjual gandum kepada orang Mesir, sebab makin hebat kelaparan itu di tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 41, 57, 'Juga dari seluruh bumi datanglah orang ke Mesir untuk membeli gandum dari Yusuf, sebab hebat kelaparan itu di seluruh bumi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 1, 'Setelah Yakub mendapat kabar, bahwa ada gandum di Mesir, berkatalah ia kepada anak-anaknya: "Mengapa kamu berpandang-pandangan saja?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 2, 'Lagi katanya: "Telah kudengar, bahwa ada gandum di Mesir; pergilah ke sana dan belilah gandum di sana untuk kita, supaya kita tetap hidup dan jangan mati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 3, 'Lalu pergilah sepuluh orang saudara Yusuf untuk membeli gandum di Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 4, 'Tetapi Yakub tidak membiarkan Benyamin, adik Yusuf, pergi bersama-sama dengan saudara-saudaranya, sebab pikirnya: "Jangan-jangan ia ditimpa kecelakaan nanti."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 5, 'Jadi di antara orang yang datang membeli gandum terdapatlah juga anak-anak Israel, sebab ada kelaparan di tanah Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 6, 'Sementara itu Yusuf telah menjadi mangkubumi di negeri itu; dialah yang menjual gandum kepada seluruh rakyat negeri itu. Jadi ketika saudara-saudara Yusuf datang, kepadanyalah mereka menghadap dan sujud dengan mukanya sampai ke tanah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 7, 'Ketika Yusuf melihat saudara-saudaranya, segeralah mereka dikenalnya, tetapi ia berlaku seolah-olah ia seorang asing kepada mereka; ia menegor mereka dengan membentak, katanya: "Dari mana kamu?" Jawab mereka: "Dari tanah Kanaan untuk membeli bahan makanan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 8, 'Memang Yusuf mengenal saudara-saudaranya itu, tetapi dia tidak dikenal mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 9, 'Lalu teringatlah Yusuf akan mimpi-mimpinya tentang mereka. Berkatalah ia kepada mereka: "Kamu ini pengintai, kamu datang untuk melihat-lihat di mana negeri ini tidak dijaga."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 10, 'Tetapi jawab mereka: "Tidak tuanku! Hanyalah untuk membeli bahan makanan hamba-hambamu ini datang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 11, 'Kami ini sekalian anak dari satu ayah; kami ini orang jujur; hamba-hambamu ini bukanlah pengintai."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 12, 'Tetapi ia berkata kepada mereka: "Tidak! Kamu datang untuk melihat-lihat di mana negeri ini tidak dijaga."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 13, 'Lalu jawab mereka: "Hamba-hambamu ini dua belas orang, kami bersaudara, anak dari satu ayah di tanah Kanaan, tetapi yang bungsu sekarang ada pada ayah kami, dan seorang sudah tidak ada lagi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 14, 'Lalu kata Yusuf kepada mereka: "Sudahlah! Seperti telah kukatakan kepadamu tadi: kamu ini pengintai.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 15, 'Dalam hal ini juga kamu harus diuji: demi hidup Firaun, kamu tidak akan pergi dari sini, jika saudaramu yang bungsu itu tidak datang ke mari.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 16, 'Suruhlah seorang dari padamu untuk menjemput adikmu itu, tetapi kamu ini harus tinggal terkurung di sini. Dengan demikian perkataanmu dapat diuji, apakah benar, dan jika tidak, demi hidup Firaun, sungguh-sungguhlah kamu ini pengintai."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 17, 'Dan dimasukkannyalah mereka bersama-sama ke dalam tahanan tiga hari lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 18, 'Pada hari yang ketiga berkatalah Yusuf kepada mereka: "Buatlah begini, maka kamu akan tetap hidup, aku takut akan Allah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 19, 'Jika kamu orang jujur, biarkanlah dari kamu bersaudara tinggal seorang terkurung dalam rumah tahanan, tetapi pergilah kamu, bawalah gandum untuk meredakan lapar seisi rumahmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 20, 'Tetapi saudaramu yang bungsu itu haruslah kamu bawa kepadaku, supaya perkataanmu itu ternyata benar dan kamu jangan mati." Demikianlah diperbuat mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 21, 'Mereka berkata seorang kepada yang lain: "Betul-betullah kita menanggung akibat dosa kita terhadap adik kita itu: bukankah kita melihat bagaimana sesak hatinya, ketika ia memohon belas kasihan kepada kita, tetapi kita tidak mendengarkan permohonannya. Itulah sebabnya kesesakan ini menimpa kita."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 22, 'Lalu Ruben menjawab mereka: "Bukankah dahulu kukatakan kepadamu: Janganlah kamu berbuat dosa terhadap anak itu! Tetapi kamu tidak mendengarkan perkataanku. Sekarang darahnya dituntut dari pada kita."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 23, 'Tetapi mereka tidak tahu, bahwa Yusuf mengerti perkataan mereka, sebab mereka memakai seorang juru bahasa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 24, 'Maka Yusuf mengundurkan diri dari mereka, lalu menangis. Kemudian ia kembali kepada mereka dan berkata-kata dengan mereka; ia mengambil Simeon dari antara mereka; lalu disuruh belenggu di depan mata mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 25, 'Sesudah itu Yusuf memerintahkan, bahwa tempat gandum mereka akan diisi dengan gandum dan bahwa uang mereka masing-masing akan dikembalikan ke dalam karungnya, serta bekal mereka di jalan akan diberikan kepada mereka. Demikianlah dilakukan orang kepada mereka itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 26, 'Sesudah itu merekapun memuat gandum itu ke atas keledai mereka, lalu berangkat dari situ.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 27, 'Ketika seorang membuka karungnya untuk memberi makan keledainya di tempat bermalam, dilihatnyalah uangnya ada di dalam mulut karungnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 28, 'Katanya kepada saudara-saudaranya: "Uangku dikembalikan; lihat, ada dalam karungku!" Lalu hati mereka menjadi tawar dan mereka berpandang-pandangan dengan gemetar serta berkata: "Apakah juga yang diperbuat Allah terhadap kita!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 29, 'Ketika mereka sampai kepada Yakub, ayah mereka, di tanah Kanaan, mereka menceritakan segala sesuatu yang dialaminya, katanya:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 30, '"Orang itu, yakni yang menjadi tuan atas negeri itu, telah menegor kami dengan membentak dan memperlakukan kami sebagai pengintai negeri itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 31, 'Tetapi kata kami kepadanya: Kami orang jujur, kami bukan pengintai.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 32, 'Kami dua belas orang bersaudara, anak-anak ayah kami; seorang sudah tidak ada lagi, dan yang bungsu ada sekarang pada ayah kami, di tanah Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 33, 'Lalu kata orang itu, yakni yang menjadi tuan atas negeri itu, kepada kami: Dari hal ini aku akan tahu, apakah kamu orang jujur: dari kamu bersaudara haruslah kamu tinggalkan seorang padaku; kemudian bawalah gandum untuk meredakan lapar seisi rumahmu dan pergilah;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 34, 'lalu bawalah kepadaku saudaramu yang bungsu itu, maka aku akan tahu, bahwa kamu bukan pengintai, tetapi orang jujur; dan aku akan mengembalikan saudaramu itu kepadamu, dan bolehlah kamu menjalani negeri ini dengan bebas."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 35, 'Ketika mereka mengosongkan karungnya, tampaklah ada pundi-pundi uang masing-masing dalam karungnya; dan ketika mereka beserta ayah mereka melihat pundi-pundi uang itu, ketakutanlah mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 36, 'Dan Yakub, ayah mereka, berkata kepadanya: "Kamu membuat aku kehilangan anak-anakku: Yusuf tidak ada lagi, dan Simeon tidak ada lagi, sekarang Benyaminpun hendak kamu bawa juga. Aku inilah yang menanggung segala-galanya itu!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 37, 'Lalu berkatalah Ruben kepada ayahnya: "Kedua anakku laki-laki boleh engkau bunuh, jika ia tidak kubawa kepadamu; serahkanlah dia ke dalam tanganku, maka dia akan kubawa kembali kepadamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 42, 38, 'Tetapi jawabnya: "Anakku itu tidak akan pergi ke sana bersama-sama dengan kamu, sebab kakaknya telah mati dan hanya dialah yang tinggal; jika dia ditimpa kecelakaan di jalan yang akan kamu tempuh, maka tentulah kamu akan menyebabkan aku yang ubanan ini turun ke dunia orang mati karena dukacita."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 1, 'Tetapi hebat sekali kelaparan di negeri itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 2, 'Dan setelah gandum yang dibawa mereka dari Mesir habis dimakan, berkatalah ayah mereka: "Pergilah pula membeli sedikit bahan makanan untuk kita."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 3, 'Lalu Yehuda menjawabnya: "Orang itu telah memperingatkan kami dengan sungguh-sungguh: Kamu tidak boleh melihat mukaku, jika adikmu itu tidak ada bersama-sama dengan kamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 4, 'Jika engkau mau membiarkan adik kami pergi bersama-sama dengan kami, maka kami mau pergi ke sana dan membeli bahan makanan bagimu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 5, 'Tetapi jika engkau tidak mau membiarkan dia pergi, maka kami tidak akan pergi ke sana, sebab orang itu telah berkata kepada kami: Kamu tidak boleh melihat mukaku, jika adikmu itu tidak ada bersama-sama dengan kamu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 6, 'Lalu berkatalah Israel: "Mengapa kamu mendatangkan malapetaka kepadaku dengan memberitahukan kepada orang itu, bahwa masih ada adikmu seorang?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 7, 'Jawab mereka: "Orang itu telah menanyai kami dengan seksama tentang kami sendiri dan tentang sanak saudara kita: Masih hidupkah ayahmu? Adakah adikmu lagi? Dan kami telah memberitahukan semuanya kepadanya seperti yang sebenarnya. Bagaimana kami dapat menduga bahwa ia akan berkata: Bawalah ke mari adikmu itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 8, 'Lalu berkatalah Yehuda kepada Israel, ayahnya: "Biarkanlah anak itu pergi bersama-sama dengan aku; maka kami akan bersiap dan pergi, supaya kita tetap hidup dan jangan mati, baik kami maupun engkau dan anak-anak kami.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 9, 'Akulah yang menanggung dia; engkau boleh menuntut dia dari padaku; jika aku tidak membawa dia kepadamu dan menempatkan dia di depanmu, maka akulah yang berdosa terhadap engkau untuk selama-lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 10, 'Jika kita tidak berlambat-lambat, maka tentulah kami sekarang sudah dua kali pulang."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 11, 'Lalu Israel, ayah mereka, berkata kepadanya: "Jika demikian, perbuatlah begini: Ambillah hasil yang terbaik dari negeri ini dalam tempat gandummu dan bawalah kepada orang itu sebagai persembahan: sedikit balsam dan sedikit madu, damar dan damar ladan, buah kemiri dan buah badam.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 12, 'Dan bawalah uang dua kali lipat banyaknya: uang yang telah dikembalikan ke dalam mulut karung-karungmu itu haruslah kamu bawa kembali; mungkin itu suatu kekhilafan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 13, 'Bawalah juga adikmu itu, bersiaplah dan kembalilah pula kepada orang itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 14, 'Allah Yang Mahakuasa kiranya membuat orang itu menaruh belas kasihan kepadamu, supaya ia membiarkan saudaramu yang lain itu beserta Benyamin kembali. Mengenai aku ini, jika terpaksa aku kehilangan anak-anakku, biarlah juga kehilangan!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 15, 'Lalu orang-orang itu mengambil persembahan itu dan mengambil uang dua kali lipat banyaknya, beserta Benyamin juga; mereka bersiap dan pergi ke Mesir. Kemudian berdirilah mereka di depan Yusuf.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 16, 'Ketika Yusuf melihat Benyamin bersama-sama dengan mereka, berkatalah ia kepada kepala rumahnya: "Bawalah orang-orang ini ke dalam rumah, sembelihlah seekor hewan dan siapkanlah itu, sebab orang-orang ini akan makan bersama-sama dengan aku pada tengah hari ini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 17, 'Orang itu melakukan seperti yang dikatakan Yusuf dan dibawanyalah orang-orang itu ke dalam rumah Yusuf.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 18, 'Lalu ketakutanlah orang-orang itu, karena mereka dibawa ke dalam rumah Yusuf. Kata mereka: "Yang menjadi sebab kita dibawa ke sini, ialah perkara uang yang dikembalikan ke dalam karung kita pada mulanya itu, supaya kita disergap dan ditangkap dan supaya kita dijadikan budak dan keledai kita diambil."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 19, 'Karena itu mereka mendekati kepala rumah Yusuf itu, dan berkata kepadanya di depan pintu rumah:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 20, '"Mohon bicara tuan! Kami dahulu datang ke mari untuk membeli bahan makanan,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 21, 'tetapi ketika kami sampai ke tempat bermalam dan membuka karung kami, tampaklah uang kami masing-masing dengan tidak kurang jumlahnya ada di dalam mulut karung. Tetapi sekarang kami membawanya kembali.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 22, 'Uang lain kami bawa juga ke mari untuk membeli bahan makanan; kami tidak tahu siapa yang menaruh uang kami itu ke dalam karung kami."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 23, 'Tetapi jawabnya: "Tenang sajalah, jangan takut; Allahmu dan Allah bapamu telah memberikan kepadamu harta terpendam dalam karungmu; uangmu itu telah kuterima." Kemudian dikeluarkannyalah Simeon dan dibawanya kepada mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 24, 'Setelah orang itu membawa mereka ke dalam rumah Yusuf, diberikannyalah air, supaya mereka membasuh kaki; juga keledai mereka diberinya makan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 25, 'Sesudah itu mereka menyiapkan persembahannya menantikan Yusuf datang pada waktu tengah hari, sebab mereka telah mendengar, bahwa mereka akan makan di situ.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 26, 'Ketika Yusuf telah pulang, mereka membawa persembahan yang ada pada mereka itu kepada Yusuf di dalam rumah, lalu sujud kepadanya sampai ke tanah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 27, 'Sesudah itu ia bertanya kepada mereka apakah mereka selamat; lagi katanya: "Apakah ayahmu yang tua yang kamu sebutkan itu selamat? Masih hidupkah ia?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 28, 'Jawab mereka: "Hambamu, ayah kami, ada selamat; ia masih hidup." Sesudah itu berlututlah mereka dan sujud.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 29, 'Ketika Yusuf memandang kepada mereka, dilihatnyalah Benyamin, adiknya, yang seibu dengan dia, lalu katanya: "Inikah adikmu yang bungsu itu, yang telah kamu sebut-sebut kepadaku?" Lagi katanya: "Allah kiranya memberikan kasih karunia kepadamu, anakku!"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 30, 'Lalu segeralah Yusuf pergi dari situ, sebab hatinya sangat terharu merindukan adiknya itu, dan dicarinyalah tempat untuk menangis; ia masuk ke dalam kamar, lalu menangis di situ.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 31, 'Sesudah itu dibasuhnyalah mukanya dan ia tampil ke luar. Ia menahan hatinya dan berkata: "Hidangkanlah makanan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 32, 'Lalu dihidangkanlah makanan, bagi Yusuf tersendiri, bagi saudara-saudaranya tersendiri dan bagi orang-orang Mesir yang bersama-sama makan dengan mereka itu tersendiri; sebab orang Mesir tidak boleh makan bersama-sama dengan orang Ibrani, karena hal itu suatu kekejian bagi orang Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 33, 'Saudara-saudaranya itu duduk di depan Yusuf, dari yang sulung sampai yang bungsu, sehingga mereka berpandang-pandangan dengan heran.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 43, 34, 'Lalu disajikan kepada mereka hidangan dari meja Yusuf, tetapi yang diterima Benyamin adalah lima kali lebih banyak dari pada setiap orang yang lain. Lalu minumlah mereka dan bersukaria bersama-sama dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 1, 'Sesudah itu diperintahkannyalah kepada kepala rumahnya: "Isilah karung orang-orang itu dengan gandum, seberapa yang dapat dibawa mereka, dan letakkanlah uang masing-masing di dalam mulut karungnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 2, 'Dan pialaku, piala perak itu, taruhlah di dalam mulut karung anak yang bungsu serta uang pembayar gandumnya juga." Maka diperbuatnyalah seperti yang dikatakan Yusuf.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 3, 'Ketika paginya hari terang tanah, orang melepas mereka beserta keledai mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 4, 'Tetapi baru saja mereka keluar dari kota itu, belum lagi jauh jaraknya, berkatalah Yusuf kepada kepala rumahnya: "Bersiaplah, kejarlah orang-orang itu, dan apabila engkau sampai kepada mereka, katakanlah kepada mereka: Mengapa kamu membalas yang baik dengan yang jahat?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 5, 'Bukankah ini piala yang dipakai tuanku untuk minum dan yang biasa dipakainya untuk menelaah? Kamu berbuat jahat dengan melakukan yang demikian."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 6, 'Ketika sampai kepada mereka, diberitakannyalah kepada mereka perkataan Yusuf itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 7, 'Jawab mereka kepadanya: "Mengapa tuanku mengatakan perkataan yang demikian? Jauhlah dari pada hamba-hambamu ini untuk berbuat begitu!', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 8, 'Bukankah uang yang kami dapati di dalam mulut karung kami telah kami bawa kembali kepadamu dari tanah Kanaan? Masakan kami mencuri emas atau perak dari rumah tuanmu?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 9, 'Pada siapa dari hamba-hambamu ini kedapatan piala itu, biarlah ia mati, juga kami ini akan menjadi budak tuanku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 10, 'Sesudah itu berkatalah ia: "Ya, usulmu itu baik; tetapi pada siapa kedapatan piala itu, hanya dialah yang akan menjadi budakku dan kamu yang lain itu akan bebas dari salah."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 11, 'Lalu segeralah mereka masing-masing menurunkan karungnya ke tanah dan masing-masing membuka karungnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 12, 'Dan kepala rumah itu memeriksanya dengan teliti; ia mulai dengan yang sulung sampai kepada yang bungsu; maka kedapatanlah piala itu dalam karung Benyamin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 13, 'Lalu mereka mengoyakkan jubahnya dan masing-masing memuati keledainya, dan mereka kembali ke kota.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 14, 'Ketika Yehuda dan saudara-saudaranya sampai ke dalam rumah Yusuf, Yusuf masih ada di situ, sujudlah mereka sampai ke tanah di depannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 15, 'Berkatalah Yusuf kepada mereka: "Perbuatan apakah yang kamu lakukan ini? Tidakkah kamu tahu, bahwa seorang yang seperti aku ini pasti dapat menelaah?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 16, 'Sesudah itu berkatalah Yehuda: "Apakah yang akan kami katakan kepada tuanku, apakah yang akan kami jawab, dan dengan apakah kami akan membenarkan diri kami? Allah telah memperlihatkan kesalahan hamba-hambamu ini. Maka kami ini, budak tuankulah kami, baik kami maupun orang pada siapa kedapatan piala itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 17, 'Tetapi jawabnya: "Jauhlah dari padaku untuk berbuat demikian! Pada siapa kedapatan piala itu, dialah yang akan menjadi budakku, tetapi kamu ini, pergilah kembali dengan selamat kepada ayahmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 18, 'Lalu tampillah Yehuda mendekatinya dan berkata: "Mohon bicara tuanku, izinkanlah kiranya hambamu ini mengucapkan sepatah kata kepada tuanku dan janganlah kiranya bangkit amarahmu terhadap hambamu ini, sebab tuanku adalah seperti Firaun sendiri.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 19, 'Tuanku telah bertanya kepada hamba-hambanya ini: Masih adakah ayah atau saudara kamu?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 20, 'Dan kami menjawab tuanku: Kami masih mempunyai ayah yang tua dan masih ada anaknya yang muda, yang lahir pada masa tuanya; kakaknya telah mati, hanya dia sendirilah yang tinggal dari mereka yang seibu, sebab itu ayahnya sangat mengasihi dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 21, 'Lalu tuanku berkata kepada hamba-hambamu ini: Bawalah dia ke mari kepadaku, supaya mataku memandang dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 22, 'Tetapi jawab kami kepada tuanku: Anak itu tidak dapat meninggalkan ayahnya, sebab jika ia meninggalkan ayahnya, tentulah ayah ini mati.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 23, 'Kemudian tuanku berkata kepada hamba-hambamu ini: Jika adikmu yang bungsu itu tidak datang ke mari bersama-sama dengan kamu, kamu tidak boleh melihat mukaku lagi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 24, 'Setelah kami kembali kepada hambamu, ayahku, maka kami memberitahukan kepadanya perkataan tuanku itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 25, 'Kemudian ayah kami berkata: Kembalilah kamu membeli sedikit bahan makanan bagi kita.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 26, 'Tetapi jawab kami: Kami tidak dapat pergi ke sana. Jika adik kami yang bungsu bersama-sama dengan kami, barulah kami akan pergi ke sana, sebab kami tidak boleh melihat muka orang itu, apabila adik kami yang bungsu tidak bersama-sama dengan kami.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 27, 'Kemudian berkatalah hambamu, ayahku, kepada kami: Kamu tahu, bahwa isteriku telah melahirkan dua orang anak bagiku;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 28, 'yang seorang telah pergi dari padaku, dan aku telah berkata: Tentulah ia diterkam oleh binatang buas, dan sampai sekarang aku tidak melihat dia kembali.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 29, 'Jika anak ini kamu ambil pula dari padaku, dan ia ditimpa kecelakaan, maka tentulah kamu akan menyebabkan aku yang ubanan ini turun ke dunia orang mati karena nasib celaka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 30, 'Maka sekarang, apabila aku datang kepada hambamu, ayahku, dan tidak ada bersama-sama dengan kami anak itu, padahal ayahku tidak dapat hidup tanpa dia,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 31, 'tentulah akan terjadi, apabila dilihatnya anak itu tidak ada, bahwa ia akan mati, dan hamba-hambamu ini akan menyebabkan hambamu, ayah kami yang ubanan itu, turun ke dunia orang mati karena dukacita.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 32, 'Tetapi hambamu ini telah menanggung anak itu terhadap ayahku dengan perkataan: Jika aku tidak membawanya kembali kepada bapa, maka akulah yang berdosa kepada bapa untuk selama-lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 33, 'Oleh sebab itu, baiklah hambamu ini tinggal menjadi budak tuanku menggantikan anak itu, dan biarlah anak itu pulang bersama-sama dengan saudara-saudaranya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 44, 34, 'Sebab masakan aku pulang kepada ayahku, apabila anak itu tidak bersama-sama dengan aku? Aku tidak akan sanggup melihat nasib celaka yang akan menimpa ayahku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 1, 'Ketika itu Yusuf tidak dapat menahan hatinya lagi di depan semua orang yang berdiri di dekatnya, lalu berserulah ia: "Suruhlah keluar semua orang dari sini." Maka tidak ada seorangpun yang tinggal di situ bersama-sama Yusuf, ketika ia memperkenalkan dirinya kepada saudara-saudaranya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 2, 'Setelah itu menangislah ia keras-keras, sehingga kedengaran kepada orang Mesir dan kepada seisi istana Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 3, 'Dan Yusuf berkata kepada saudara-saudaranya: "Akulah Yusuf! Masih hidupkah bapa?" Tetapi saudara-saudaranya tidak dapat menjawabnya, sebab mereka takut dan gemetar menghadapi dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 4, 'Lalu kata Yusuf kepada saudara-saudaranya itu: "Marilah dekat-dekat." Maka mendekatlah mereka. Katanya lagi: "Akulah Yusuf, saudaramu, yang kamu jual ke Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 5, 'Tetapi sekarang, janganlah bersusah hati dan janganlah menyesali diri, karena kamu menjual aku ke sini, sebab untuk memelihara kehidupanlah Allah menyuruh aku mendahului kamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 6, 'Karena telah dua tahun ada kelaparan dalam negeri ini dan selama lima tahun lagi orang tidak akan membajak atau menuai.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 7, 'Maka Allah telah menyuruh aku mendahului kamu untuk menjamin kelanjutan keturunanmu di bumi ini dan untuk memelihara hidupmu, sehingga sebagian besar dari padamu tertolong.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 8, 'Jadi bukanlah kamu yang menyuruh aku ke sini, tetapi Allah; Dialah yang telah menempatkan aku sebagai bapa bagi Firaun dan tuan atas seluruh istananya dan sebagai kuasa atas seluruh tanah Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 9, 'Segeralah kamu kembali kepada bapa dan katakanlah kepadanya: Beginilah kata Yusuf, anakmu: Allah telah menempatkan aku sebagai tuan atas seluruh Mesir; datanglah mendapatkan aku, janganlah tunggu-tunggu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 10, 'Engkau akan tinggal di tanah Gosyen dan akan dekat kepadaku, engkau serta anak dan cucumu, kambing domba dan lembu sapimu dan segala milikmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 11, 'Di sanalah aku memelihara engkau?sebab kelaparan ini masih ada lima tahun lagi?supaya engkau jangan jatuh miskin bersama seisi rumahmu dan semua orang yang ikut serta dengan engkau.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 12, 'Dan kamu telah melihat dengan mata sendiri, dan saudaraku Benyamin juga, bahwa mulutku sendiri mengatakannya kepadamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 13, 'Sebab itu ceritakanlah kepada bapa segala kemuliaanku di negeri Mesir ini, dan segala yang telah kamu lihat, kemudian segeralah bawa bapa ke mari."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 14, 'Lalu dipeluknyalah leher Benyamin, adiknya itu, dan menangislah ia, dan menangis pulalah Benyamin pada bahu Yusuf.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 15, 'Yusuf mencium semua saudaranya itu dengan mesra dan ia menangis sambil memeluk mereka. Sesudah itu barulah saudara-saudaranya bercakap-cakap dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 16, 'Ketika dalam istana Firaun terdengar kabar, bahwa saudara-saudara Yusuf datang, hal itu diterima dengan baik oleh Firaun dan pegawai-pegawainya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 17, 'Lalu berkatalah Firaun kepada Yusuf: "Katakanlah kepada saudara-saudaramu Buatlah begini: muatilah binatang-binatangmu dan pergilah ke tanah Kanaan,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 18, 'jemputlah ayahmu dan seisi rumahmu dan datanglah mendapatkan aku, maka aku akan memberikan kepadamu apa yang paling baik di tanah Mesir, sehingga kamu akan mengecap kesuburan tanah ini.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 19, 'Selanjutnya engkau mendapat perintah mengatakan kepada mereka: Buatlah begini: bawalah kereta dari tanah Mesir untuk anak-anakmu dan isteri-isterimu, jemputlah ayahmu dari sana dan datanglah ke mari.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 20, 'Janganlah kamu merasa sayang meninggalkan barang-barangmu, sebab apa yang paling baik di seluruh tanah Mesir ini adalah milikmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 21, 'Demikianlah dilakukan oleh anak-anak Israel itu. Yusuf memberikan kereta kepada mereka menurut perintah Firaun; juga diberikan kepada mereka bekal di jalan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 22, 'Kepada mereka masing-masing diberikannya sepotong pesalin dan kepada Benyamin diberikannya tiga ratus uang perak dan lima potong pesalin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 23, 'Di samping itu kepada ayahnya dikirimkannya sepuluh ekor keledai jantan, dimuati dengan apa yang paling baik di Mesir, lagipula sepuluh ekor keledai betina, dimuati dengan gandum dan roti dan makanan untuk ayahnya dalam perjalanan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 24, 'Kemudian ia melepas saudara-saudaranya serta berkata kepada mereka: "Janganlah berbantah-bantah di jalan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 25, 'Demikianlah mereka pergi dari tanah Mesir dan sampai di tanah Kanaan, kepada Yakub, ayah mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 26, 'Mereka menceritakan kepadanya: "Yusuf masih hidup, bahkan dialah yang menjadi kuasa atas seluruh tanah Mesir." Tetapi hati Yakub tetap dingin, sebab ia tidak dapat mempercayai mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 27, 'Tetapi ketika mereka menyampaikan kepadanya segala perkataan yang diucapkan Yusuf, dan ketika dilihatnya kereta yang dikirim oleh Yusuf untuk menjemputnya, maka bangkitlah kembali semangat Yakub, ayah mereka itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 45, 28, 'Kata Yakub: "Cukuplah itu; anakku Yusuf masih hidup; aku mau pergi melihatnya, sebelum aku mati."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 1, 'Jadi berangkatlah Israel dengan segala miliknya dan ia tiba di Bersyeba, lalu dipersembahkannya korban sembelihan kepada Allah Ishak ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 2, 'Berfirmanlah Allah kepada Israel dalam penglihatan waktu malam: "Yakub, Yakub!" Sahutnya: "Ya, Tuhan."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 3, 'Lalu firman-Nya: "Akulah Allah, Allah ayahmu, janganlah takut pergi ke Mesir, sebab Aku akan membuat engkau menjadi bangsa yang besar di sana.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 4, 'Aku sendiri akan menyertai engkau pergi ke Mesir dan tentulah Aku juga akan membawa engkau kembali; dan tangan Yusuflah yang akan mengatupkan kelopak matamu nanti."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 5, 'Lalu berangkatlah Yakub dari Bersyeba, dan anak-anak Israel membawa Yakub, ayah mereka, beserta anak dan isteri mereka, dan mereka menaiki kereta yang dikirim Firaun untuk menjemputnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 6, 'Mereka membawa juga ternaknya dan harta bendanya, yang telah diperoleh mereka di tanah Kanaan, lalu tibalah mereka di Mesir, yakni Yakub dan seluruh keturunannya bersama-sama dengan dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 7, 'Anak-anak dan cucu-cucunya laki-laki dan perempuan, seluruh keturunannya dibawanyalah ke Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 8, 'Inilah nama-nama bani Israel yang datang ke Mesir, yakni Yakub beserta keturunannya. Anak sulung Yakub ialah Ruben.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 9, 'Anak-anak Ruben ialah Henokh, Palu, Hezron dan Karmi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 10, 'Anak-anak Simeon ialah Yemuel, Yamin, Ohad, Yakhin dan Zohar serta Saul, anak seorang perempuan Kanaan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 11, 'Anak-anak Lewi ialah Gerson, Kehat dan Merari.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 12, 'Anak-anak Yehuda ialah Er, Onan, Syela, Peres dan Zerah; tetapi Er dan Onan mati di tanah Kanaan; dan anak-anak Peres ialah Hezron dan Hamul.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 13, 'Anak-anak Isakhar ialah Tola, Pua, Ayub dan Simron.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 14, 'Anak-anak Zebulon ialah Sered, Elon dan Yahleel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 15, 'Itulah keturunan Lea, yang melahirkan bagi Yakub di Padan-Aram anak-anak lelaki serta Dina juga, anaknya yang perempuan. Jadi seluruhnya, laki-laki dan perempuan, berjumlah tiga puluh tiga jiwa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 16, 'Anak-anak Gad ialah Zifyon, Hagi, Syuni, Ezbon, Eri, Arodi dan Areli.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 17, 'Anak-anak Asyer ialah Yimna, Yiswa, Yiswi dan Beria; Serah ialah saudara perempuan mereka; dan anak-anak Beria ialah Heber dan Malkiel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 18, 'Itulah keturunan Zilpa, yakni hamba perempuan yang telah diberikan Laban kepada Lea, anaknya perempuan, dan yang melahirkan anak-anak bagi Yakub; seluruhnya enam belas jiwa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 19, 'Anak-anak Rahel, isteri Yakub, ialah Yusuf dan Benyamin.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 20, 'Bagi Yusuf lahir Manasye dan Efraim di tanah Mesir, yang dilahirkan baginya oleh Asnat, anak perempuan Potifera, imam di On.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 21, 'Anak-anak Benyamin ialah Bela, Bekher, Asybel, Gera, Naaman, Ehi, Rosh, Mupim, Hupim dan Ared.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 22, 'Itulah keturunan Rahel, yang telah lahir bagi Yakub, seluruhnya berjumlah empat belas jiwa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 23, 'Anak Dan ialah Husim.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 24, 'Anak-anak Naftali ialah Yahzeel, Guni, Yezer dan Syilem.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 25, 'Itulah keturunan Bilha, yakni hamba perempuan yang diberikan Laban kepada Rahel, anaknya yang perempuan dan yang melahirkan anak-anak itu bagi Yakub?seluruhnya berjumlah tujuh jiwa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 26, 'Semua orang yang tiba di Mesir bersama-sama dengan Yakub, yakni anak-anak kandungnya, dengan tidak terhitung isteri anak-anaknya, seluruhnya berjumlah enam puluh enam jiwa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 27, 'Anak-anak Yusuf yang lahir baginya di Mesir ada dua orang. Jadi keluarga Yakub yang tiba di Mesir, seluruhnya berjumlah tujuh puluh jiwa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 28, 'Yakub menyuruh Yehuda berjalan lebih dahulu mendapatkan Yusuf, supaya Yusuf datang ke Gosyen menemui ayahnya. Sementara itu sampailah mereka ke tanah Gosyen.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 29, 'Lalu Yusuf memasang keretanya dan pergi ke Gosyen, mendapatkan Israel, ayahnya. Ketika ia bertemu dengan dia, dipeluknyalah leher ayahnya dan lama menangis pada bahunya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 30, 'Berkatalah Israel kepada Yusuf: "Sekarang bolehlah aku mati, setelah aku melihat mukamu dan mengetahui bahwa engkau masih hidup."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 31, 'Kemudian berkatalah Yusuf kepada saudara-saudaranya dan kepada keluarga ayahnya itu: "Aku mau menghadap Firaun dan memberitahukan kepadanya: Saudara-saudaraku dan keluarga ayahku, yang tinggal di tanah Kanaan, telah datang kepadaku;', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 32, 'orang-orang itu gembala kambing domba, sebab mereka itu pemelihara ternak, dan kambing dombanya, lembu sapinya dan segala miliknya telah dibawa mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 33, 'Apabila Firaun memanggil kamu dan bertanya: Apakah pekerjaanmu?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 46, 34, 'maka jawablah: Hamba-hambamu ini pemelihara ternak, sejak dari kecil sampai sekarang, baik kami maupun nenek moyang kami?dengan maksud supaya kamu boleh diam di tanah Gosyen." ?Sebab segala gembala kambing domba adalah suatu kekejian bagi orang Mesir.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 1, 'Kemudian pergilah Yusuf memberitahukan kepada Firaun: "Ayahku dan saudara-saudaraku beserta kambing dombanya, lembu sapinya dan segala miliknya telah datang dari tanah Kanaan, dan sekarang mereka ada di tanah Gosyen."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 2, 'Dari antara saudara-saudaranya itu dibawanya lima orang menghadap Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 3, 'Firaun bertanya kepada saudara-saudara Yusuf itu: "Apakah pekerjaanmu?" Jawab mereka kepada Firaun: "Hamba-hambamu ini gembala domba, baik kami maupun nenek moyang kami."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 4, 'Lagi kata mereka kepada Firaun: "Kami datang untuk tinggal di negeri ini sebagai orang asing, sebab tidak ada lagi padang rumput untuk kumpulan ternak hamba-hambamu ini, karena hebat kelaparan itu di tanah Kanaan; maka sekarang, izinkanlah hamba-hambamu ini menetap di tanah Gosyen."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 5, 'Lalu berkatalah Firaun kepada Yusuf: "Ayahmu dan saudara-saudaramu telah datang kepadamu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 6, 'Tanah Mesir ini terbuka untukmu. Tunjukkanlah kepada ayahmu dan kepada saudara-saudaramu tempat menetap di tempat yang terbaik dari negeri ini, biarlah mereka diam di tanah Gosyen. Dan jika engkau tahu di antara mereka orang-orang yang tangkas, tempatkanlah mereka menjadi pengawas ternakku."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 7, 'Yusuf membawa juga Yakub, ayahnya, menghadap Firaun. Lalu Yakub memohonkan berkat bagi Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 8, 'Kemudian bertanyalah Firaun kepada Yakub: "Sudah berapa tahun umurmu?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 9, 'Jawab Yakub kepada Firaun: "Tahun-tahun pengembaraanku sebagai orang asing berjumlah seratus tiga puluh tahun. Tahun-tahun hidupku itu sedikit saja dan buruk adanya, tidak mencapai umur nenek moyangku, yakni jumlah tahun mereka mengembara sebagai orang asing."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 10, 'Lalu Yakub memohonkan berkat bagi Firaun, sesudah itu keluarlah ia dari depan Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 11, 'Yusuf menunjukkan kepada ayahnya dan saudara-saudaranya tempat untuk menetap dan memberikan kepada mereka tanah milik di tanah Mesir, di tempat yang terbaik di negeri itu, di tanah Rameses, seperti yang diperintahkan Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 12, 'Dan Yusuf memelihara ayahnya, saudara-saudaranya dan seisi rumah ayahnya dengan makanan, menurut jumlah anak-anak mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 13, 'Di seluruh negeri itu tidak ada makanan, sebab kelaparan itu sangat hebat, sehingga seisi tanah Mesir dan tanah Kanaan lemah lesu karena kelaparan itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 14, 'Maka Yusuf mengumpulkan segala uang yang terdapat di tanah Mesir dan di tanah Kanaan, yakni uang pembayar gandum yang dibeli mereka; dan Yusuf membawa uang itu ke dalam istana Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 15, 'Setelah habis uang di tanah Mesir dan di tanah Kanaan, datanglah semua orang Mesir menghadap Yusuf serta berkata: "Berilah makanan kepada kami! Mengapa kami harus mati di depanmu? Sebab tidak ada lagi uang."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 16, 'Jawab Yusuf: "Jika tidak ada lagi uang, berilah ternakmu, maka aku akan memberi makanan kepadamu sebagai ganti ternakmu itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 17, 'Lalu mereka membawa ternaknya kepada Yusuf dan Yusuf memberi makanan kepada mereka ganti kuda, kumpulan kambing domba dan kumpulan lembu sapi dan keledainya, jadi disediakannyalah bagi mereka makanan ganti segala ternaknya pada tahun itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 18, 'Setelah lewat tahun itu, datanglah mereka kepadanya, pada tahun yang kedua, serta berkata kepadanya: "Tidak usah kami sembunyikan kepada tuanku, bahwa setelah uang kami habis dan setelah kumpulan ternak kami menjadi milik tuanku, tidaklah ada lagi yang tinggal yang dapat kami serahkan kepada tuanku selain badan kami dan tanah kami.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 19, 'Mengapa kami harus mati di depan matamu, baik kami maupun tanah kami? Belilah kami dan tanah kami sebagai ganti makanan, maka kami dengan tanah kami akan menjadi hamba kepada Firaun. Berikanlah benih, supaya kami hidup dan jangan mati, dan supaya tanah itu jangan menjadi tandus."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 20, 'Lalu Yusuf membeli segala tanah orang Mesir untuk Firaun, sebab orang Mesir itu masing-masing menjual ladangnya, karena berat kelaparan itu menimpa mereka. Demikianlah negeri itu menjadi milik Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 21, 'Dan tentang rakyat itu, diperhambakannyalah mereka di daerah Mesir dari ujung yang satu sampai ujung yang lain.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 22, 'Hanya tanah para imam tidak dibelinya, sebab para imam mendapat tunjangan tetap dari Firaun, dan mereka hidup dari tunjangan itu; itulah sebabnya mereka tidak menjual tanahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 23, 'Berkatalah Yusuf kepada rakyat itu: "Pada hari ini aku telah membeli kamu dan tanahmu untuk Firaun; inilah benih bagimu, supaya kamu dapat menabur di tanah itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 24, 'Mengenai hasilnya, kamu harus berikan seperlima bagian kepada Firaun, dan yang empat bagian lagi, itulah menjadi benih untuk ladangmu dan menjadi makanan kamu dan mereka yang ada di rumahmu, dan menjadi makanan anak-anakmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 25, 'Lalu berkatalah mereka: "Engkau telah memelihara hidup kami; asal kiranya kami mendapat kasih tuanku, biarlah kami menjadi hamba kepada Firaun."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 26, 'Yusuf membuat hal itu menjadi suatu ketetapan mengenai tanah di Mesir sampai sekarang, yakni bahwa seperlima dari hasilnya menjadi milik Firaun; hanya tanah para imam tidak menjadi milik Firaun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 27, 'Maka diamlah Israel di tanah Mesir, di tanah Gosyen, dan mereka menjadi penduduk di situ. Mereka beranak cucu dan sangat bertambah banyak.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 28, 'Dan Yakub masih hidup tujuh belas tahun di tanah Mesir, maka umur Yakub, yakni tahun-tahun hidupnya, menjadi seratus empat puluh tujuh tahun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 29, 'Ketika hampir waktunya bahwa Israel akan mati, dipanggilnyalah anaknya, Yusuf, dan berkata kepadanya: "Jika aku mendapat kasihmu, letakkanlah kiranya tanganmu di bawah pangkal pahaku, dan bersumpahlah, bahwa engkau akan menunjukkan kasih dan setia kepadaku: Janganlah kiranya kuburkan aku di Mesir,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 30, 'karena aku mau mendapat perhentian bersama-sama dengan nenek moyangku. Sebab itu angkutlah aku dari Mesir dan kuburkanlah aku dalam kubur mereka." Jawabnya: "Aku akan berbuat seperti katamu itu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 47, 31, 'Kemudian kata Yakub: "Bersumpahlah kepadaku." Maka Yusufpun bersumpah kepadanya. Lalu sujudlah Israel di sebelah kepala tempat tidurnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 1, 'Sesudah itu ada orang mengatakan kepada Yusuf: "Ayahmu sakit!" Lalu dibawanyalah kedua anaknya, Manasye dan Efraim.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 2, 'Ketika diberitahukan kepada Yakub: "Telah datang anakmu Yusuf kepadamu," maka Israel mengumpulkan segenap kekuatannya dan duduklah ia di tempat tidurnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 3, 'Berkatalah Yakub kepada Yusuf: "Allah, Yang Mahakuasa telah menampakkan diri kepadaku di Lus di tanah Kanaan dan memberkati aku', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 4, 'serta berfirman kepadaku: Akulah yang membuat engkau beranak cucu, dan Aku akan membuat engkau bertambah banyak dan menjadi sekumpulan bangsa-bangsa; Aku akan memberikan negeri ini kepada keturunanmu untuk menjadi miliknya sampai selama-lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 5, 'Maka sekarang kedua anakmu yang lahir bagimu di tanah Mesir, sebelum aku datang kepadamu ke Mesir, akulah yang empunya mereka; akulah yang akan empunya Efraim dan Manasye sama seperti Ruben dan Simeon.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 6, 'Dan keturunanmu yang kauperoleh sesudah mereka, engkaulah yang empunya, tetapi dalam pembagian warisan nama mereka akan disebutkan berdasarkan nama kedua saudaranya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 7, 'Kalau aku, pada waktu perjalananku dari Padan, aku kematian Rahel di tanah Kanaan di jalan, ketika kami tidak berapa jauh lagi dari Efrata, dan aku menguburkannya di sana, di sisi jalan ke Efrata" ?yaitu Betlehem.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 8, 'Ketika Israel melihat anak-anak Yusuf itu, bertanyalah ia: "Siapakah ini?"', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 9, 'Jawab Yusuf kepada ayahnya: "Inilah anak-anakku yang telah diberikan Allah kepadaku di sini." Maka kata Yakub: "Dekatkanlah mereka kepadaku, supaya kuberkati mereka."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 10, 'Adapun mata Israel telah kabur karena tuanya, jadi ia tidak dapat lagi melihat. Kemudian Yusuf mendekatkan mereka kepada ayahnya: dan mereka dicium serta didekap oleh ayahnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 11, 'Lalu berkatalah Israel kepada Yusuf: "Tidak kusangka-sangka, bahwa aku akan melihat mukamu lagi, tetapi sekarang Allah bahkan memberi aku melihat keturunanmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 12, 'Lalu Yusuf menarik mereka dari antara lutut ayahnya, dan ia sujud dengan mukanya sampai ke tanah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 13, 'Setelah itu Yusuf memegang mereka keduanya, dengan tangan kanan dipegangnya Efraim, yaitu di sebelah kiri Israel, dan dengan tangan kiri Manasye, yaitu di sebelah kanan Israel, lalu didekatkannyalah mereka kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 14, 'Tetapi Israel mengulurkan tangan kanannya dan meletakkannya di atas kepala Efraim, walaupun ia yang bungsu, dan tangan kirinya di atas kepala Manasye?jadi tangannya bersilang, walaupun Manasye yang sulung.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 15, 'Sesudah itu diberkatinyalah Yusuf, katanya: "Nenekku dan ayahku, Abraham dan Ishak, telah hidup di hadapan Allah; Allah itu, sebagai Allah yang telah menjadi gembalaku selama hidupku sampai sekarang,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 16, 'dan sebagai Malaikat yang telah melepaskan aku dari segala bahaya, Dialah kiranya yang memberkati orang-orang muda ini, sehingga namaku serta nama nenek dan bapaku, Abraham dan Ishak, termasyhur oleh karena mereka dan sehingga mereka bertambah-tambah menjadi jumlah yang besar di bumi."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 17, 'Ketika Yusuf melihat bahwa ayahnya meletakkan tangan kanannya di atas kepala Efraim, hal itu dipandangnya tidak baik; lalu dipegangnya tangan ayahnya untuk memindahkannya dari atas kepala Efraim ke atas kepala Manasye.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 18, 'Katanya kepada ayahnya: "Janganlah demikian, ayahku, sebab inilah yang sulung, letakkanlah tangan kananmu ke atas kepalanya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 19, 'Tetapi ayahnya menolak, katanya: "Aku tahu, anakku, aku tahu; ia juga akan menjadi suatu bangsa dan ia juga akan menjadi besar kuasanya; walaupun begitu, adiknya akan lebih besar kuasanya dari padanya, dan keturunan adiknya itu akan menjadi sejumlah besar bangsa-bangsa."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 20, 'Lalu diberkatinyalah mereka pada waktu itu, katanya: "Dengan menyebutkan namamulah orang Israel akan memberkati, demikian: Allah kiranya membuat engkau seperti Efraim dan seperti Manasye." Demikianlah didahulukannya Efraim dari pada Manasye.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 21, 'Kemudian berkatalah Israel kepada Yusuf: "Tidak lama lagi aku akan mati, tetapi Allah akan menyertai kamu dan membawa kamu kembali ke negeri nenek moyangmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 48, 22, 'Dan sekarang aku memberikan kepadamu sebagai kelebihanmu dari pada saudara-saudaramu, suatu punggung gunung yang kurebut dengan pedang dan panahku dari tangan orang Amori."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 1, 'Kemudian Yakub memanggil anak-anaknya dan berkata: "Datanglah berkumpul, supaya kuberitahukan kepadamu, apa yang akan kamu alami di kemudian hari.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 2, 'Berhimpunlah kamu dan dengarlah, ya anak-anak Yakub, dengarlah kepada Israel, ayahmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 3, 'Ruben, engkaulah anak sulungku, kekuatanku dan permulaan kegagahanku, engkaulah yang terutama dalam keluhuran, yang terutama dalam kesanggupan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 4, 'Engkau yang membual sebagai air, tidak lagi engkau yang terutama, sebab engkau telah menaiki tempat tidur ayahmu; waktu itu engkau telah melanggar kesuciannya. Dia telah menaiki petiduranku!', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 5, 'Simeon dan Lewi bersaudara; senjata mereka ialah alat kekerasan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 6, 'Janganlah kiranya jiwaku turut dalam permupakatan mereka, janganlah kiranya rohku bersatu dengan perkumpulan mereka, sebab dalam kemarahannya mereka telah membunuh orang dan dalam keangkaraannya mereka telah memotong urat keting lembu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 7, 'Terkutuklah kemarahan mereka, sebab amarahnya keras, terkutuklah keberangan mereka, sebab berangnya bengis. Aku akan membagi-bagikan mereka di antara anak-anak Yakub dan menyerakkan mereka di antara anak-anak Israel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 8, 'Yehuda, engkau akan dipuji oleh saudara-saudaramu, tanganmu akan menekan tengkuk musuhmu, kepadamu akan sujud anak-anak ayahmu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 9, 'Yehuda adalah seperti anak singa: setelah menerkam, engkau naik ke suatu tempat yang tinggi, hai anakku; ia meniarap dan berbaring seperti singa jantan atau seperti singa betina; siapakah yang berani membangunkannya?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 10, 'Tongkat kerajaan tidak akan beranjak dari Yehuda ataupun lambang pemerintahan dari antara kakinya, sampai dia datang yang berhak atasnya, maka kepadanya akan takluk bangsa-bangsa.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 11, 'Ia akan menambatkan keledainya pada pohon anggur dan anak keledainya pada pohon anggur pilihan; ia akan mencuci pakaiannya dengan anggur dan bajunya dengan darah buah anggur.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 12, 'Matanya akan merah karena anggur dan giginya akan putih karena susu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 13, 'Zebulon akan diam di tepi pantai laut, ia akan menjadi pangkalan kapal, dan batasnya akan bersisi dengan Sidon.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 14, 'Isakhar adalah seperti keledai yang kuat tulangnya, yang meniarap diapit bebannya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 15, 'ketika dilihatnya, bahwa perhentian itu baik dan negeri itu permai, maka disendengkannyalah bahunya untuk memikul, lalu menjadi budak rodi.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 16, 'Adapun Dan, ia akan mengadili bangsanya sebagai salah satu suku Israel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 17, 'Semoga Dan menjadi seperti ular di jalan, seperti ular beludak di denai yang memagut tumit kuda, sehingga penunggangnya jatuh ke belakang.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 18, 'Aku menanti-nantikan keselamatan yang dari pada-Mu, ya TUHAN.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 19, 'Gad, ia akan diserang oleh gerombolan, tetapi ia akan menyerang tumit mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 20, 'Asyer, makanannya akan limpah mewah dan ia akan memberikan santapan raja-raja.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 21, 'Naftali adalah seperti rusa betina yang terlepas; ia akan melahirkan anak-anak indah.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 22, 'Yusuf adalah seperti pohon buah-buahan yang muda, pohon buah-buahan yang muda pada mata air. Dahan-dahannya naik mengatasi tembok.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 23, 'Walaupun pemanah-pemanah telah mengusiknya, memanahnya dan menyerbunya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 24, 'namun panahnya tetap kokoh dan lengan tangannya tinggal liat, oleh pertolongan Yang Mahakuat pelindung Yakub, oleh sebab gembalanya Gunung Batu Israel,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 25, 'oleh Allah ayahmu yang akan menolong engkau, dan oleh Allah Yang Mahakuasa, yang akan memberkati engkau dengan berkat dari langit di atas, dengan berkat samudera raya yang letaknya di bawah, dengan berkat buah dada dan kandungan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 26, 'Berkat ayahmu melebihi berkat gunung-gunung yang sejak dahulu, yakni yang paling sedap di bukit-bukit yang berabad-abad; semuanya itu akan turun ke atas kepala Yusuf, ke atas batu kepala orang yang teristimewa di antara saudara-saudaranya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 27, 'Benyamin adalah seperti serigala yang menerkam; pada waktu pagi ia memakan mangsanya dan pada waktu petang ia membagi-bagi rampasannya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 28, 'Itulah semuanya suku Israel, dua belas jumlahnya; dan itulah yang dikatakan ayahnya kepada mereka, ketika ia memberkati mereka; tiap-tiap orang diberkatinya dengan berkat yang diuntukkan kepada mereka masing-masing.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 29, 'Kemudian berpesanlah Yakub kepada mereka: "Apabila aku nanti dikumpulkan kepada kaum leluhurku, kuburkanlah aku di sisi nenek moyangku dalam gua yang di ladang Efron, orang Het itu,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 30, 'dalam gua yang di ladang Makhpela di sebelah timur Mamre di tanah Kanaan, ladang yang telah dibeli Abraham dari Efron, orang Het itu, untuk menjadi kuburan milik.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 31, 'Di situlah dikuburkan Abraham beserta Sara, isterinya; di situlah dikuburkan Ishak beserta Ribka, isterinya,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 32, 'dan di situlah juga kukuburkan Lea; ladang dengan gua yang ada di sana telah dibeli dari orang Het."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 49, 33, 'Setelah Yakub selesai berpesan kepada anak-anaknya, ditariknyalah kakinya ke atas tempat berbaring dan meninggallah ia, maka ia dikumpulkan kepada kaum leluhurnya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 1, 'Lalu Yusuf merebahkan dirinya mendekap muka ayahnya serta menangisi dan mencium dia.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 2, 'Dan Yusuf memerintahkan kepada tabib-tabib, yaitu hamba-hambanya, untuk merempah-rempahi mayat ayahnya; maka tabib-tabib itu merempah-rempahi mayat Israel.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 3, 'Hal itu memerlukan empat puluh hari lamanya, sebab demikianlah lamanya waktu yang diperlukan untuk merempah-rempahi, dan orang Mesir menangisi dia tujuh puluh hari lamanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 4, 'Setelah lewat hari-hari penangisan itu, berkatalah Yusuf kepada seisi istana Firaun: "Jika kiranya aku mendapat kasihmu, katakanlah kepada Firaun,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 5, 'bahwa ayahku telah menyuruh aku bersumpah, katanya: Tidak lama lagi aku akan mati; dalam kuburku yang telah kugali di tanah Kanaan, di situlah kaukuburkan aku. Oleh sebab itu, izinkanlah aku pergi ke sana, supaya aku menguburkan ayahku; kemudian aku akan kembali."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 6, 'Lalu berkatalah Firaun: "Pergilah ke sana dan kuburkanlah ayahmu itu, seperti yang telah disuruhnya engkau bersumpah."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 7, 'Lalu berjalanlah Yusuf ke sana untuk menguburkan ayahnya, dan bersama-sama dengan dia berjalanlah semua pegawai Firaun, para tua-tua dari istananya, dan semua tua-tua dari tanah Mesir,', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 8, 'serta seisi rumah Yusuf juga, saudara-saudaranya dan seisi rumah ayahnya; hanya anak-anaknya serta kambing domba dan lembu sapinya ditinggalkan mereka di tanah Gosyen.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 9, 'Baik kereta maupun orang-orang berkuda turut pergi ke sana bersama-sama dengan dia, sehingga iring-iringan itu sangat besar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 10, 'Setelah mereka sampai ke Goren-Haatad, yang di seberang sungai Yordan, maka mereka mengadakan di situ ratapan yang sangat sedih dan riuh; dan Yusuf mengadakan perkabungan tujuh hari lamanya karena ayahnya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 11, 'Ketika penduduk negeri itu, orang-orang Kanaan, melihat perkabungan di Goren-Haatad itu, berkatalah mereka: "Inilah perkabungan orang Mesir yang amat riuh." Itulah sebabnya tempat itu dinamai Abel-Mizraim, yang letaknya di seberang Yordan.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 12, 'Anak-anak Yakub melakukan kepadanya, seperti yang dipesankannya kepada mereka.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 13, 'Anak-anaknya mengangkut dia ke tanah Kanaan, dan mereka menguburkan dia dalam gua di ladang Makhpela yang telah dibeli Abraham dari Efron, orang Het itu, untuk menjadi kuburan milik, yaitu ladang yang di sebelah timur Mamre.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 14, 'Setelah ayahnya dikuburkan, pulanglah Yusuf ke Mesir, dia dan saudara-saudaranya dan semua orang yang turut pergi ke sana bersama-sama dengan dia untuk menguburkan ayahnya itu.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 15, 'Ketika saudara-saudara Yusuf melihat, bahwa ayah mereka telah mati, berkatalah mereka: "Boleh jadi Yusuf akan mendendam kita dan membalaskan sepenuhnya kepada kita segala kejahatan yang telah kita lakukan kepadanya."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 16, 'Sebab itu mereka menyuruh menyampaikan pesan ini kepada Yusuf: "Sebelum ayahmu mati, ia telah berpesan:', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 17, 'Beginilah harus kamu katakan kepada Yusuf: Ampunilah kiranya kesalahan saudara-saudaramu dan dosa mereka, sebab mereka telah berbuat jahat kepadamu. Maka sekarang, ampunilah kiranya kesalahan yang dibuat hamba-hamba Allah ayahmu." Lalu menangislah Yusuf, ketika orang berkata demikian kepadanya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 18, 'Juga saudara-saudaranya datang sendiri dan sujud di depannya serta berkata: "Kami datang untuk menjadi budakmu."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 19, 'Tetapi Yusuf berkata kepada mereka: "Janganlah takut, sebab aku inikah pengganti Allah?', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 20, 'Memang kamu telah mereka-rekakan yang jahat terhadap aku, tetapi Allah telah mereka-rekakannya untuk kebaikan, dengan maksud melakukan seperti yang terjadi sekarang ini, yakni memelihara hidup suatu bangsa yang besar.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 21, 'Jadi janganlah takut, aku akan menanggung makanmu dan makan anak-anakmu juga." Demikianlah ia menghiburkan mereka dan menenangkan hati mereka dengan perkataannya.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 22, 'Adapun Yusuf, ia tetap tinggal di Mesir beserta kaum keluarganya; dan Yusuf hidup seratus sepuluh tahun.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 23, 'Jadi Yusuf sempat melihat anak cucu Efraim sampai keturunan yang ketiga; juga anak-anak Makhir, anak Manasye, lahir di pangkuan Yusuf.', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 24, 'Berkatalah Yusuf kepada saudara-saudaranya: "Tidak lama lagi aku akan mati; tentu Allah akan memperhatikan kamu dan membawa kamu keluar dari negeri ini, ke negeri yang telah dijanjikan-Nya dengan sumpah kepada Abraham, Ishak dan Yakub."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 25, 'Lalu Yusuf menyuruh anak-anak Israel bersumpah, katanya: "Tentu Allah akan memperhatikan kamu; pada waktu itu kamu harus membawa tulang-tulangku dari sini."', 'id', 'TB'),
  ('1', 'kej', 'Kejadian', 50, 26, 'Kemudian matilah Yusuf, berumur seratus sepuluh tahun. Mayatnya dirempah-rempahi, dan ditaruh dalam peti mati di Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 1, 'Inilah nama para anak Israel yang datang ke Mesir bersama-sama dengan Yakub; mereka datang dengan keluarganya masing-masing:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 2, 'Ruben, Simeon, Lewi dan Yehuda;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 3, 'Isakhar, Zebulon dan Benyamin;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 4, 'Dan serta Naftali, Gad dan Asyer.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 5, 'Seluruh keturunan yang diperoleh Yakub berjumlah tujuh puluh jiwa. Tetapi Yusuf telah ada di Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 6, 'Kemudian matilah Yusuf, serta semua saudara-saudaranya dan semua orang yang seangkatan dengan dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 7, 'Orang-orang Israel beranak cucu dan tak terbilang jumlahnya; mereka bertambah banyak dan dengan dahsyat berlipat ganda, sehingga negeri itu dipenuhi mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 8, 'Kemudian bangkitlah seorang raja baru memerintah tanah Mesir, yang tidak mengenal Yusuf.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 9, 'Berkatalah raja itu kepada rakyatnya: "Bangsa Israel itu sangat banyak dan lebih besar jumlahnya dari pada kita.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 10, 'Marilah kita bertindak dengan bijaksana terhadap mereka, supaya mereka jangan bertambah banyak lagi dan?jika terjadi peperangan?jangan bersekutu nanti dengan musuh kita dan memerangi kita, lalu pergi dari negeri ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 11, 'Sebab itu pengawas-pengawas rodi ditempatkan atas mereka untuk menindas mereka dengan kerja paksa: mereka harus mendirikan bagi Firaun kota-kota perbekalan, yakni Pitom dan Raamses.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 12, 'Tetapi makin ditindas, makin bertambah banyak dan berkembang mereka, sehingga orang merasa takut kepada orang Israel itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 13, 'Lalu dengan kejam orang Mesir memaksa orang Israel bekerja,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 14, 'dan memahitkan hidup mereka dengan pekerjaan yang berat, yaitu mengerjakan tanah liat dan batu bata, dan berbagai-bagai pekerjaan di padang, ya segala pekerjaan yang dengan kejam dipaksakan orang Mesir kepada mereka itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 15, 'Raja Mesir juga memerintahkan kepada bidan-bidan yang menolong perempuan Ibrani, seorang bernama Sifra dan yang lain bernama Pua, katanya:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 16, '"Apabila kamu menolong perempuan Ibrani pada waktu bersalin, kamu harus memperhatikan waktu anak itu lahir: jika anak laki-laki, kamu harus membunuhnya, tetapi jika anak perempuan, bolehlah ia hidup."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 17, 'Tetapi bidan-bidan itu takut akan Allah dan tidak melakukan seperti yang dikatakan raja Mesir kepada mereka, dan membiarkan bayi-bayi itu hidup.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 18, 'Lalu raja Mesir memanggil bidan-bidan itu dan bertanya kepada mereka: "Mengapakah kamu berbuat demikian membiarkan hidup bayi-bayi itu?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 19, 'Jawab bidan-bidan itu kepada Firaun: "Sebab perempuan Ibrani tidak sama dengan perempuan Mesir; melainkan mereka kuat: sebelum bidan datang, mereka telah bersalin."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 20, 'Maka Allah berbuat baik kepada bidan-bidan itu; bertambah banyaklah bangsa itu dan sangat berlipat ganda.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 21, 'Dan karena bidan-bidan itu takut akan Allah, maka Ia membuat mereka berumah tangga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 1, 22, 'Lalu Firaun memberi perintah kepada seluruh rakyatnya: "Lemparkanlah segala anak laki-laki yang lahir bagi orang Ibrani ke dalam sungai Nil; tetapi segala anak perempuan biarkanlah hidup."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 1, 'Seorang laki-laki dari keluarga Lewi kawin dengan seorang perempuan Lewi;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 2, 'lalu mengandunglah ia dan melahirkan seorang anak laki-laki. Ketika dilihatnya, bahwa anak itu cantik, disembunyikannya tiga bulan lamanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 3, 'Tetapi ia tidak dapat menyembunyikannya lebih lama lagi, sebab itu diambilnya sebuah peti pandan, dipakalnya dengan gala-gala dan ter, diletakkannya bayi itu di dalamnya dan ditaruhnya peti itu di tengah-tengah teberau di tepi sungai Nil;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 4, 'kakaknya perempuan berdiri di tempat yang agak jauh untuk melihat, apakah yang akan terjadi dengan dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 5, 'Maka datanglah puteri Firaun untuk mandi di sungai Nil, sedang dayang-dayangnya berjalan-jalan di tepi sungai Nil, lalu terlihatlah olehnya peti yang di tengah-tengah teberau itu, maka disuruhnya hambanya perempuan untuk mengambilnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 6, 'Ketika dibukanya, dilihatnya bayi itu, dan tampaklah anak itu menangis, sehingga belas kasihanlah ia kepadanya dan berkata: "Tentulah ini bayi orang Ibrani."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 7, 'Lalu bertanyalah kakak anak itu kepada puteri Firaun: "Akan kupanggilkah bagi tuan puteri seorang inang penyusu dari perempuan Ibrani untuk menyusukan bayi itu bagi tuan puteri?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 8, 'Sahut puteri Firaun kepadanya: "Baiklah." Lalu pergilah gadis itu memanggil ibu bayi itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 9, 'Maka berkatalah puteri Firaun kepada ibu itu: "Bawalah bayi ini dan susukanlah dia bagiku, maka aku akan memberi upah kepadamu." Kemudian perempuan itu mengambil bayi itu dan menyusuinya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 10, 'Ketika anak itu telah besar, dibawanyalah kepada puteri Firaun, yang mengangkatnya menjadi anaknya, dan menamainya Musa, sebab katanya: "Karena aku telah menariknya dari air."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 11, 'Pada waktu itu, ketika Musa telah dewasa, ia keluar mendapatkan saudara-saudaranya untuk melihat kerja paksa mereka; lalu dilihatnyalah seorang Mesir memukul seorang Ibrani, seorang dari saudara-saudaranya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 12, 'Ia menoleh ke sana sini dan ketika dilihatnya tidak ada orang, dibunuhnya orang Mesir itu, dan disembunyikannya mayatnya dalam pasir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 13, 'Ketika keesokan harinya ia keluar lagi, didapatinya dua orang Ibrani tengah berkelahi. Ia bertanya kepada yang bersalah itu: "Mengapa engkau pukul temanmu?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 14, 'Tetapi jawabnya: "Siapakah yang mengangkat engkau menjadi pemimpin dan hakim atas kami? Apakah engkau bermaksud membunuh aku, sama seperti engkau telah membunuh orang Mesir itu?" Musa menjadi takut, sebab pikirnya: "Tentulah perkara itu telah ketahuan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 15, 'Ketika Firaun mendengar tentang perkara itu, dicarinya ikhtiar untuk membunuh Musa. Tetapi Musa melarikan diri dari hadapan Firaun dan tiba di tanah Midian, lalu ia duduk-duduk di tepi sebuah sumur.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 16, 'Adapun imam di Midian itu mempunyai tujuh anak perempuan. Mereka datang menimba air dan mengisi palungan-palungan untuk memberi minum kambing domba ayahnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 17, 'Maka datanglah gembala-gembala yang mengusir mereka, lalu Musa bangkit menolong mereka dan memberi minum kambing domba mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 18, 'Ketika mereka sampai kepada Rehuel, ayah mereka, berkatalah ia: "Mengapa selekas itu kamu pulang hari ini?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 19, 'Jawab mereka: "Seorang Mesir menolong kami terhadap gembala-gembala, bahkan ia menimba air banyak-banyak untuk kami dan memberi minum kambing domba."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 20, 'Ia berkata kepada anak-anaknya: "Di manakah ia? Mengapakah kamu tinggalkan orang itu? Panggillah dia makan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 21, 'Musa bersedia tinggal di rumah itu, lalu diberikan Rehuellah Zipora, anaknya, kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 22, 'Perempuan itu melahirkan seorang anak laki-laki, maka Musa menamainya Gersom, sebab katanya: "Aku telah menjadi seorang pendatang di negeri asing."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 23, 'Lama sesudah itu matilah raja Mesir. Tetapi orang Israel masih mengeluh karena perbudakan, dan mereka berseru-seru, sehingga teriak mereka minta tolong karena perbudakan itu sampai kepada Allah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 24, 'Allah mendengar mereka mengerang, lalu Ia mengingat kepada perjanjian-Nya dengan Abraham, Ishak dan Yakub.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 2, 25, 'Maka Allah melihat orang Israel itu, dan Allah memperhatikan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 1, 'Adapun Musa, ia biasa menggembalakan kambing domba Yitro, mertuanya, imam di Midian. Sekali, ketika ia menggiring kambing domba itu ke seberang padang gurun, sampailah ia ke gunung Allah, yakni gunung Horeb.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 2, 'Lalu Malaikat TUHAN menampakkan diri kepadanya di dalam nyala api yang keluar dari semak duri. Lalu ia melihat, dan tampaklah: semak duri itu menyala, tetapi tidak dimakan api.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 3, 'Musa berkata: "Baiklah aku menyimpang ke sana untuk memeriksa penglihatan yang hebat itu. Mengapakah tidak terbakar semak duri itu?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 4, 'Ketika dilihat TUHAN, bahwa Musa menyimpang untuk memeriksanya, berserulah Allah dari tengah-tengah semak duri itu kepadanya: "Musa, Musa!" dan ia menjawab: "Ya, Allah."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 5, 'Lalu Ia berfirman: "Janganlah datang dekat-dekat: tanggalkanlah kasutmu dari kakimu, sebab tempat, di mana engkau berdiri itu, adalah tanah yang kudus."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 6, 'Lagi Ia berfirman: "Akulah Allah ayahmu, Allah Abraham, Allah Ishak dan Allah Yakub." Lalu Musa menutupi mukanya, sebab ia takut memandang Allah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 7, 'Dan TUHAN berfirman: "Aku telah memperhatikan dengan sungguh kesengsaraan umat-Ku di tanah Mesir, dan Aku telah mendengar seruan mereka yang disebabkan oleh pengerah-pengerah mereka, ya, Aku mengetahui penderitaan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 8, 'Sebab itu Aku telah turun untuk melepaskan mereka dari tangan orang Mesir dan menuntun mereka keluar dari negeri itu ke suatu negeri yang baik dan luas, suatu negeri yang berlimpah-limpah susu dan madunya, ke tempat orang Kanaan, orang Het, orang Amori, orang Feris, orang Hewi dan orang Yebus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 9, 'Sekarang seruan orang Israel telah sampai kepada-Ku; juga telah Kulihat, betapa kerasnya orang Mesir menindas mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 10, 'Jadi sekarang, pergilah, Aku mengutus engkau kepada Firaun untuk membawa umat-Ku, orang Israel, keluar dari Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 11, 'Tetapi Musa berkata kepada Allah: "Siapakah aku ini, maka aku yang akan menghadap Firaun dan membawa orang Israel keluar dari Mesir?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 12, 'Lalu firman-Nya: "Bukankah Aku akan menyertai engkau? Inilah tanda bagimu, bahwa Aku yang mengutus engkau: apabila engkau telah membawa bangsa itu keluar dari Mesir, maka kamu akan beribadah kepada Allah di gunung ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 13, 'Lalu Musa berkata kepada Allah: "Tetapi apabila aku mendapatkan orang Israel dan berkata kepada mereka: Allah nenek moyangmu telah mengutus aku kepadamu, dan mereka bertanya kepadaku: bagaimana tentang nama-Nya? ?apakah yang harus kujawab kepada mereka?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 14, 'Firman Allah kepada Musa: "AKU ADALAH AKU." Lagi firman-Nya: "Beginilah kaukatakan kepada orang Israel itu: AKULAH AKU telah mengutus aku kepadamu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 15, 'Selanjutnya berfirmanlah Allah kepada Musa: "Beginilah kaukatakan kepada orang Israel: TUHAN, Allah nenek moyangmu, Allah Abraham, Allah Ishak dan Allah Yakub, telah mengutus aku kepadamu: itulah nama-Ku untuk selama-lamanya dan itulah sebutan-Ku turun-temurun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 16, 'Pergilah, kumpulkanlah para tua-tua Israel dan katakanlah kepada mereka: TUHAN, Allah nenek moyangmu, Allah Abraham, Ishak dan Yakub, telah menampakkan diri kepadaku, serta berfirman: Aku sudah mengindahkan kamu, juga apa yang dilakukan kepadamu di Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 17, 'Jadi Aku telah berfirman: Aku akan menuntun kamu keluar dari kesengsaraan di Mesir menuju ke negeri orang Kanaan, orang Het, orang Amori, orang Feris, orang Hewi dan orang Yebus, ke suatu negeri yang berlimpah-limpah susu dan madunya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 18, 'Dan bilamana mereka mendengarkan perkataanmu, maka engkau harus beserta para tua-tua Israel pergi kepada raja Mesir, dan kamu harus berkata kepadanya: TUHAN, Allah orang Ibrani, telah menemui kami; oleh sebab itu, izinkanlah kiranya kami pergi ke padang gurun tiga hari perjalanan jauhnya untuk mempersembahkan korban kepada TUHAN, Allah kami.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 19, 'Tetapi Aku tahu, bahwa raja Mesir tidak akan membiarkan kamu pergi, kecuali dipaksa oleh tangan yang kuat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 20, 'Tetapi Aku akan mengacungkan tangan-Ku dan memukul Mesir dengan segala perbuatan yang ajaib, yang akan Kulakukan di tengah-tengahnya; sesudah itu ia akan membiarkan kamu pergi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 21, 'Dan Aku akan membuat orang Mesir bermurah hati terhadap bangsa ini, sehingga, apabila kamu pergi, kamu tidak pergi dengan tangan hampa,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 3, 22, 'tetapi tiap-tiap perempuan harus meminta dari tetangganya dan dari perempuan yang tinggal di rumahnya, barang-barang perak dan emas dan kain-kain, yang akan kamu kenakan kepada anak-anakmu lelaki dan perempuan; demikianlah kamu akan merampasi orang Mesir itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 1, 'Lalu sahut Musa: "Bagaimana jika mereka tidak percaya kepadaku dan tidak mendengarkan perkataanku, melainkan berkata: TUHAN tidak menampakkan diri kepadamu?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 2, 'TUHAN berfirman kepadanya: "Apakah yang di tanganmu itu?" Jawab Musa: "Tongkat."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 3, 'Firman TUHAN: "Lemparkanlah itu ke tanah." Dan ketika dilemparkannya ke tanah, maka tongkat itu menjadi ular, sehingga Musa lari meninggalkannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 4, 'Tetapi firman TUHAN kepada Musa: "Ulurkanlah tanganmu dan peganglah ekornya" ?Musa mengulurkan tangannya, ditangkapnya ular itu, lalu menjadi tongkat di tangannya', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 5, '?"supaya mereka percaya, bahwa TUHAN, Allah nenek moyang mereka, Allah Abraham, Allah Ishak dan Allah Yakub telah menampakkan diri kepadamu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 6, 'Lagi firman TUHAN kepadanya: "Masukkanlah tanganmu ke dalam bajumu." Dimasukkannya tangannya ke dalam bajunya, dan setelah ditariknya ke luar, maka tangannya kena kusta, putih seperti salju.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 7, 'Sesudah itu firman-Nya: "Masukkanlah tanganmu kembali ke dalam bajumu." Musa memasukkan tangannya kembali ke dalam bajunya dan setelah ditariknya ke luar, maka tangan itu pulih kembali seperti seluruh badannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 8, '"Jika mereka tidak percaya kepadamu dan tidak mengindahkan tanda mujizat yang pertama, maka mereka akan percaya kepada tanda mujizat yang kedua.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 9, 'Dan jika mereka tidak juga percaya kepada kedua tanda mujizat ini dan tidak mendengarkan perkataanmu, maka engkau harus mengambil air dari sungai Nil dan harus kaucurahkan di tanah yang kering, lalu air yang kauambil itu akan menjadi darah di tanah yang kering itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 10, 'Lalu kata Musa kepada TUHAN: "Ah, Tuhan, aku ini tidak pandai bicara, dahulupun tidak dan sejak Engkau berfirman kepada hamba-Mupun tidak, sebab aku berat mulut dan berat lidah."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 11, 'Tetapi TUHAN berfirman kepadanya: "Siapakah yang membuat lidah manusia, siapakah yang membuat orang bisu atau tuli, membuat orang melihat atau buta; bukankah Aku, yakni TUHAN?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 12, 'Oleh sebab itu, pergilah, Aku akan menyertai lidahmu dan mengajar engkau, apa yang harus kaukatakan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 13, 'Tetapi Musa berkata: "Ah, Tuhan, utuslah kiranya siapa saja yang patut Kauutus."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 14, 'Maka bangkitlah murka TUHAN terhadap Musa dan Ia berfirman: "Bukankah di situ Harun, orang Lewi itu, kakakmu? Aku tahu, bahwa ia pandai bicara; lagipula ia telah berangkat menjumpai engkau, dan apabila ia melihat engkau, ia akan bersukacita dalam hatinya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 15, 'Maka engkau harus berbicara kepadanya dan menaruh perkataan itu ke dalam mulutnya; Aku akan menyertai lidahmu dan lidahnya dan mengajarkan kepada kamu apa yang harus kamu lakukan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 16, 'Ia harus berbicara bagimu kepada bangsa itu, dengan demikian ia akan menjadi penyambung lidahmu dan engkau akan menjadi seperti Allah baginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 17, 'Dan bawalah tongkat ini di tanganmu, yang harus kaupakai untuk membuat tanda-tanda mujizat."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 18, 'Lalu Musa kembali kepada mertuanya Yitro serta berkata kepadanya: "Izinkanlah kiranya aku kembali kepada saudara-saudaraku, yang ada di Mesir, untuk melihat apakah mereka masih hidup." Yitro berkata kepada Musa: "Pergilah dengan selamat."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 19, 'Adapun TUHAN sudah berfirman kepada Musa di Midian: "Kembalilah ke Mesir, sebab semua orang yang ingin mencabut nyawamu telah mati."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 20, 'Kemudian Musa mengajak isteri dan anak-anaknya lelaki, lalu menaikkan mereka ke atas keledai dan ia kembali ke tanah Mesir; dan tongkat Allah itu dipegangnya di tangannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 21, 'Firman TUHAN kepada Musa: "Pada waktu engkau hendak kembali ini ke Mesir, ingatlah, supaya segala mujizat yang telah Kuserahkan ke dalam tanganmu, kauperbuat di depan Firaun. Tetapi Aku akan mengeraskan hatinya, sehingga ia tidak membiarkan bangsa itu pergi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 22, 'Maka engkau harus berkata kepada Firaun: Beginilah firman TUHAN: Israel ialah anak-Ku, anak-Ku yang sulung;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 23, 'sebab itu Aku berfirman kepadamu: Biarkanlah anak-Ku itu pergi, supaya ia beribadah kepada-Ku; tetapi jika engkau menolak membiarkannya pergi, maka Aku akan membunuh anakmu, anakmu yang sulung."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 24, 'Tetapi di tengah jalan, di suatu tempat bermalam, TUHAN bertemu dengan Musa dan berikhtiar untuk membunuhnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 25, 'Lalu Zipora mengambil pisau batu, dipotongnya kulit khatan anaknya, kemudian disentuhnya dengan kulit itu kaki Musa sambil berkata: "Sesungguhnya engkau pengantin darah bagiku."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 26, 'Lalu TUHAN membiarkan Musa. "Pengantin darah," kata Zipora waktu itu, karena mengingat sunat itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 27, 'Berfirmanlah TUHAN kepada Harun: "Pergilah ke padang gurun menjumpai Musa." Ia pergi dan bertemu dengan dia di gunung Allah, lalu menciumnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 28, 'Kemudian Musa memberitahukan kepada Harun segala firman TUHAN yang disuruhkan-Nya kepadanya untuk disampaikan dan segala tanda mujizat yang diperintahkan-Nya kepadanya untuk dibuat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 29, 'Lalu pergilah Musa beserta Harun dan mereka mengumpulkan semua tua-tua Israel.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 30, 'Harun mengucapkan segala firman yang telah diucapkan TUHAN kepada Musa, serta membuat di depan bangsa itu tanda-tanda mujizat itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 4, 31, 'Lalu percayalah bangsa itu, dan ketika mereka mendengar, bahwa TUHAN telah mengindahkan orang Israel dan telah melihat kesengsaraan mereka, maka berlututlah mereka dan sujud menyembah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 1, 'Kemudian Musa dan Harun pergi menghadap Firaun, lalu berkata kepadanya: "Beginilah firman TUHAN, Allah Israel: Biarkanlah umat-Ku pergi untuk mengadakan perayaan bagi-Ku di padang gurun."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 2, 'Tetapi Firaun berkata: "Siapakah TUHAN itu yang harus kudengarkan firman-Nya untuk membiarkan orang Israel pergi? Tidak kenal aku TUHAN itu dan tidak juga aku akan membiarkan orang Israel pergi."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 3, 'Lalu kata mereka: "Allah orang Ibrani telah menemui kami; izinkanlah kiranya kami pergi ke padang gurun tiga hari perjalanan jauhnya, untuk mempersembahkan korban kepada TUHAN, Allah kami, supaya jangan nanti mendatangkan kepada kami penyakit sampar atau pedang."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 4, 'Tetapi raja Mesir berkata kepada mereka: "Musa dan Harun, mengapakah kamu bawa-bawa bangsa ini melalaikan pekerjaannya? Pergilah melakukan pekerjaanmu!"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 5, 'Lagi kata Firaun: "Lihat, sekarang telah terlalu banyak bangsamu di negeri ini, masakan kamu hendak menghentikan mereka dari kerja paksanya!"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 6, 'Pada hari itu juga Firaun memerintahkan kepada pengerah-pengerah bangsa itu dan kepada mandur-mandur mereka sendiri:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 7, '"Tidak boleh lagi kamu memberikan jerami kepada bangsa itu untuk membuat batu bata, seperti sampai sekarang; biarlah mereka sendiri yang pergi mengumpulkan jerami,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 8, 'tetapi jumlah batu bata, yang harus dibuat mereka sampai sekarang, bebankanlah itu juga kepada mereka dan jangan menguranginya, karena mereka pemalas. Itulah sebabnya mereka berteriak-teriak: Izinkanlah kami pergi mempersembahkan korban kepada Allah kami.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 9, 'Pekerjaan orang-orang ini harus diperberat, sehingga mereka terikat kepada pekerjaannya dan jangan mempedulikan perkataan dusta."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 10, 'Maka para pengerah bangsa itu dan para mandurnya pergi dan berkata kepada mereka: "Beginilah kata Firaun: Aku tidak memberi jerami lagi kepadamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 11, 'Pergilah kamu sendiri mengambil jerami, di mana saja kamu mendapatnya, tetapi pekerjaanmu sedikitpun tidak boleh kurang."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 12, 'Lalu berseraklah bangsa itu ke seluruh tanah Mesir untuk mengumpulkan tunggul gandum sebagai pengganti jerami.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 13, 'Dan pengerah-pengerah itu mendesak mereka dengan berkata: "Selesaikan pekerjaanmu, yaitu tugas sehari, seperti pada waktu ada jerami."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 14, 'Lalu pengerah-pengerah Firaun memukul mandur-mandur Israel, yang mereka angkat, sambil bertanya: "Mengapakah kamu pada hari ini tidak menyelesaikan jumlah batu bata yang harus kamu buat seperti kemarin?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 15, 'Sesudah itu pergilah para mandur Israel kepada Firaun dan mengadukan halnya kepadanya: "Mengapakah tuanku berlaku seperti itu terhadap hamba-hambamu ini?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 16, 'Jerami tidak diberikan lagi kepada hamba-hambamu ini tetapi walaupun begitu, kami diperintahkan: Buatlah batu bata. Dan dalam pada itu hamba-hambamu ini dipukuli, padahal rakyat tuankulah yang bersalah."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 17, 'Tetapi ia berkata: "Pemalas kamu, pemalas! Itulah sebabnya kamu berkata: Izinkanlah kami pergi mempersembahkan korban kepada TUHAN!', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 18, 'Jadi sekarang, pergilah, bekerja! Jerami tidak akan diberikan lagi kepadamu, tetapi jumlah batu bata yang sama harus kamu serahkan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 19, 'Maka mengertilah para mandur Israel, bahwa mereka ada dalam keadaan susah, karena dikatakan kepada mereka: "Kamu tidak boleh mengurangi jumlah batu bata pada tiap-tiap hari."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 20, 'Waktu mereka meninggalkan Firaun berjumpalah mereka dengan Musa dan Harun, yang sedang menantikan mereka,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 21, 'lalu mereka berkata kepada keduanya: "Kiranya TUHAN memperhatikan perbuatanmu dan menghukumkan kamu, karena kamu telah membusukkan nama kami kepada Firaun dan hamba-hambanya dan dengan demikian kamu telah memberikan pisau kepada mereka untuk membunuh kami."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 22, 'Lalu Musa kembali menghadap TUHAN, katanya: "Tuhan, mengapakah Kauperlakukan umat ini begitu bengis? Mengapa pula aku yang Kauutus?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 5, 23, 'Sebab sejak aku pergi menghadap Firaun untuk berbicara atas nama-Mu, dengan jahat diperlakukannya umat ini, dan Engkau tidak melepaskan umat-Mu sama sekali."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 1, '(5-24) Tetapi TUHAN berfirman kepada Musa: "Sekarang engkau akan melihat, apa yang akan Kulakukan kepada Firaun; sebab dipaksa oleh tangan yang kuat ia akan membiarkan mereka pergi, ya dipaksa oleh tangan yang kuat ia akan mengusir mereka dari negerinya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 2, '(6-1) Selanjutnya berfirmanlah Allah kepada Musa: "Akulah TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 3, '(6-2) Aku telah menampakkan diri kepada Abraham, Ishak dan Yakub sebagai Allah Yang Mahakuasa, tetapi dengan nama-Ku TUHAN Aku belum menyatakan diri.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 4, '(6-3) Bukan saja Aku telah mengadakan perjanjian-Ku dengan mereka untuk memberikan kepada mereka tanah Kanaan, tempat mereka tinggal sebagai orang asing,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 5, '(6-4) tetapi Aku sudah mendengar juga erang orang Israel yang telah diperbudak oleh orang Mesir, dan Aku ingat kepada perjanjian-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 6, '(6-5) Sebab itu katakanlah kepada orang Israel: Akulah TUHAN, Aku akan membebaskan kamu dari kerja paksa orang Mesir, melepaskan kamu dari perbudakan mereka dan menebus kamu dengan tangan yang teracung dan dengan hukuman-hukuman yang berat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 7, '(6-6) Aku akan mengangkat kamu menjadi umat-Ku dan Aku akan menjadi Allahmu, supaya kamu mengetahui, bahwa Akulah, TUHAN, Allahmu, yang membebaskan kamu dari kerja paksa orang Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 8, '(6-7) Dan Aku akan membawa kamu ke negeri yang dengan sumpah telah Kujanjikan memberikannya kepada Abraham, Ishak dan Yakub, dan Aku akan memberikannya kepadamu untuk menjadi milikmu; Akulah TUHAN."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 9, '(6-8) Lalu Musa mengatakan demikian kepada orang Israel, tetapi mereka tidak mendengarkan Musa karena mereka putus asa dan karena perbudakan yang berat itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 10, '(6-9) Kemudian TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 11, '(6-10) "Pergilah menghadap, katakanlah kepada Firaun, raja Mesir, bahwa ia harus membiarkan orang Israel pergi dari negerinya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 12, '(6-11) Tetapi Musa berkata di hadapan TUHAN: "Orang Israel sendiri tidak mendengarkan aku, bagaimanakah mungkin Firaun akan mendengarkan aku, aku seorang yang tidak petah lidahnya!"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 13, '(6-12) Demikianlah TUHAN telah berfirman kepada Musa dan Harun, serta mengutus mereka kepada orang Israel dan kepada Firaun, raja Mesir, dengan membawa perintah supaya orang Israel dibawa keluar dari Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 14, '(6-13) Inilah para kepala kaum keluarga mereka: Anak-anak Ruben anak sulung Israel: Henokh, Palu, Hezron dan Karmi; itulah kaum-kaum Ruben.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 15, '(6-14) Anak-anak Simeon: Yemuel, Yamin, Ohad, Yakhin, Zohar, dan Saul, anak seorang perempuan Kanaan; itulah kaum-kaum Simeon.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 16, '(6-15) Inilah nama anak-anak Lewi menurut urutan kelahirannya: Gerson, Kehat dan Merari. Umur Lewi seratus tiga puluh tujuh tahun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 17, '(6-16) Anak-anak Gerson: Libni dan Simei, menurut kaum mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 18, '(6-17) Anak-anak Kehat: Amram, Yizhar, Hebron dan Uziel. Umur Kehat seratus tiga puluh tiga tahun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 19, '(6-18) Anak-anak Merari: Mahli dan Musi. Itulah kaum-kaum Lewi menurut urutannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 20, '(6-19) Dan Amram mengambil Yokhebed, saudara ayahnya, menjadi isterinya, dan perempuan ini melahirkan Harun dan Musa baginya. Umur Amram seratus tiga puluh tujuh tahun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 21, '(6-20) Anak-anak Yizhar: Korah, Nefeg dan Zikhri.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 22, '(6-21) Anak-anak Uziel: Misael, Elsafan dan Sitri.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 23, '(6-22) Dan Harun mengambil Eliseba, anak perempuan Aminadab, saudara perempuan Nahason, menjadi isterinya, dan perempuan ini melahirkan baginya Nadab, Abihu, Eleazar dan Itamar.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 24, '(6-23) Anak-anak Korah: Asir, Elkana dan Abiasaf; itulah kaum-kaum orang Korah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 25, '(6-24) Eleazar, anak Harun, mengambil salah seorang anak perempuan Putiel menjadi isterinya dan perempuan ini melahirkan Pinehas baginya. Itulah para kepala kaum keluarga orang Lewi menurut kaum mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 26, '(6-25) Itulah Harun dan Musa, yang diperintahkan TUHAN: "Bawalah orang Israel keluar dari tanah Mesir menurut pasukan mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 27, '(6-26) Merekalah yang berbicara kepada Firaun, raja Mesir, supaya mereka membawa orang Israel keluar dari Mesir. Itulah Musa dan Harun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 28, '(6-27) Pada waktu TUHAN berfirman kepada Musa di tanah Mesir,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 29, '(6-28) TUHAN berfirman kepadanya: "Akulah TUHAN; katakanlah kepada Firaun, raja Mesir, segala yang Kufirmankan kepadamu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 6, 30, '(6-29) Tetapi Musa berkata di hadapan TUHAN: "Bukankah aku ini seorang yang tidak petah lidahnya, bagaimanakah mungkin Firaun akan mendengarkan aku?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 1, 'Berfirmanlah TUHAN kepada Musa: "Lihat, Aku mengangkat engkau sebagai Allah bagi Firaun, dan Harun, abangmu, akan menjadi nabimu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 2, 'Engkau harus mengatakan segala yang Kuperintahkan kepadamu, dan Harun, abangmu, harus berbicara kepada Firaun, supaya dibiarkannya orang Israel itu pergi dari negerinya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 3, 'Tetapi Aku akan mengeraskan hati Firaun, dan Aku akan memperbanyak tanda-tanda dan mujizat-mujizat yang Kubuat di tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 4, 'Bilamana Firaun tidak mendengarkan kamu, maka Aku akan mendatangkan tangan-Ku kepada Mesir dan mengeluarkan pasukan-Ku, umat-Ku, orang Israel, dari tanah Mesir dengan hukuman-hukuman yang berat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 5, 'Dan orang Mesir itu akan mengetahui, bahwa Akulah TUHAN, apabila Aku mengacungkan tangan-Ku terhadap Mesir dan membawa orang Israel keluar dari tengah-tengah mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 6, 'Demikianlah diperbuat Musa dan Harun; seperti yang diperintahkan TUHAN kepada mereka, demikianlah diperbuat mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 7, 'Adapun Musa delapan puluh tahun umurnya dan Harun delapan puluh tiga tahun, ketika mereka berbicara kepada Firaun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 8, 'Dan TUHAN berfirman kepada Musa dan Harun:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 9, '"Apabila Firaun berkata kepada kamu: Tunjukkanlah suatu mujizat, maka haruslah kaukatakan kepada Harun: Ambillah tongkatmu dan lemparkanlah itu di depan Firaun. Maka tongkat itu akan menjadi ular."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 10, 'Musa dan Harun pergi menghadap Firaun, lalu mereka berbuat seperti yang diperintahkan TUHAN; Harun melemparkan tongkatnya di depan Firaun dan para pegawainya, maka tongkat itu menjadi ular.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 11, 'Kemudian Firaunpun memanggil orang-orang berilmu dan ahli-ahli sihir; dan merekapun, ahli-ahli Mesir itu, membuat yang demikian juga dengan ilmu mantera mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 12, 'Masing-masing mereka melemparkan tongkatnya, dan tongkat-tongkat itu menjadi ular; tetapi tongkat Harun menelan tongkat-tongkat mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 13, 'Tetapi hati Firaun berkeras, sehingga tidak mau mendengarkan mereka keduanya?seperti yang telah difirmankan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 14, 'Berfirmanlah TUHAN kepada Musa: "Firaun berkeras hati, ia menolak membiarkan bangsa itu pergi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 15, 'Pergilah kepada Firaun pada waktu pagi, pada waktu biasanya ia keluar ke sungai; nantikanlah dia di tepi sungai Nil dengan memegang di tanganmu tongkat yang tadinya berubah menjadi ular.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 16, 'Dan katakanlah kepadanya: TUHAN, Allah orang Ibrani, telah mengutus aku kepadamu untuk mengatakan: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku di padang gurun; meskipun begitu sampai sekarang engkau tidak mau mendengarkan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 17, 'Sebab itu beginilah firman TUHAN: Dari hal yang berikut akan kauketahui, bahwa Akulah TUHAN. Lihat, dengan tongkat yang di tanganku ini akan kupukul air yang di sungai Nil dan air itu akan berubah menjadi darah,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 18, 'dan ikan yang dalam sungai Nil akan mati, sehingga sungai Nil akan berbau busuk; maka orang Mesir akan segan meminum air dari sungai Nil ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 19, 'TUHAN berfirman kepada Musa: "Katakanlah kepada Harun: Ambillah tongkatmu, ulurkanlah tanganmu ke atas segala air orang Mesir, ke atas sungai, selokan, kolam dan ke atas segala kumpulan air yang ada pada mereka, supaya semuanya menjadi darah, dan akan ada darah di seluruh tanah Mesir, bahkan dalam wadah kayu dan wadah batu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 20, 'Demikianlah Musa dan Harun berbuat seperti yang difirmankan TUHAN; diangkatnya tongkat itu dan dipukulkannya kepada air yang di sungai Nil, di depan mata Firaun dan pegawai-pegawainya, maka seluruh air yang di sungai Nil berubah menjadi darah;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 21, 'matilah ikan di sungai Nil, sehingga sungai Nil itu berbau busuk dan orang Mesir tidak dapat meminum air dari sungai Nil; dan di seluruh tanah Mesir ada darah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 22, 'Tetapi para ahli Mesir membuat yang demikian juga dengan ilmu-ilmu mantera mereka, sehingga hati Firaun berkeras dan ia tidak mau mendengarkan mereka keduanya seperti yang telah difirmankan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 23, 'Firaun berpaling, lalu masuk ke istananya dan tidak mau memperhatikan hal itu juga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 24, 'Tetapi semua orang Mesir menggali-gali di sekitar sungai Nil mencari air untuk diminum, sebab mereka tidak dapat meminum air sungai Nil.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 7, 25, 'Demikianlah genap tujuh hari berlalu setelah TUHAN menulahi sungai Nil.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 1, 'Berfirmanlah TUHAN kepada Musa: "Pergilah menghadap Firaun dan katakan kepadanya: Beginilah firman TUHAN: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 2, 'jika engkau menolak membiarkannya pergi, maka Aku akan menulahi seluruh daerahmu dengan katak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 3, 'Katak-katak akan mengeriap dalam sungai Nil, lalu naik dan masuk ke dalam istanamu dan kamar tidurmu, ya sampai ke dalam tempat tidurmu, ke dalam rumah pegawai-pegawaimu, dan rakyatmu, bahkan ke dalam pembakaran rotimu serta ke dalam tempat adonanmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 4, 'Katak-katak itu akan naik memanjati engkau, memanjati rakyatmu dan segala pegawaimu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 5, 'Berfirmanlah TUHAN kepada Musa: "Katakanlah kepada Harun: Ulurkanlah tanganmu dengan tongkatmu ke atas sungai, ke atas selokan dan ke atas kolam, dan buatlah katak-katak bermunculan meliputi tanah Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 6, 'Lalu Harun mengulurkan tangannya ke atas segala air di Mesir, maka bermunculanlah katak-katak, lalu menutupi tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 7, 'Tetapi para ahli itupun membuat yang demikian juga dengan ilmu-ilmu mantera mereka, sehingga mereka membuat katak-katak bermunculan meliputi tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 8, 'Kemudian Firaun memanggil Musa dan Harun serta berkata: "Berdoalah kepada TUHAN, supaya dijauhkan-Nya katak-katak itu dari padaku dan dari pada rakyatku; maka aku akan membiarkan bangsa itu pergi, supaya mereka mempersembahkan korban kepada TUHAN."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 9, 'Kata Musa kepada Firaun: "Silakanlah tuanku katakan kepadaku, bila aku akan berdoa untukmu, untuk pegawaimu dan rakyatmu, supaya katak-katak itu dilenyapkan dari padamu dan dari rumah-rumahmu, dan hanya tinggal di sungai Nil saja."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 10, 'Katanya: "Besok." Lalu kata Musa: "Jadilah seperti katamu itu, supaya tuanku mengetahui, bahwa tidak ada yang seperti TUHAN, Allah kami.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 11, 'Maka katak-katak itu akan dijauhkan dari padamu, dari rumah-rumahmu, dari pegawai-pegawaimu dan dari rakyatmu; dan hanya akan tinggal di sungai Nil saja."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 12, 'Lalu Musa dan Harun keluar meninggalkan Firaun, dan Musa berseru kepada TUHAN karena katak-katak, yang didatangkan-Nya kepada Firaun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 13, 'Dan TUHAN melakukan seperti yang dikatakan Musa, sehingga katak-katak itu mati lenyap dari rumah, dari halaman dan dari ladang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 14, 'Dikumpulkan oranglah bangkai-bangkainya bertumpuk-tumpuk, sehingga tanah itu berbau busuk.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 15, 'Tetapi ketika Firaun melihat, bahwa telah terasa kelegaan, ia tetap berkeras hati, dan tidak mau mendengarkan mereka keduanya?seperti yang telah difirmankan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 16, 'Berfirmanlah TUHAN kepada Musa: "Katakanlah kepada Harun: Ulurkanlah tongkatmu dan pukulkanlah itu ke debu tanah, maka debu itu akan menjadi nyamuk di seluruh tanah Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 17, 'Lalu mereka berbuat demikian; Harun mengulurkan tangannya dengan tongkatnya dan memukulkannya ke debu tanah, maka nyamuk-nyamuk itu hinggap pada manusia dan pada binatang. Segala debu tanah menjadi nyamuk di seluruh tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 18, 'Para ahli itupun membuat yang demikian juga dengan ilmu-ilmu manteranya untuk mengadakan nyamuk-nyamuk, tetapi mereka tidak dapat. Demikianlah nyamuk-nyamuk itu hinggap pada manusia dan pada binatang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 19, 'Lalu berkatalah para ahli itu kepada Firaun: "Inilah tangan Allah." Tetapi hati Firaun berkeras, dan ia tidak mau mendengarkan mereka?seperti yang telah difirmankan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 20, 'Berfirmanlah TUHAN kepada Musa: "Bangunlah pagi-pagi dan berdirilah menantikan Firaun, pada waktu biasanya ia keluar ke sungai, dan katakanlah kepadanya: Beginilah firman TUHAN: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 21, 'sebab jika engkau tidak membiarkan umat-Ku itu pergi, maka Aku akan melepaskan pikat terhadap engkau, terhadap pegawai-pegawaimu, rakyatmu dan rumah-rumahmu, sehingga rumah-rumah orang Mesir, bahkan tanah, di mana mereka berdiri akan penuh dengan pikat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 22, 'Tetapi pada hari itu Aku akan mengecualikan tanah Gosyen, di mana umat-Ku tinggal, sehingga di sana tidak ada terdapat pikat, supaya engkau mengetahui, bahwa Aku, TUHAN, ada di negeri ini.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 23, 'Sebab Aku akan mengadakan perbedaan antara umat-Ku dan bangsamu. Besok tanda mujizat ini akan terjadi."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 24, 'TUHAN berbuat demikian; maka datanglah banyak-banyak pikat ke dalam istana Firaun dan ke dalam rumah pegawai-pegawainya dan ke seluruh tanah Mesir; negeri itu menderita karena pikat itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 25, 'Lalu Firaun memanggil Musa dan Harun serta berkata: "Pergilah, persembahkanlah korban kepada Allahmu di negeri ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 26, 'Tetapi Musa berkata: "Tidak mungkin kami berbuat demikian, sebab korban yang akan kami persembahkan kepada TUHAN, Allah kami, adalah kekejian bagi orang Mesir. Apabila kami mempersembahkan korban yang menjadi kekejian bagi orang Mesir itu, di depan mata mereka, tidakkah mereka akan melempari kami dengan batu?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 27, 'Kami harus pergi ke padang gurun tiga hari perjalanan jauhnya untuk mempersembahkan korban kepada TUHAN, Allah kami, seperti yang difirmankan-Nya kepada kami."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 28, 'Lalu kata Firaun: "Baik, aku akan membiarkan kamu pergi untuk mempersembahkan korban kepada TUHAN, Allahmu, di padang gurun; hanya janganlah kamu pergi terlalu jauh. Berdoalah untuk aku."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 29, 'Lalu kata Musa: "Sekarang aku keluar meninggalkan tuanku dan akan berdoa kepada TUHAN, maka pikat itu akan dijauhkan besok dari Firaun, dari pegawai-pegawainya dan rakyatnya; hanya janganlah Firaun berlaku curang lagi dengan tidak membiarkan bangsa itu pergi untuk mempersembahkan korban kepada TUHAN."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 30, 'Sesudah itu keluarlah Musa meninggalkan Firaun, lalu berdoa kepada TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 31, 'Dan TUHAN membuat seperti yang dikatakan Musa: pikat itu dijauhkan-Nya dari Firaun, dari pegawai-pegawainya dan rakyatnya; seekorpun tidak ada yang tinggal.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 8, 32, 'Tetapi sekali inipun Firaun tetap berkeras hati; ia tidak membiarkan bangsa itu pergi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 1, 'Berfirmanlah TUHAN kepada Musa: "Pergilah menghadap Firaun dan berbicaralah kepadanya: Beginilah firman TUHAN, Allah orang Ibrani: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 2, 'Sebab jika engkau menolak membiarkan mereka pergi dan masih menahan mereka,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 3, 'maka ternakmu, yang ada di padang, kuda, keledai, unta, lembu sapi dan kambing domba, akan kena tulah TUHAN, yakni kena penyakit sampar yang dahsyat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 4, 'Dan TUHAN akan membuat perbedaan antara ternak orang Israel dan ternak orang Mesir, sehingga tidak ada yang akan mati seekorpun dari segala ternak orang Israel."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 5, 'Selanjutnya TUHAN menentukan waktunya, firman-Nya: "Besoklah TUHAN akan melakukan hal itu di negeri ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 6, 'Dan TUHAN melakukan hal itu keesokan harinya; segala ternak orang Mesir itu mati, tetapi dari ternak orang Israel tidak ada seekorpun yang mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 7, 'Lalu Firaun menyuruh orang ke sana dan sesungguhnyalah dari ternak orang Israel tidak ada seekorpun yang mati. Tetapi Firaun tetap berkeras hati dan tidak mau membiarkan bangsa itu pergi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 8, 'Berfirmanlah TUHAN kepada Musa dan Harun: "Ambillah jelaga dari dapur peleburan serangkup penuh, dan Musa harus menghamburkannya ke udara di depan mata Firaun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 9, 'Maka jelaga itu akan menjadi debu meliputi seluruh tanah Mesir, dan akan menjadikan barah yang memecah sebagai gelembung, pada manusia dan binatang di seluruh tanah Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 10, 'Lalu mereka mengambil jelaga dari dapur peleburan, dan berdiri di depan Firaun, kemudian Musa menghamburkannya ke udara, maka terjadilah barah, yang memecah sebagai gelembung pada manusia dan binatang,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 11, 'sehingga ahli-ahli itu tidak dapat tetap berdiri di depan Musa, karena barah-barah itu; sebab ahli-ahli itupun juga kena barah sama seperti semua orang Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 12, 'Tetapi TUHAN mengeraskan hati Firaun, sehingga ia tidak mendengarkan mereka?seperti yang telah difirmankan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 13, 'Berfirmanlah TUHAN kepada Musa: "Bangunlah pagi-pagi dan berdirilah menantikan Firaun dan katakan kepadanya: Beginilah firman TUHAN, Allah orang Ibrani: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 14, 'Sebab sekali ini Aku akan melepaskan segala tulah-Ku terhadap engkau sendiri, terhadap pegawai-pegawaimu dan terhadap rakyatmu, dengan maksud supaya engkau mengetahui, bahwa tidak ada yang seperti Aku di seluruh bumi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 15, 'Bukankah sudah lama Aku dapat mengacungkan tangan-Ku untuk membunuh engkau dan rakyatmu dengan penyakit sampar, sehingga engkau terhapus dari atas bumi;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 16, 'akan tetapi inilah sebabnya Aku membiarkan engkau hidup, yakni supaya memperlihatkan kepadamu kekuatan-Ku, dan supaya nama-Ku dimasyhurkan di seluruh bumi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 17, 'Engkau masih selalu mengalangi umat-Ku, sehingga engkau tidak membiarkan mereka pergi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 18, 'Sesungguhnya besok kira-kira waktu ini Aku akan menurunkan hujan es yang sangat dahsyat, seperti yang belum pernah terjadi di Mesir sejak Mesir dijadikan sampai sekarang ini.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 19, 'Oleh sebab itu, ternakmu dan segala yang kaupunyai di padang, suruhlah dibawa ke tempat yang aman; semua orang dan segala hewan, yang ada di padang dan tidak pulang berkumpul ke rumah, akan ditimpa oleh hujan es itu, sehingga mati."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 20, 'Maka siapa di antara para pegawai Firaun yang takut kepada firman TUHAN, menyuruh hamba-hambanya serta ternaknya lari ke rumah,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 21, 'tetapi siapa yang tidak mengindahkan firman TUHAN, meninggalkan hamba-hambanya serta ternaknya di padang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 22, 'Berfirmanlah TUHAN kepada Musa: "Ulurkanlah tanganmu ke langit, supaya hujan es turun di seluruh tanah Mesir, menimpa manusia dan binatang dan menimpa tumbuh-tumbuhan di padang di tanah Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 23, 'Lalu Musa mengulurkan tongkatnya ke langit, maka TUHAN mengadakan guruh dan hujan es, dan apipun menyambar ke bumi, dan TUHAN menurunkan hujan es meliputi tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 24, 'Dan turunlah hujan es, beserta api yang berkilat-kilat di tengah-tengah hujan es itu, terlalu dahsyat, seperti yang belum pernah terjadi di seluruh negeri orang Mesir, sejak mereka menjadi suatu bangsa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 25, 'Hujan es itu menimpa binasa segala sesuatu yang ada di padang, di seluruh tanah Mesir, dari manusia sampai binatang; juga segala tumbuh-tumbuhan di padang ditimpa binasa oleh hujan itu dan segala pohon di padang ditumbangkannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 26, 'Hanya di tanah Gosyen, tempat kediaman orang Israel, tidak ada turun hujan es.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 27, 'Lalu Firaun menyuruh memanggil Musa dan Harun serta berkata kepada mereka: "Aku telah berdosa sekali ini, TUHAN itu yang benar, tetapi aku dan rakyatkulah yang bersalah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 28, 'Berdoalah kepada TUHAN; guruh yang sangat dahsyat dan hujan es itu sudah cukup. Maka aku akan membiarkan kamu pergi, tidak usah kamu tinggal lebih lama lagi."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 29, 'Dan berkatalah Musa kepadanya: "Sekeluar aku dari kota ini, aku akan mengembangkan tanganku kepada TUHAN; guruh akan berhenti dan hujan es tidak akan turun lagi, supaya engkau mengetahui, bahwa bumi adalah milik TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 30, 'Tetapi tentang engkau dan para pegawaimu, aku tahu, bahwa kamu belum takut kepada TUHAN Allah."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 31, '?Tanaman rami dan jelai telah tertimpa binasa, sebab jelai itu sedang berbulir dan rami itu sedang berbunga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 32, 'Tetapi gandum dan sekoi tidak tertimpa binasa, sebab belum lagi musimnya. ?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 33, 'Lalu keluarlah Musa dari kota itu meninggalkan Firaun, dikembangkannyalah tangannya kepada TUHAN, maka berhentilah guruh dan hujan es dan hujan tidak tercurah lagi ke bumi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 34, 'Tetapi ketika Firaun melihat, bahwa hujan, hujan es dan guruh telah berhenti, maka teruslah ia berbuat dosa; ia tetap berkeras hati, baik ia maupun para pegawainya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 9, 35, 'Berkeraslah hati Firaun, sehingga ia tidak membiarkan orang Israel pergi?seperti yang telah difirmankan TUHAN dengan perantaraan Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 1, 'Berfirmanlah TUHAN kepada Musa: "Pergilah menghadap Firaun, sebab Aku telah membuat hatinya dan hati para pegawainya berkeras, supaya Aku mengadakan tanda-tanda mujizat yang Kubuat ini di antara mereka,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 2, 'dan supaya engkau dapat menceriterakan kepada anak cucumu, bagaimana Aku mempermain-mainkan orang Mesir dan tanda-tanda mujizat mana yang telah Kulakukan di antara mereka, supaya kamu mengetahui, bahwa Akulah TUHAN."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 3, 'Lalu Musa dan Harun pergi menghadap Firaun dan berkata kepadanya: "Beginilah firman TUHAN, Allah orang Ibrani: Berapa lama lagi engkau menolak untuk merendahkan dirimu di hadapan-Ku? Biarkanlah umat-Ku pergi supaya mereka beribadah kepada-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 4, 'Sebab jika engkau menolak membiarkan umat-Ku pergi, maka besok Aku akan mendatangkan belalang-belalang ke dalam daerahmu;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 5, 'belalang itu akan menutupi permukaan bumi, sehingga orang tidak dapat melihat tanah; belalang itu akan memakan habis sisa yang terluput, yang masih tinggal bagimu dari hujan es itu, bahkan akan memakan habis segala pohonmu yang tumbuh di padang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 6, 'Belalang itu akan memenuhi rumahmu, rumah semua pegawaimu, rumah semua orang Mesir seperti yang belum pernah dilihat oleh bapamu dan nenek moyangmu, sejak mereka lahir ke bumi sampai hari ini." Lalu berpalinglah ia dan keluar meninggalkan Firaun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 7, 'Sesudah itu berkatalah para pegawai Firaun kepadanya: "Berapa lama lagi orang ini akan menjadi jerat kepada kita? Biarkanlah orang-orang itu pergi supaya mereka beribadah kepada TUHAN, Allah mereka. Belumkah tuanku insaf, bahwa Mesir pasti akan binasa?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 8, 'Lalu Musa dan Harun dibawalah kembali kepada Firaun dan berkatalah Firaun kepada mereka: "Pergilah, beribadahlah kepada TUHAN, Allahmu. Siapa-siapa sebenarnya yang akan pergi itu?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 9, 'Jawab Musa: "Kami hendak pergi dengan orang-orang yang muda dan yang tua; dengan anak-anak lelaki kami dan perempuan, dengan kambing domba kami dan lembu sapi kami, sebab kami harus mengadakan perayaan untuk TUHAN."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 10, 'Tetapi Firaun berkata kepada mereka: "TUHAN boleh menyertai kamu, jika aku membiarkan kamu pergi dengan anak-anakmu! Lihat, jahatlah maksudmu!', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 11, 'Bukan demikian, kamu boleh pergi, tetapi hanya laki-laki, dan beribadahlah kepada TUHAN, sebab itulah yang kamu kehendaki." Lalu mereka diusir dari depan Firaun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 12, 'Berfirmanlah TUHAN kepada Musa: "Ulurkanlah tanganmu ke atas tanah Mesir mendatangkan belalang dan belalang akan datang meliputi tanah Mesir dan memakan habis segala tumbuh-tumbuhan di tanah, semuanya yang ditinggalkan oleh hujan es itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 13, 'Lalu Musa mengulurkan tongkatnya ke atas tanah Mesir, dan TUHAN mendatangkan angin timur melintasi negeri itu, sehari-harian dan semalam-malaman, dan setelah hari pagi, angin timur membawa belalang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 14, 'Datanglah belalang meliputi seluruh tanah Mesir dan hinggap di seluruh daerah Mesir, sangat banyak; sebelum itu tidak pernah ada belalang yang demikian banyaknya dan sesudah itupun tidak akan terjadi lagi yang demikian.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 15, 'Belalang menutupi seluruh permukaan bumi, sehingga negeri itu menjadi gelap olehnya; belalang memakan habis segala tumbuh-tumbuhan di tanah dan segala buah-buahan pada pohon-pohon yang ditinggalkan oleh hujan es itu, sehingga tidak ada tinggal lagi yang hijau pada pohon atau tumbuh-tumbuhan di padang di seluruh tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 16, 'Maka segeralah Firaun memanggil Musa dan Harun serta berkata: "Aku telah berbuat dosa terhadap TUHAN, Allahmu, dan terhadap kamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 17, 'Oleh sebab itu, ampunilah kiranya dosaku untuk sekali ini saja dan berdoalah kepada TUHAN, Allahmu itu, supaya bahaya maut ini dijauhkan-Nya dari padaku."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 18, 'Lalu keluarlah Musa meninggalkan Firaun dan berdoa kepada TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 19, 'Maka TUHAN membuat angin bertiup dari jurusan sebaliknya, yakni angin barat yang sangat kencang, yang membawa belalang itu dan melemparkannya ke dalam Laut Teberau: tidak ada satu belalangpun yang tinggal di seluruh daerah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 20, 'Tetapi TUHAN mengeraskan hati Firaun, sehingga tidak mau membiarkan orang Israel pergi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 21, 'Berfirmanlah TUHAN kepada Musa: "Ulurkanlah tanganmu ke langit, supaya datang gelap meliputi tanah Mesir, sehingga orang dapat meraba gelap itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 22, 'Lalu Musa mengulurkan tangannya ke langit dan datanglah gelap gulita di seluruh tanah Mesir selama tiga hari.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 23, 'Tidak ada orang yang dapat melihat temannya, juga tidak ada orang yang dapat bangun dari tempatnya selama tiga hari; tetapi pada semua orang Israel ada terang di tempat kediamannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 24, 'Lalu Firaun memanggil Musa serta berkata: "Pergilah, beribadahlah kepada TUHAN, hanya kambing dombamu dan lembu sapimu harus ditinggalkan, juga anak-anakmu boleh turut beserta kamu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 25, 'Tetapi Musa berkata: "Bahkan korban sembelihan dan korban bakaran harus engkau berikan kepada kami, supaya kami menyediakannya untuk TUHAN, Allah kami.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 26, 'Dan juga ternak kami harus turut beserta kami dan satu kakipun tidak akan tinggal, sebab dari ternak itulah kami harus ambil untuk beribadah kepada TUHAN, Allah kami; dan kami tidak tahu, dengan apa kami harus beribadah kepada TUHAN, sebelum kami sampai di sana."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 27, 'Tetapi TUHAN mengeraskan hati Firaun, sehingga dia tidak mau membiarkan mereka pergi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 28, 'Lalu Firaun berkata kepadanya: "Pergilah dari padaku; awaslah engkau, jangan lihat mukaku lagi, sebab pada waktu engkau melihat mukaku, engkau akan mati."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 10, 29, 'Kemudian Musa berkata: "Tepat seperti ucapanmu itu! Aku takkan melihat mukamu lagi!"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 1, 'Berfirmanlah TUHAN kepada Musa: "Aku akan mendatangkan satu tulah lagi atas Firaun dan atas Mesir, sesudah itu ia akan membiarkan kamu pergi dari sini; apabila ia membiarkan kamu pergi, ia akan benar-benar mengusir kamu dari sini.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 2, 'Baiklah katakan kepada bangsa itu, supaya setiap laki-laki meminta barang-barang emas dan perak kepada tetangganya dan setiap perempuan kepada tetangganya pula."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 3, 'Lalu TUHAN membuat orang Mesir bermurah hati terhadap bangsa itu; lagipula Musa adalah seorang yang sangat terpandang di tanah Mesir, di mata pegawai-pegawai Firaun dan di mata rakyat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 4, 'Berkatalah Musa: "Beginilah firman TUHAN: Pada waktu tengah malam Aku akan berjalan dari tengah-tengah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 5, 'Maka tiap-tiap anak sulung di tanah Mesir akan mati, dari anak sulung Firaun yang duduk di takhtanya sampai kepada anak sulung budak perempuan yang menghadapi batu kilangan, juga segala anak sulung hewan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 6, 'Dan seruan yang hebat akan terjadi di seluruh tanah Mesir, seperti yang belum pernah terjadi dan seperti yang tidak akan ada lagi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 7, 'Tetapi kepada siapa juga dari orang Israel, seekor anjingpun tidak akan berani menggonggong, baik kepada manusia maupun kepada binatang, supaya kamu mengetahui, bahwa TUHAN membuat perbedaan antara orang Mesir dan orang Israel.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 8, 'Dan semua pegawaimu ini akan datang kepadaku dan sujud kepadaku serta berkata: Keluarlah, engkau dan seluruh rakyat yang mengikut engkau; sesudah itu aku akan keluar." Lalu Musa meninggalkan Firaun dengan marah yang bernyala-nyala.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 9, 'Berfirmanlah TUHAN kepada Musa: "Firaun tidak akan mendengarkan kamu, supaya mujizat-mujizat yang Kubuat bertambah banyak di tanah Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 11, 10, 'Musa dan Harun telah melakukan segala mujizat ini di depan Firaun. Tetapi TUHAN mengeraskan hati Firaun, sehingga tidak membiarkan orang Israel pergi dari negerinya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 1, 'Berfirmanlah TUHAN kepada Musa dan Harun di tanah Mesir:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 2, '"Bulan inilah akan menjadi permulaan segala bulan bagimu; itu akan menjadi bulan pertama bagimu tiap-tiap tahun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 3, 'Katakanlah kepada segenap jemaah Israel: Pada tanggal sepuluh bulan ini diambillah oleh masing-masing seekor anak domba, menurut kaum keluarga, seekor anak domba untuk tiap-tiap rumah tangga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 4, 'Tetapi jika rumah tangga itu terlalu kecil jumlahnya untuk mengambil seekor anak domba, maka ia bersama-sama dengan tetangganya yang terdekat ke rumahnya haruslah mengambil seekor, menurut jumlah jiwa; tentang anak domba itu, kamu buatlah perkiraan menurut keperluan tiap-tiap orang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 5, 'Anak dombamu itu harus jantan, tidak bercela, berumur setahun; kamu boleh ambil domba atau kambing.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 6, 'Kamu harus mengurungnya sampai hari yang keempat belas bulan ini; lalu seluruh jemaah Israel yang berkumpul, harus menyembelihnya pada waktu senja.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 7, 'Kemudian dari darahnya haruslah diambil sedikit dan dibubuhkan pada kedua tiang pintu dan pada ambang atas, pada rumah-rumah di mana orang memakannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 8, 'Dagingnya harus dimakan mereka pada malam itu juga; yang dipanggang mereka harus makan dengan roti yang tidak beragi beserta sayur pahit.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 9, 'Janganlah kamu memakannya mentah atau direbus dalam air; hanya dipanggang di api, lengkap dengan kepalanya dan betisnya dan isi perutnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 10, 'Janganlah kamu tinggalkan apa-apa dari daging itu sampai pagi; apa yang tinggal sampai pagi kamu bakarlah habis dengan api.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 11, 'Dan beginilah kamu memakannya: pinggangmu berikat, kasut pada kakimu dan tongkat di tanganmu; buru-burulah kamu memakannya; itulah Paskah bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 12, 'Sebab pada malam ini Aku akan menjalani tanah Mesir, dan semua anak sulung, dari anak manusia sampai anak binatang, akan Kubunuh, dan kepada semua allah di Mesir akan Kujatuhkan hukuman, Akulah, TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 13, 'Dan darah itu menjadi tanda bagimu pada rumah-rumah di mana kamu tinggal: Apabila Aku melihat darah itu, maka Aku akan lewat dari pada kamu. Jadi tidak akan ada tulah kemusnahan di tengah-tengah kamu, apabila Aku menghukum tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 14, 'Hari ini akan menjadi hari peringatan bagimu. Kamu harus merayakannya sebagai hari raya bagi TUHAN turun-temurun. Kamu harus merayakannya sebagai ketetapan untuk selamanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 15, 'Kamu makanlah roti yang tidak beragi tujuh hari lamanya; pada hari pertamapun kamu buanglah segala ragi dari rumahmu, sebab setiap orang yang makan sesuatu yang beragi, dari hari pertama sampai hari ketujuh, orang itu harus dilenyapkan dari antara Israel.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 16, 'Kamu adakanlah pertemuan yang kudus, baik pada hari yang pertama maupun pada hari yang ketujuh; pada hari-hari itu tidak boleh dilakukan pekerjaan apapun; hanya apa yang perlu dimakan setiap orang, itu sajalah yang boleh kamu sediakan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 17, 'Jadi kamu harus tetap merayakan hari raya makan roti yang tidak beragi, sebab tepat pada hari ini juga Aku membawa pasukan-pasukanmu keluar dari tanah Mesir. Maka haruslah kamu rayakan hari ini turun-temurun; itulah suatu ketetapan untuk selamanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 18, 'Dalam bulan pertama, pada hari yang keempat belas bulan itu pada waktu petang, kamu makanlah roti yang tidak beragi, sampai kepada hari yang kedua puluh satu bulan itu, pada waktu petang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 19, 'Tujuh hari lamanya tidak boleh ada ragi dalam rumahmu, sebab setiap orang yang makan sesuatu yang beragi, orang itu harus dilenyapkan dari antara jemaah Israel, baik ia orang asing, baik ia orang asli.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 20, 'Sesuatu apapun yang beragi tidak boleh kamu makan; kamu makanlah roti yang tidak beragi di segala tempat kediamanmu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 21, 'Lalu Musa memanggil semua tua-tua Israel serta berkata kepada mereka: "Pergilah, ambillah kambing domba untuk kaummu dan sembelihlah anak domba Paskah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 22, 'Kemudian kamu harus mengambil seikat hisop dan mencelupkannya dalam darah yang ada dalam sebuah pasu, dan darah itu kamu harus sapukan pada ambang atas dan pada kedua tiang pintu; seorangpun dari kamu tidak boleh keluar pintu rumahnya sampai pagi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 23, 'Dan TUHAN akan menjalani Mesir untuk menulahinya; apabila Ia melihat darah pada ambang atas dan pada kedua tiang pintu itu, maka TUHAN akan melewati pintu itu dan tidak membiarkan pemusnah masuk ke dalam rumahmu untuk menulahi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 24, 'Kamu harus memegang ini sebagai ketetapan sampai selama-lamanya bagimu dan bagi anak-anakmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 25, 'Dan apabila kamu tiba di negeri yang akan diberikan TUHAN kepadamu, seperti yang difirmankan-Nya, maka kamu harus pelihara ibadah ini.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 26, 'Dan apabila anak-anakmu berkata kepadamu: Apakah artinya ibadahmu ini?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 27, 'maka haruslah kamu berkata: Itulah korban Paskah bagi TUHAN yang melewati rumah-rumah orang Israel di Mesir, ketika Ia menulahi orang Mesir, tetapi menyelamatkan rumah-rumah kita." Lalu berlututlah bangsa itu dan sujud menyembah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 28, 'Pergilah orang Israel, lalu berbuat demikian; seperti yang diperintahkan TUHAN kepada Musa dan Harun, demikianlah diperbuat mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 29, 'Maka pada tengah malam TUHAN membunuh tiap-tiap anak sulung di tanah Mesir, dari anak sulung Firaun yang duduk di takhtanya sampai kepada anak sulung orang tawanan, yang ada dalam liang tutupan, beserta segala anak sulung hewan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 30, 'Lalu bangunlah Firaun pada malam itu, bersama semua pegawainya dan semua orang Mesir; dan kedengaranlah seruan yang hebat di Mesir, sebab tidak ada rumah yang tidak kematian.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 31, 'Lalu pada malam itu dipanggilnyalah Musa dan Harun, katanya: "Bangunlah, keluarlah dari tengah-tengah bangsaku, baik kamu maupun orang Israel; pergilah, beribadahlah kepada TUHAN, seperti katamu itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 32, 'Bawalah juga kambing dombamu dan lembu sapimu, seperti katamu itu, tetapi pergilah! Dan pohonkanlah juga berkat bagiku."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 33, 'Orang Mesir juga mendesak dengan keras kepada bangsa itu, menyuruh bangsa itu pergi dengan segera dari negeri itu, sebab kata mereka: "Nanti kami mati semuanya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 34, 'Lalu bangsa itu mengangkat adonannya, sebelum diragi, dengan tempat adonan mereka terbungkus dalam kainnya di atas bahunya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 35, 'Orang Israel melakukan juga seperti kata Musa; mereka meminta dari orang Mesir barang-barang emas dan perak serta kain-kain.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 36, 'Dan TUHAN membuat orang Mesir bermurah hati terhadap bangsa itu, sehingga memenuhi permintaan mereka. Demikianlah mereka merampasi orang Mesir itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 37, 'Kemudian berangkatlah orang Israel dari Raamses ke Sukot, kira-kira enam ratus ribu orang laki-laki berjalan kaki, tidak termasuk anak-anak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 38, 'Juga banyak orang dari berbagai-bagai bangsa turut dengan mereka; lagi sangat banyak ternak kambing domba dan lembu sapi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 39, 'Adonan yang dibawa mereka dari Mesir dibakarlah menjadi roti bundar yang tidak beragi, sebab adonan itu tidak diragi, karena mereka diusir dari Mesir dan tidak dapat berlambat-lambat, dan mereka tidak pula menyediakan bekal baginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 40, 'Lamanya orang Israel diam di Mesir adalah empat ratus tiga puluh tahun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 41, 'Sesudah lewat empat ratus tiga puluh tahun, tepat pada hari itu juga, keluarlah segala pasukan TUHAN dari tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 42, 'Malam itulah malam berjaga-jaga bagi TUHAN, untuk membawa mereka keluar dari tanah Mesir. Dan itulah juga malam berjaga-jaga bagi semua orang Israel, turun-temurun, untuk kemuliaan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 43, 'Berfirmanlah TUHAN kepada Musa dan Harun: "Inilah ketetapan mengenai Paskah: Tidak seorangpun dari bangsa asing boleh memakannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 44, 'Seorang budak belian barulah boleh memakannya, setelah engkau menyunat dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 45, 'Orang pendatang dan orang upahan tidak boleh memakannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 46, 'Paskah itu harus dimakan dalam satu rumah juga; tidak boleh kaubawa sedikitpun dari daging itu keluar rumah; satu tulangpun tidak boleh kamu patahkan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 47, 'Segenap jemaah Israel haruslah merayakannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 48, 'Tetapi apabila seorang asing telah menetap padamu dan mau merayakan Paskah bagi TUHAN, maka setiap laki-laki yang bersama-sama dengan dia, wajiblah disunat; barulah ia boleh mendekat untuk merayakannya; ia akan dianggap sebagai orang asli. Tetapi tidak seorangpun yang tidak bersunat boleh memakannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 49, 'Satu hukum saja akan berlaku untuk orang asli dan untuk orang asing yang menetap di tengah-tengah kamu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 50, 'Seluruh orang Israel berbuat demikian; seperti yang diperintahkan TUHAN kepada Musa dan Harun, demikianlah diperbuat mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 12, 51, 'Dan tepat pada hari itu juga TUHAN membawa orang Israel keluar dari tanah Mesir, menurut pasukan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 1, 'Berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 2, '"Kuduskanlah bagi-Ku semua anak sulung, semua yang lahir terdahulu dari kandungan pada orang Israel, baik pada manusia maupun pada hewan; Akulah yang empunya mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 3, 'Lalu berkatalah Musa kepada bangsa itu: "Peringatilah hari ini, sebab pada hari ini kamu keluar dari Mesir, dari rumah perbudakan; karena dengan kekuatan tangan-Nya TUHAN telah membawa kamu keluar dari sana. Sebab itu tidak boleh dimakan sesuatupun yang beragi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 4, 'Hari ini kamu keluar, dalam bulan Abib.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 5, 'Apabila TUHAN telah membawa engkau ke negeri orang Kanaan, orang Het, orang Amori, orang Hewi dan orang Yebus, negeri yang telah dijanjikan-Nya dengan sumpah kepada nenek moyangmu untuk memberikannya kepadamu, suatu negeri yang berlimpah-limpah susu dan madunya, maka engkau harus melakukan ibadah ini dalam bulan ini juga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 6, 'Makanlah roti yang tidak beragi tujuh hari lamanya dan pada hari yang ketujuh akan diadakan hari raya bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 7, 'Roti yang tidak beragi haruslah dimakan selama tujuh hari itu; sesuatupun yang beragi tidak boleh dilihat padamu, bahkan ragi tidak boleh dilihat padamu di seluruh daerahmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 8, 'Pada hari itu harus kauberitahukan kepada anakmu laki-laki: Ibadah ini adalah karena mengingat apa yang dibuat TUHAN kepadaku pada waktu aku keluar dari Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 9, 'Hal itu bagimu harus menjadi tanda pada tanganmu dan menjadi peringatan di dahimu, supaya hukum TUHAN ada di bibirmu; sebab dengan tangan yang kuat TUHAN telah membawa engkau keluar dari Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 10, 'Haruslah kaupegang ketetapan ini pada waktunya yang sudah ditentukan, dari tahun ke tahun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 11, 'Apabila engkau telah dibawa TUHAN ke negeri orang Kanaan, seperti yang telah dijanjikan-Nya dengan sumpah kepadamu dan kepada nenek moyangmu, dan negeri itu telah diberikan-Nya kepadamu,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 12, 'maka haruslah kaupersembahkan bagi TUHAN segala yang lahir terdahulu dari kandungan; juga setiap kali ada hewan yang kaupunyai beranak pertama kali, anak jantan yang sulung adalah bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 13, 'Tetapi setiap anak keledai yang lahir terdahulu kautebuslah dengan seekor domba; atau, jika engkau tidak menebusnya, engkau harus mematahkan batang lehernya. Tetapi mengenai manusia, setiap anak sulung di antara anak-anakmu lelaki, haruslah kautebus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 14, 'Dan apabila anakmu akan bertanya kepadamu di kemudian hari: Apakah artinya itu? maka haruslah engkau berkata kepadanya: Dengan kekuatan tangan-Nya TUHAN telah membawa kita keluar dari Mesir, dari rumah perbudakan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 15, 'Sebab ketika Firaun dengan tegar menolak untuk membiarkan kita pergi, maka TUHAN membunuh semua anak sulung di tanah Mesir, dari anak sulung manusia sampai anak sulung hewan. Itulah sebabnya maka aku biasa mempersembahkan kepada TUHAN segala binatang jantan yang lahir terdahulu dari kandungan, sedang semua anak sulung di antara anak-anakku lelaki kutebus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 16, 'Hal itu harus menjadi tanda pada tanganmu dan menjadi lambang di dahimu, sebab dengan kekuatan tangan-Nya TUHAN membawa kita keluar dari Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 17, 'Setelah Firaun membiarkan bangsa itu pergi, Allah tidak menuntun mereka melalui jalan ke negeri orang Filistin, walaupun jalan ini yang paling dekat; sebab firman Allah: "Jangan-jangan bangsa itu menyesal, apabila mereka menghadapi peperangan, sehingga mereka kembali ke Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 18, 'Tetapi Allah menuntun bangsa itu berputar melalui jalan di padang gurun menuju ke Laut Teberau. Dengan siap sedia berperang berjalanlah orang Israel dari tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 19, 'Musa membawa tulang-tulang Yusuf, sebab tadinya Yusuf telah menyuruh anak-anak Israel bersumpah dengan sungguh-sungguh: "Allah tentu akan mengindahkan kamu, maka kamu harus membawa tulang-tulangku dari sini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 20, 'Demikianlah mereka berangkat dari Sukot dan berkemah di Etam, di tepi padang gurun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 21, 'TUHAN berjalan di depan mereka, pada siang hari dalam tiang awan untuk menuntun mereka di jalan, dan pada waktu malam dalam tiang api untuk menerangi mereka, sehingga mereka dapat berjalan siang dan malam.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 13, 22, 'Dengan tidak beralih tiang awan itu tetap ada pada siang hari dan tiang api pada waktu malam di depan bangsa itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 1, 'Berfirmanlah TUHAN kepada Musa, demikian:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 2, '"Katakanlah kepada orang Israel, supaya mereka balik kembali dan berkemah di depan Pi-Hahirot, antara Migdol dan laut; tepat di depan Baal-Zefon berkemahlah kamu, di tepi laut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 3, 'Maka Firaun akan berkata tentang orang Israel: Mereka telah sesat di negeri ini, padang gurun telah mengurung mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 4, 'Aku akan mengeraskan hati Firaun, sehingga ia mengejar mereka. Dan terhadap Firaun dan seluruh pasukannya Aku akan menyatakan kemuliaan-Ku, sehingga orang Mesir mengetahui, bahwa Akulah TUHAN." Lalu mereka berbuat demikian.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 5, 'Ketika diberitahukan kepada raja Mesir, bahwa bangsa itu telah lari, maka berubahlah hati Firaun dan pegawai-pegawainya terhadap bangsa itu, dan berkatalah mereka: "Apakah yang telah kita perbuat ini, bahwa kita membiarkan orang Israel pergi dari perbudakan kita?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 6, 'Kemudian ia memasang keretanya dan membawa rakyatnya serta.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 7, 'Ia membawa enam ratus kereta yang terpilih, ya, segala kereta Mesir, masing-masing lengkap dengan perwiranya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 8, 'Demikianlah TUHAN mengeraskan hati Firaun, raja Mesir itu, sehingga ia mengejar orang Israel. Tetapi orang Israel berjalan terus dipimpin oleh tangan yang dinaikkan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 9, 'Adapun orang Mesir, segala kuda dan kereta Firaun, orang-orang berkuda dan pasukannya, mengejar mereka dan mencapai mereka pada waktu mereka berkemah di tepi laut, dekat Pi-Hahirot di depan Baal-Zefon.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 10, 'Ketika Firaun telah dekat, orang Israel menoleh, maka tampaklah orang Mesir bergerak menyusul mereka. Lalu sangat ketakutanlah orang Israel dan mereka berseru-seru kepada TUHAN,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 11, 'dan mereka berkata kepada Musa: "Apakah karena tidak ada kuburan di Mesir, maka engkau membawa kami untuk mati di padang gurun ini? Apakah yang kauperbuat ini terhadap kami dengan membawa kami keluar dari Mesir?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 12, 'Bukankah ini telah kami katakan kepadamu di Mesir: Janganlah mengganggu kami dan biarlah kami bekerja pada orang Mesir. Sebab lebih baik bagi kami untuk bekerja pada orang Mesir dari pada mati di padang gurun ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 13, 'Tetapi berkatalah Musa kepada bangsa itu: "Janganlah takut, berdirilah tetap dan lihatlah keselamatan dari TUHAN, yang akan diberikan-Nya hari ini kepadamu; sebab orang Mesir yang kamu lihat hari ini, tidak akan kamu lihat lagi untuk selama-lamanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 14, 'TUHAN akan berperang untuk kamu, dan kamu akan diam saja."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 15, 'Berfirmanlah TUHAN kepada Musa: "Mengapakah engkau berseru-seru demikian kepada-Ku? Katakanlah kepada orang Israel, supaya mereka berangkat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 16, 'Dan engkau, angkatlah tongkatmu dan ulurkanlah tanganmu ke atas laut dan belahlah airnya, sehingga orang Israel akan berjalan dari tengah-tengah laut di tempat kering.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 17, 'Tetapi sungguh Aku akan mengeraskan hati orang Mesir, sehingga mereka menyusul orang Israel, dan terhadap Firaun dan seluruh pasukannya, keretanya dan orangnya yang berkuda, Aku akan menyatakan kemuliaan-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 18, 'Maka orang Mesir akan mengetahui, bahwa Akulah TUHAN, apabila Aku memperlihatkan kemuliaan-Ku terhadap Firaun, keretanya dan orangnya yang berkuda."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 19, 'Kemudian bergeraklah Malaikat Allah, yang tadinya berjalan di depan tentara Israel, lalu berjalan di belakang mereka; dan tiang awan itu bergerak dari depan mereka, lalu berdiri di belakang mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 20, 'Demikianlah tiang itu berdiri di antara tentara orang Mesir dan tentara orang Israel; dan oleh karena awan itu menimbulkan kegelapan, maka malam itu lewat, sehingga yang satu tidak dapat mendekati yang lain, semalam-malaman itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 21, 'Lalu Musa mengulurkan tangannya ke atas laut, dan semalam-malaman itu TUHAN menguakkan air laut dengan perantaraan angin timur yang keras, membuat laut itu menjadi tanah kering; maka terbelahlah air itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 22, 'Demikianlah orang Israel berjalan dari tengah-tengah laut di tempat kering; sedang di kiri dan di kanan mereka air itu sebagai tembok bagi mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 23, 'Orang Mesir mengejar dan menyusul mereka?segala kuda Firaun, keretanya dan orangnya yang berkuda?sampai ke tengah-tengah laut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 24, 'Dan pada waktu jaga pagi, TUHAN yang di dalam tiang api dan awan itu memandang kepada tentara orang Mesir, lalu dikacaukan-Nya tentara orang Mesir itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 25, 'Ia membuat roda keretanya berjalan miring dan maju dengan berat, sehingga orang Mesir berkata: "Marilah kita lari meninggalkan orang Israel, sebab Tuhanlah yang berperang untuk mereka melawan Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 26, 'Berfirmanlah TUHAN kepada Musa: "Ulurkanlah tanganmu ke atas laut, supaya air berbalik meliputi orang Mesir, meliputi kereta mereka dan orang mereka yang berkuda."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 27, 'Musa mengulurkan tangannya ke atas laut, maka menjelang pagi berbaliklah air laut ke tempatnya, sedang orang Mesir lari menuju air itu; demikianlah TUHAN mencampakkan orang Mesir ke tengah-tengah laut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 28, 'Berbaliklah segala air itu, lalu menutupi kereta dan orang berkuda dari seluruh pasukan Firaun, yang telah menyusul orang Israel itu ke laut; seorangpun tidak ada yang tinggal dari mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 29, 'Tetapi orang Israel berjalan di tempat kering dari tengah-tengah laut, sedang di kiri dan di kanan mereka air itu sebagai tembok bagi mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 30, 'Demikianlah pada hari itu TUHAN menyelamatkan orang Israel dari tangan orang Mesir. Dan orang Israel melihat orang Mesir mati terhantar di pantai laut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 14, 31, 'Ketika dilihat oleh orang Israel, betapa besarnya perbuatan yang dilakukan TUHAN terhadap orang Mesir, maka takutlah bangsa itu kepada TUHAN dan mereka percaya kepada TUHAN dan kepada Musa, hamba-Nya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 1, 'Pada waktu itu Musa bersama-sama dengan orang Israel menyanyikan nyanyian ini bagi TUHAN yang berbunyi: "Baiklah aku menyanyi bagi TUHAN, sebab Ia tinggi luhur, kuda dan penunggangnya dilemparkan-Nya ke dalam laut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 2, 'TUHAN itu kekuatanku dan mazmurku, Ia telah menjadi keselamatanku. Ia Allahku, kupuji Dia, Ia Allah bapaku, kuluhurkan Dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 3, 'TUHAN itu pahlawan perang; TUHAN, itulah nama-Nya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 4, 'Kereta Firaun dan pasukannya dibuang-Nya ke dalam laut; para perwiranya yang pilihan dibenamkan ke dalam Laut Teberau.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 5, 'Samudera raya menutupi mereka; ke air yang dalam mereka tenggelam seperti batu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 6, 'Tangan kanan-Mu, TUHAN, mulia karena kekuasaan-Mu, tangan kanan-Mu, TUHAN, menghancurkan musuh.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 7, 'Dengan keluhuran-Mu yang besar Engkau meruntuhkan siapa yang bangkit menentang Engkau; Engkau melepaskan api murka-Mu, yang memakan mereka sebagai tunggul gandum.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 8, 'Karena nafas hidung-Mu segala air naik bertimbun-timbun; segala aliran berdiri tegak seperti bendungan; air bah membeku di tengah-tengah laut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 9, 'Kata musuh: Aku akan mengejar, akan mencapai mereka, akan membagi-bagi jarahan; nafsuku akan kulampiaskan kepada mereka, akan kuhunus pedangku; tanganku akan melenyapkan mereka!', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 10, 'Engkau meniup dengan taufan-Mu, lautpun menutupi mereka; sebagai timah mereka tenggelam dalam air yang hebat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 11, 'Siapakah yang seperti Engkau, di antara para allah, ya TUHAN; siapakah seperti Engkau, mulia karena kekudusan-Mu, menakutkan karena perbuatan-Mu yang masyhur, Engkau pembuat keajaiban?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 12, 'Engkau mengulurkan tangan kanan-Mu; bumipun menelan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 13, 'Dengan kasih setia-Mu Engkau menuntun umat yang telah Kautebus; dengan kekuatan-Mu Engkau membimbingnya ke tempat kediaman-Mu yang kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 14, 'Bangsa-bangsa mendengarnya, merekapun menggigil; kegentaran menghinggapi penduduk tanah Filistin.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 15, 'Pada waktu itu gemparlah para kepala kaum di Edom, kedahsyatan menghinggapi orang-orang berkuasa di Moab; semua penduduk tanah Kanaan gemetar.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 16, 'Ngeri dan takut menimpa mereka, karena kebesaran tangan-Mu mereka kaku seperti batu, sampai umat-Mu menyeberang, ya TUHAN, sampai umat yang Kauperoleh menyeberang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 17, 'Engkau membawa mereka dan Kaucangkokkan mereka di atas gunung milik-Mu sendiri; di tempat yang telah Kaubuat kediaman-Mu, ya TUHAN; di tempat kudus, yang didirikan tangan-Mu, ya TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 18, 'TUHAN memerintah kekal selama-lamanya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 19, 'Ketika kuda Firaun dengan keretanya dan orangnya yang berkuda telah masuk ke laut, maka TUHAN membuat air laut berbalik meliputi mereka, tetapi orang Israel berjalan di tempat kering dari tengah-tengah laut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 20, 'Lalu Miryam, nabiah itu, saudara perempuan Harun, mengambil rebana di tangannya, dan tampillah semua perempuan mengikutinya memukul rebana serta menari-nari.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 21, 'Dan menyanyilah Miryam memimpin mereka: "Menyanyilah bagi TUHAN, sebab Ia tinggi luhur; kuda dan penunggangnya dilemparkan-Nya ke dalam laut."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 22, 'Musa menyuruh orang Israel berangkat dari Laut Teberau, lalu mereka pergi ke padang gurun Syur; tiga hari lamanya mereka berjalan di padang gurun itu dengan tidak mendapat air.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 23, 'Sampailah mereka ke Mara, tetapi mereka tidak dapat meminum air yang di Mara itu, karena pahit rasanya. Itulah sebabnya dinamai orang tempat itu Mara.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 24, 'Lalu bersungut-sungutlah bangsa itu kepada Musa, kata mereka: "Apakah yang akan kami minum?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 25, 'Musa berseru-seru kepada TUHAN, dan TUHAN menunjukkan kepadanya sepotong kayu; Musa melemparkan kayu itu ke dalam air; lalu air itu menjadi manis. Di sanalah diberikan TUHAN ketetapan-ketetapan dan peraturan-peraturan kepada mereka dan di sanalah TUHAN mencoba mereka,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 26, 'firman-Nya: "Jika kamu sungguh-sungguh mendengarkan suara TUHAN, Allahmu, dan melakukan apa yang benar di mata-Nya, dan memasang telingamu kepada perintah-perintah-Nya dan tetap mengikuti segala ketetapan-Nya, maka Aku tidak akan menimpakan kepadamu penyakit manapun, yang telah Kutimpakan kepada orang Mesir; sebab Aku Tuhanlah yang menyembuhkan engkau."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 15, 27, 'Sesudah itu sampailah mereka di Elim; di sana ada dua belas mata air dan tujuh puluh pohon korma, lalu berkemahlah mereka di sana di tepi air itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 1, 'Setelah mereka berangkat dari Elim, tibalah segenap jemaah Israel di padang gurun Sin, yang terletak di antara Elim dan gunung Sinai, pada hari yang kelima belas bulan yang kedua, sejak mereka keluar dari tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 2, 'Di padang gurun itu bersungut-sungutlah segenap jemaah Israel kepada Musa dan Harun;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 3, 'dan berkata kepada mereka: "Ah, kalau kami mati tadinya di tanah Mesir oleh tangan TUHAN ketika kami duduk menghadapi kuali berisi daging dan makan roti sampai kenyang! Sebab kamu membawa kami keluar ke padang gurun ini untuk membunuh seluruh jemaah ini dengan kelaparan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 4, 'Lalu berfirmanlah TUHAN kepada Musa: "Sesungguhnya Aku akan menurunkan dari langit hujan roti bagimu; maka bangsa itu akan keluar dan memungut tiap-tiap hari sebanyak yang perlu untuk sehari, supaya mereka Kucoba, apakah mereka hidup menurut hukum-Ku atau tidak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 5, 'Dan pada hari yang keenam, apabila mereka memasak yang dibawa mereka pulang, maka yang dibawa itu akan terdapat dua kali lipat banyaknya dari apa yang dipungut mereka sehari-hari."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 6, 'Sesudah itu berkatalah Musa dan Harun kepada seluruh orang Israel: "Petang ini kamu akan mengetahui bahwa Tuhanlah yang telah membawa kamu keluar dari tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 7, 'Dan besok pagi kamu melihat kemuliaan TUHAN, karena Ia telah mendengar sungut-sungutmu kepada-Nya. Sebab, apalah kami ini maka kamu bersungut-sungut kepada kami?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 8, 'Lagi kata Musa: "Jika memang TUHAN yang memberi kamu makan daging pada waktu petang dan makan roti sampai kenyang pada waktu pagi, karena TUHAN telah mendengar sungut-sungutmu yang kamu sungut-sungutkan kepada-Nya?apalah kami ini? Bukan kepada kami sungut-sungutmu itu, tetapi kepada TUHAN."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 9, 'Kata Musa kepada Harun: "Katakanlah kepada segenap jemaah Israel: Marilah dekat ke hadapan TUHAN, sebab Ia telah mendengar sungut-sungutmu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 10, 'Dan sedang Harun berbicara kepada segenap jemaah Israel, mereka memalingkan mukanya ke arah padang gurun?maka tampaklah kemuliaan TUHAN dalam awan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 11, 'Lalu berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 12, '"Aku telah mendengar sungut-sungut orang Israel; katakanlah kepada mereka: Pada waktu senja kamu akan makan daging dan pada waktu pagi kamu akan kenyang makan roti; maka kamu akan mengetahui, bahwa Akulah TUHAN, Allahmu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 13, 'Pada waktu petang datanglah berduyun-duyun burung puyuh yang menutupi perkemahan itu; dan pada waktu pagi terletaklah embun sekeliling perkemahan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 14, 'Ketika embun itu telah menguap, tampaklah pada permukaan padang gurun sesuatu yang halus, sesuatu yang seperti sisik, halus seperti embun beku di bumi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 15, 'Ketika orang Israel melihatnya, berkatalah mereka seorang kepada yang lain: "Apakah ini?" Sebab mereka tidak tahu apa itu. Tetapi Musa berkata kepada mereka: "Inilah roti yang diberikan TUHAN kepadamu menjadi makananmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 16, 'Beginilah perintah TUHAN: Pungutlah itu, tiap-tiap orang menurut keperluannya; masing-masing kamu boleh mengambil untuk seisi kemahnya, segomer seorang, menurut jumlah jiwa."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 17, 'Demikianlah diperbuat orang Israel; mereka mengumpulkan, ada yang banyak, ada yang sedikit.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 18, 'Ketika mereka menakarnya dengan gomer, maka orang yang mengumpulkan banyak, tidak kelebihan dan orang yang mengumpulkan sedikit, tidak kekurangan. Tiap-tiap orang mengumpulkan menurut keperluannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 19, 'Musa berkata kepada mereka: "Seorangpun tidak boleh meninggalkan dari padanya sampai pagi."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 20, 'Tetapi ada yang tidak mendengarkan Musa dan meninggalkan dari padanya sampai pagi, lalu berulat dan berbau busuk. Maka Musa menjadi marah kepada mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 21, 'Setiap pagi mereka memungutnya, tiap-tiap orang menurut keperluannya; tetapi ketika matahari panas, cairlah itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 22, 'Dan pada hari yang keenam mereka memungut roti itu dua kali lipat banyaknya, dua gomer untuk tiap-tiap orang; dan datanglah semua pemimpin jemaah memberitahukannya kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 23, 'Lalu berkatalah Musa kepada mereka: "Inilah yang dimaksudkan TUHAN: Besok adalah hari perhentian penuh, sabat yang kudus bagi TUHAN; maka roti yang perlu kamu bakar, bakarlah, dan apa yang perlu kamu masak, masaklah; dan segala kelebihannya biarkanlah di tempatnya untuk disimpan sampai pagi."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 24, 'Mereka membiarkannya di tempatnya sampai keesokan harinya, seperti yang diperintahkan Musa; lalu tidaklah berbau busuk dan tidak ada ulat di dalamnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 25, 'Selanjutnya kata Musa: "Makanlah itu pada hari ini, sebab hari ini adalah sabat untuk TUHAN, pada hari ini tidaklah kamu mendapatnya di padang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 26, 'Enam hari lamanya kamu memungutnya, tetapi pada hari yang ketujuh ada sabat; maka roti itu tidak ada pada hari itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 27, 'Tetapi ketika pada hari ketujuh ada dari bangsa itu yang keluar memungutnya, tidaklah mereka mendapatnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 28, 'Sebab itu TUHAN berfirman kepada Musa: "Berapa lama lagi kamu menolak mengikuti segala perintah-Ku dan hukum-Ku?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 29, 'Perhatikanlah, TUHAN telah memberikan sabat itu kepadamu; itulah sebabnya pada hari keenam Ia memberikan kepadamu roti untuk dua hari. Tinggallah kamu di tempatmu masing-masing, seorangpun tidak boleh keluar dari tempatnya pada hari ketujuh itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 30, 'Lalu beristirahatlah bangsa itu pada hari ketujuh.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 31, 'Umat Israel menyebutkan namanya: manna; warnanya putih seperti ketumbar dan rasanya seperti rasa kue madu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 32, 'Musa berkata: "Beginilah perintah TUHAN: Ambillah segomer penuh untuk disimpan turun-temurun, supaya keturunan mereka melihat roti yang Kuberi kamu makan di padang gurun, ketika Aku membawa kamu keluar dari tanah Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 33, 'Sebab itu Musa berkata kepada Harun: "Ambillah sebuah buli-buli, taruhlah manna di dalamnya segomer penuh, dan tempatkanlah itu di hadapan TUHAN untuk disimpan turun-temurun."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 34, 'Seperti yang diperintahkan TUHAN kepada Musa, demikianlah buli-buli itu ditempatkan Harun di hadapan tabut hukum Allah untuk disimpan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 35, 'Orang Israel makan manna empat puluh tahun lamanya, sampai mereka tiba di tanah yang didiami orang; mereka makan manna sampai tiba di perbatasan tanah Kanaan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 16, 36, 'Adapun segomer ialah sepersepuluh efa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 1, 'Kemudian berangkatlah segenap jemaah Israel dari padang gurun Sin, berjalan dari tempat persinggahan ke tempat persinggahan, sesuai dengan titah TUHAN, lalu berkemahlah mereka di Rafidim, tetapi di sana tidak ada air untuk diminum bangsa itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 2, 'Jadi mulailah mereka itu bertengkar dengan Musa, kata mereka: "Berikanlah air kepada kami, supaya kami dapat minum." Tetapi Musa berkata kepada mereka: "Mengapakah kamu bertengkar dengan aku? Mengapakah kamu mencobai TUHAN?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 3, 'Hauslah bangsa itu akan air di sana; bersungut-sungutlah bangsa itu kepada Musa dan berkata: "Mengapa pula engkau memimpin kami keluar dari Mesir, untuk membunuh kami, anak-anak kami dan ternak kami dengan kehausan?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 4, 'Lalu berseru-serulah Musa kepada TUHAN, katanya: "Apakah yang akan kulakukan kepada bangsa ini? Sebentar lagi mereka akan melempari aku dengan batu!"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 5, 'Berfirmanlah TUHAN kepada Musa: "Berjalanlah di depan bangsa itu dan bawalah beserta engkau beberapa orang dari antara para tua-tua Israel; bawalah juga di tanganmu tongkatmu yang kaupakai memukul sungai Nil dan pergilah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 6, 'Maka Aku akan berdiri di sana di depanmu di atas gunung batu di Horeb; haruslah kaupukul gunung batu itu dan dari dalamnya akan keluar air, sehingga bangsa itu dapat minum." Demikianlah diperbuat Musa di depan mata tua-tua Israel.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 7, 'Dinamailah tempat itu Masa dan Meriba, oleh karena orang Israel telah bertengkar dan oleh karena mereka telah mencobai TUHAN dengan mengatakan: "Adakah TUHAN di tengah-tengah kita atau tidak?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 8, 'Lalu datanglah orang Amalek dan berperang melawan orang Israel di Rafidim.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 9, 'Musa berkata kepada Yosua: "Pilihlah orang-orang bagi kita, lalu keluarlah berperang melawan orang Amalek, besok aku akan berdiri di puncak bukit itu dengan memegang tongkat Allah di tanganku."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 10, 'Lalu Yosua melakukan seperti yang dikatakan Musa kepadanya dan berperang melawan orang Amalek; tetapi Musa, Harun dan Hur telah naik ke puncak bukit.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 11, 'Dan terjadilah, apabila Musa mengangkat tangannya, lebih kuatlah Israel, tetapi apabila ia menurunkan tangannya, lebih kuatlah Amalek.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 12, 'Maka penatlah tangan Musa, sebab itu mereka mengambil sebuah batu, diletakkanlah di bawahnya, supaya ia duduk di atasnya; Harun dan Hur menopang kedua belah tangannya, seorang di sisi yang satu, seorang di sisi yang lain, sehingga tangannya tidak bergerak sampai matahari terbenam.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 13, 'Demikianlah Yosua mengalahkan Amalek dan rakyatnya dengan mata pedang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 14, 'Kemudian berfirmanlah TUHAN kepada Musa: "Tuliskanlah semuanya ini dalam sebuah kitab sebagai tanda peringatan, dan ingatkanlah ke telinga Yosua, bahwa Aku akan menghapuskan sama sekali ingatan kepada Amalek dari kolong langit."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 15, 'Lalu Musa mendirikan sebuah mezbah dan menamainya: "Tuhanlah panji-panjiku!"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 17, 16, 'Ia berkata: "Tangan di atas panji-panji TUHAN! TUHAN berperang melawan Amalek turun-temurun."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 1, 'Kedengaranlah kepada Yitro, imam di Midian, mertua Musa, segala yang dilakukan Allah kepada Musa dan kepada Israel, umat-Nya, yakni bahwa TUHAN telah membawa orang Israel keluar dari Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 2, 'Lalu Yitro, mertua Musa, membawa serta Zipora, isteri Musa?yang dahulu disuruh Musa pulang?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 3, 'dan kedua anak laki-laki Zipora; yang seorang bernama Gersom, sebab kata Musa: "Aku telah menjadi seorang pendatang di negeri asing,"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 4, 'dan yang seorang lagi bernama Eliezer, sebab katanya: "Allah bapaku adalah penolongku dan telah menyelamatkan aku dari pedang Firaun."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 5, 'Ketika Yitro, mertua Musa, beserta anak-anak dan isteri Musa sampai kepadanya di padang gurun, tempat ia berkemah dekat gunung Allah,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 6, 'disuruhnyalah mengatakan kepada Musa: "Aku, mertuamu Yitro, datang kepadamu membawa isterimu beserta kedua anaknya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 7, 'Lalu keluarlah Musa menyongsong mertuanya itu, sujudlah ia kepadanya dan menciumnya; mereka menanyakan keselamatan masing-masing, lalu masuk ke dalam kemah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 8, 'Sesudah itu Musa menceritakan kepada mertuanya segala yang dilakukan TUHAN kepada Firaun dan kepada orang Mesir karena Israel dan segala kesusahan yang mereka alami di jalan dan bagaimana TUHAN menyelamatkan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 9, 'Bersukacitalah Yitro tentang segala kebaikan, yang dilakukan TUHAN kepada orang Israel, bahwa Ia telah menyelamatkan mereka dari tangan orang Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 10, 'Lalu kata Yitro: "Terpujilah TUHAN, yang telah menyelamatkan kamu dari tangan orang Mesir dan dari tangan Firaun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 11, 'Sekarang aku tahu, bahwa TUHAN lebih besar dari segala allah; sebab Ia telah menyelamatkan bangsa ini dari tangan orang Mesir, karena memang orang-orang ini telah bertindak angkuh terhadap mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 12, 'Dan Yitro, mertua Musa, mempersembahkan korban bakaran dan beberapa korban sembelihan bagi Allah; lalu Harun dan semua tua-tua Israel datang untuk makan bersama-sama dengan mertua Musa di hadapan Allah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 13, 'Keesokan harinya duduklah Musa mengadili di antara bangsa itu; dan bangsa itu berdiri di depan Musa, dari pagi sampai petang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 14, 'Ketika mertua Musa melihat segala yang dilakukannya kepada bangsa itu, berkatalah ia: "Apakah ini yang kaulakukan kepada bangsa itu? Mengapakah engkau seorang diri saja yang duduk, sedang seluruh bangsa itu berdiri di depanmu dari pagi sampai petang?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 15, 'Kata Musa kepada mertuanya itu: "Sebab bangsa ini datang kepadaku untuk menanyakan petunjuk Allah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 16, 'Apabila ada perkara di antara mereka, maka mereka datang kepadaku dan aku mengadili antara yang seorang dan yang lain; lagipula aku memberitahukan kepada mereka ketetapan-ketetapan dan keputusan-keputusan Allah."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 17, 'Tetapi mertua Musa menjawabnya: "Tidak baik seperti yang kaulakukan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 18, 'Engkau akan menjadi sangat lelah, baik engkau baik bangsa yang beserta engkau ini; sebab pekerjaan ini terlalu berat bagimu, takkan sanggup engkau melakukannya seorang diri saja.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 19, 'Jadi sekarang dengarkanlah perkataanku, aku akan memberi nasihat kepadamu dan Allah akan menyertai engkau. Adapun engkau, wakililah bangsa itu di hadapan Allah dan kauhadapkanlah perkara-perkara mereka kepada Allah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 20, 'Kemudian haruslah engkau mengajarkan kepada mereka ketetapan-ketetapan dan keputusan-keputusan, dan memberitahukan kepada mereka jalan yang harus dijalani, dan pekerjaan yang harus dilakukan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 21, 'Di samping itu kaucarilah dari seluruh bangsa itu orang-orang yang cakap dan takut akan Allah, orang-orang yang dapat dipercaya, dan yang benci kepada pengejaran suap; tempatkanlah mereka di antara bangsa itu menjadi pemimpin seribu orang, pemimpin seratus orang, pemimpin lima puluh orang dan pemimpin sepuluh orang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 22, 'Dan sewaktu-waktu mereka harus mengadili di antara bangsa; maka segala perkara yang besar haruslah dihadapkan mereka kepadamu, tetapi segala perkara yang kecil diadili mereka sendiri; dengan demikian mereka meringankan pekerjaanmu, dan mereka bersama-sama dengan engkau turut menanggungnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 23, 'Jika engkau berbuat demikian dan Allah memerintahkan hal itu kepadamu, maka engkau akan sanggup menahannya, dan seluruh bangsa ini akan pulang dengan puas senang ke tempatnya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 24, 'Musa mendengarkan perkataan mertuanya itu dan dilakukannyalah segala yang dikatakannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 25, 'Dari seluruh orang Israel Musa memilih orang-orang cakap dan mengangkat mereka menjadi kepala atas bangsa itu, menjadi pemimpin seribu orang, pemimpin seratus orang, pemimpin lima puluh orang dan pemimpin sepuluh orang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 26, 'Mereka ini mengadili di antara bangsa itu sewaktu-waktu; perkara-perkara yang sukar dihadapkan mereka kepada Musa, tetapi perkara-perkara yang kecil diadili mereka sendiri.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 18, 27, 'Kemudian Musa membiarkan mertuanya itu pergi dan ia pulang ke negerinya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 1, 'Pada bulan ketiga setelah orang Israel keluar dari tanah Mesir, mereka tiba di padang gurun Sinai pada hari itu juga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 2, 'Setelah mereka berangkat dari Rafidim, tibalah mereka di padang gurun Sinai, lalu mereka berkemah di padang gurun; orang Israel berkemah di sana di depan gunung itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 3, 'Lalu naiklah Musa menghadap Allah, dan TUHAN berseru dari gunung itu kepadanya: "Beginilah kaukatakan kepada keturunan Yakub dan kauberitakan kepada orang Israel:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 4, 'Kamu sendiri telah melihat apa yang Kulakukan kepada orang Mesir, dan bagaimana Aku telah mendukung kamu di atas sayap rajawali dan membawa kamu kepada-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 5, 'Jadi sekarang, jika kamu sungguh-sungguh mendengarkan firman-Ku dan berpegang pada perjanjian-Ku, maka kamu akan menjadi harta kesayangan-Ku sendiri dari antara segala bangsa, sebab Akulah yang empunya seluruh bumi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 6, 'Kamu akan menjadi bagi-Ku kerajaan imam dan bangsa yang kudus. Inilah semuanya firman yang harus kaukatakan kepada orang Israel."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 7, 'Lalu datanglah Musa dan memanggil para tua-tua bangsa itu dan membawa ke depan mereka segala firman yang diperintahkan TUHAN kepadanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 8, 'Seluruh bangsa itu menjawab bersama-sama: "Segala yang difirmankan TUHAN akan kami lakukan." Lalu Musapun menyampaikan jawab bangsa itu kepada TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 9, 'Berfirmanlah TUHAN kepada Musa: "Sesungguhnya Aku akan datang kepadamu dalam awan yang tebal, dengan maksud supaya dapat didengar oleh bangsa itu apabila Aku berbicara dengan engkau, dan juga supaya mereka senantiasa percaya kepadamu." Lalu Musa memberitahukan perkataan bangsa itu kepada TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 10, 'Berfirmanlah TUHAN kepada Musa: "Pergilah kepada bangsa itu; suruhlah mereka menguduskan diri pada hari ini dan besok, dan mereka harus mencuci pakaiannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 11, 'Menjelang hari ketiga mereka harus bersiap, sebab pada hari ketiga TUHAN akan turun di depan mata seluruh bangsa itu di gunung Sinai.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 12, 'Sebab itu haruslah engkau memasang batas bagi bangsa itu berkeliling sambil berkata: Jagalah baik-baik, jangan kamu mendaki gunung itu atau kena kepada kakinya, sebab siapapun yang kena kepada gunung itu, pastilah ia dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 13, 'Tangan seorangpun tidak boleh merabanya, sebab pastilah ia dilempari dengan batu atau dipanahi sampai mati; baik binatang baik manusia, ia tidak akan dibiarkan hidup. Hanya apabila sangkakala berbunyi panjang, barulah mereka boleh mendaki gunung itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 14, 'Lalu turunlah Musa dari gunung mendapatkan bangsa itu; disuruhnyalah bangsa itu menguduskan diri dan merekapun mencuci pakaiannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 15, 'Maka kata Musa kepada bangsa itu: "Bersiaplah menjelang hari yang ketiga, dan janganlah kamu bersetubuh dengan perempuan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 16, 'Dan terjadilah pada hari ketiga, pada waktu terbit fajar, ada guruh dan kilat dan awan padat di atas gunung dan bunyi sangkakala yang sangat keras, sehingga gemetarlah seluruh bangsa yang ada di perkemahan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 17, 'Lalu Musa membawa bangsa itu keluar dari perkemahan untuk menjumpai Allah dan berdirilah mereka pada kaki gunung.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 18, 'Gunung Sinai ditutupi seluruhnya dengan asap, karena TUHAN turun ke atasnya dalam api; asapnya membubung seperti asap dari dapur, dan seluruh gunung itu gemetar sangat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 19, 'Bunyi sangkakala kian lama kian keras. Berbicaralah Musa, lalu Allah menjawabnya dalam guruh.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 20, 'Lalu turunlah TUHAN ke atas gunung Sinai, ke atas puncak gunung itu, maka TUHAN memanggil Musa ke puncak gunung itu, dan naiklah Musa ke atas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 21, 'Kemudian TUHAN berfirman kepada Musa: "Turunlah, peringatkanlah kepada bangsa itu, supaya mereka jangan menembus mendapatkan TUHAN hendak melihat-lihat; sebab tentulah banyak dari mereka akan binasa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 22, 'Juga para imam yang datang mendekat kepada TUHAN haruslah menguduskan dirinya, supaya TUHAN jangan melanda mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 23, 'Lalu berkatalah Musa kepada TUHAN: "Tidak akan mungkin bangsa itu mendaki gunung Sinai ini, sebab Engkau sendiri telah memperingatkan kepada kami, demikian: Pasanglah batas sekeliling gunung itu dan nyatakanlah itu kudus."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 24, 'Lalu TUHAN berfirman kepadanya: "Pergilah, turunlah, kemudian naiklah pula, engkau beserta Harun; tetapi para imam dan rakyat tidak boleh menembus untuk mendaki menghadap TUHAN, supaya mereka jangan dilanda-Nya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 19, 25, 'Lalu turunlah Musa mendapatkan bangsa itu dan menyatakan hal itu kepada mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 1, 'Lalu Allah mengucapkan segala firman ini:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 2, '"Akulah TUHAN, Allahmu, yang membawa engkau keluar dari tanah Mesir, dari tempat perbudakan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 3, 'Jangan ada padamu allah lain di hadapan-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 4, 'Jangan membuat bagimu patung yang menyerupai apapun yang ada di langit di atas, atau yang ada di bumi di bawah, atau yang ada di dalam air di bawah bumi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 5, 'Jangan sujud menyembah kepadanya atau beribadah kepadanya, sebab Aku, TUHAN, Allahmu, adalah Allah yang cemburu, yang membalaskan kesalahan bapa kepada anak-anaknya, kepada keturunan yang ketiga dan keempat dari orang-orang yang membenci Aku,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 6, 'tetapi Aku menunjukkan kasih setia kepada beribu-ribu orang, yaitu mereka yang mengasihi Aku dan yang berpegang pada perintah-perintah-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 7, 'Jangan menyebut nama TUHAN, Allahmu, dengan sembarangan, sebab TUHAN akan memandang bersalah orang yang menyebut nama-Nya dengan sembarangan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 8, 'Ingatlah dan kuduskanlah hari Sabat:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 9, 'enam hari lamanya engkau akan bekerja dan melakukan segala pekerjaanmu,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 10, 'tetapi hari ketujuh adalah hari Sabat TUHAN, Allahmu; maka jangan melakukan sesuatu pekerjaan, engkau atau anakmu laki-laki, atau anakmu perempuan, atau hambamu laki-laki, atau hambamu perempuan, atau hewanmu atau orang asing yang di tempat kediamanmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 11, 'Sebab enam hari lamanya TUHAN menjadikan langit dan bumi, laut dan segala isinya, dan Ia berhenti pada hari ketujuh; itulah sebabnya TUHAN memberkati hari Sabat dan menguduskannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 12, 'Hormatilah ayahmu dan ibumu, supaya lanjut umurmu di tanah yang diberikan TUHAN, Allahmu, kepadamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 13, 'Jangan membunuh.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 14, 'Jangan berzinah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 15, 'Jangan mencuri.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 16, 'Jangan mengucapkan saksi dusta tentang sesamamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 17, 'Jangan mengingini rumah sesamamu; jangan mengingini isterinya, atau hambanya laki-laki, atau hambanya perempuan, atau lembunya atau keledainya, atau apapun yang dipunyai sesamamu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 18, 'Seluruh bangsa itu menyaksikan guruh mengguntur, kilat sabung-menyabung, sangkakala berbunyi dan gunung berasap. Maka bangsa itu takut dan gemetar dan mereka berdiri jauh-jauh.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 19, 'Mereka berkata kepada Musa: "Engkaulah berbicara dengan kami, maka kami akan mendengarkan; tetapi janganlah Allah berbicara dengan kami, nanti kami mati."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 20, 'Tetapi Musa berkata kepada bangsa itu: "Janganlah takut, sebab Allah telah datang dengan maksud untuk mencoba kamu dan dengan maksud supaya takut akan Dia ada padamu, agar kamu jangan berbuat dosa."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 21, 'Adapun bangsa itu berdiri jauh-jauh, tetapi Musa pergi mendekati embun yang kelam di mana Allah ada.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 22, 'Lalu berfirmanlah TUHAN kepada Musa: "Beginilah kaukatakan kepada orang Israel: Kamu sendiri telah menyaksikan, bahwa Aku berbicara dengan kamu dari langit.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 23, 'Janganlah kamu membuat di samping-Ku allah perak, juga allah emas janganlah kamu buat bagimu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 24, 'Kaubuatlah bagi-Ku mezbah dari tanah dan persembahkanlah di atasnya korban bakaranmu dan korban keselamatanmu, kambing dombamu dan lembu sapimu. Pada setiap tempat yang Kutentukan menjadi tempat peringatan bagi nama-Ku, Aku akan datang kepadamu dan memberkati engkau.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 25, 'Tetapi jika engkau membuat bagi-Ku mezbah dari batu, maka jangan engkau mendirikannya dari batu pahat, sebab apabila engkau mengerjakannya dengan beliung, maka engkau melanggar kekudusannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 20, 26, 'Juga jangan engkau naik tangga ke atas ke mezbah-Ku, supaya auratmu jangan kelihatan di atasnya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 1, '"Inilah peraturan-peraturan yang harus kaubawa ke depan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 2, 'Apabila engkau membeli seorang budak Ibrani, maka haruslah ia bekerja padamu enam tahun lamanya, tetapi pada tahun yang ketujuh ia diizinkan keluar sebagai orang merdeka, dengan tidak membayar tebusan apa-apa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 3, 'Jika ia datang seorang diri saja, maka keluarpun ia seorang diri; jika ia mempunyai isteri, maka isterinya itu diizinkan keluar bersama-sama dengan dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 4, 'Jika tuannya memberikan kepadanya seorang isteri dan perempuan itu melahirkan anak-anak lelaki atau perempuan, maka perempuan itu dengan anak-anaknya tetap menjadi kepunyaan tuannya, dan budak laki-laki itu harus keluar seorang diri.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 5, 'Tetapi jika budak itu dengan sungguh-sungguh berkata: Aku cinta kepada tuanku, kepada isteriku dan kepada anak-anakku, aku tidak mau keluar sebagai orang merdeka,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 6, 'maka haruslah tuannya itu membawanya menghadap Allah, lalu membawanya ke pintu atau ke tiang pintu, dan tuannya itu menusuk telinganya dengan penusuk, dan budak itu bekerja pada tuannya untuk seumur hidup.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 7, 'Apabila ada seorang menjual anaknya yang perempuan sebagai budak, maka perempuan itu tidak boleh keluar seperti cara budak-budak lelaki keluar.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 8, 'Jika perempuan itu tidak disukai tuannya, yang telah menyediakannya bagi dirinya sendiri, maka haruslah tuannya itu mengizinkan ia ditebus; tuannya itu tidak berhak untuk menjualnya kepada bangsa asing, karena ia memungkiri janjinya kepada perempuan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 9, 'Jika tuannya itu menyediakannya bagi anaknya laki-laki, maka haruslah tuannya itu memperlakukannya seperti anak-anak perempuan berhak diperlakukan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 10, 'Jika tuannya itu mengambil perempuan lain, ia tidak boleh mengurangi makanan perempuan itu, pakaiannya dan persetubuhan dengan dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 11, 'Jika tuannya itu tidak melakukan ketiga hal itu kepadanya, maka perempuan itu harus diizinkan keluar, dengan tidak membayar uang tebusan apa-apa."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 12, '"Siapa yang memukul seseorang, sehingga mati, pastilah ia dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 13, 'Tetapi jika pembunuhan itu tidak disengaja, melainkan tangannya ditentukan Allah melakukan itu, maka Aku akan menunjukkan bagimu suatu tempat, ke mana ia dapat lari.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 14, 'Tetapi apabila seseorang berlaku angkara terhadap sesamanya, hingga ia membunuhnya dengan tipu daya, maka engkau harus mengambil orang itu dari mezbah-Ku, supaya ia mati dibunuh.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 15, 'Siapa yang memukul ayahnya atau ibunya, pastilah ia dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 16, 'Siapa yang menculik seorang manusia, baik ia telah menjualnya, baik orang itu masih terdapat padanya, ia pasti dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 17, 'Siapa yang mengutuki ayahnya atau ibunya, ia pasti dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 18, 'Apabila ada orang bertengkar dan yang seorang memukul yang lain dengan batu atau dengan tinjunya, sehingga yang lain itu memang tidak mati, tetapi terpaksa berbaring di tempat tidur,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 19, 'maka orang yang memukul itu bebas dari hukuman, jika yang lain itu dapat bangkit lagi dan dapat berjalan di luar dengan memakai tongkat; hanya ia harus membayar kerugian orang yang lain itu, karena terpaksa menganggur, dan menanggung pengobatannya sampai sembuh.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 20, 'Apabila seseorang memukul budaknya laki-laki atau perempuan dengan tongkat, sehingga mati karena pukulan itu, pastilah budak itu dibalaskan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 21, 'Hanya jika budak itu masih hidup sehari dua, maka janganlah dituntut belanya, sebab budak itu adalah miliknya sendiri.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 22, 'Apabila ada orang berkelahi dan seorang dari mereka tertumbuk kepada seorang perempuan yang sedang mengandung, sehingga keguguran kandungan, tetapi tidak mendapat kecelakaan yang membawa maut, maka pastilah ia didenda sebanyak yang dikenakan oleh suami perempuan itu kepadanya, dan ia harus membayarnya menurut putusan hakim.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 23, 'Tetapi jika perempuan itu mendapat kecelakaan yang membawa maut, maka engkau harus memberikan nyawa ganti nyawa,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 24, 'mata ganti mata, gigi ganti gigi, tangan ganti tangan, kaki ganti kaki,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 25, 'lecur ganti lecur, luka ganti luka, bengkak ganti bengkak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 26, 'Apabila seseorang memukul mata budaknya laki-laki atau mata budaknya perempuan dan merusakkannya, maka ia harus melepaskan budak itu sebagai orang merdeka pengganti kerusakan matanya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 27, 'Dan jika ia menumbuk sampai tanggal gigi budaknya laki-laki atau gigi budaknya perempuan, maka ia harus melepaskan budak itu sebagai orang merdeka pengganti kehilangan giginya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 28, 'Apabila seekor lembu menanduk seorang laki-laki atau perempuan, sehingga mati, maka pastilah lembu itu dilempari mati dengan batu dan dagingnya tidak boleh dimakan, tetapi pemilik lembu itu bebas dari hukuman.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 29, 'Tetapi jika lembu itu sejak dahulu telah sering menanduk dan pemiliknya telah diperingatkan, tetapi tidak mau menjaganya, kemudian lembu itu menanduk mati seorang laki-laki atau perempuan, maka lembu itu harus dilempari mati dengan batu, tetapi pemiliknyapun harus dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 30, 'Jika dibebankan kepadanya uang pendamaian, maka haruslah dibayarnya segala yang dibebankan kepadanya itu sebagai tebusan nyawanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 31, 'Kalau ditanduknya seorang anak laki-laki atau perempuan, maka pemiliknya harus diperlakukan menurut peraturan itu juga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 32, 'Tetapi jika lembu itu menanduk seorang budak laki-laki atau perempuan, maka pemiliknya harus membayar tiga puluh syikal perak kepada tuan budak itu, dan lembu itu harus dilempari mati dengan batu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 33, 'Apabila seseorang membuka sumur, atau apabila seseorang menggali sumur, dengan tidak menutupnya, dan seekor lembu atau keledai jatuh ke dalamnya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 34, 'maka pemilik sumur itu harus membayar ganti kerugian: ia harus mengganti harga binatang itu dengan uang kepada pemiliknya, tetapi binatang yang mati itu menjadi kepunyaannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 35, 'Apabila lembu seseorang menanduk lembu orang lain, sehingga mati, maka lembu yang hidup itu harus dijual, uangnya dibagi dan binatang yang mati itupun harus dibagi juga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 21, 36, 'Tetapi jikalau lembu itu terkenal telah sering menanduk sejak dahulu, dan walaupun demikian pemiliknya tidak mau menjaganya, maka ia harus membayar ganti kerugian sepenuhnya: lembu ganti lembu, tetapi binatang yang mati itu menjadi kepunyaannya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 1, '"Apabila seseorang mencuri seekor lembu atau seekor domba dan membantainya atau menjualnya, maka ia harus membayar gantinya, yakni lima ekor lembu ganti lembu itu dan empat ekor domba ganti domba itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 2, 'Jika seorang pencuri kedapatan waktu membongkar, dan ia dipukul orang sehingga mati, maka si pemukul tidak berhutang darah;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 3, 'tetapi jika pembunuhan itu terjadi setelah matahari terbit, maka ia berhutang darah. Pencuri itu harus membayar ganti kerugian sepenuhnya; jika ia orang yang tak punya, ia harus dijual ganti apa yang dicurinya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 4, 'Jika yang dicurinya itu masih terdapat padanya dalam keadaan hidup, baik lembu, keledai atau domba, maka ia harus membayar ganti kerugian dua kali lipat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 5, 'Apabila seseorang menggembalakan ternaknya di ladangnya atau di kebun anggurnya dan ternak itu dibiarkannya berjalan lepas, sehingga makan habis ladang orang lain, maka ia harus memberikan hasil yang terbaik dari ladangnya sendiri atau hasil yang terbaik dari kebun anggurnya sebagai ganti kerugian.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 6, 'Apabila ada api dinyalakan dan api itu menjilat semak duri, tetapi tumpukan gandum atau gandum yang belum dituai atau seluruh ladang itu ikut juga dimakan api, maka orang yang menyebabkan kebakaran itu harus membayar ganti kerugian sepenuhnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 7, 'Apabila seseorang menitipkan kepada temannya uang atau barang, dan itu dicuri dari rumah orang itu, maka jika pencuri itu terdapat, ia harus membayar ganti kerugian dua kali lipat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 8, 'Jika pencuri itu tidak terdapat, maka tuan rumah harus pergi menghadap Allah untuk bersumpah, bahwa ia tidak mengulurkan tangannya mengambil harta kepunyaan temannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 9, 'Dalam tiap-tiap perkara pertengkaran harta, baik tentang seekor lembu, tentang seekor keledai, tentang seekor domba, tentang sehelai pakaian, baik tentang barang apapun yang kehilangan, kalau seorang mengatakan: Inilah kepunyaanku?maka perkara kedua orang itu harus dibawa ke hadapan Allah. Siapa yang dipersalahkan oleh Allah haruslah membayar kepada temannya ganti kerugian dua kali lipat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 10, 'Apabila seseorang menitipkan kepada temannya seekor keledai atau lembu atau seekor domba atau binatang apapun dan binatang itu mati, atau patah kakinya atau dihalau orang dengan kekerasan, dengan tidak ada orang yang melihatnya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 11, 'maka sumpah di hadapan TUHAN harus menentukan di antara kedua orang itu, apakah ia tidak mengulurkan tangannya mengambil harta kepunyaan temannya, dan pemilik harus menerima sumpah itu, dan yang lain itu tidak usah membayar ganti kerugian.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 12, 'Tetapi jika binatang itu benar-benar dicuri orang dari padanya, maka ia harus membayar ganti kerugian kepada pemilik.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 13, 'Jika binatang itu benar-benar diterkam oleh binatang buas, maka ia harus membawanya sebagai bukti. Tidak usah ia membayar ganti binatang yang diterkam itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 14, 'Apabila seseorang meminjam seekor binatang dari temannya, dan binatang itu patah kakinya atau mati, ketika pemiliknya tidak ada di situ, maka ia harus membayar ganti kerugian sepenuhnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 15, 'Tetapi jika pemiliknya ada di situ, maka tidak usahlah ia membayar ganti kerugian. Jika binatang itu disewa, maka kerugian itu telah termasuk dalam sewa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 16, 'Apabila seseorang membujuk seorang anak perawan yang belum bertunangan, dan tidur dengan dia, maka haruslah ia mengambilnya menjadi isterinya dengan membayar mas kawin.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 17, 'Jika ayah perempuan itu sungguh-sungguh menolak memberikannya kepadanya, maka ia harus juga membayar perak itu sepenuhnya, sebanyak mas kawin anak perawan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 18, '"Seorang ahli sihir perempuan janganlah engkau biarkan hidup.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 19, 'Siapapun yang tidur dengan seekor binatang, pastilah ia dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 20, 'Siapa yang mempersembahkan korban kepada allah kecuali kepada TUHAN sendiri, haruslah ia ditumpas."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 21, '"Janganlah kautindas atau kautekan seorang orang asing, sebab kamupun dahulu adalah orang asing di tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 22, 'Seseorang janda atau anak yatim janganlah kamu tindas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 23, 'Jika engkau memang menindas mereka ini, tentulah Aku akan mendengarkan seruan mereka, jika mereka berseru-seru kepada-Ku dengan nyaring.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 24, 'Maka murka-Ku akan bangkit dan Aku akan membunuh kamu dengan pedang, sehingga isteri-isterimu menjadi janda dan anak-anakmu menjadi yatim.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 25, 'Jika engkau meminjamkan uang kepada salah seorang dari umat-Ku, orang yang miskin di antaramu, maka janganlah engkau berlaku sebagai seorang penagih hutang terhadap dia: janganlah kamu bebankan bunga uang kepadanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 26, 'Jika engkau sampai mengambil jubah temanmu sebagai gadai, maka haruslah engkau mengembalikannya kepadanya sebelum matahari terbenam,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 27, 'sebab hanya itu saja penutup tubuhnya, itulah pemalut kulitnya?pakai apakah ia pergi tidur? Maka apabila ia berseru-seru kepada-Ku, Aku akan mendengarkannya, sebab Aku ini pengasih."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 28, '"Janganlah engkau mengutuki Allah dan janganlah engkau menyumpahi seorang pemuka di tengah-tengah bangsamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 29, 'Janganlah lalai mempersembahkan hasil gandummu dan hasil anggurmu. Yang sulung dari anak-anakmu lelaki haruslah kaupersembahkan kepada-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 30, 'Demikian juga harus kauperbuat dengan lembu sapimu dan dengan kambing dombamu: tujuh hari lamanya anak-anak binatang itu harus tinggal pada induknya, tetapi pada hari yang kedelapan haruslah kaupersembahkan binatang-binatang itu kepada-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 22, 31, 'Haruslah kamu menjadi orang-orang kudus bagi-Ku: daging ternak yang diterkam di padang oleh binatang buas, janganlah kamu makan, tetapi haruslah kamu lemparkan kepada anjing."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 1, '"Janganlah engkau menyebarkan kabar bohong; janganlah engkau membantu orang yang bersalah dengan menjadi saksi yang tidak benar.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 2, 'Janganlah engkau turut-turut kebanyakan orang melakukan kejahatan, dan dalam memberikan kesaksian mengenai sesuatu perkara janganlah engkau turut-turut kebanyakan orang membelokkan hukum.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 3, 'Juga janganlah memihak kepada orang miskin dalam perkaranya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 4, 'Apabila engkau melihat lembu musuhmu atau keledainya yang sesat, maka segeralah kaukembalikan binatang itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 5, 'Apabila engkau melihat rebah keledai musuhmu karena berat bebannya, maka janganlah engkau enggan menolongnya. Haruslah engkau rela menolong dia dengan membongkar muatan keledainya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 6, 'Janganlah engkau memperkosa hak orang miskin di antaramu dalam perkaranya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 7, 'Haruslah kaujauhkan dirimu dari perkara dusta. Orang yang tidak bersalah dan orang yang benar tidak boleh kaubunuh, sebab Aku tidak akan membenarkan orang yang bersalah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 8, 'Suap janganlah kauterima, sebab suap membuat buta mata orang-orang yang melihat dan memutarbalikkan perkara orang-orang yang benar.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 9, 'Orang asing janganlah kamu tekan, karena kamu sendiri telah mengenal keadaan jiwa orang asing, sebab kamupun dahulu adalah orang asing di tanah Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 10, 'Enam tahunlah lamanya engkau menabur di tanahmu dan mengumpulkan hasilnya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 11, 'tetapi pada tahun ketujuh haruslah engkau membiarkannya dan meninggalkannya begitu saja, supaya orang miskin di antara bangsamu dapat makan, dan apa yang ditinggalkan mereka haruslah dibiarkan dimakan binatang hutan. Demikian juga kaulakukan dengan kebun anggurmu dan kebun zaitunmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 12, 'Enam harilah lamanya engkau melakukan pekerjaanmu, tetapi pada hari ketujuh haruslah engkau berhenti, supaya lembu dan keledaimu tidak bekerja dan supaya anak budakmu perempuan dan orang asing melepaskan lelah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 13, 'Dalam segala hal yang Kufirmankan kepadamu haruslah kamu berawas-awas; nama allah lain janganlah kamu panggil, janganlah nama itu kedengaran dari mulutmu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 14, '"Tiga kali setahun haruslah engkau mengadakan perayaan bagi-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 15, 'Hari raya Roti Tidak Beragi haruslah kaupelihara; tujuh hari lamanya engkau harus makan roti yang tidak beragi, seperti yang telah Kuperintahkan kepadamu, pada waktu yang ditetapkan dalam bulan Abib, sebab dalam bulan itulah engkau keluar dari Mesir, tetapi janganlah orang menghadap ke hadirat-Ku dengan tangan hampa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 16, 'Kaupeliharalah juga hari raya menuai, yakni menuai buah bungaran dari hasil usahamu menabur di ladang; demikian juga hari raya pengumpulan hasil pada akhir tahun, apabila engkau mengumpulkan hasil usahamu dari ladang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 17, 'Tiga kali setahun semua orangmu yang laki-laki harus menghadap ke hadirat Tuhanmu TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 18, 'Janganlah kaupersembahkan darah korban sembelihan yang kepada-Ku beserta sesuatu yang beragi, dan janganlah lemak korban hari raya-Ku bermalam sampai pagi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 19, 'Yang terbaik dari buah bungaran hasil tanahmu haruslah kaubawa ke dalam rumah TUHAN, Allahmu. Janganlah kaumasak anak kambing dalam susu induknya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 20, '"Sesungguhnya Aku mengutus seorang malaikat berjalan di depanmu, untuk melindungi engkau di jalan dan untuk membawa engkau ke tempat yang telah Kusediakan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 21, 'Jagalah dirimu di hadapannya dan dengarkanlah perkataannya, janganlah engkau mendurhaka kepadanya, sebab pelanggaranmu tidak akan diampuninya, sebab nama-Ku ada di dalam dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 22, 'Tetapi jika engkau sungguh-sungguh mendengarkan perkataannya, dan melakukan segala yang Kufirmankan, maka Aku akan memusuhi musuhmu, dan melawan lawanmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 23, 'Sebab malaikat-Ku akan berjalan di depanmu dan membawa engkau kepada orang Amori, orang Het, orang Feris, orang Kanaan, orang Hewi dan orang Yebus, dan Aku akan melenyapkan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 24, 'Janganlah engkau sujud menyembah kepada allah mereka atau beribadah kepadanya, dan janganlah engkau meniru perbuatan mereka, tetapi haruslah engkau memusnahkan sama sekali patung-patung berhala buatan mereka, dan tugu-tugu berhala mereka haruslah kauremukkan sama sekali.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 25, 'Tetapi kamu harus beribadah kepada TUHAN, Allahmu; maka Ia akan memberkati roti makananmu dan air minumanmu dan Aku akan menjauhkan penyakit dari tengah-tengahmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 26, 'Tidak akan ada di negerimu perempuan yang keguguran atau mandul. Aku akan menggenapkan tahun umurmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 27, 'Kengerian terhadap Aku akan Kukirimkan mendahului engkau: Aku akan mengacaukan semua orang yang kaudatangi, dan Aku akan membuat semua musuhmu lari membelakangi engkau.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 28, 'Lagi Aku akan melepaskan tabuhan mendahului engkau, sehingga binatang-binatang itu menghalau orang Hewi, orang Kanaan dan orang Het itu dari depanmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 29, 'Aku tidak akan menghalau mereka dari depanmu dalam satu tahun, supaya negeri itu jangan menjadi sepi, dan segala binatang hutan jangan bertambah banyak melebihi engkau.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 30, 'Sedikit demi sedikit Aku akan menghalau mereka dari depanmu, sampai engkau beranak cucu sedemikian, hingga engkau dapat memiliki negeri itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 31, 'Aku akan menentukan batas daerahmu dari Laut Teberau sampai Laut Filistin dan dari padang gurun sampai sungai Efrat, sebab Aku akan menyerahkan penduduk negeri itu ke dalam tanganmu, sehingga engkau menghalau mereka dari depanmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 32, 'Janganlah mengadakan perjanjian dengan mereka ataupun dengan allah mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 23, 33, 'Mereka tidak akan tetap diam di negerimu, supaya mereka jangan membuat engkau berdosa kepada-Ku, dengan beribadah kepada allah mereka, sebab tentulah hal itu menjadi jerat bagimu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 1, 'Berfirmanlah Ia kepada Musa: "Naiklah menghadap TUHAN, engkau dan Harun, Nadab dan Abihu dan tujuh puluh orang dari para tua-tua Israel dan sujudlah kamu menyembah dari jauh.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 2, 'Hanya Musa sendirilah yang mendekat kepada TUHAN, tetapi mereka itu tidak boleh mendekat, dan bangsa itu tidak boleh naik bersama-sama dengan dia."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 3, 'Lalu datanglah Musa dan memberitahukan kepada bangsa itu segala firman TUHAN dan segala peraturan itu, maka seluruh bangsa itu menjawab serentak: "Segala firman yang telah diucapkan TUHAN itu, akan kami lakukan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 4, 'Lalu Musa menuliskan segala firman TUHAN itu. Keesokan harinya pagi-pagi didirikannyalah mezbah di kaki gunung itu, dengan dua belas tugu sesuai dengan kedua belas suku Israel.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 5, 'Kemudian disuruhnyalah orang-orang muda dari bangsa Israel, maka mereka mempersembahkan korban bakaran dan menyembelih lembu-lembu jantan sebagai korban keselamatan kepada TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 6, 'Sesudah itu Musa mengambil sebagian dari darah itu, lalu ditaruhnya ke dalam pasu, sebagian lagi dari darah itu disiramkannya pada mezbah itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 7, 'Diambilnyalah kitab perjanjian itu, lalu dibacakannya dengan didengar oleh bangsa itu dan mereka berkata: "Segala firman TUHAN akan kami lakukan dan akan kami dengarkan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 8, 'Kemudian Musa mengambil darah itu dan menyiramkannya pada bangsa itu serta berkata: "Inilah darah perjanjian yang diadakan TUHAN dengan kamu, berdasarkan segala firman ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 9, 'Dan naiklah Musa dengan Harun, Nadab dan Abihu dan tujuh puluh orang dari para tua-tua Israel.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 10, 'Lalu mereka melihat Allah Israel; kaki-Nya berjejak pada sesuatu yang buatannya seperti lantai dari batu nilam dan yang terangnya seperti langit yang cerah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 11, 'Tetapi kepada pemuka-pemuka orang Israel itu tidaklah diulurkan-Nya tangan-Nya; mereka memandang Allah, lalu makan dan minum.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 12, 'TUHAN berfirman kepada Musa: "Naiklah menghadap Aku, ke atas gunung, dan tinggallah di sana, maka Aku akan memberikan kepadamu loh batu, yakni hukum dan perintah, yang telah Kutuliskan untuk diajarkan kepada mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 13, 'Lalu bangunlah Musa dengan Yosua, abdinya, maka naiklah Musa ke atas gunung Allah itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 14, 'Tetapi kepada para tua-tua itu ia berkata: "Tinggallah di sini menunggu kami, sampai kami kembali lagi kepadamu; bukankah Harun dan Hur ada bersama-sama dengan kamu, siapa yang ada perkaranya datanglah kepada mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 15, 'Maka Musa mendaki gunung dan awan itu menutupinya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 16, 'Kemuliaan TUHAN diam di atas gunung Sinai, dan awan itu menutupinya enam hari lamanya; pada hari ketujuh dipanggil-Nyalah Musa dari tengah-tengah awan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 17, 'Tampaknya kemuliaan TUHAN sebagai api yang menghanguskan di puncak gunung itu pada pemandangan orang Israel.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 24, 18, 'Masuklah Musa ke tengah-tengah awan itu dengan mendaki gunung itu. Lalu tinggallah ia di atas gunung itu empat puluh hari dan empat puluh malam lamanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 1, 'Berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 2, '"Katakanlah kepada orang Israel, supaya mereka memungut bagi-Ku persembahan khusus; dari setiap orang yang terdorong hatinya, haruslah kamu pungut persembahan khusus kepada-Ku itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 3, 'Inilah persembahan khusus yang harus kamu pungut dari mereka: emas, perak, tembaga;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 4, 'kain ungu tua, kain ungu muda, kain kirmizi, lenan halus, bulu kambing;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 5, 'kulit domba jantan yang diwarnai merah, kulit lumba-lumba dan kayu penaga;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 6, 'minyak untuk lampu, rempah-rempah untuk minyak urapan dan untuk ukupan dari wangi-wangian,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 7, 'permata krisopras dan permata tatahan untuk baju efod dan untuk tutup dada.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 8, 'Dan mereka harus membuat tempat kudus bagi-Ku, supaya Aku akan diam di tengah-tengah mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 9, 'Menurut segala apa yang Kutunjukkan kepadamu sebagai contoh Kemah Suci dan sebagai contoh segala perabotannya, demikianlah harus kamu membuatnya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 10, '"Haruslah mereka membuat tabut dari kayu penaga, dua setengah hasta panjangnya, satu setengah hasta lebarnya dan satu setengah hasta tingginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 11, 'Haruslah engkau menyalutnya dengan emas murni; dari dalam dan dari luar engkau harus menyalutnya dan di atasnya harus kaubuat bingkai emas sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 12, 'Haruslah engkau menuang empat gelang emas untuk tabut itu dan pasanglah gelang itu pada keempat penjurunya, yaitu dua gelang pada rusuknya yang satu dan dua gelang pada rusuknya yang kedua.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 13, 'Engkau harus membuat kayu pengusung dari kayu penaga dan menyalutnya dengan emas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 14, 'Haruslah engkau memasukkan kayu pengusung itu ke dalam gelang yang ada pada rusuk tabut itu, supaya dengan itu tabut dapat diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 15, 'Kayu pengusung itu haruslah tetap tinggal dalam gelang itu, tidak boleh dicabut dari dalamnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 16, 'Dalam tabut itu haruslah kautaruh loh hukum, yang akan Kuberikan kepadamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 17, 'Juga engkau harus membuat tutup pendamaian dari emas murni, dua setengah hasta panjangnya dan satu setengah hasta lebarnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 18, 'Dan haruslah kaubuat dua kerub dari emas, kaubuatlah itu dari emas tempaan, pada kedua ujung tutup pendamaian itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 19, 'Buatlah satu kerub pada ujung sebelah sini dan satu kerub pada ujung sebelah sana; seiras dengan tutup pendamaian itu kamu buatlah kerub itu di atas kedua ujungnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 20, 'Kerub-kerub itu harus mengembangkan kedua sayapnya ke atas, sedang sayap-sayapnya menudungi tutup pendamaian itu dan mukanya menghadap kepada masing-masing; kepada tutup pendamaian itulah harus menghadap muka kerub-kerub itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 21, 'Haruslah kauletakkan tutup pendamaian itu di atas tabut dan dalam tabut itu engkau harus menaruh loh hukum, yang akan Kuberikan kepadamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 22, 'Dan di sanalah Aku akan bertemu dengan engkau dan dari atas tutup pendamaian itu, dari antara kedua kerub yang di atas tabut hukum itu, Aku akan berbicara dengan engkau tentang segala sesuatu yang akan Kuperintahkan kepadamu untuk disampaikan kepada orang Israel."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 23, '"Lagi haruslah engkau membuat meja dari kayu penaga, dua hasta panjangnya, sehasta lebarnya dan satu setengah hasta tingginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 24, 'Haruslah engkau menyalutnya dengan emas murni dan membuat bingkai emas sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 25, 'Haruslah engkau membuat sekelilingnya jalur pinggir yang setapak tangan lebarnya dan kaubuatlah bingkai emas sekeliling jalur pinggirnya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 26, 'Haruslah engkau membuat untuk meja itu empat gelang emas dan kaupasanglah gelang-gelang itu di keempat penjurunya, pada keempat kakinya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 27, 'Gelang itu haruslah dekat ke jalur pinggirnya sebagai tempat memasukkan kayu pengusung, supaya meja itu dapat diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 28, 'Haruslah engkau membuat kayu pengusung itu dari kayu penaga dan menyalutnya dengan emas, dan dengan itulah meja harus diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 29, 'Haruslah engkau membuat pinggannya, cawannya, kendinya dan pialanya, yang dipakai untuk persembahan curahan; haruslah engkau membuat semuanya itu dari emas murni.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 30, 'Dan haruslah engkau tetap meletakkan roti sajian di atas meja itu di hadapan-Ku."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 31, '"Haruslah engkau membuat kandil dari emas murni; dari emas tempaan harus kandil itu dibuat, baik kakinya baik batangnya; kelopaknya?dengan tombolnya dan kembangnya?haruslah seiras dengan kandil itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 32, 'Enam cabang harus timbul dari sisinya: tiga cabang kandil itu dari sisi yang satu dan tiga cabang dari sisi yang lain.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 33, 'Tiga kelopak yang berupa bunga badam pada cabang yang satu?dengan tombol dan kembangnya?dan tiga kelopak yang serupa pada cabang yang lain?dengan tombol dan kembangnya?;demikianlah juga kaubuat keenam cabang yang timbul dari kandil itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 34, 'Pada kandil itu sendiri harus ada empat kelopak berupa bunga badam?dengan tombolnya dan kembangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 35, 'Juga harus ada satu tombol di bawah sepasang cabang yang pertama, yang timbul dari kandil itu, dan satu tombol di bawah yang kedua, dan satu tombol di bawah yang ketiga; demikianlah juga kaubuat keenam cabang yang timbul dari kandil itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 36, 'Tombol dan cabang itu harus timbul dari kandil itu, dan semuanya itu haruslah dibuat dari sepotong emas tempaan yang murni.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 37, 'Haruslah kaubuat pada kandil itu tujuh lampu dan lampu-lampu itu haruslah dipasang di atas kandil itu, sehingga diterangi yang di depannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 38, 'Sepitnya dan penadahnya haruslah dari emas murni.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 39, 'Dari satu talenta emas murni haruslah dibuat kandil itu dengan segala perkakasnya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 25, 40, 'Dan ingatlah, bahwa engkau membuat semuanya itu menurut contoh yang telah ditunjukkan kepadamu di atas gunung itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 1, '"Kemah Suci itu haruslah kaubuat dari sepuluh tenda dari lenan halus yang dipintal benangnya dan dari kain ungu tua, kain ungu muda dan kain kirmizi; dengan ada kerubnya, buatan ahli tenun, haruslah kaubuat semuanya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 2, 'Panjang tiap-tiap tenda haruslah dua puluh delapan hasta dan lebar tiap-tiap tenda empat hasta: segala tenda itu harus sama ukurannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 3, 'Lima dari tenda itu haruslah dirangkap menjadi satu, dan yang lima lagi juga harus dirangkap menjadi satu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 4, 'Pada rangkapan yang pertama, di tepi satu tenda yang di ujung, haruslah engkau membuat sosok-sosok kain ungu tua dan demikian juga di tepi satu tenda yang paling ujung pada rangkapan yang kedua.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 5, 'Lima puluh sosok harus kaubuat pada tenda yang satu dan lima puluh sosok pada tenda yang di ujung pada rangkapan yang kedua, sehingga sosok-sosok itu tepat berhadapan satu sama lain.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 6, 'Dan haruslah engkau membuat lima puluh kaitan emas dan menyambung tenda-tenda Kemah Suci yang satu dengan yang lain dengan memakai kaitan itu, sehingga menjadi satu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 7, 'Juga haruslah engkau membuat tenda-tenda dari bulu kambing menjadi atap kemah yang menudungi Kemah Suci, sebelas tenda harus kaubuat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 8, 'Panjang tiap-tiap tenda harus tiga puluh hasta dan lebar tiap-tiap tenda empat hasta: yang sebelas tenda itu harus sama ukurannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 9, 'Lima dari tenda itu haruslah kausambung dengan tersendiri, dan enam dari tenda itu dengan tersendiri, dan tenda yang keenam haruslah kaulipat dua, di sebelah depan kemah itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 10, 'Haruslah engkau membuat lima puluh sosok pada rangkapan yang pertama di tepi satu tenda yang di ujung dan lima puluh sosok di tepi satu tenda pada rangkapan yang kedua.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 11, 'Haruslah engkau membuat lima puluh kaitan tembaga dan memasukkan kaitan itu ke dalam sosok-sosok dan menyambung tenda-tenda kemah itu, supaya menjadi satu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 12, 'Mengenai bagian yang berjuntai itu, yang berlebih pada tenda kemah itu, haruslah setengah dari tenda yang berlebih itu berjuntai di sebelah belakang Kemah Suci.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 13, 'Sehasta di sebelah sini dan sehasta di sebelah sana pada bagian yang berlebih pada panjang tenda-tenda kemah itu haruslah berjuntai pada sisi-sisi Kemah Suci, di sebelah sini dan di sebelah sana untuk menudunginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 14, 'Juga haruslah engkau membuat untuk kemah itu tudung dari kulit domba jantan yang diwarnai merah, dan tudung dari kulit lumba-lumba di atasnya lagi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 15, 'Haruslah engkau membuat untuk Kemah Suci papan dari kayu penaga yang berdiri tegak,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 16, 'sepuluh hasta panjangnya satu papan dan satu setengah hasta lebarnya tiap-tiap papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 17, 'Tiap-tiap papan harus ada dua pasaknya yang disengkang satu sama lain; demikianlah harus kauperbuat dengan segala papan Kemah Suci.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 18, 'Haruslah engkau membuat papan-papan untuk Kemah Suci, dua puluh papan pada sebelah selatan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 19, 'Dan haruslah kaubuat empat puluh alas perak di bawah kedua puluh papan itu, dua alas di bawah satu papan untuk kedua pasaknya, dan seterusnya dua alas di bawah setiap papan untuk kedua pasaknya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 20, 'Juga untuk sisi yang kedua dari Kemah Suci, pada sebelah utara, kaubuatlah dua puluh papan', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 21, 'dengan empat puluh alas peraknya: dua alas di bawah satu papan dan seterusnya dua alas di bawah setiap papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 22, 'Untuk sisi belakang Kemah Suci, pada sebelah barat, haruslah kaubuat enam papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 23, 'Dua papan haruslah kaubuat untuk sudut Kemah Suci, di sisi belakang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 24, 'Kedua papan itu haruslah kembar pasaknya di sebelah bawah dan seperti itu juga kembar pasaknya di sebelah atas, di dekat gelang yang satu itu; demikianlah harus kedua papan itu; haruslah itu merupakan kedua sudutnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 25, 'Jadi harus ada delapan papan dengan alas peraknya: enam belas alas; dua alas di bawah satu papan dan seterusnya dua alas di bawah setiap papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 26, 'Juga haruslah kaubuat kayu lintang dari kayu penaga: lima untuk papan-papan pada sisi yang satu dari Kemah Suci,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 28, 'Dan kayu lintang yang di tengah, di tengah-tengah papan-papan itu, haruslah melintang terus dari ujung ke ujung.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 29, 'Papan-papan itu haruslah kausalut dengan emas, gelang-gelang itu haruslah kaubuat dari emas sebagai tempat memasukkan kayu-kayu lintang itu, dan kayu-kayu lintang itu haruslah kausalut dengan emas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 30, 'Kemudian haruslah kaudirikan Kemah Suci sesuai dengan rancangan yang telah ditunjukkan kepadamu di atas gunung itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 31, 'Haruslah kaubuat tabir dari kain ungu tua, dan kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya; haruslah dibuat dengan ada kerubnya, buatan ahli tenun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 32, 'Haruslah engkau menggantungkannya pada empat tiang dari kayu penaga, yang disalut dengan emas, dengan ada kaitannya dari emas, berdasarkan empat alas perak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 33, 'Haruslah tabir itu kaugantungkan pada kaitan penyambung tenda itu dan haruslah kaubawa tabut hukum ke sana, ke belakang tabir itu, sehingga tabir itu menjadi pemisah bagimu antara tempat kudus dan tempat maha kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 34, 'Tutup pendamaian itu haruslah kauletakkan di atas tabut hukum di dalam tempat maha kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 35, 'Meja itu haruslah kautaruh di depan tabir itu, dan kandil itu berhadapan dengan meja itu pada sisi selatan dari Kemah Suci, dan meja itu haruslah kautempatkan pada sisi utara.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 36, 'Juga haruslah kaubuat tirai untuk pintu kemah itu dari kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya: tenunan yang berwarna-warna.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 26, 37, 'Haruslah kaubuat lima tiang dari kayu penaga untuk tirai itu dan kausalutlah itu dengan emas, dengan ada kaitannya dari emas, dan untuk itu haruslah kautuang lima alas dari tembaga."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 1, '"Haruslah engkau membuat mezbah dari kayu penaga, lima hasta panjangnya dan lima hasta lebarnya, sehingga mezbah itu empat persegi, tetapi tiga hasta tingginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 2, 'Haruslah engkau membuat tanduk-tanduknya pada keempat sudutnya; tanduk-tanduknya itu haruslah seiras dengan mezbah itu dan haruslah engkau menyalutnya dengan tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 3, 'Juga harus engkau membuat kuali-kualinya tempat menaruh abunya, dan sodok-sodoknya dan bokor-bokor penyiramannya, garpu-garpunya dan perbaraan-perbaraannya; semua perkakasnya itu harus kaubuat dari tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 4, 'Haruslah engkau membuat untuk itu kisi-kisi, yakni jala-jala tembaga, dan pada jala-jala itu haruslah kaubuat empat gelang tembaga pada keempat ujungnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 5, 'Haruslah engkau memasang jala-jala itu di bawah jalur mezbah itu; mulai dari sebelah bawah, sehingga jala-jala itu sampai setengah tinggi mezbah itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 6, 'Haruslah engkau membuat kayu-kayu pengusung untuk mezbah itu, kayu-kayu pengusung dari kayu penaga dan menyalutnya dengan tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 7, 'Kayu-kayu pengusungnya itu haruslah dimasukkan ke dalam gelang-gelang itu dan kayu-kayu pengusung itu haruslah ada pada kedua rusuk mezbah itu waktu mezbah itu diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 8, 'Mezbah itu harus kaubuat berongga dan dari papan, seperti yang ditunjukkan kepadamu di atas gunung itu, demikianlah harus dibuat mezbah itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 9, '"Haruslah engkau membuat pelataran Kemah Suci; untuk pelataran itu pada sebelah selatan harus dibuat layar dari lenan halus yang dipintal benangnya, seratus hasta panjangnya pada sisi yang satu itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 10, 'Tiang-tiangnya harus ada dua puluh, dan alas-alas tiang itu harus dua puluh, dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya harus dari perak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 11, 'Demikian juga pada sebelah utara, pada panjangnya, harus ada layar yang seratus hasta panjangnya, tiang-tiangnya harus ada dua puluh dan alas-alas tiang itu harus dua puluh, dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya harus dari perak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 12, 'Dan pada lebar pelataran itu pada sebelah barat harus ada layar yang lima puluh hasta, dengan sepuluh tiangnya dan sepuluh alas tiang itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 13, 'Lebar pelataran itu, yaitu bagian muka pada sebelah timur harus lima puluh hasta,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 14, 'yakni lima belas hasta layar untuk sisi yang satu di samping pintu gerbang itu, dengan tiga tiangnya dan tiga alas tiang itu;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 15, 'dan juga untuk sisi yang kedua di samping pintu gerbang itu lima belas hasta layar, dengan tiga tiangnya dan tiga alas tiang itu;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 16, 'tetapi untuk pintu gerbang pelataran itu tirai dua puluh hasta dari kain ungu tua dan kain ungu muda, kain kirmizi dan dari lenan halus yang dipintal benangnya?tenunan yang berwarna-warna?dengan empat tiangnya dan empat alas tiang itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 17, 'Segala tiang yang mengelilingi pelataran itu haruslah dihubungkan dengan penyambung-penyambung perak, dan kaitan-kaitannya harus dari perak dan alas-alasnya dari tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 18, 'Panjang pelataran itu harus seratus hasta, lebarnya lima puluh hasta dan tingginya lima hasta, dari lenan halus yang dipintal benangnya, dan alas-alasnya harus dari tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 19, 'Adapun segala perabotan untuk seluruh perlengkapan Kemah Suci, dan juga segala patoknya dan segala patok pelataran: semuanya harus dari tembaga."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 20, '"Haruslah kauperintahkan kepada orang Israel, supaya mereka membawa kepadamu minyak zaitun tumbuk yang murni untuk lampu, supaya orang dapat memasang lampu agar tetap menyala.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 27, 21, 'Di dalam Kemah Pertemuan di depan tabir yang menutupi tabut hukum, haruslah Harun dan anak-anaknya mengaturnya dari petang sampai pagi di hadapan TUHAN. Itulah suatu ketetapan yang berlaku untuk selama-lamanya bagi orang Israel turun-temurun."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 1, '"Engkau harus menyuruh abangmu Harun bersama-sama dengan anak-anaknya datang kepadamu, dari tengah-tengah orang Israel, untuk memegang jabatan imam bagi-Ku?Harun dan anak-anak Harun, yakni Nadab, Abihu, Eleazar dan Itamar.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 2, 'Haruslah engkau membuat pakaian kudus bagi Harun, abangmu, sebagai perhiasan kemuliaan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 3, 'Haruslah engkau mengatakan kepada semua orang yang ahli, yang telah Kupenuhi dengan roh keahlian, membuat pakaian Harun, untuk menguduskan dia, supaya dipegangnya jabatan imam bagi-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 4, 'Inilah pakaian yang harus dibuat mereka: tutup dada, baju efod, gamis, kemeja yang ada raginya, serban dan ikat pinggang. Demikianlah mereka harus membuat pakaian kudus bagi Harun, abangmu, dan bagi anak-anaknya, supaya ia memegang jabatan imam bagi-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 5, 'Untuk itu haruslah mereka mengambil emas, kain ungu tua dan kain ungu muda, kain kirmizi dan lenan halus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 6, 'Baju efod itu harus dibuat mereka dari emas, kain ungu tua dan kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya: buatan seorang ahli.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 7, 'Haruslah ada pada baju efod itu dua tutup bahu yang disambung kepadanya, pada kedua ujungnyalah harus baju efod itu disambung.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 8, 'Sabuk pengikat yang ada pada baju efod itu haruslah sama buatannya dan seiras dengan baju efod itu, yakni dari emas, kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 9, 'Haruslah kauambil dua permata krisopras dan mengukirkan nama para anak Israel pada permata itu,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 10, 'enam dari nama mereka itu pada permata yang pertama dan keenam nama lagi pada permata yang kedua, menurut urutan kelahirannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 11, 'Seperti buatan seorang pengasah permata, diukirkan seperti meterai, demikianlah harus kauukirkan pada kedua permata itu nama para anak Israel; dililit dengan ikat emas harus kaubuat permata itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 12, 'Kemudian haruslah kautaruh kedua permata itu pada kedua tutup bahu baju efod sebagai permata peringatan untuk mengingat orang Israel; maka ke hadapan TUHAN haruslah Harun membawa nama mereka di atas kedua tutup bahunya menjadi tanda peringatan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 13, 'Haruslah kaubuat ikat emas', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 14, 'dan dua untai dari emas murni; sebagai utas haruslah kaubuat itu, yang buatannya sebagai tali berjalin dan haruslah kaupasang untai berjalin itu pada ikat itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 15, 'Haruslah engkau membuat tutup dada pernyataan keputusan: buatan seorang ahli. Buatannya sama dengan baju efod, demikianlah harus engkau membuatnya, yakni dari emas, kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya haruslah engkau membuatnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 16, 'Haruslah itu empat persegi, lipat dua, sejengkal panjangnya dan sejengkal lebarnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 17, 'Haruslah kautatah itu dengan permata tatahan, empat jajar permata: permata yaspis merah, krisolit, malakit, itulah jajar yang pertama;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 18, 'jajar yang kedua: permata batu darah, lazurit, yaspis hijau;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 19, 'jajar yang ketiga: permata ambar, akik, kecubung,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 20, 'jajar yang keempat: permata pirus, krisopras dan nefrit. Dengan berikatkan emas, demikianlah permata-permata itu dalam tatahannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 21, 'Sesuai dengan nama para anak Israel, permata itu haruslah dua belas banyaknya; dan pada tiap-tiap permata haruslah ada, diukirkan seperti meterai, nama salah satu suku dari yang dua belas itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 22, 'Juga haruslah kaubuat untuk tutup dada itu untai berpilin, yang buatannya sebagai tali berjalin, dari emas murni.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 23, 'Juga haruslah kaubuat untuk tutup dada itu dua gelang emas dan kedua gelang itu harus kaupasang pada kedua ujung tutup dada.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 24, 'Haruslah kedua untai emas yang berjalin itu kaupasang pada kedua gelang itu, pada ujung tutup dada.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 25, 'Kedua ujung lain dari kedua untai berjalin itu haruslah kaupasang pada kedua ikat emas itu, demikianlah kaupasang pada tutup bahu baju efod, di sebelah depannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 26, 'Haruslah engkau membuat dua gelang emas dan membubuhnya pada kedua ujung tutup dada itu, pada pinggirnya yang sebelah dalam, yang berhadapan dengan baju efod.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 27, 'Juga haruslah engkau membuat dua gelang emas dan memasangnya pada kedua tutup bahu baju efod, di sebelah bawah pada bagian depan, dekat ke tempat persambungannya, di sebelah atas sabuk baju efod.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 28, 'Kemudian haruslah tutup dada itu dengan gelangnya diikatkan kepada gelang baju efod dengan memakai tali ungu tua, sehingga tetap di atas sabuk baju efod, dan tutup dada itu tidak dapat bergeser dari baju efod.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 29, 'Demikianlah di atas jantungnya harus dibawa Harun nama para anak Israel pada tutup dada pernyataan keputusan itu, apabila ia masuk ke dalam tempat kudus, supaya menjadi tanda peringatan yang tetap di hadapan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 30, 'Dan di dalam tutup dada pernyataan keputusan itu haruslah kautaruh Urim dan Tumim; haruslah itu di atas jantung Harun, apabila ia masuk menghadap TUHAN, dan Harun harus tetap membawa keputusan bagi orang Israel di atas jantungnya, di hadapan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 31, 'Haruslah kaubuat gamis baju efod dari kain ungu tua seluruhnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 32, 'Lehernya haruslah di tengah-tengahnya; lehernya itu harus mempunyai pinggir sekelilingnya, buatan tukang tenun, seperti leher baju zirah haruslah lehernya itu, supaya jangan koyak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 33, 'Pada ujung gamis itu haruslah kaubuat buah delima dari kain ungu tua, kain ungu muda dan kain kirmizi, pada sekeliling ujung gamis itu, dan di antaranya berselang-seling giring-giring emas,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 34, 'sehingga satu giring-giring emas dan satu buah delima selalu berselang-seling, pada ujung gamis itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 35, 'Haruslah gamis itu dipakai Harun, apabila ia menyelenggarakan kebaktian, dan bunyinya harus kedengaran, apabila ia masuk ke dalam tempat kudus di hadapan TUHAN dan apabila ia keluar pula, supaya ia jangan mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 36, 'Juga haruslah engkau membuat patam dari emas murni dan pada patam itu kauukirkanlah, diukirkan seperti meterai: Kudus bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 37, 'Haruslah patam itu engkau beri bertali ungu tua, dan haruslah itu dilekatkan pada serban, di sebelah depan serban itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 38, 'Patam itu haruslah ada pada dahi Harun, dan Harun harus menanggung akibat kesalahan terhadap segala yang dikuduskan oleh orang Israel, yakni terhadap segala persembahan kudusnya; maka haruslah patam itu tetap ada pada dahinya, sehingga TUHAN berkenan akan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 39, 'Haruslah engkau menenun kemeja dengan ada raginya, dari lenan halus, dan membuat serban dari lenan halus dan haruslah kaubuat ikat pinggang dari tenunan yang berwarna-warna.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 40, 'Juga bagi anak-anak Harun haruslah kaubuat kemeja-kemeja dan haruslah kaubuat ikat-ikat pinggang bagi mereka, dan destar-destar haruslah kaubuat bagi mereka untuk menjadi perhiasan kemuliaan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 41, 'Maka semuanya itu haruslah kaukenakan kepada abangmu Harun bersama-sama dengan anak-anaknya, kemudian engkau harus mengurapi, mentahbiskan dan menguduskan mereka, sehingga mereka dapat memegang jabatan imam bagi-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 42, 'Buatlah celana-celana lenan bagi mereka untuk menutupi daging auratnya: celana itu haruslah dari pinggang sampai paha panjangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 28, 43, 'Harun dan anak-anaknya haruslah memakainya, apabila mereka masuk ke dalam Kemah Pertemuan atau apabila mereka datang ke mezbah untuk menyelenggarakan kebaktian di tempat kudus, supaya mereka jangan membawa kesalahan kepada dirinya, lalu mati. Itulah suatu ketetapan untuk selama-lamanya baginya dan bagi keturunannya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 1, '"Inilah yang harus kaulakukan kepada mereka, untuk menguduskan mereka, supaya mereka memegang jabatan imam bagi-Ku: Ambillah seekor lembu jantan muda dan dua ekor domba jantan yang tidak bercela,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 2, 'roti yang tidak beragi dan roti bundar yang tidak beragi, yang diolah dengan minyak, dan roti tipis yang tidak beragi, yang diolesi dengan minyak; dari tepung gandum yang terbaik haruslah kaubuat semuanya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 3, 'Kautaruhlah semuanya dalam sebuah bakul dan kaupersembahkanlah semuanya dalam bakul itu, demikian juga lembu jantan dan kedua domba jantan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 4, 'Lalu kausuruhlah Harun dan anak-anaknya datang ke pintu Kemah Pertemuan dan haruslah engkau membasuh mereka dengan air.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 5, 'Kemudian kauambillah pakaian itu, lalu kaukenakanlah kepada Harun kemeja, gamis baju efod, dan baju efod serta tutup dada; kaukebatkanlah sabuk baju efod kepadanya;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 6, 'kautaruhlah serban di kepalanya dan jamang yang kudus kaububuh pada serban itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 7, 'Sesudah itu kauambillah minyak urapan dan kautuang ke atas kepalanya, dan kauurapilah dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 8, 'Kausuruhlah anak-anaknya mendekat dan kaukenakanlah kemeja-kemeja itu kepada mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 9, 'Kauikatkanlah ikat pinggang kepada mereka, kepada Harun dan anak-anaknya, dan kaulilitkanlah destar itu kepada kepala mereka, maka merekalah yang akan memegang jabatan imam; itulah suatu ketetapan untuk selama-lamanya. Demikianlah engkau harus mentahbiskan Harun dan anak-anaknya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 10, 'Kemudian haruslah kaubawa lembu jantan itu ke depan Kemah Pertemuan, lalu haruslah Harun dan anak-anaknya meletakkan tangannya ke atas kepala lembu jantan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 11, 'Haruslah kausembelih lembu jantan itu di hadapan TUHAN di depan pintu Kemah Pertemuan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 12, 'Haruslah kauambil sedikit dari darah lembu jantan itu dan kaububuh dengan jarimu pada tanduk-tanduk mezbah, dan segala darah selebihnya haruslah kaucurahkan pada bagian bawah mezbah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 13, 'Kemudian kauambillah segala lemak yang menutupi isi perut, umbai hati, kedua buah pinggang dan segala lemak yang melekat padanya, dan kaubakarlah di atas mezbah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 14, 'Tetapi daging lembu jantan itu, kulitnya dan kotorannya haruslah kaubakar habis dengan api di luar perkemahan, itulah korban penghapus dosa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 15, 'Kemudian haruslah kauambil domba jantan yang satu, lalu haruslah Harun dan anak-anaknya meletakkan tangannya ke atas kepala domba jantan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 16, 'Haruslah kausembelih domba jantan itu dan kauambillah darahnya dan kausiramkan pada mezbah sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 17, 'Haruslah kaupotong-potong domba jantan itu menurut bagian-bagian tertentu, kaubasuhlah isi perutnya dan betis-betisnya dan kautaruh itu di atas potongan-potongannya dan di atas kepalanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 18, 'Kemudian haruslah kaubakar seluruh domba jantan itu di atas mezbah; itulah korban bakaran, suatu persembahan yang harum bagi TUHAN, yakni suatu korban api-apian bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 19, 'Kemudian haruslah kauambil domba jantan yang lain, lalu haruslah Harun dan anak-anaknya meletakkan tangannya ke atas kepala domba jantan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 20, 'Haruslah kausembelih domba jantan itu, kauambillah sedikit dari darahnya dan kaububuh pada cuping telinga kanan Harun dan pada cuping telinga kanan anak-anaknya, pada ibu jari tangan kanan dan pada ibu jari kaki kanan mereka, dan darah selebihnya kausiramkanlah pada mezbah sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 21, 'Haruslah kauambil sedikit dari darah yang ada di atas mezbah dan dari minyak urapan itu dan kaupercikkanlah kepada Harun dan kepada pakaiannya, dan juga kepada anak-anaknya dan pada pakaian anak-anaknya; maka ia akan kudus, ia dan pakaiannya, dan juga anak-anaknya dan pakaian anak-anaknya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 22, 'Dari domba jantan itu haruslah kauambil lemaknya, ekornya yang berlemak, lemak yang menutupi isi perutnya, umbai hatinya, kedua buah pinggangnya, lemak yang melekat padanya, paha kanannya?sebab itulah domba jantan persembahan pentahbisan?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 23, 'kauambillah juga satu keping roti, satu roti bundar yang berminyak dan satu roti tipis dari dalam bakul berisi roti yang tidak beragi, yang ada di hadapan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 24, 'Haruslah kautaruh seluruhnya ke atas telapak tangan Harun dan ke atas telapak tangan anak-anaknya dan haruslah kaupersembahkan semuanya sebagai persembahan unjukan di hadapan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 25, 'Kemudian haruslah kauambil semuanya dari tangan mereka dan kaubakar di atas mezbah, yaitu di atas korban bakaran, sebagai persembahan yang harum di hadapan TUHAN; itulah suatu korban api-apian bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 26, 'Selanjutnya haruslah kauambil dada dari domba jantan yang adalah bagi pentahbisan Harun dan kaupersembahkan sebagai persembahan unjukan di hadapan TUHAN, dan itulah bagian untukmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 27, 'Demikianlah harus kaukuduskan dada persembahan unjukan dan paha persembahan khusus yang dipersembahkan dari domba jantan yang adalah bagi pentahbisan Harun dan anak-anaknya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 28, 'Itulah yang menjadi bagian untuk Harun dan anak-anaknya menurut ketetapan yang berlaku untuk selama-lamanya bagi orang Israel, sebab inilah suatu persembahan khusus, maka haruslah itu menjadi persembahan khusus dari pihak orang Israel, yang diambil dari korban keselamatan mereka, dan menjadi persembahan khusus mereka bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 29, 'Pakaian kudus kepunyaan Harun itu haruslah turun kepada anak-anaknya yang kemudian, supaya mereka memakainya apabila mereka diurapi dan ditahbiskan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 30, 'Tujuh hari lamanya haruslah pakaian itu dikenakan oleh imam penggantinya dari antara anak-anaknya, yang akan masuk ke dalam Kemah Pertemuan untuk menyelenggarakan kebaktian di tempat kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 31, 'Domba jantan persembahan pentahbisan itu haruslah kauambil dan dagingnya kaumasak pada suatu tempat yang kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 32, 'Haruslah Harun dan anak-anaknya memakan daging domba jantan itu serta roti yang ada di dalam bakul di depan pintu Kemah Pertemuan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 33, 'Haruslah mereka memakan semuanya itu yang dipakai untuk mengadakan pendamaian pada waktu mereka ditahbiskan dan dikuduskan, tetapi orang awam janganlah memakannya, sebab persembahan kudus semuanya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 34, 'Jika ada yang tinggal dari daging persembahan pentahbisan dan dari roti itu sampai pagi, haruslah kaubakar habis yang tinggal itu dengan api, janganlah dimakan, sebab persembahan kudus semuanya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 35, 'Maka haruslah kauperbuat demikian kepada Harun dan kepada anak-anaknya, tepat seperti yang Kuperintahkan kepadamu; selama tujuh hari haruslah kautahbiskan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 36, 'Tiap-tiap hari haruslah engkau mengolah seekor lembu jantan menjadi korban penghapus dosa untuk mengadakan pendamaian dan haruslah kausucikan mezbah itu, dengan mengadakan pendamaian baginya; haruslah engkau mengurapinya untuk menguduskannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 37, 'Tujuh hari lamanya haruslah engkau mengadakan pendamaian bagi mezbah itu; haruslah engkau menguduskannya, maka mezbah itu akan menjadi maha kudus; setiap orang yang kena kepada mezbah itu akan menjadi kudus."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 38, '"Inilah yang harus kauolah di atas mezbah itu: dua anak domba berumur setahun, tetap tiap-tiap hari.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 39, 'Domba yang satu haruslah kauolah pada waktu pagi dan domba yang lain kauolah pada waktu senja.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 40, 'Dan beserta domba yang satu kauolah sepersepuluh efa tepung yang terbaik dengan minyak tumbuk seperempat hin, dan korban curahan dari seperempat hin anggur.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 41, 'Domba yang lain haruslah kauolah pada waktu senja; sama seperti korban sajian dan korban curahannya pada waktu pagi harus engkau mengolahnya sebagai persembahan yang harum, suatu korban api-apian bagi TUHAN,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 42, 'suatu korban bakaran yang tetap di antara kamu turun-temurun, di depan pintu Kemah Pertemuan di hadapan TUHAN. Sebab di sana Aku akan bertemu dengan kamu, untuk berfirman kepadamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 43, 'Di sanalah Aku akan bertemu dengan orang Israel, dan tempat itu akan dikuduskan oleh kemuliaan-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 44, 'Aku akan menguduskan Kemah Pertemuan dan mezbah itu, lalu Harun dan anak-anaknya akan Kukuduskan supaya mereka memegang jabatan imam bagi-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 45, 'Aku akan diam di tengah-tengah orang Israel dan Aku akan menjadi Allah mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 29, 46, 'Maka mereka akan mengetahui, bahwa Akulah, TUHAN, Allah mereka, yang telah membawa mereka keluar dari tanah Mesir, supaya Aku diam di tengah-tengah mereka; Akulah TUHAN, Allah mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 1, '"Haruslah kaubuat mezbah, tempat pembakaran ukupan; haruslah kaubuat itu dari kayu penaga;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 2, 'sehasta panjangnya dan sehasta lebarnya, sehingga menjadi empat persegi, tetapi haruslah dua hasta tingginya; tanduk-tanduknya haruslah seiras dengan mezbah itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 3, 'Haruslah kausalut itu dengan emas murni, bidang atasnya dan bidang-bidang sisinya sekelilingnya, serta tanduk-tanduknya. Haruslah kaubuat bingkai emas sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 4, 'Haruslah kaubuat dua gelang emas untuk mezbah itu di bawah bingkainya; pada kedua rusuknya haruslah kaubuat gelang itu, pada kedua bidang sisinya, dan haruslah gelang itu menjadi tempat memasukkan kayu pengusung, supaya dengan itu mezbah dapat diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 5, 'Haruslah kaubuat kayu pengusung itu dari kayu penaga dan kausalutlah dengan emas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 6, 'Haruslah kautaruh tempat pembakaran itu di depan tabir penutup tabut hukum, di depan tutup pendamaian yang di atas loh hukum, di mana Aku akan bertemu dengan engkau.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 7, 'Di atasnya haruslah Harun membakar ukupan dari wangi-wangian; tiap-tiap pagi, apabila ia membersihkan lampu-lampu, haruslah ia membakarnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 8, 'Juga apabila Harun memasang lampu-lampu itu pada waktu senja, haruslah ia membakarnya sebagai ukupan yang tetap di hadapan TUHAN di antara kamu turun-temurun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 9, 'Di atas mezbah itu janganlah kamu persembahkan ukupan yang lain ataupun korban bakaran ataupun korban sajian, juga korban curahan janganlah kamu curahkan di atasnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 10, 'Sekali setahun haruslah Harun mengadakan pendamaian di atas tanduk-tanduknya; dengan darah korban penghapus dosa pembawa pendamaian haruslah ia sekali setahun mengadakan pendamaian bagi mezbah itu di antara kamu turun-temurun; itulah barang maha kudus bagi TUHAN."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 11, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 12, '"Apabila engkau menghitung jumlah orang Israel pada waktu mereka didaftarkan, maka haruslah mereka masing-masing mempersembahkan kepada TUHAN uang pendamaian karena nyawanya, pada waktu orang mendaftarkan mereka, supaya jangan ada tulah di antara mereka pada waktu pendaftarannya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 13, 'Inilah yang harus dipersembahkan tiap-tiap orang yang akan termasuk orang-orang yang terdaftar itu: setengah syikal, ditimbang menurut syikal kudus?syikal ini dua puluh gera beratnya?;setengah syikal itulah persembahan khusus kepada TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 14, 'Setiap orang yang akan termasuk orang-orang yang terdaftar itu, yang berumur dua puluh tahun ke atas, haruslah mempersembahkan persembahan khusus itu kepada TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 15, 'Orang kaya janganlah mempersembahkan lebih dan orang miskin janganlah mempersembahkan kurang dari setengah syikal itu pada waktu dipersembahkan persembahan khusus itu kepada TUHAN untuk mengadakan pendamaian bagi nyawa kamu sekalian.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 16, 'Dan haruslah engkau memungut uang pendamaian itu dari orang Israel dan menggunakannya untuk ibadah dalam Kemah Pertemuan; supaya itu menjadi peringatan di hadapan TUHAN untuk mengingat kepada orang Israel dan untuk mengadakan pendamaian bagi nyawa kamu sekalian."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 17, 'Berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 18, '"Haruslah engkau membuat bejana dan juga alasnya dari tembaga, untuk pembasuhan, dan kautempatkanlah itu antara Kemah Pertemuan dan mezbah, dan kautaruhlah air ke dalamnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 19, 'Maka Harun dan anak-anaknya haruslah membasuh tangan dan kaki mereka dengan air dari dalamnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 20, 'Apabila mereka masuk ke dalam Kemah Pertemuan, haruslah mereka membasuh tangan dan kaki dengan air, supaya mereka jangan mati. Demikian juga apabila mereka datang ke mezbah itu untuk menyelenggarakan kebaktian dan untuk membakar korban api-apian bagi TUHAN,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 21, 'haruslah mereka membasuh tangan dan kaki mereka, supaya mereka jangan mati. Itulah yang harus menjadi ketetapan bagi mereka untuk selama-lamanya, bagi dia dan bagi keturunannya turun-temurun."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 22, 'Berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 23, '"Ambillah rempah-rempah pilihan, mur tetesan lima ratus syikal, dan kayu manis yang harum setengah dari itu, yakni dua ratus lima puluh syikal, dan tebu yang baik dua ratus lima puluh syikal,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 24, 'dan kayu teja lima ratus syikal, ditimbang menurut syikal kudus, dan minyak zaitun satu hin.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 25, 'Haruslah kaubuat semuanya itu menjadi minyak urapan yang kudus, suatu campuran rempah-rempah yang dicampur dengan cermat seperti buatan seorang tukang campur rempah-rempah; itulah yang harus menjadi minyak urapan yang kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 26, 'Haruslah engkau mengurapi dengan itu Kemah Pertemuan dan tabut hukum,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 27, 'meja dengan segala perkakasnya, kandil dengan perkakasnya, dan mezbah pembakaran ukupan;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 28, 'mezbah korban bakaran dengan segala perkakasnya, bejana pembasuhan dengan alasnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 29, 'Haruslah kaukuduskan semuanya, sehingga menjadi maha kudus; setiap orang yang kena kepadanya akan menjadi kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 30, 'Engkau harus juga mengurapi dan menguduskan Harun dan anak-anaknya supaya mereka memegang jabatan imam bagi-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 31, 'Dan kepada orang Israel haruslah kaukatakan demikian: Inilah yang harus menjadi minyak urapan yang kudus bagi-Ku di antara kamu turun-temurun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 32, 'Kepada badan orang biasa janganlah minyak itu dicurahkan, dan janganlah kaubuat minyak yang semacam itu dengan memakai campuran itu juga: itulah minyak yang kudus, dan haruslah itu kudus bagimu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 33, 'Orang yang mencampur rempah-rempah menjadi minyak yang semacam itu atau yang membubuhnya pada badan orang awam, haruslah dilenyapkan dari antara bangsanya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 34, 'Berfirmanlah TUHAN kepada Musa: "Ambillah wangi-wangian, yakni getah damar, kulit lokan dan getah rasamala, wangi-wangian itu serta kemenyan yang tulen, masing-masing sama banyaknya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 35, 'Semuanya ini haruslah kaubuat menjadi ukupan, suatu campuran rempah-rempah, seperti buatan seorang tukang campur rempah-rempah, digarami, murni, kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 36, 'Sebagian dari ukupan itu haruslah kaugiling sampai halus, dan sedikit dari padanya kauletakkanlah di hadapan tabut hukum di dalam Kemah Pertemuan, di mana Aku akan bertemu dengan engkau; haruslah itu maha kudus bagimu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 37, 'Dan tentang ukupan yang harus kaubuat menurut campuran yang seperti itu juga janganlah kamu buat bagi kamu sendiri; itulah bagian untuk TUHAN, yang kudus bagimu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 30, 38, 'Orang yang akan membuat minyak yang semacam itu dengan maksud untuk menghirup baunya, haruslah dilenyapkan dari antara bangsanya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 1, 'Berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 2, '"Lihat, telah Kutunjuk Bezaleel bin Uri bin Hur, dari suku Yehuda,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 3, 'dan telah Kupenuhi dia dengan Roh Allah, dengan keahlian dan pengertian dan pengetahuan, dalam segala macam pekerjaan,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 4, 'untuk membuat berbagai rancangan supaya dikerjakan dari emas, perak dan tembaga;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 5, 'untuk mengasah batu permata supaya ditatah; untuk mengukir kayu dan untuk bekerja dalam segala macam pekerjaan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 6, 'Juga Aku telah menetapkan di sampingnya Aholiab bin Ahisamakh, dari suku Dan; dalam hati setiap orang ahli telah Kuberikan keahlian. Haruslah mereka membuat segala apa yang telah Kuperintahkan kepadamu:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 7, 'Kemah Pertemuan, tabut untuk hukum, tutup pendamaian yang terletak di atasnya, dan segala perabotan kemah itu,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 8, 'yakni meja dengan perkakasnya, kandil dari emas murni dengan segala perkakasnya, mezbah pembakaran ukupan,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 9, 'mezbah korban bakaran dengan segala perkakasnya, bejana pembasuhan dengan alasnya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 10, 'pakaian jabatan, baik pakaian kudus kepunyaan imam Harun, maupun pakaian anak-anaknya, untuk memegang jabatan imam,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 11, 'minyak urapan dan ukupan dari wangi-wangian untuk tempat kudus; tepat seperti yang telah Kuperintahkan kepadamu haruslah mereka membuat semuanya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 12, 'Berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 13, '"Katakanlah kepada orang Israel, demikian: Akan tetapi hari-hari Sabat-Ku harus kamu pelihara, sebab itulah peringatan antara Aku dan kamu, turun-temurun, sehingga kamu mengetahui, bahwa Akulah TUHAN, yang menguduskan kamu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 14, 'Haruslah kamu pelihara hari Sabat, sebab itulah hari kudus bagimu; siapa yang melanggar kekudusan hari Sabat itu, pastilah ia dihukum mati, sebab setiap orang yang melakukan pekerjaan pada hari itu, orang itu harus dilenyapkan dari antara bangsanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 15, 'Enam hari lamanya boleh dilakukan pekerjaan, tetapi pada hari yang ketujuh haruslah ada sabat, hari perhentian penuh, hari kudus bagi TUHAN: setiap orang yang melakukan pekerjaan pada hari Sabat, pastilah ia dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 16, 'Maka haruslah orang Israel memelihara hari Sabat, dengan merayakan sabat, turun-temurun, menjadi perjanjian kekal.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 17, 'Antara Aku dan orang Israel maka inilah suatu peringatan untuk selama-lamanya, sebab enam hari lamanya TUHAN menjadikan langit dan bumi, dan pada hari yang ketujuh Ia berhenti bekerja untuk beristirahat."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 31, 18, 'Dan TUHAN memberikan kepada Musa, setelah Ia selesai berbicara dengan dia di gunung Sinai, kedua loh hukum Allah, loh batu, yang ditulisi oleh jari Allah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 1, 'Ketika bangsa itu melihat, bahwa Musa mengundur-undurkan turun dari gunung itu, maka berkumpullah mereka mengerumuni Harun dan berkata kepadanya: "Mari, buatlah untuk kami allah, yang akan berjalan di depan kami sebab Musa ini, orang yang telah memimpin kami keluar dari tanah Mesir?kami tidak tahu apa yang telah terjadi dengan dia."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 2, 'Lalu berkatalah Harun kepada mereka: "Tanggalkanlah anting-anting emas yang ada pada telinga isterimu, anakmu laki-laki dan perempuan, dan bawalah semuanya kepadaku."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 3, 'Lalu seluruh bangsa itu menanggalkan anting-anting emas yang ada pada telinga mereka dan membawanya kepada Harun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 4, 'Diterimanyalah itu dari tangan mereka, dibentuknya dengan pahat, dan dibuatnyalah dari padanya anak lembu tuangan. Kemudian berkatalah mereka: "Hai Israel, inilah Allahmu, yang telah menuntun engkau keluar dari tanah Mesir!"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 5, 'Ketika Harun melihat itu, didirikannyalah mezbah di depan anak lembu itu. Berserulah Harun, katanya: "Besok hari raya bagi TUHAN!"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 6, 'Dan keesokan harinya pagi-pagi maka mereka mempersembahkan korban bakaran dan korban keselamatan, sesudah itu duduklah bangsa itu untuk makan dan minum; kemudian bangunlah mereka dan bersukaria.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 7, 'Berfirmanlah TUHAN kepada Musa: "Pergilah, turunlah, sebab bangsamu yang kaupimpin keluar dari tanah Mesir telah rusak lakunya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 8, 'Segera juga mereka menyimpang dari jalan yang Kuperintahkan kepada mereka; mereka telah membuat anak lembu tuangan, dan kepadanya mereka sujud menyembah dan mempersembahkan korban, sambil berkata: Hai Israel, inilah Allahmu yang telah menuntun engkau keluar dari tanah Mesir."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 9, 'Lagi firman TUHAN kepada Musa: "Telah Kulihat bangsa ini dan sesungguhnya mereka adalah suatu bangsa yang tegar tengkuk.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 10, 'Oleh sebab itu biarkanlah Aku, supaya murka-Ku bangkit terhadap mereka dan Aku akan membinasakan mereka, tetapi engkau akan Kubuat menjadi bangsa yang besar."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 11, 'Lalu Musa mencoba melunakkan hati TUHAN, Allahnya, dengan berkata: "Mengapakah, TUHAN, murka-Mu bangkit terhadap umat-Mu, yang telah Kaubawa keluar dari tanah Mesir dengan kekuatan yang besar dan dengan tangan yang kuat?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 12, 'Mengapakah orang Mesir akan berkata: Dia membawa mereka keluar dengan maksud menimpakan malapetaka kepada mereka dan membunuh mereka di gunung dan membinasakannya dari muka bumi? Berbaliklah dari murka-Mu yang bernyala-nyala itu dan menyesallah karena malapetaka yang hendak Kaudatangkan kepada umat-Mu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 13, 'Ingatlah kepada Abraham, Ishak dan Israel, hamba-hamba-Mu itu, sebab kepada mereka Engkau telah bersumpah demi diri-Mu sendiri dengan berfirman kepada mereka: Aku akan membuat keturunanmu sebanyak bintang di langit, dan seluruh negeri yang telah Kujanjikan ini akan Kuberikan kepada keturunanmu, supaya dimilikinya untuk selama-lamanya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 14, 'Dan menyesallah TUHAN karena malapetaka yang dirancangkan-Nya atas umat-Nya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 15, 'Setelah itu berpalinglah Musa, lalu turun dari gunung dengan kedua loh hukum Allah dalam tangannya, loh-loh yang bertulis pada kedua sisinya; bertulis sebelah-menyebelah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 16, 'Kedua loh itu ialah pekerjaan Allah dan tulisan itu ialah tulisan Allah, ditukik pada loh-loh itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 17, 'Ketika Yosua mendengar suara bangsa itu bersorak, berkatalah ia kepada Musa: "Ada bunyi sorak peperangan kedengaran di perkemahan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 18, 'Tetapi jawab Musa: "Bukan bunyi nyanyian kemenangan, bukan bunyi nyanyian kekalahan?bunyi orang menyanyi berbalas-balasan, itulah yang kudengar."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 19, 'Dan ketika ia dekat ke perkemahan itu dan melihat anak lembu dan melihat orang menari-nari, maka bangkitlah amarah Musa; dilemparkannyalah kedua loh itu dari tangannya dan dipecahkannya pada kaki gunung itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 20, 'Sesudah itu diambilnyalah anak lembu yang dibuat mereka itu, dibakarnya dengan api dan digilingnya sampai halus, kemudian ditaburkannya ke atas air dan disuruhnya diminum oleh orang Israel.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 21, 'Lalu berkatalah Musa kepada Harun: "Apakah yang dilakukan bangsa ini kepadamu, sehingga engkau mendatangkan dosa yang sebesar itu kepada mereka?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 22, 'Tetapi jawab Harun: "Janganlah bangkit amarah tuanku; engkau sendiri tahu, bahwa bangsa ini jahat semata-mata.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 23, 'Mereka berkata kepadaku: Buatlah untuk kami allah, yang akan berjalan di depan kami sebab Musa ini, orang yang telah memimpin kami keluar dari tanah Mesir?kami tidak tahu apa yang telah terjadi dengan dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 24, 'Lalu aku berkata kepada mereka: Siapa yang empunya emas haruslah menanggalkannya. Mereka memberikannya kepadaku dan aku melemparkannya ke dalam api, dan keluarlah anak lembu ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 25, 'Ketika Musa melihat, bahwa bangsa itu seperti kuda terlepas dari kandang?sebab Harun telah melepaskannya, sampai menjadi buah cemooh bagi lawan mereka?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 26, 'maka berdirilah Musa di pintu gerbang perkemahan itu serta berkata: "Siapa yang memihak kepada TUHAN datanglah kepadaku!" Lalu berkumpullah kepadanya seluruh bani Lewi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 27, 'Berkatalah ia kepada mereka: "Beginilah firman TUHAN, Allah Israel: Baiklah kamu masing-masing mengikatkan pedangnya pada pinggangnya dan berjalanlah kian ke mari melalui perkemahan itu dari pintu gerbang ke pintu gerbang, dan biarlah masing-masing membunuh saudaranya dan temannya dan tetangganya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 28, 'Bani Lewi melakukan seperti yang dikatakan Musa dan pada hari itu tewaslah kira-kira tiga ribu orang dari bangsa itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 29, 'Kemudian berkatalah Musa: "Baktikanlah dirimu mulai hari ini kepada TUHAN, masing-masing dengan membayarkan jiwa anaknya laki-laki dan saudaranya?yakni supaya kamu diberi berkat pada hari ini."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 30, 'Keesokan harinya berkatalah Musa kepada bangsa itu: "Kamu ini telah berbuat dosa besar, tetapi sekarang aku akan naik menghadap TUHAN, mungkin aku akan dapat mengadakan pendamaian karena dosamu itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 31, 'Lalu kembalilah Musa menghadap TUHAN dan berkata: "Ah, bangsa ini telah berbuat dosa besar, sebab mereka telah membuat allah emas bagi mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 32, 'Tetapi sekarang, kiranya Engkau mengampuni dosa mereka itu?dan jika tidak, hapuskanlah kiranya namaku dari dalam kitab yang telah Kautulis."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 33, 'Tetapi TUHAN berfirman kepada Musa: "Siapa yang berdosa kepada-Ku, nama orang itulah yang akan Kuhapuskan dari dalam kitab-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 34, 'Tetapi pergilah sekarang, tuntunlah bangsa itu ke tempat yang telah Kusebutkan kepadamu; akan berjalan malaikat-Ku di depanmu, tetapi pada hari pembalasan-Ku itu Aku akan membalaskan dosa mereka kepada mereka."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 32, 35, 'Demikianlah TUHAN menulahi bangsa itu, karena mereka telah menyuruh membuat anak lembu buatan Harun itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 1, 'Berfirmanlah TUHAN kepada Musa: "Pergilah, berjalanlah dari sini, engkau dan bangsa itu yang telah kaupimpin keluar dari tanah Mesir, ke negeri yang telah Kujanjikan dengan sumpah kepada Abraham, Ishak dan Yakub, demikian: Kepada keturunanmulah akan Kuberikan negeri itu?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 2, 'Aku akan mengutus seorang malaikat berjalan di depanmu dan akan menghalau orang Kanaan, orang Amori, orang Het, orang Feris, orang Hewi dan orang Yebus?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 3, 'yakni ke suatu negeri yang berlimpah-limpah susu dan madu. Sebab Aku tidak akan berjalan di tengah-tengahmu, karena engkau ini bangsa yang tegar tengkuk, supaya Aku jangan membinasakan engkau di jalan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 4, 'Ketika bangsa itu mendengar ancaman yang mengerikan ini, berkabunglah mereka dan seorangpun tidak ada yang memakai perhiasannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 5, 'Berfirmanlah TUHAN kepada Musa: "Katakanlah kepada orang Israel: Kamu ini bangsa yang tegar tengkuk. Jika Aku berjalan di tengah-tengahmu sesaatpun, tentulah Aku akan membinasakan kamu. Oleh sebab itu, tanggalkanlah perhiasanmu, maka Aku akan melihat, apa yang akan Kulakukan kepadamu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 6, 'Demikianlah orang Israel tidak memakai perhiasan-perhiasan lagi sejak dari gunung Horeb.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 7, 'Sesudah itu Musa mengambil kemah dan membentangkannya di luar perkemahan, jauh dari perkemahan, dan menamainya Kemah Pertemuan. Setiap orang yang mencari TUHAN, keluarlah ia pergi ke Kemah Pertemuan yang di luar perkemahan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 8, 'Apabila Musa keluar pergi ke kemah itu, bangunlah seluruh bangsa itu dan berdirilah mereka, masing-masing di pintu kemahnya, dan mereka mengikuti Musa dengan matanya, sampai ia masuk ke dalam kemah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 9, 'Apabila Musa masuk ke dalam kemah itu, turunlah tiang awan dan berhenti di pintu kemah dan berbicaralah TUHAN dengan Musa di sana.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 10, 'Setelah seluruh bangsa itu melihat, bahwa tiang awan berhenti di pintu kemah, maka mereka bangun dan sujud menyembah, masing-masing di pintu kemahnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 11, 'Dan TUHAN berbicara kepada Musa dengan berhadapan muka seperti seorang berbicara kepada temannya; kemudian kembalilah ia ke perkemahan. Tetapi abdinya, Yosua bin Nun, seorang yang masih muda, tidaklah meninggalkan kemah itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 12, 'Lalu berkatalah Musa kepada TUHAN: "Memang Engkau berfirman kepadaku: Suruhlah bangsa ini berangkat, tetapi Engkau tidak memberitahukan kepadaku, siapa yang akan Kauutus bersama-sama dengan aku. Namun demikian Engkau berfirman: Aku mengenal namamu dan juga engkau mendapat kasih karunia di hadapan-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 13, 'Maka sekarang, jika aku kiranya mendapat kasih karunia di hadapan-Mu, beritahukanlah kiranya jalan-Mu kepadaku, sehingga aku mengenal Engkau, supaya aku tetap mendapat kasih karunia di hadapan-Mu. Ingatlah, bahwa bangsa ini umat-Mu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 14, 'Lalu Ia berfirman: "Aku sendiri hendak membimbing engkau dan memberikan ketenteraman kepadamu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 15, 'Berkatalah Musa kepada-Nya: "Jika Engkau sendiri tidak membimbing kami, janganlah suruh kami berangkat dari sini.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 16, 'Dari manakah gerangan akan diketahui, bahwa aku telah mendapat kasih karunia di hadapan-Mu, yakni aku dengan umat-Mu ini? Bukankah karena Engkau berjalan bersama-sama dengan kami, sehingga kami, aku dengan umat-Mu ini, dibedakan dari segala bangsa yang ada di muka bumi ini?"', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 17, 'Berfirmanlah TUHAN kepada Musa: "Juga hal yang telah kaukatakan ini akan Kulakukan, karena engkau telah mendapat kasih karunia di hadapan-Ku dan Aku mengenal engkau."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 18, 'Tetapi jawabnya: "Perlihatkanlah kiranya kemuliaan-Mu kepadaku."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 19, 'Tetapi firman-Nya: "Aku akan melewatkan segenap kegemilangan-Ku dari depanmu dan menyerukan nama TUHAN di depanmu: Aku akan memberi kasih karunia kepada siapa yang Kuberi kasih karunia dan mengasihani siapa yang Kukasihani."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 20, 'Lagi firman-Nya: "Engkau tidak tahan memandang wajah-Ku, sebab tidak ada orang yang memandang Aku dapat hidup."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 21, 'Berfirmanlah TUHAN: "Ada suatu tempat dekat-Ku, di mana engkau dapat berdiri di atas gunung batu;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 22, 'apabila kemuliaan-Ku lewat, maka Aku akan menempatkan engkau dalam lekuk gunung itu dan Aku akan menudungi engkau dengan tangan-Ku, sampai Aku berjalan lewat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 33, 23, 'Kemudian Aku akan menarik tangan-Ku dan engkau akan melihat belakang-Ku, tetapi wajah-Ku tidak akan kelihatan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 1, 'Berfirmanlah TUHAN kepada Musa: "Pahatlah dua loh batu sama dengan yang mula-mula, maka Aku akan menulis pada loh itu segala firman yang ada pada loh yang mula-mula, yang telah kaupecahkan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 2, 'Bersiaplah menjelang pagi dan naiklah pada waktu pagi ke atas gunung Sinai; berdirilah di sana menghadap Aku di puncak gunung itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 3, 'Tetapi janganlah ada seorangpun yang naik bersama-sama dengan engkau dan juga seorangpun tidak boleh kelihatan di seluruh gunung itu, bahkan kambing domba dan lembu sapipun tidak boleh makan rumput di sekitar gunung itu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 4, 'Lalu Musa memahat dua loh batu sama dengan yang mula-mula; bangunlah ia pagi-pagi dan naiklah ia ke atas gunung Sinai, seperti yang diperintahkan TUHAN kepadanya, dan membawa kedua loh batu itu di tangannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 5, 'Turunlah TUHAN dalam awan, lalu berdiri di sana dekat Musa serta menyerukan nama TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 6, 'Berjalanlah TUHAN lewat dari depannya dan berseru: "TUHAN, TUHAN, Allah penyayang dan pengasih, panjang sabar, berlimpah kasih-Nya dan setia-Nya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 7, 'yang meneguhkan kasih setia-Nya kepada beribu-ribu orang, yang mengampuni kesalahan, pelanggaran dan dosa; tetapi tidaklah sekali-kali membebaskan orang yang bersalah dari hukuman, yang membalaskan kesalahan bapa kepada anak-anaknya dan cucunya, kepada keturunan yang ketiga dan keempat."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 8, 'Segeralah Musa berlutut ke tanah, lalu sujud menyembah', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 9, 'serta berkata: "Jika aku telah mendapat kasih karunia di hadapan-Mu, ya Tuhan, berjalanlah kiranya Tuhan di tengah-tengah kami; sekalipun bangsa ini suatu bangsa yang tegar tengkuk, tetapi ampunilah kesalahan dan dosa kami; ambillah kami menjadi milik-Mu."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 10, 'Firman-Nya: "Sungguh, Aku mengadakan suatu perjanjian. Di depan seluruh bangsamu ini akan Kulakukan perbuatan-perbuatan yang ajaib, seperti yang belum pernah dijadikan di seluruh bumi di antara segala bangsa; seluruh bangsa, yang di tengah-tengahnya engkau diam, akan melihat perbuatan TUHAN, sebab apa yang akan Kulakukan dengan engkau, sungguh-sungguh dahsyat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 11, 'Tetapi engkau, berpeganglah pada yang Kuperintahkan kepadamu pada hari ini. Lihat, Aku akan menghalau dari depanmu orang Amori, orang Kanaan, orang Het, orang Feris, orang Hewi dan orang Yebus.', 'id', 'TB')
